CARDIO.register({"item":"d162","meta":{"num":"d162","label":"162","spe":"dermato","short":"IST, syphilis, HPV","title":"Infections sexuellement transmissibles (IST)","section":"D","chapter":9,"pages":"177-208","sdd":[{"num":16,"label":"Adénopathies uniques ou multiples"},{"num":80,"label":"Alopécie et chute de cheveux"},{"num":91,"label":"Anomalie des muqueuses"},{"num":101,"label":"Écoulement urétral"},{"num":104,"label":"Leucorrhées"},{"num":235,"label":"Démarche diagnostique et dépistage rapide du VIH"},{"num":305,"label":"Dépistage et conseils devant une infection sexuellement transmissible"},{"num":310,"label":"Prévention chez un malade contagieux"},{"num":322,"label":"Vaccinations de l'adulte et de l'enfant"}]},"objectives":[{"id":"d162-obj-01","rank":"A","rubric":"Étiologies","title":"Connaître les causes des IST selon leur expression clinique","desc":""},{"id":"d162-obj-02","rank":"B","rubric":"Prévalence, épidémiologie","title":"Connaître la fréquence des différentes IST et leurs facteurs de risque","desc":""},{"id":"d162-obj-03","rank":"A","rubric":"Prise en charge","title":"Connaître les mesures préventives des IST","desc":"Préservatif, vaccination"},{"id":"d162-obj-04","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de prise en charge du ou des partenaires","desc":""},{"id":"d162-obj-05","rank":"A","rubric":"Étiologies","title":"Connaître les causes des ulcérations génitales infectieuses ou non infectieuses","desc":""},{"id":"d162-obj-06","rank":"A","rubric":"Contenu multimédia","title":"Herpès génital","desc":""},{"id":"d162-obj-07","rank":"A","rubric":"Contenu multimédia","title":"Syphilis primaire (chancre)","desc":""},{"id":"d162-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques de l'urétrite masculine","desc":"Prostatite, orchiépididymite"},{"id":"d162-obj-09","rank":"B","rubric":"Étiologies","title":"Connaître les causes des urétrites chez l'homme","desc":""},{"id":"d162-obj-10","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une infection génitale basse chez la femme","desc":""},{"id":"d162-obj-11","rank":"B","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une infection génitale haute chez la femme (salpingite, endométrite)","desc":""},{"id":"d162-obj-12","rank":"A","rubric":"Étiologies","title":"Connaître les causes d'infections génitales basses chez la femme","desc":""},{"id":"d162-obj-13","rank":"B","rubric":"Étiologies","title":"Connaître les causes d'infections génitales hautes chez la femme","desc":""},{"id":"d162-obj-14","rank":"B","rubric":"Diagnostic positif","title":"Connaître les manifestations extragénitales des IST","desc":""},{"id":"d162-obj-15","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires à réaliser en cas d'IST : ulcérations génitales, urétrites, orchites, infections basses de la femme, infections hautes de la femme, localisations extragénitales","desc":""},{"id":"d162-obj-16","rank":"B","rubric":"Prise en charge","title":"Connaître les mesures générales de prise en charge des IST (médicamenteux et non médicamenteux)","desc":""},{"id":"d162-obj-17","rank":"B","rubric":"Examens complémentaires","title":"Connaître les explorations à réaliser en cas d'infection génitale haute chez la femme","desc":""},{"id":"d162-obj-18","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités du traitement probabiliste des IST","desc":""},{"id":"d162-obj-19","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités de dépistage des infections à HPV","desc":"Prévention"},{"id":"d162-obj-20","rank":"A","rubric":"Prise en charge","title":"Savoir choisir les antibiotiques après documentation microbiologique de l'IST","desc":""},{"id":"d162-obj-21","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités thérapeutiques des infections génitales hautes de la femme","desc":""},{"id":"d162-obj-22","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités de prévention des IST","desc":"Prévention (vaccination comprise)"},{"id":"d162-obj-23","rank":"A","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une syphilis précoce","desc":""},{"id":"d162-obj-24","rank":"B","rubric":"Diagnostic positif","title":"Connaître les signes cliniques d'une syphilis tardive","desc":""},{"id":"d162-obj-25","rank":"B","rubric":"Diagnostic positif","title":"Connaître les différentes présentations cliniques de la syphilis secondaire (formes neurologiques notamment)","desc":""},{"id":"d162-obj-26","rank":"B","rubric":"Contenu multimédia","title":"Photographie d'une éruption au stade de syphilis secondaire","desc":""},{"id":"d162-obj-27","rank":"A","rubric":"Examens complémentaires","title":"Connaître les tests sérologiques au cours de la syphilis","desc":""},{"id":"d162-obj-28","rank":"A","rubric":"Prise en charge","title":"Savoir traiter la syphilis primaire","desc":""},{"id":"d162-obj-29","rank":"B","rubric":"Prise en charge","title":"Savoir traiter la syphilis secondaire","desc":""},{"id":"d162-obj-30","rank":"A","rubric":"Diagnostic positif","title":"Connaître les manifestations cliniques liées au HPV","desc":""},{"id":"d162-obj-31","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités de traitement des infections liées au HPV","desc":""},{"id":"d162-obj-32","rank":"B","rubric":"Étiologies","title":"Connaître les étiologies parasitaires des IST","desc":"Trichomonose, phtiriase"},{"id":"d162-obj-33","rank":"B","rubric":"Diagnostic positif","title":"Connaître les examens complémentaires à réaliser pour le diagnostic d'une trichomonose, d'une infection à Chlamydia trachomatis et Neisseria gonorrhoeae","desc":"Prélèvement à acheminer rapidement au laboratoire si examen direct"},{"id":"d162-obj-34","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités du traitement d'une trichomonose, d'une infection à Chlamydia trachomatis et Neisseria gonorrhoeae","desc":"Molécules, patient et partenaire(s) simultanément"},{"id":"d162-obj-35","rank":"A","rubric":"Suivi et/ou pronostic","title":"Principales conséquences à long terme des infections génitales hautes chez la femme","desc":""},{"id":"d162-obj-36","rank":"B","rubric":"Diagnostic positif","title":"Reconnaître les particularités des IST en fonction de l'âge","desc":"Étiologies chez la femme ménopausée et chez la jeune fille"},{"id":"d162-obj-37","rank":"B","rubric":"Contenu multimédia","title":"Photographie de condylomes","desc":""}],"course":{"sections":[{"id":"d162-sec-01","title":"Situer les IST : partir du signe d'appel","rank":"A","objectives":["d162-obj-01","d162-obj-02","d162-obj-05","d162-obj-06","d162-obj-09","d162-obj-12"],"content":"**IST** = infection sexuellement transmissible. Démarche : partir du **signe d'appel**, puis chercher le germe.\n\n| Signe d'appel | Causes à évoquer |\n|---|---|\n| **Écoulement urétral** (urétrite, homme) | **gonocoque**, **Chlamydia trachomatis** ; trichomonose [B] |\n| **Leucorrhées** (pertes vaginales), **cervicite** (femme) | mêmes germes ; **Trichomonas** [B] |\n| **Ulcération génitale, anale ou buccale** | **syphilis**, herpès, chancre mou, donovanose, lymphogranulomatose vénérienne (LGV) |\n| **Éruption, adénopathies, alopécie** | **syphilis secondaire** |\n| **Végétations** (« crêtes-de-coq ») | **HPV** (papillomavirus humain) : condylomes |\n\n**Ulcération génitale : comparer au chancre syphilitique** (indolore, fond propre, induré, adénopathie non inflammatoire)\n- **Herpès** : ulcérations superficielles **douloureuses**, contours polycycliques.\n- **Chancre mou** : fond sale, **très douloureux**, adénopathies inflammatoires ; sujets africains.\n- **Donovanose** : peu douloureuse, aspect granulomateux ; sujets africains.\n- **LGV** (ou maladie de Nicolas-Favre) : anorectite, ulcérations anogénitales, diarrhée trompeuse ; sujets africains ou homosexuels masculins.\n\n- Candidose et vaginose bactérienne : **pas** des IST ; la trichomonose en est une.\n- Autres IST, vues dans d'autres items : herpès (item 168), VIH (virus de l'immunodéficience humaine, item 169), hépatites, phtiriase et scabiose (item 171) [B].\n- [B] Épidémiologie : HPV = IST la plus fréquente ; Chlamydia = 1re cause identifiée d'urétrite aiguë ; syphilis en hausse depuis 2000, surtout chez les homosexuels masculins.","keyPoints":["Ulcération génitale, anale ou buccale : penser **d'abord à la syphilis** ; autres causes : herpès, chancre mou, donovanose, LGV.","Herpès = ulcérations **douloureuses** à contours polycycliques ; chancre syphilitique = **indolore**, induré.","Écoulement urétral ou cervicite : **gonocoque** et **Chlamydia trachomatis**.","Trichomonose = IST ; candidose et vaginose bactérienne = **pas** des IST.","Toute IST : chercher une **IST associée** et traiter les **partenaires**."],"pitfalls":["Urétrite **mixte** possible (gonocoque + Chlamydia dans 15 % des cas) : on traite toujours aussi le Chlamydia.","Aucun caractère du chancre n'est pathognomonique : toute ulcération muqueuse aiguë doit faire évoquer la syphilis."],"src":"p. 177-179, 187, 189, 196-197, 200, 206, 208"},{"id":"d162-sec-02","title":"Gonococcie : urétrite et cervicite à gonocoque","rank":"A","objectives":["d162-obj-08","d162-obj-10","d162-obj-12","d162-obj-14","d162-obj-15","d162-obj-18","d162-obj-20","d162-obj-33","d162-obj-34"],"content":"**Germe** : *Neisseria gonorrhoeae* (gonocoque), **diplocoque à Gram négatif**. **Incubation courte : 2 à 7 jours** ; le patient est contagieux.\n\n**Reconnaître**\n- **Homme** : urétrite antérieure aiguë **bruyante** (portage asymptomatique exceptionnel) : écoulement **purulent** (90 %), dysurie (gêne à la miction), brûlures, prurit urétral.\n- **Femme** : **asymptomatique dans 70 % des cas** ; sinon cervicite : leucorrhées purulentes, pesanteur pelvienne, signes d'urétrite, col peu inflammatoire avec pus à l'orifice. Si l'infection monte (endométrite, salpingite) : douleurs pelviennes, stérilité tubaire, grossesse extra-utérine (GEU), moins souvent qu'avec Chlamydia.\n- **Pharynx, anus** : le plus souvent **asymptomatiques** (anorectite muette dans 2/3 des cas). Portage pharyngé fréquent chez les homo- ou bisexuels : le **rechercher** si rapports à risque (oro-génitaux réceptifs non protégés). Les antibiotiques y diffusent mal → portage persistant après traitement.\n- [B] Complications : prostatite, épididymite (homme) ; **septicémie** (fièvre, lésions cutanées, arthrites).\n\n**Examens**\n- **PCR** (amplification génique), couplée à celle de Chlamydia (**PCR biplex**) : **1er jet d'urine** chez l'homme (10-20 mL, ≥ 2 h après la dernière miction), **auto-écouvillonnage vaginal** chez la femme ; gorge et/ou anus selon les pratiques. Patient symptomatique : prélever l'écoulement urétral s'il existe.\n- [B] **Culture** systématique : confirme et donne l'**antibiogramme** (la PCR n'en donne pas). Examen direct : diplocoques intracellulaires « en grains de café ».\n\n**Traiter** : traitement « minute » = dose unique (DU) donnée en consultation.\n- **Ceftriaxone 1 g IM** (intramusculaire, pour le gonocoque) **+ anti-Chlamydia systématique** (urétrite mixte dans 15 %) : **doxycycline 7 jours**, préférée à l'azithromycine 1 g.\n- Rapports évités ou protégés **≥ 7 jours** ; **partenaires traités** ; même schéma si VIH.\n- [B] Résistances croissantes du gonocoque (pénicilline, cyclines, ciprofloxacine) : schémas à réactualiser. Contrôle clinique à J7 (7e jour) ; si forme asymptomatique, PCR de contrôle à 15 jours.","keyPoints":["Gonocoque : incubation **courte (2-7 j)**, écoulement urétral **purulent** (90 %).","Femme : **70 % asymptomatiques** ; sinon cervicite avec leucorrhées purulentes.","Diagnostic : **PCR** sur 1er jet d'urine (homme) ou auto-écouvillonnage vaginal (femme) ; gorge et anus selon les pratiques.","Traitement minute : **ceftriaxone + anti-Chlamydia systématique** (doxycycline 7 j).","**Partenaires traités**, rapports évités ou protégés **≥ 7 jours**."],"pitfalls":["Pharynx et anus : souvent muets mais contagieux ; les prélever en cas de pratiques à risque.","La PCR ne donne pas la sensibilité aux antibiotiques : la culture garde un intérêt [B]."],"src":"p. 179-183, 187"},{"id":"d162-sec-03","title":"Chlamydiose : Chlamydia trachomatis et conséquences tardives","rank":"A","objectives":["d162-obj-08","d162-obj-10","d162-obj-11","d162-obj-12","d162-obj-13","d162-obj-14","d162-obj-15","d162-obj-20","d162-obj-21","d162-obj-33","d162-obj-34","d162-obj-35"],"content":"**Germe** : *Chlamydia trachomatis*, bacille à Gram négatif **intracellulaire obligatoire** (sérotypes D à K : infections urogénitales ; L1-L3 : lymphogranulomatose vénérienne [B]).\n\n**Pourquoi c'est un enjeu** : **portage asymptomatique très fréquent** (**50 % chez l'homme, 50 à 90 % chez la femme**) → la bactérie circule sans bruit et les complications tardives surviennent.\n\n**Reconnaître** : tableau **moins bruyant** que le gonocoque ; incubation variable (jours à mois).\n- **Homme** : urétrite ; écoulement présent dans < 50 % des cas, **clair, modéré, intermittent**.\n- **Femme** : cervicite le plus souvent asymptomatique ; sinon leucorrhées blanchâtres ou jaunâtres, cystalgies (douleurs vésicales), dyspareunie (douleur aux rapports) ; col fragile, sécrétions mucopurulentes.\n- Pharynx, anus : rarement symptomatiques.\n\n**Conséquences à long terme chez la femme** (infection génitale haute, IGH : endométrite, salpingite, souvent subaiguës ou chroniques) : **douleurs pelviennes inflammatoires, stérilité tubaire, grossesse extra-utérine (GEU)**. Chlamydia = 50 % des salpingites de la femme jeune, **70 % des stérilités tubaires**.\n- [B] Homme : épididymite, prostatite chronique. Deux sexes : syndrome oculo-urétro-synovial (arthrite réactionnelle, urétrite, conjonctivite). Nouveau-né : conjonctivite, pneumopathie.\n\n**Examens** : **PCR = examen clé** (plus sensible que la culture) : 1er jet d'urine (homme) ; auto-écouvillonnage vaginal (femme symptomatique) ou vulvovaginal (asymptomatique). **Sérologie inutile.**\n\n**Traiter** : **doxycycline 100 mg 2 fois/jour pendant 7 jours** (azithromycine 1 g en dose unique si observance incertaine) ; partenaires traités.\n- [B] **Femme enceinte** : azithromycine 1 g en dose unique (cyclines contre-indiquées) ; PCR de contrôle à 1 mois.\n- [B] IGH non compliquée : ceftriaxone 1 g (dose unique) + doxycycline + métronidazole 10 jours ; PCR de contrôle à 2-3 mois.","keyPoints":["Chlamydia : **portage asymptomatique** très fréquent (50 % des hommes, 50-90 % des femmes).","Écoulement urétral **clair, intermittent**, présent dans moins de 50 % des cas.","Diagnostic : **PCR** (examen clé) ; la **sérologie est inutile**.","Chez la femme, conséquences tardives : douleurs pelviennes, **stérilité tubaire**, **GEU**.","Traitement : **doxycycline 7 jours** ; partenaires traités."],"pitfalls":["Pas de symptôme ne veut pas dire pas d'infection : le portage silencieux entretient la transmission et les complications.","PCR de contrôle trop précoce (avant 4 semaines) : faux positif possible [B].","Femme enceinte : la doxycycline (une cycline) est contre-indiquée, on utilise l'azithromycine [B]."],"src":"p. 182-187"},{"id":"d162-sec-04","title":"Syphilis : définition, chancre et syphilis secondaire","rank":"A","objectives":["d162-obj-05","d162-obj-07","d162-obj-23","d162-obj-24","d162-obj-25","d162-obj-26"],"content":"**Syphilis** : IST due à *Treponema pallidum* (spirochète), **très contagieuse** et **non immunisante** (on peut se réinfecter). Transmission essentiellement sexuelle, fellation comprise [B].\n- **Précoce** (< 1 an) = primaire + secondaire + **latente précoce** (sérologie positive, aucun signe, début < 1 an). **Tardive** (> 1 an) = tertiaire + latente tardive.\n\n**Syphilis primaire** : incubation 10-90 jours (**3 semaines** en moyenne) → **chancre** + **adénopathie satellite**.\n- **Chancre** : érosion de 5-15 mm, en général **unique** (parfois multiple « en miroir »), **fond propre**, **indurée** (impossible à plisser entre 2 doigts : le caractère le plus évocateur), **indolore**. Il fourmille de tréponèmes : **contagieux**.\n- Sièges : sillon balano-préputial (homme), vulve (femme), bouche, pharynx, anus. Chancre du vagin, du col, du rectum ou du pharynx : **invisible**, diagnostic souvent manqué.\n- **Adénopathie** satellite **non inflammatoire**, souvent unilatérale.\n- **Guérison spontanée** en quelques semaines sans séquelle, mais la maladie continue : ~30 % des patients non traités font une syphilis secondaire ; une forme tardive est possible sans passer par elle.\n- Aucun caractère n'est pathognomonique → **toute ulcération muqueuse aiguë** (génitale, orale, anale) : penser syphilis.\n\n**Syphilis secondaire** (diffusion du tréponème, en règle < 1 an) : éruptions successives (« floraisons »), polymorphes, + signes généraux ; « **grande simulatrice** ».\n- **Roséole** : macules rose pâle du tronc, dans les 6 semaines après le chancre, disparaît en 7-10 jours → ne pas la confondre avec une **virose** (dont la primo-infection VIH) ou une **toxidermie**.\n- **Syphilides** (lésions cutanées) **papuleuses** : papules **cuivrées**, fine desquamation possible ; **papules palmo-plantaires** (~30 %) : **très évocatrices** ; syphilides génitales très contagieuses.\n- [B] Peut simuler une dermatite séborrhéique, une acné, un psoriasis, un lichen plan, un eczéma.\n- [B] Atteinte oculaire ou d'une paire crânienne = neurosyphilis précoce → ponction lombaire.","keyPoints":["Chancre : **indolore, indurée, à fond propre**, avec adénopathie **non inflammatoire** ; incubation moyenne **3 semaines**.","Toute **ulcération muqueuse aiguë** (génitale, orale, anale) : évoquer la syphilis.","Précoce < 1 an (primaire, secondaire, latente précoce) ; tardive > 1 an.","Syphilis secondaire = « **grande simulatrice** » : papules **cuivrées**, papules **palmo-plantaires** très évocatrices.","Roséole : ne pas la confondre avec une **virose** ou une **toxidermie**."],"pitfalls":["Chancre invisible (vagin, col, rectum, pharynx) : syphilis primaire souvent méconnue.","Le chancre guérit seul : la disparition de la lésion ne veut pas dire que la syphilis est guérie."],"src":"p. 187-193, 196-197, 200"},{"id":"d162-sec-05","title":"Syphilis : lire la sérologie","rank":"A","objectives":["d162-obj-15","d162-obj-27"],"content":"Le tréponème **ne se cultive pas** : le diagnostic repose surtout sur la **sérologie** (2 familles de tests).\n\n| Test | Exemples | À retenir |\n|---|---|---|\n| **TT** (test tréponémique) | **ELISA** (test immuno-enzymatique automatisé), TPHA (test d'agglutination) | **spécifique** des tréponématoses ; qualitatif |\n| **TNT** (test non tréponémique) | **VDRL** (Venereal Disease Research Laboratory), **RPR** (Rapid Plasma Reagin) | **non spécifique** ; **titre** = évolutivité, suivi |\n\n- **Ordre** : **ELISA en 1er** ; **TNT seulement si le TT est positif**.\n- **Cinétique** : TT positif dès le 7e-10e jour du chancre, TNT vers le 10e-15e jour → pendant les **7 premiers jours du chancre, TT et TNT peuvent être négatifs**.\n- **Syphilis secondaire** : TT **et** TNT **toujours positifs** (titre du TNT en général entre 1/16 et 1/128). Syphilis primaire : tous les profils sont possibles.\n\n**Lire le résultat** (TT d'abord, puis TNT)\n\n| TT | TNT | Interprétation |\n|---|---|---|\n| − | − | pas de tréponématose (ou chancre de moins de 7 jours) |\n| + | + | tréponématose ; titre élevé (ex. 1/16) = maladie **évolutive** |\n| + | − | **cicatrice sérologique** (guérie) ou infection très précoce |\n| − | + | le plus souvent **fausse sérologie** : **lupus**, **syndrome des anticorps anti-phospholipides (SAPL)**, **grossesse** |\n\n- Aucun test ne distingue la syphilis des tréponématoses non vénériennes (pian, béjel, pinta).\n- Suivi du traitement : **TNT quantitatif** (le TT quantitatif varie trop d'un examen à l'autre).","keyPoints":["**ELISA (TT) en premier** ; **TNT seulement si TT positif**.","Syphilis secondaire : **TT et TNT toujours positifs**.","**7 premiers jours du chancre** : TT et TNT possiblement négatifs.","TNT positif isolé (TT négatif) = **fausse sérologie** (lupus, SAPL, grossesse) ; TT + et TNT − = **cicatrice sérologique**.","Le TT dit s'il y a une tréponématose ; le TNT renseigne l'évolutivité et sert au suivi."],"pitfalls":["Sérologie négative dans les 7 premiers jours d'un chancre : elle n'élimine pas la syphilis.","TNT positif isolé : le plus souvent faux positif, mais il peut précéder le TT (10 % des cas) en début de syphilis primaire."],"src":"p. 194-196, 200"},{"id":"d162-sec-06","title":"Syphilis : traiter, suivre, partenaires","rank":"A","objectives":["d162-obj-04","d162-obj-18","d162-obj-20","d162-obj-28","d162-obj-29"],"content":"**Règle de l'OMS** (Organisation mondiale de la santé) : devant une **ulcération génitale**, **ne pas attendre** les résultats de la sérologie (TT, test tréponémique ; TNT, test non tréponémique) pour traiter. Si syphilis précoce suspectée : examen clinique soigneux (signes neurologiques, oculaires), **rechercher une autre IST** (gonocoque, Chlamydia, VIH, hépatite B), prescrire un TT ; avis spécialisé dans les cas délicats (femme enceinte, patient séropositif pour le VIH, allergie à la pénicilline).\n\n**Traitement des syphilis précoces** (primaire, secondaire, latente précoce : **même schéma**)\n- **Benzathine-benzylpénicilline 2,4 MU** (millions d'unités) **IM, 1 seule injection**.\n- **Allergie** à la pénicilline : **doxycycline 100 mg matin et soir pendant 14 jours**, sauf femme enceinte et patient séropositif pour le VIH (pour eux : induction de tolérance à la pénicilline).\n- **Réaction d'Herxheimer** : quelques heures après l'injection (surtout en secondaire), liée à la **lyse des tréponèmes** → fièvre, céphalées, myalgies, éruption accentuée. **Bénigne, ce n'est pas une allergie** ; antipyrétique ; prévenir le patient.\n\n**Suivi** : clinique + **TNT quantitatif** à **3 mois, 6 mois, 1 an**, puis chaque année jusqu'à négativation.\n- Efficace si le titre est **divisé par 4 à 6 mois** ; sinon avis spécialisé et **3 injections** de benzathine-benzylpénicilline 2,4 MU à 8 jours d'intervalle.\n- **Titre multiplié par 4** = **recontamination**. TNT négatif attendu 1 an après une syphilis primaire, 2 ans après une secondaire.\n\n**Partenaires** d'une syphilis certaine : contact **< 6 semaines** → **traiter d'emblée** (2,4 MU) + sérologie ; contact **> 6 semaines** → **sérologie** : positive → traiter, négative → refaire à **3 mois**.\n- Patient séropositif pour le VIH : même traitement ; sérologie syphilis au moins 1 fois par an si pratiques à risque.\n- Syphilis **grave chez la femme enceinte** (atteinte fœtale après le 4e mois).\n- Avoir une syphilis = sexualité à haut risque : chercher d'autres IST, répéter la prévention.","keyPoints":["Ulcération génitale : **ne pas attendre** la sérologie pour traiter (OMS).","Syphilis précoce : **benzathine-benzylpénicilline 2,4 MU IM, 1 injection** ; allergie : **doxycycline 14 jours**.","**Herxheimer** = fièvre, céphalées, myalgies après l'injection : **bénin, pas une allergie**.","Suivi : **TNT quantitatif** à 3 mois, 6 mois, 1 an puis annuel ; titre **÷ 4 à 6 mois** ; **× 4** = recontamination.","Contact : **< 6 semaines → traiter**, **> 6 semaines → sérologie** (refaite à 3 mois si négative)."],"pitfalls":["Ne pas prendre une réaction d'Herxheimer pour une allergie à la pénicilline.","Doxycycline : pas chez la femme enceinte ni chez le patient séropositif pour le VIH."],"src":"p. 197-200"},{"id":"d162-sec-07","title":"HPV : reconnaître les condylomes et examiner","rank":"A","objectives":["d162-obj-02","d162-obj-15","d162-obj-19","d162-obj-30","d162-obj-37"],"content":"**HPV** (papillomavirus humain) : une des IST les **plus fréquentes** (formes latentes), surtout chez les 16-25 ans ; la plupart des sujets éliminent le virus en quelques mois.\n- [B] **Bas risque** (HPV 6 et 11) : ~90 % des **condylomes** (verrues génitales). **Haut risque**, oncogènes (**HPV 16 et 18**) : lésions précancéreuses puis cancers.\n- [B] Transmission surtout sexuelle ; aussi par linge humide ou à l'accouchement. VIH et immunodépression : plus fréquent, plus sévère.\n\n**Reconnaître** : le diagnostic des **condylomes est clinique**, par un examen complet anal et génital.\n- **Condylomes acuminés** (« **crêtes-de-coq** ») : masses charnues hérissées de verrucosités de 0,2 à 1 cm, de quelques-unes à plusieurs dizaines.\n- **Condylomes plans** : maculo-papules rosées, parfois invisibles à l'œil nu → **acide acétique** pour les révéler.\n- **Néoplasies intra-épithéliales** : lésions précancéreuses (col, vulve, anus, pénis), risque de carcinome épidermoïde surtout au col.\n- Sièges : homme = pubis, prépuce, sillon balano-préputial ; femme = vulve, souvent **multifocal** (vagin, périnée, anus) → examen gynécologique et anal complet.\n- Enfant : contamination manuportée (verrues) ou par linge, ou mère-enfant ; **mauvais marqueur de sévices sexuels**.\n\n**Examens**\n- Col : **frottis cervico-vaginal** ± colposcopie (acide acétique à 5 %), ou **test HPV-HR** (haut risque, par PCR, amplification génique) **à partir de 30 ans** : avant 30 ans le virus n'est pas encore éliminé, le test est presque toujours positif sans maladie.\n- Anus : anuscopie. **Biopsie** seulement si doute ou suspicion de néoplasie.\n- Chercher une **IST associée (25 %)** : VIH, test tréponémique, hépatite B ; PCR Chlamydia et gonocoque.\n- [B] Différentiels : couronne perlée du gland, syphilides secondaires, kératoses séborrhéiques, molluscum contagiosum, nodules scabieux.","keyPoints":["Condylomes : diagnostic **clinique** (« crêtes-de-coq »).","[B] HPV 6 et 11 : condylomes ; **HPV 16 et 18** : lésions précancéreuses et cancers.","Toujours chercher une **IST associée** (25 %) ; chez la femme, examen gynécologique et dépistage du col.","Col : **frottis** ou **test HPV-HR à partir de 30 ans**.","Enfant : condylomes = **mauvais marqueur de sévices sexuels**."],"pitfalls":["Test HPV-HR avant 30 ans : presque toujours positif sans maladie, il est réservé aux femmes de 30 ans et plus.","Condylomes plans : parfois invisibles à l'œil nu, d'où l'acide acétique."],"src":"p. 200-203, 205-206"},{"id":"d162-sec-08","title":"HPV : traiter, vacciner, dépister","rank":"A","objectives":["d162-obj-03","d162-obj-19","d162-obj-22","d162-obj-31"],"content":"**Traitement des condylomes** [B] : il n'existe **pas de traitement du virus** ; on **détruit les lésions visibles**. Récidives fréquentes (le virus persiste dans la peau saine) → suivi à 1 mois, puis tous les 3 mois jusqu'à guérison, puis à 6 mois.\n- Destruction **physique** (cryothérapie à l'azote liquide, laser CO2, électrocoagulation : risque cicatriciel), **chimique** (podophyllotoxine 0,5 %, appliquée par le patient, **contre-indiquée pendant la grossesse**) ou **immunologique** (imiquimod).\n- Informer : dédramatiser (un comportement à risque n'est pas nécessaire pour avoir des condylomes) et **examiner le/la partenaire**.\n\n**Prévenir par la vaccination** : protège contre les dysplasies du col, de l'anus et de l'oropharynx ; surtout efficace **avant toute contamination**.\n\n| Population | Schéma (vaccin **nonavalent**, 9 types d'HPV) |\n|---|---|\n| Filles **et garçons** de **11 à 14 ans** | **2 doses** (espacées de 6 à 13 mois) |\n| Rattrapage de **15 à 19 ans** révolus | **3 doses** (0, 2 et 6 mois) |\n| **HSH** (hommes ayant des rapports sexuels avec des hommes) | **3 doses** jusqu'à **26 ans** révolus |\n\n- Immunodéprimés : mêmes âges, rattrapage jusqu'à 19 ans. Toute nouvelle vaccination commence par le vaccin nonavalent.\n\n**Dépister le cancer du col** : **frottis cervico-vaginal tous les 3 ans** ou **test HPV-HR** (haut risque) ; dysplasie même mineure → **colposcopie** (± biopsie dirigée). Vaccin + dépistage = prévention du cancer du col.","keyPoints":["**Vaccin nonavalent** : filles **et garçons** de 11-14 ans (**2 doses**), rattrapage 15-19 ans (**3 doses**, 0-2-6 mois).","**HSH** : vaccination jusqu'à **26 ans** (3 doses).","La vaccination est préventive : à faire **avant toute contamination**.","Prévention du cancer du col = **vaccin + dépistage** (frottis tous les 3 ans ou test HPV-HR).","[B] Pas de traitement du virus : on détruit les lésions ; **récidives fréquentes**."],"pitfalls":["Podophyllotoxine : contre-indiquée chez la femme enceinte [B].","Les condylomes n'impliquent pas un comportement à risque : dédramatiser, ne pas culpabiliser [B]."],"src":"p. 204-206"},{"id":"d162-sec-09","title":"Trichomonose et autres IST","rank":"B","objectives":["d162-obj-32","d162-obj-33","d162-obj-34"],"content":"**Trichomonose** : due à *Trichomonas vaginalis*, **protozoaire flagellé**. C'est une **IST**, contrairement à la candidose et à la vaginose bactérienne. Transmission presque exclusivement sexuelle ; incubation de 4 à 28 jours.\n\n**Reconnaître**\n- **Homme** : le plus souvent **asymptomatique** ; sinon urétrite subaiguë ou balanoposthite (gland et prépuce), parfois écoulement matinal et prurit.\n- **Femme** : asymptomatique dans la majorité des cas ; sinon vulvovaginite ou cervicovaginite : **prurit intense**, leucorrhées **abondantes, verdâtres, spumeuses, malodorantes**, vulve œdématiée, **colpite « léopard »** (aspect ponctué du col au spéculum).\n- Différencier d'une vaginose bactérienne et d'une candidose : pas toujours aisé.\n\n**Diagnostic** : **examen direct à l'état frais** (le parasite est **mobile**) ou **PCR**. Prélèvement : écoulement urétral ou 1er jet d'urine (homme) ; cul-de-sac vaginal postérieur (femme).\n\n**Traiter** : **métronidazole** (2 g en dose unique, ou 500 mg 2 fois/jour pendant 7 jours) ou secnidazole 2 g en dose unique. **Traiter simultanément le/la partenaire** (forte transmissibilité).\n- Proposer au patient et à ses partenaires : VIH, test tréponémique, hépatite B, PCR Chlamydia + gonocoque.\n\n**Autres IST**, vues dans d'autres items : herpès (168), VIH (169), hépatites, phtiriase et scabiose (171) ; la scabiose se transmet comme une IST → chercher des conduites à risque et dépister les autres IST.","keyPoints":["Trichomonose = IST (protozoaire) ; **asymptomatique** le plus souvent.","Femme : leucorrhées **verdâtres, spumeuses, malodorantes**, prurit, colpite « léopard ».","Diagnostic : examen direct à l'état frais (parasite **mobile**) ou PCR.","Traitement : **métronidazole** (ou secnidazole) + **partenaire traité en même temps**."],"pitfalls":["Ne pas confondre avec la vaginose bactérienne ou la candidose, qui ne sont pas des IST."],"src":"p. 206-208"},{"id":"d162-sec-10","title":"Conduite commune à toute IST : partenaires, dépistage, prévention","rank":"A","objectives":["d162-obj-02","d162-obj-03","d162-obj-04","d162-obj-16","d162-obj-18","d162-obj-20","d162-obj-22","d162-obj-35"],"content":"**Devant toute IST**\n- **Partenaires** : identifier les partenaires contaminés ou contaminateurs et leur proposer dépistage, diagnostic ou **traitement probabiliste** (sans attendre les résultats).\n- **Autres IST** : proposer **systématiquement** une sérologie **VIH**, un **test tréponémique** (TT, syphilis) et une sérologie **hépatite B** ; PCR Chlamydia + gonocoque selon le cas.\n- **Pas de rapports non protégés** pendant le traitement (≥ 7 jours pour une urétrite) ; insister sur le risque de **recontamination** ; éduquer le patient.\n- **PrEP** (prophylaxie pré-exposition au VIH, traitement préventif) à envisager si prises de risque trop régulières.\n\n**Traitement probabiliste** (urétrite et contacts) : traitement « minute » en consultation. Préférer **ceftriaxone + doxycycline 7 jours** : l'azithromycine en dose unique est remise en question (résistances apparues chez un autre germe, Mycoplasma genitalium). Même traitement si VIH.\n\n**Après documentation du germe**, adapter l'antibiotique : gonocoque → ceftriaxone ; Chlamydia → doxycycline ; syphilis → benzathine-benzylpénicilline ; trichomonose → métronidazole.\n\n**Prévenir** : **préservatif** et **vaccination anti-HPV** ; dépistage des partenaires et des sujets à risque.\n- [B] Dépistage : Chlamydia par autoprélèvement vaginal chez les femmes de moins de 25 ans ; sérologie de la syphilis chez les sujets à risque (au moins 1 fois par an si VIH), obligatoire au 1er trimestre de grossesse.\n- **Conséquences tardives d'une infection génitale haute (IGH) chez la femme** : douleurs pelviennes inflammatoires, stérilité tubaire, grossesse extra-utérine (GEU) → enjeu de santé publique chez les sujets jeunes.","keyPoints":["Devant toute IST : **partenaires**, proposer **VIH + test tréponémique + hépatite B**, rapports protégés, **PrEP** si risques répétés.","Traitement probabiliste de l'urétrite : **ceftriaxone + doxycycline 7 jours**.","Prévention : **préservatif** + **vaccination anti-HPV**.","Conséquences tardives d'une IGH chez la femme : douleurs pelviennes, **stérilité tubaire**, **GEU**."],"pitfalls":["Traiter un patient sans traiter ses partenaires expose à la recontamination.","Azithromycine 1 g en dose unique : commode, mais la doxycycline 7 jours est préférée."],"src":"p. 182, 185, 187-188, 205, 208"}],"essentials":[{"id":"d162-ess-01","rank":"A","text":"Caractères du chancre syphilitique : ulcération **indolore**, à fond propre, **indurée** (impossible à plisser), avec adénopathie satellite **non inflammatoire**.","src":"p. 188-190","q":"Comment décrire les caractères du chancre syphilitique (douleur, fond, consistance, adénopathie) ?"},{"id":"d162-ess-02","rank":"A","text":"Devant une ulcération muqueuse aiguë (génitale, orale ou anale) : évoquer systématiquement la **syphilis**, car aucun caractère du chancre n'est pathognomonique.","src":"p. 189","q":"Devant une ulcération muqueuse aiguë génitale, orale ou anale, quel diagnostic évoquer systématiquement et pourquoi ?"},{"id":"d162-ess-03","rank":"A","text":"Ordre des tests de sérologie syphilitique : **ELISA** (test tréponémique, TT) en premier ; **TNT** (test non tréponémique : VDRL ou RPR) seulement si le TT est positif.","src":"p. 194, 200","q":"Dans quel ordre réalise-t-on les tests sérologiques de la syphilis et à quelle condition le second est-il fait ?"},{"id":"d162-ess-04","rank":"A","text":"Sérologie au début du chancre : durant les **7 premiers jours**, le test tréponémique (TT) et le non tréponémique (TNT) peuvent être **négatifs** → traiter sans attendre (recommandation de l'OMS, Organisation mondiale de la santé).","src":"p. 195-197","q":"Que peuvent montrer les sérologies dans les 7 premiers jours du chancre et quelle conduite adopter ?"},{"id":"d162-ess-05","rank":"A","text":"Sérologie de la syphilis secondaire : le test tréponémique (TT) et le non tréponémique (TNT) sont **toujours positifs** (titre du TNT généralement entre 1/16 et 1/128).","src":"p. 195, 200","q":"Que montrent les sérologies de la syphilis secondaire (tests tréponémique et non tréponémique, titre) ?"},{"id":"d162-ess-06","rank":"A","text":"Sérologie de syphilis discordante : TNT (test non tréponémique) positif avec TT (test tréponémique) négatif = **fausse sérologie** (lupus, syndrome des anticorps anti-phospholipides, grossesse) ; TT positif avec TNT négatif = **cicatrice sérologique**.","src":"p. 194-196","q":"Comment interprète-t-on une sérologie syphilitique discordante, dans chacun des deux sens ?"},{"id":"d162-ess-07","rank":"A","text":"Traitement de la syphilis précoce : **benzathine-benzylpénicilline 2,4 MU** (millions d'unités) en **une injection IM** (intramusculaire) ; si allergie, **doxycycline 14 jours**.","src":"p. 198","q":"Quel est le traitement de la syphilis précoce (molécule, dose, voie) et l'alternative en cas d'allergie ?"},{"id":"d162-ess-08","rank":"A","text":"Réaction d'Herxheimer après l'injection : fièvre, céphalées, myalgies quelques heures après, liée à la lyse des tréponèmes ; **bénigne**, ce n'est **pas** une allergie à la pénicilline.","src":"p. 198","q":"Qu'est-ce que la réaction d'Herxheimer après traitement de la syphilis (signes, mécanisme, signification) ?"},{"id":"d162-ess-09","rank":"A","text":"Suivi biologique d'une syphilis traitée : **TNT quantitatif** (test non tréponémique) ; titre **divisé par 4** à 6 mois ; titre **multiplié par 4** = recontamination.","src":"p. 195, 198","q":"Comment suit-on biologiquement une syphilis traitée et comment interprète-t-on l'évolution du titre ?"},{"id":"d162-ess-10","rank":"A","text":"Contact sexuel d'une syphilis certaine : **< 6 semaines** → traiter d'emblée (une injection de 2,4 millions d'unités, MU) ; **> 6 semaines** → sérologie, à refaire à 3 mois si négative.","src":"p. 198","q":"Quelle est la conduite pour un contact sexuel d'une syphilis certaine selon le délai (moins ou plus de 6 semaines) ?"},{"id":"d162-ess-11","rank":"A","text":"Syphilis secondaire, lésions évocatrices : papules **cuivrées** et papules **palmo-plantaires** ; la roséole ne doit pas être confondue avec une virose ou une toxidermie.","src":"p. 191-192, 200","q":"Quelles lésions cutanées évoquent une syphilis secondaire et avec quoi la roséole peut-elle être confondue ?"},{"id":"d162-ess-12","rank":"A","text":"Classification de la syphilis : **précoce** (< 1 an) = primaire, secondaire, latente précoce ; **tardive** (> 1 an) = tertiaire, latente tardive.","src":"p. 188","q":"Comment classe-t-on la syphilis en précoce et tardive (seuil, stades) ?"},{"id":"d162-ess-13","rank":"A","text":"Gonococcie de l'homme : incubation courte de **2 à 7 jours** et écoulement urétral **purulent** dans 90 % des cas.","src":"p. 180","q":"Comment décrire la gonococcie de l'homme : incubation et signe principal avec sa fréquence ?"},{"id":"d162-ess-14","rank":"A","text":"Gonococcie de la femme : asymptomatique dans **70 %** des cas ; sinon cervicite avec leucorrhées purulentes et col peu inflammatoire.","src":"p. 180-181","q":"Comment décrire la gonococcie de la femme : fréquence des formes asymptomatiques et tableau clinique ?"},{"id":"d162-ess-15","rank":"A","text":"Gonocoque et Chlamydia, diagnostic : **PCR** (amplification génique) sur **1er jet d'urine** chez l'homme, **auto-écouvillonnage vaginal** chez la femme.","src":"p. 181, 185","q":"Comment diagnostique-t-on le gonocoque et Chlamydia (technique, prélèvement chez l'homme et chez la femme) ?"},{"id":"d162-ess-16","rank":"A","text":"Traitement minute d'une urétrite : **ceftriaxone** en dose unique + **anti-Chlamydia systématique** (**doxycycline 7 jours** préférée à l'azithromycine 1 g) ; rapports protégés **≥ 7 jours** et partenaires traités.","src":"p. 182, 187","q":"Quel est le traitement « minute » d'une urétrite (molécules, durée, mesures associées) ?"},{"id":"d162-ess-17","rank":"A","text":"Chlamydia trachomatis, clinique : portage **asymptomatique** très fréquent (50 % des hommes, 50 à 90 % des femmes) ; écoulement urétral **clair**, intermittent.","src":"p. 184","q":"Comment décrire la clinique de l'infection à Chlamydia trachomatis : portage et écoulement ?"},{"id":"d162-ess-18","rank":"A","text":"Chlamydia trachomatis, examen clé : **PCR** ; la **sérologie** n'a aucun intérêt pour le diagnostic.","src":"p. 185","q":"Quel est l'examen clé du diagnostic d'infection à Chlamydia trachomatis et la place de la sérologie ?"},{"id":"d162-ess-19","rank":"A","text":"Conséquences à long terme d'une infection génitale haute chez la femme : douleurs pelviennes inflammatoires, **stérilité tubaire**, **grossesse extra-utérine**.","src":"p. 181, 183-184","q":"Quelles sont les conséquences à long terme d'une infection génitale haute chez la femme ?"},{"id":"d162-ess-20","rank":"A","text":"Conduite à tenir devant toute IST (infection sexuellement transmissible) : traiter les **partenaires**, proposer **VIH + test tréponémique + hépatite B**, pas de rapports non protégés pendant le traitement, **PrEP** (prophylaxie pré-exposition au VIH) si prises de risque répétées.","src":"p. 182, 185, 208","q":"Quelle est la conduite à tenir devant toute IST (partenaires, dépistages associés, rapports, prévention) ?"},{"id":"d162-ess-21","rank":"A","text":"Diagnostic et bilan des condylomes : examen **clinique** (« crêtes-de-coq ») et recherche d'une **IST associée** (25 % des cas).","src":"p. 201, 205","q":"Comment fait-on le diagnostic de condylomes et que recherche-t-on, avec quelle fréquence ?"},{"id":"d162-ess-22","rank":"A","text":"Dépistage du cancer du col de l'utérus : **frottis tous les 3 ans** ou **test HPV-HR** (haut risque, à partir de 30 ans) ; dysplasie même mineure → colposcopie.","src":"p. 202, 205","q":"Comment dépiste-t-on le cancer du col de l'utérus (examens, rythme, âge) et que faire devant une dysplasie, même mineure ?"},{"id":"d162-ess-23","rank":"A","text":"Vaccin anti-HPV nonavalent : filles **et garçons** de **11 à 14 ans** (2 doses), rattrapage **15-19 ans** (3 doses, 0-2-6 mois), HSH (hommes ayant des rapports sexuels avec des hommes) jusqu'à **26 ans**.","src":"p. 204-205","q":"Quelles sont les indications du vaccin anti-HPV nonavalent (âges, schéma, population particulière) ?"},{"id":"d162-ess-24","rank":"B","text":"Types d'HPV et conséquences : HPV **6 et 11** (bas risque) = ~90 % des condylomes ; HPV **16 et 18** (haut risque) = lésions précancéreuses puis cancers.","src":"p. 201","q":"Quels types d'HPV sont de bas risque et de haut risque, et quelles lésions causent-ils ?"},{"id":"d162-ess-25","rank":"B","text":"Trichomonose, signes, diagnostic et traitement : leucorrhées **verdâtres, spumeuses, malodorantes**, parasite **mobile** à l'examen direct ; **métronidazole** et partenaire traité en même temps.","src":"p. 207-208","q":"Comment décrire la trichomonose : signes, diagnostic et traitement ?"},{"id":"d162-ess-51","rank":"A","q":"Citez les signes d'une urétrite gonococcique non compliquée chez l'homme (5) ?","text":"**Écoulement purulent** (90 %), **dysurie**, douleurs urétrales (brûlures), **prurit urétral**, méatite voire balanite.","src":"p. 180","kind":"liste"},{"id":"d162-ess-52","rank":"A","q":"Citez les signes d'une anorectite gonococcique ?","text":"Asymptomatique dans **2/3** des cas ; sinon prurit anal, anite, écoulement rectal purulent, diarrhée, saignements, **syndrome rectal** (ténesme, épreintes) et défécations incomplètes.","src":"p. 180","kind":"liste"},{"id":"d162-ess-53","rank":"B","q":"Citez les complications d'une gonococcie (homme, femme, deux sexes) ?","text":"Homme : **prostatite, épididymite**. Femme : endométrite, **salpingite**, algies pelviennes, stérilité tubaire, GEU. Deux sexes : **septicémie** (fièvre, purpura/papulo-pustules acrales, arthrites septiques, ténosynovites), endocardite, méningite.","src":"p. 181","kind":"liste"},{"id":"d162-ess-54","rank":"B","q":"Citez les sites de prélèvement de la PCR gonocoque/Chlamydia ?","text":"Homme : **1er jet urinaire** (10-20 mL, ≥ 2 h après la dernière miction). Femme : **auto-écouvillonnage vaginal**. Selon les pratiques : prélèvement **pharyngé et/ou anal**.","src":"p. 181","kind":"liste"},{"id":"d162-ess-55","rank":"B","q":"Citez les alternatives à la ceftriaxone dans la gonococcie non compliquée en cas d'allergie aux β-lactamines ?","text":"**Azithromycine 2 g** PO DU, **gentamicine 240 mg** IM DU, **ciprofloxacine 500 mg** PO DU (avec antibiogramme).","src":"p. 182","kind":"liste"},{"id":"d162-ess-56","rank":"B","q":"Citez les complications de la chlamydiose génitale (homme, femme, deux sexes, nouveau-né) ?","text":"Homme : **épididymite**, prostatite chronique. Femme : endométrite, salpingite, algies, **stérilité tubaire**, GEU, périhépatite. Deux sexes : **syndrome oculo-urétro-synovial**, kératoconjonctivite, arthrite. Nouveau-né : kératoconjonctivite, pneumopathie.","src":"p. 184-185","kind":"liste"},{"id":"d162-ess-57","rank":"B","q":"Citez les 5 éléments du syndrome oculo-urétro-synovial (Chlamydia) ?","text":"**Polyarthrite** réactionnelle, **urétrite**, **conjonctivite** bilatérale, **balanite circinée**, **kératodermie** palmo-plantaire psoriasiforme.","src":"p. 184-185","kind":"liste"},{"id":"d162-ess-58","rank":"B","q":"Citez les indications de dépistage de Chlamydia trachomatis ?","text":"Systématique : femmes sexuellement actives de **15-25 ans** (autoprélèvement vaginal). Ciblé : hommes à risque (tout âge), femmes **> 25 ans** à risque, femmes enceintes consultant pour **IVG**.","src":"p. 183, 187","kind":"liste"},{"id":"d162-ess-59","rank":"B","q":"Citez les traitements de la chlamydiose non compliquée, 1re et 2e intention ?","text":"1re : **doxycycline 100 mg ×2/j 7 j** ou **azithromycine 1 g** DU (mauvaise observance). 2e : **érythromycine 500 mg ×4/j 7 j** ou **ofloxacine 200 mg ×2/j 7 j**.","src":"p. 185","kind":"liste"},{"id":"d162-ess-60","rank":"B","q":"Citez le traitement d'une infection génitale haute non compliquée (recommandations 2018) ?","text":"**Ceftriaxone 1 g** IV/IM DU + **doxycycline 100 mg ×2/j 10 j** + **métronidazole 500 mg ×2/j 10 j** ; contrôle PCR 2 à 3 mois après.","src":"p. 186","kind":"liste"},{"id":"d162-ess-61","rank":"A","q":"Citez les sièges habituels du chancre syphilitique ?","text":"Homme : **sillon balano-préputial** (gland, fourreau). Femme : **vulve** (vagin : inaperçu). Deux sexes : muqueuse **buccale/pharyngée**, **anorectale**.","src":"p. 189","kind":"liste"},{"id":"d162-ess-62","rank":"B","q":"Citez les manifestations cutanéo-muqueuses de la syphilis secondaire (hors roséole) ?","text":"**Syphilides papuleuses** cuivrées, **palmo-plantaires**, **génitales/périnéales**, fausse perlèche, lésions séborrhéiques des sillons nasogéniens, papules acnéiformes du menton, **dépapillation linguale**, alopécie en « fourrure mitée ».","src":"p. 190-192","kind":"liste"},{"id":"d162-ess-63","rank":"B","q":"Citez les manifestations extra-cutanées de la syphilis secondaire (au moins 7) ?","text":"Fébricule, céphalées, syndrome méningé, raucité, **polyadénopathies**, hépatosplénomégalie (hépatite), polyarthralgies, douleurs osseuses, **uvéite/névrite optique**, atteinte d'une **paire crânienne**.","src":"p. 193","kind":"liste"},{"id":"d162-ess-64","rank":"B","q":"Citez les causes de fausse sérologie syphilitique (VDRL positif, TT négatif) ?","text":"Non infectieuses : **grossesse**, toxicomanie IV, hépatopathie chronique, gammapathie monoclonale, **lupus**, **SAPL**, cancers. Infectieuses : lèpre, tuberculose, leptospirose, borréliose, scarlatine, varicelle, **MNI**, VIH, paludisme...","src":"p. 195","kind":"liste"},{"id":"d162-ess-65","rank":"B","q":"Citez les diagnostics différentiels de la syphilis secondaire selon l'aspect ?","text":"Roséole : **virose (primo-infection VIH)**, **toxidermie**. Visage : dermatite séborrhéique, **acné**, psoriasis. Papules : **psoriasis, lichen plan, eczéma**.","src":"p. 197","kind":"liste"},{"id":"d162-ess-66","rank":"B","q":"Citez les diagnostics différentiels des condylomes acuminés ?","text":"**Couronne perlée du gland**/papillomatose vestibulaire, **condylomata lata** (syphilis), lésions dysplasiques, kératoses séborrhéiques, **molluscum contagiosum**, nodules scabieux.","src":"p. 203","kind":"liste"},{"id":"d162-ess-67","rank":"B","q":"Citez les traitements curatifs des condylomes (physique, chimique, immunologique) ?","text":"Physique : **cryothérapie**, **laser CO2**, électrocoagulation. Chimique : **podophyllotoxine 0,5 %**. Immunologique : **imiquimod**. Pas de traitement spécifique de l'HPV.","src":"p. 205-206","kind":"liste"},{"id":"d162-ess-68","rank":"B","q":"Quelles sont les résistances actuelles du gonocoque (pénicilline, cyclines, ciprofloxacine) ?","text":"Pénicilline (β-lactamase) **15 %**, cyclines **20 %**, ciprofloxacine **40 %** ; CMI des C3G en hausse avec résistances vraies ponctuelles.","src":"p. 180","kind":"piege"},{"id":"d162-ess-69","rank":"B","q":"Quel seuil définit l'urétrite « biologique » et que montre l'examen direct du gonocoque ?","text":"**> 5 PNN** au grossissement 100 ou **> 10 PNN** au grossissement 400 ; diplocoques Gram négatif « **en grains de café** » **intracellulaires** (une forme extracellulaire n'est pas certaine).","src":"p. 181","kind":"piege"},{"id":"d162-ess-70","rank":"B","q":"Quels contrôles après traitement d'une gonococcie et d'une chlamydiose ?","text":"Gonocoque : clinique **J7** ; PCR **15 jours** après si asymptomatique. Chlamydia : PCR **pas trop précoce** (débris pendant 4 semaines) ; 3-6 mois si risque de réinfection.","src":"p. 183, 185","kind":"piege"},{"id":"d162-ess-71","rank":"B","q":"Quelles durées de ceftriaxone pour septicémie, endocardite, méningite et salpingite gonococciques ?","text":"Septicémie **7-10 j** (1 g/j IV) ; méningite **10-14 j** ; endocardite **4 semaines** (1-2 g/j IV) ; endométrite/salpingite **14 j**.","src":"p. 182-183","kind":"piege"},{"id":"d162-ess-72","rank":"A","q":"Après quel délai le TT et le TNT se positivent-ils, et quand sont-ils maximaux ?","text":"TT : **7e-10e jour** du chancre. TNT : **10-15 jours** (maximum entre le **3e et le 6e mois**) ; négatifs durant les 7 premiers jours ; dans 10 % le TNT précède le TT.","src":"p. 194-195","kind":"piege"},{"id":"d162-ess-73","rank":"A","q":"Le titre du TT est-il utile au suivi ? Et le TNT en phase secondaire ?","text":"TT quantitatif **non utile** (variable) : seul le TT qualitatif compte. TNT : plateau **1/16 à 1/128** en secondaire, ne distingue pas latente précoce/tardive ; sert au suivi.","src":"p. 194-195","kind":"piege"},{"id":"d162-ess-74","rank":"A","q":"En quel délai le TNT doit-il être négatif après traitement d'une syphilis primaire, secondaire ?","text":"Négatif **1 an** après une syphilis **primaire**, dans un délai de **2 ans** après une syphilis **secondaire**.","src":"p. 198","kind":"piege"},{"id":"d162-ess-75","rank":"A","q":"Que faire si le TNT n'est pas divisé par 4 à 6 mois après traitement d'une syphilis ?","text":"Avis **spécialisé** et traitement par **3 injections** de benzathine-benzylpénicilline 2,4 MU à **8 jours d'intervalle**.","src":"p. 198","kind":"piege"},{"id":"d162-ess-76","rank":"A","q":"Syphilis précoce et allergie à la pénicilline : quelle alternative et quelles exceptions ?","text":"**Doxycycline 100 mg matin et soir 14 jours**, sauf **femme enceinte** et patient **VIH+** (induction de tolérance à la pénicilline).","src":"p. 198","kind":"piege"},{"id":"d162-ess-77","rank":"B","q":"Syphilis secondaire : une céphalée signe-t-elle une neurosyphilis, et que faire devant une atteinte ophtalmique ?","text":"Les céphalées **ne sont pas synonymes** de neurosyphilis. Atteinte **ophtalmique ou d'une paire crânienne** = neurosyphilis précoce : **ponction lombaire** et pénicilline G **14 jours**, quel que soit le résultat.","src":"p. 193","kind":"piege"},{"id":"d162-ess-78","rank":"B","q":"Roséole syphilitique : délai d'apparition, durée et taille des macules ?","text":"1re éruption dans les **6 semaines** suivant le chancre, **7-10 jours**, macules rose pâle de **5 à 15 mm** du tronc, sans signe fonctionnel.","src":"p. 190","kind":"piege"},{"id":"d162-ess-79","rank":"B","q":"Quelle fréquence des syphilides palmo-plantaires en syphilis secondaire ?","text":"Environ **30 %** des cas : inconstantes, discrètes, cuivrées, à cheval sur les plis palmaires, mais très évocatrices.","src":"p. 192","kind":"piege"},{"id":"d162-ess-80","rank":"B","q":"À quelle fréquence dépister la syphilis chez le patient VIH et quand pendant la grossesse ?","text":"Au moins **1 fois/an** chez le patient VIH à risque ; sérologie **obligatoire au 1er trimestre** de la grossesse. Passage placentaire surtout après la 16e SA.","src":"p. 188, 199","kind":"piege"},{"id":"d162-ess-81","rank":"A","q":"Pourquoi le test HPV-HR n'est-il pas utilisé avant 30 ans ?","text":"Avant 30 ans la clairance spontanée n'est pas totale : positivité **presque certaine** sans pathologie sous-jacente ; test recommandé en 1re intention **à partir de 30 ans**.","src":"p. 202","kind":"piege"},{"id":"d162-ess-82","rank":"A","q":"Les condylomes de l'enfant sont-ils un marqueur de sévices sexuels ?","text":"Ils sont un **mauvais marqueur** de sévices (contamination manuportée à partir de verrues vulgaires, linges, ou mère-enfant), mais la vigilance reste de mise.","src":"p. 203","kind":"piege"},{"id":"d162-ess-83","rank":"B","q":"Quel schéma d'application de la podophyllotoxine et de l'imiquimod, et quelles précautions ?","text":"Podophyllotoxine 0,5 % : **matin et soir 3 jours consécutifs/semaine**, sur les lésions seules, **contre-indiquée** femme enceinte et enfant. Imiquimod : **3 fois/semaine 16 semaines**, prudence chez la femme enceinte.","src":"p. 205-206","kind":"piege"},{"id":"d162-ess-84","rank":"B","q":"Quel suivi après traitement de condylomes ?","text":"À **1 mois**, puis **tous les 3 mois** jusqu'à guérison clinique, puis **6 mois** après guérison ; récidives fréquentes (virus persistant dans l'épiderme sain), examen du partenaire.","src":"p. 204","kind":"piege"},{"id":"d162-ess-85","rank":"A","q":"La trichomonose est-elle une IST comme la candidose ou la vaginose bactérienne ?","text":"**Non** pour ces dernières : la trichomonose (*Trichomonas vaginalis*, protozoaire flagellé) est **considérée comme une IST**, contrairement à la candidose et à la vaginose bactérienne.","src":"p. 206","kind":"piege"},{"id":"d162-ess-86","rank":"B","q":"Quels sont les sérotypes de Chlamydia trachomatis responsables d'IST urogénitale et de LGV ?","text":"Sérotypes **D à K** : infections urogénitales. Sérotypes **L1, L2, L3** : lymphogranulomatose vénérienne (**maladie de Nicolas-Favre**), résurgence depuis 2003 chez les HSH, souvent VIH+.","src":"p. 183","kind":"B"},{"id":"d162-ess-87","rank":"B","q":"Quelle est l'épidémiologie de Chlamydia trachomatis par rapport au gonocoque ?","text":"**50 fois plus fréquente** que la gonococcie ; 1re cause d'IST bactérienne et d'urétrite aiguë identifiée ; pic 15-34 ans (femme), 20-39 ans (homme).","src":"p. 183","kind":"B"},{"id":"d162-ess-88","rank":"B","q":"Quels sont les signes de la trichomonose féminine et masculine ?","text":"Homme : le plus souvent **asymptomatique**, urétrite subaiguë, balanoposthite. Femme : leucorrhées **verdâtres spumeuses malodorantes**, vulve œdématiée, colpite en « **léopard** », prurit, dyspareunie.","src":"p. 207","kind":"B"},{"id":"d162-ess-89","rank":"B","q":"Quelle est la situation épidémiologique des infections à HPV ?","text":"IST **la plus fréquente** ; ~40 % des jeunes Européennes infectées ; la plupart éliminent le virus ; < 10 % porteurs asymptomatiques ; ~1 % développent des lésions génitales. **HPV 6 et 11** : ~90 % des condylomes.","src":"p. 200-201","kind":"B"}],"numbers":[{"id":"d162-num-01","rank":"A","label":"Incubation de la gonococcie","value":"2 à 7 jours (courte)","src":"p. 180"},{"id":"d162-num-02","rank":"A","label":"Gonococcie masculine : fréquence de l'écoulement purulent","value":"90 % des cas","src":"p. 180"},{"id":"d162-num-03","rank":"A","label":"Gonococcie chez la femme : part des formes asymptomatiques","value":"70 %","src":"p. 180"},{"id":"d162-num-04","rank":"A","label":"Urétrite mixte (gonocoque + Chlamydia)","value":"15 % des cas → traitement anti-Chlamydia systématique","src":"p. 182"},{"id":"d162-num-05","rank":"A","label":"Chlamydia trachomatis : portage asymptomatique","value":"50 % chez l'homme ; 50 à 90 % chez la femme","src":"p. 184"},{"id":"d162-num-06","rank":"A","label":"Part des stérilités tubaires dues à Chlamydia trachomatis","value":"70 % (et 50 % des salpingites de la femme jeune)","src":"p. 183"},{"id":"d162-num-07","rank":"A","label":"Rapports sexuels après traitement d'une urétrite","value":"évités ou protégés pendant au moins 7 jours","src":"p. 182"},{"id":"d162-num-08","rank":"A","label":"Syphilis primaire : durée d'incubation","value":"10 à 90 jours, 3 semaines en moyenne","src":"p. 188"},{"id":"d162-num-09","rank":"A","label":"Syphilis précoce / tardive : limite de durée","value":"précoce < 1 an ; tardive > 1 an","src":"p. 188"},{"id":"d162-num-10","rank":"A","label":"Chancres non traités évoluant vers une syphilis secondaire","value":"environ 30 %","src":"p. 190"},{"id":"d162-num-11","rank":"A","label":"Début du chancre : période où la sérologie (TT, TNT) peut être négative","value":"les 7 premiers jours","src":"p. 195-196"},{"id":"d162-num-12","rank":"A","label":"Syphilis précoce : traitement de référence","value":"benzathine-benzylpénicilline 2,4 MU (millions d'unités) en 1 injection IM (intramusculaire)","src":"p. 198"},{"id":"d162-num-13","rank":"A","label":"Syphilis précoce avec allergie à la pénicilline","value":"doxycycline 100 mg matin et soir pendant 14 jours (sauf femme enceinte et VIH)","src":"p. 198"},{"id":"d162-num-14","rank":"A","label":"Efficacité du traitement de la syphilis : évolution du titre du TNT (test non tréponémique)","value":"divisé par 4 à 6 mois ; multiplié par 4 = recontamination","src":"p. 195, 198"},{"id":"d162-num-15","rank":"A","label":"Contrôles d'une syphilis traitée","value":"3 mois, 6 mois, 1 an, puis chaque année jusqu'à négativation","src":"p. 198"},{"id":"d162-num-16","rank":"A","label":"Contact sexuel d'une syphilis certaine : seuil de 6 semaines","value":"< 6 semaines : traiter ; > 6 semaines : sérologie (refaite à 3 mois si négative)","src":"p. 198"},{"id":"d162-num-17","rank":"A","label":"Condylomes : fréquence d'une IST associée","value":"25 % des cas en moyenne","src":"p. 205"},{"id":"d162-num-18","rank":"A","label":"Dépistage du col : test HPV-HR (haut risque) ou frottis","value":"test HPV-HR à partir de 30 ans ; frottis tous les 3 ans","src":"p. 202, 205"},{"id":"d162-num-19","rank":"A","label":"Vaccin HPV nonavalent : schémas","value":"11-14 ans : 2 doses ; 15-19 ans : 3 doses (0-2-6 mois) ; HSH (hommes ayant des rapports sexuels avec des hommes) jusqu'à 26 ans : 3 doses","src":"p. 204-205"},{"id":"d162-num-20","rank":"B","label":"Trichomonose : incubation et traitement minute","value":"4 à 28 jours ; métronidazole 2 g en dose unique","src":"p. 207"}],"mnemonics":[{"id":"d162-mn-01","rank":"A","title":"Caractères du chancre syphilitique","mnemonic":"PINS","expansion":"- **P**ropre : fond propre, rosé\n- **I**ndolore\n- i**N**duré : impossible à plisser entre 2 doigts (le caractère le plus évocateur)\n- **S**atellite : adénopathie non inflammatoire\n\nÀ côté : 5-15 mm, en général unique.","src":"p. 188-190"},{"id":"d162-mn-02","rank":"A","title":"Sérologie de la syphilis : qui fait quoi ?","mnemonic":"Le TT tranche, le TNT titre","expansion":"- **TT** (ELISA, TPHA) : **tranche** → affirme ou infirme une tréponématose (qualitatif)\n- **TNT** (VDRL, RPR) : **titre** → précise l'évolutivité et sert au suivi (÷ 4 à 6 mois)\n- Ordre : ELISA d'abord ; TNT seulement si le TT est positif.","src":"p. 194-195, 200"},{"id":"d162-mn-03","rank":"A","title":"Ulcération génitale : les 5 causes à comparer","mnemonic":"Sept Hérissons Chantent Devant Nicolas (S-H-C-D-N)","expansion":"- **S**yphilis : indolore, indurée, fond propre\n- **H**erpès : douloureuse, contours polycycliques\n- **C**hancre mou : fond sale, très douloureux, adénopathies inflammatoires\n- **D**onovanose : peu douloureuse, granulomateuse\n- **N**icolas-Favre (LGV) : anorectite, ulcérations anogénitales, diarrhée trompeuse","src":"p. 188, 197"},{"id":"d162-mn-04","rank":"A","title":"Sérologies à proposer systématiquement devant une IST","mnemonic":"V.T.H.","expansion":"- **V** : VIH\n- **T** : test tréponémique (syphilis)\n- **H** : hépatite B\n\nÀ proposer à chaque IST, en plus du traitement des partenaires.","src":"p. 182, 185, 208"},{"id":"d162-mn-05","rank":"A","title":"Gonocoque ou Chlamydia ?","mnemonic":"G = Gros bruit, C = Calme","expansion":"- **G**onocoque = **G**ros bruit : incubation courte (2-7 j), écoulement purulent (90 %), femme asymptomatique dans 70 %\n- **C**hlamydia = **C**alme : portage asymptomatique 50 % (hommes) et 50-90 % (femmes), écoulement clair dans moins de 50 %, incubation variable","src":"p. 180, 184, 186"},{"id":"d162-mn-06","rank":"A","title":"Vaccin anti-HPV : combien de doses ?","mnemonic":"2 pour les jeunes, 3 pour les grands","expansion":"- **11-14 ans** (filles et garçons) : **2 doses** (espacées de 6 à 13 mois)\n- **15-19 ans** (rattrapage) : **3 doses** (0, 2, 6 mois)\n- **HSH jusqu'à 26 ans** : **3 doses** (0, 2, 6 mois)\n\nVaccin nonavalent (9 types d'HPV).","src":"p. 204-205"}]},"questions":[{"id":"d162-qroc-001","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["étiologie"],"difficulty":1,"question":"Quels sont les deux principaux germes responsables d'urétrite (et, chez la femme, de cervicite) ?","answer":"Chlamydia trachomatis et le gonocoque (Neisseria gonorrhoeae)","accept":["chlamydia et gonocoque","gonocoque et chlamydia","chlamydia trachomatis et gonocoque","gonocoque et chlamydia trachomatis","neisseria gonorrhoeae et chlamydia trachomatis"],"keywords":["chlamydia","gonoc"],"explanation":"Chlamydia trachomatis et le gonocoque dominent les urétrites. Leurs équivalents féminins (cervicites, cervicovaginites) ont la même épidémiologie et la même prise en charge.","src":"p. 187","deep":"**Pourquoi** : ces deux bactéries, seules ou associées, donnent des urétrites chez l'homme et des cervicovaginites chez la femme ; les formes féminines partagent leur épidémiologie et leur prise en charge (p. 179, 187).\n**Piège** : la co-infection existe (urétrite mixte dans 15 % des cas) : c'est pourquoi un traitement anti-Chlamydia est systématiquement associé à celui du gonocoque (p. 182).\n**À relier** : en dépistage, une seule PCR « biplex » recherche les deux germes (p. 181)."},{"id":"d162-qroc-002","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["étiologie","définition"],"difficulty":1,"question":"Quel est l'aspect du gonocoque (Neisseria gonorrhoeae) à la coloration de Gram ?","answer":"Diplocoque à Gram négatif (encapsulé), intra- ou extracellulaire","accept":["diplocoque à gram négatif","diplocoque gram négatif","diplocoque gram -","diplocoques à gram négatif","diplocoques gram négatif"],"keywords":["diplocoque","gram"],"explanation":"Le gonocoque est un diplocoque encapsulé à Gram négatif, que l'on voit à l'intérieur ou à l'extérieur des cellules.","src":"p. 179","deep":"**Pourquoi** : le gonocoque est un diplocoque encapsulé à Gram négatif, que l'on trouve dans ou hors des cellules (p. 179).\n**Piège** : ne pas le confondre avec C. trachomatis, qui est un bacille à Gram négatif, intracellulaire obligatoire et immobile (p. 183).\n**À relier** : sites principaux du gonocoque : urètre chez l'homme, col et vagin chez la femme ; le portage pharyngé est fréquent et le plus souvent asymptomatique (p. 180)."},{"id":"d162-qroc-003","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation, courte, d'une gonococcie ?","answer":"2 à 7 jours","accept":["2 à 7 jours","2-7 jours","entre 2 et 7 jours","2 à 7 j"],"keywords":["2","7"],"explanation":"L'incubation de la gonococcie est courte (2 à 7 jours) et le malade est contagieux. Celle de la chlamydiose est plus longue et variable (de quelques jours à quelques mois).","src":"p. 180, 184","deep":"**Pourquoi** : l'incubation courte (2 à 7 jours) s'accompagne d'une contagiosité du malade ; chez l'homme, le tableau est le plus souvent bruyant (p. 180).\n**Piège** : pour C. trachomatis, l'incubation est variable, de quelques jours à quelques mois (p. 184) : un rapport ancien n'écarte pas une IST.\n**À relier** : l'écoulement est purulent dans 90 % des gonococcies, clair dans 40-50 % des chlamydioses (tableau 9.1, p. 186)."},{"id":"d162-qroc-004","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quel signe est présent dans environ 90 % des urétrites gonococciques de l'homme ?","answer":"Un écoulement urétral purulent","accept":["écoulement purulent","écoulement urétral purulent","ecoulement uretral purulent","urétrite purulente"],"keywords":["purulent"],"explanation":"L'urétrite antérieure aiguë est la manifestation la plus fréquente : écoulement purulent (90 %), dysurie, brûlures urétrales. Dans la chlamydiose, l'écoulement est au contraire clair, modéré et inconstant.","src":"p. 180, 184","deep":"**Pourquoi** : l'urétrite antérieure aiguë est la forme la plus fréquente chez l'homme : écoulement purulent (90 %), dysurie, brûlures, prurit urétral, méatite voire balanite (p. 180).\n**Piège** : le tableau est le plus souvent bruyant mais peut être asymptomatique ; l'anorectite gonococcique est même muette dans 2/3 des cas (p. 180).\n**À relier** : dans la chlamydiose, l'écoulement manque dans plus de la moitié des cas et il est le plus souvent clair, modéré et intermittent (p. 184)."},{"id":"d162-qroc-005","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique","pièges"],"difficulty":1,"question":"Quelle proportion des infections gonococciques non compliquées de la femme est asymptomatique ?","answer":"70 %","accept":["70 %","70%","70 pour cent","environ 70 %"],"keywords":["70"],"explanation":"L'infection gonococcique de la femme est asymptomatique dans 70 % des cas. Quand elle s'exprime, c'est surtout par une cervicite avec leucorrhées purulentes.","src":"p. 180","deep":"**Pourquoi** : chez la femme, l'infection gonococcique non compliquée est asymptomatique 7 fois sur 10 ; quand elle s'exprime, c'est surtout par une cervicite (p. 180).\n**Piège** : chez l'homme, c'est l'inverse à l'urètre : le portage asymptomatique y est exceptionnel (p. 180).\n**À relier** : la cervicite à C. trachomatis est asymptomatique dans 50 à 90 % des cas (p. 184) ; chez la femme, la PCR se fait sur auto-écouvillonnage vaginal (p. 181)."},{"id":"d162-qroc-006","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"À l'examen au spéculum d'une cervicite gonococcique, quel est l'aspect du col ?","answer":"Col non ou peu inflammatoire, avec un écoulement purulent à l'orifice cervical","accept":["col peu inflammatoire","col non inflammatoire","col non ou peu inflammatoire","peu inflammatoire"],"keywords":["inflammatoire","purulent"],"explanation":"La cervicite gonococcique associe leucorrhées purulentes, pesanteur pelvienne et parfois signes d'urétrite, avec un col peu inflammatoire mais un écoulement purulent à l'orifice cervical.","src":"p. 180-181","deep":"**Pourquoi** : la cervicite gonococcique associe leucorrhées purulentes et pesanteur pelvienne ; le col reste non ou peu inflammatoire alors que du pus sort de l'orifice cervical (p. 181).\n**Piège** : dans la chlamydiose, l'examen montre au contraire un col fragile, des sécrétions mucopurulentes et/ou un ectropion friable et hémorragique (p. 184).\n**À relier** : l'anorectite gonococcique est plus rare chez la femme que chez l'homme ; l'oropharyngite a les mêmes caractères dans les deux sexes (p. 181)."},{"id":"d162-qroc-007","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"Dans un contexte de dépistage du gonocoque, quelle technique est préconisée, le plus souvent couplée à la recherche de C. trachomatis ?","answer":"La PCR (amplification génique), souvent biplex avec C. trachomatis","accept":["pcr","pcr biplex","amplification génique","amplification genique"],"keywords":["pcr"],"explanation":"En dépistage, la PCR (amplification génique) est préconisée, le plus souvent biplex (gonocoque + C. trachomatis), sur 1er jet urinaire chez l'homme, auto-écouvillonnage vaginal chez la femme, et prélèvements pharyngé et/ou anal selon les pratiques (p. 181).","src":"p. 181-182","deep":"**Pourquoi** : les techniques d'amplification génique ont rendu le dépistage de C. trachomatis et du gonocoque plus rapide et plus sensible (p. 187).\n**Piège** : chez un homme symptomatique, on prélève d'abord l'écoulement urétral spontané ; sans écoulement, au mieux un 1er jet d'urine, sinon un prélèvement endo-urétral (p. 181).\n**À relier** : pour C. trachomatis, la PCR est plus sensible que la culture et la sérologie n'a aucun intérêt (p. 185)."},{"id":"d162-qroc-008","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":1,"question":"Chez l'homme, sur quel prélèvement réalise-t-on la PCR gonocoque / C. trachomatis ?","answer":"1er jet urinaire (10 à 20 mL), au moins 2 h après la dernière miction","accept":["1er jet urinaire","premier jet urinaire","1er jet d'urine","premier jet d'urine","jet urinaire"],"keywords":["jet"],"explanation":"Chez l'homme, la PCR se fait sur un 1er jet urinaire de 10 à 20 mL, au moins 2 heures après la dernière miction. En cas d'écoulement urétral spontané, on peut aussi le prélever.","src":"p. 181, 185","deep":"**Pourquoi** : chez l'homme, symptomatique ou non, la PCR se fait sur 10 à 20 mL de 1er jet urinaire, recueillis au moins 2 heures après la dernière miction (p. 181, 185).\n**Piège** : un milieu de jet ou une miction toute récente ne correspondent pas au prélèvement décrit : ce sont bien le 1er jet et le délai de 2 heures qui sont exigés.\n**À relier** : chez la femme, auto-écouvillonnage vaginal ; dans les deux sexes, prélèvement pharyngé et/ou anal selon les pratiques sexuelles (p. 181)."},{"id":"d162-qroc-009","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":1,"question":"Chez la femme, quel prélèvement est recommandé pour la PCR gonocoque / C. trachomatis ?","answer":"Un auto-écouvillonnage vaginal","accept":["auto-écouvillonnage vaginal","autoprélèvement vaginal","auto prélèvement vaginal","écouvillonnage vaginal","prélèvement vaginal"],"keywords":["vaginal"],"explanation":"Chez la femme, on privilégie l'auto-écouvillonnage vaginal, y compris chez la femme symptomatique (plutôt que l'écouvillonnage de l'endocol par un professionnel). Selon les pratiques sexuelles, on ajoute des prélèvements pharyngé et/ou anal.","src":"p. 181, 185","deep":"**Pourquoi** : chez la femme symptomatique, l'auto-écouvillonnage vaginal est à préférer à l'écouvillonnage de l'endocol par un professionnel ; chez la femme asymptomatique, on fait un écouvillonnage vulvovaginal en autoprélèvement (p. 185).\n**Piège** : un prélèvement génital seul peut manquer un portage : selon les pratiques sexuelles, on ajoute des prélèvements pharyngé et/ou anal (p. 181).\n**À relier** : chez l'homme, c'est le 1er jet urinaire, au moins 2 heures après la dernière miction (p. 181)."},{"id":"d162-qroc-010","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":1,"question":"Quel traitement doit être systématiquement associé à celui d'une gonococcie, car l'urétrite est mixte dans 15 % des cas ?","answer":"Un traitement anti-Chlamydia","accept":["anti-chlamydia","anti chlamydia","traitement anti-chlamydia","traitement de la chlamydiose","traitement chlamydia"],"keywords":["chlamydia"],"explanation":"Un traitement anti-Chlamydia est systématique devant une gonococcie (urétrite mixte dans 15 % des cas). Le traitement minute, en dose unique délivré sur place, est recommandé.","src":"p. 182","deep":"**Pourquoi** : l'urétrite est mixte (gonocoque + C. trachomatis) dans 15 % des cas, d'où l'association systématique d'un traitement anti-Chlamydia (p. 182).\n**Piège** : le traitement est délivré sur place, en dose unique (traitement minute), lors de la consultation ; et il est identique en cas d'infection par le VIH (p. 182).\n**À relier** : pour le volet anti-Chlamydia, on privilégie la doxycycline 7 jours associée à une injection de ceftriaxone, plutôt que l'azithromycine en prise unique (p. 187)."},{"id":"d162-qroc-011","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["traitement"],"difficulty":1,"question":"Quel antibiotique, en injection IM unique de 1000 mg, est le traitement de première intention d'une gonococcie non compliquée ?","answer":"La ceftriaxone (1000 mg en IM unique)","accept":["ceftriaxone","ceftriaxone 1000 mg","ceftriaxone 1 g"],"keywords":["ceftriaxone"],"explanation":"Première intention : ceftriaxone 1000 mg IM unique (IV si anomalie de l'hémostase). En cas d'allergie aux bêta-lactamines : azithromycine 2 g, gentamicine 240 mg IM ou ciprofloxacine 500 mg (avec antibiogramme), en dose unique.","src":"p. 182","deep":"**Pourquoi** : en première intention, ceftriaxone 1000 mg en IM unique, ou en IV si anomalie de l'hémostase (p. 182).\n**Piège** : en cas d'allergie aux β-lactamines : azithromycine 2 g PO, gentamycine 240 mg IM ou ciprofloxacine 500 mg PO, toutes en dose unique ; la ciprofloxacine seulement avec antibiogramme (p. 182) ; 40 % des souches sont résistantes à la ciprofloxacine (p. 180).\n**À relier** : on y ajoute toujours un anti-Chlamydia : doxycycline 7 jours, à privilégier par rapport à l'azithromycine 1 g (p. 182)."},{"id":"d162-qroc-012","type":"QROC","rank":"A","objective":"d162-obj-03","tags":["prévention","traitement"],"difficulty":1,"question":"Pendant combien de temps les rapports sexuels doivent-ils être évités ou protégés après le traitement d'une gonococcie ?","answer":"Au moins 7 jours","accept":["au moins 7 jours","7 jours","1 semaine","une semaine"],"keywords":["7 jours"],"explanation":"Les rapports doivent être évités ou protégés pendant au moins 7 jours, et le (la, les) partenaire(s) doivent être traités.","src":"p. 182","deep":"**Pourquoi** : après le traitement d'une gonococcie, les rapports sont évités ou protégés au moins 7 jours, et le ou les partenaires sont traités systématiquement (p. 182).\n**Piège** : dans la chlamydiose, la consigne porte sur toute la période du traitement : pas de rapports non protégés pendant celle-ci (p. 185).\n**À relier** : comme pour toute IST, on insiste sur le risque de recontamination et on envisage une PrEP en cas de prises de risque trop régulières (p. 182)."},{"id":"d162-qroc-013","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["traitement","prévention"],"difficulty":1,"question":"Dans la gonococcie, que doit-on faire systématiquement pour le (la, les) partenaire(s) ?","answer":"Les traiter (après les avoir identifiés et leur avoir proposé un dépistage)","accept":["les traiter","traiter les partenaires","traitement du partenaire","traitement des partenaires","traiter le partenaire"],"keywords":["trait"],"explanation":"Le traitement des partenaires est systématique. Comme pour toute IST, on identifie les partenaires contaminés ou contaminateurs et on leur propose dépistage, diagnostic et/ou traitement probabiliste.","src":"p. 182","deep":"**Pourquoi** : dans la gonococcie, le traitement du ou des partenaires est systématique (p. 182).\n**Piège** : on recherche à la fois les partenaires contaminés ET le partenaire contaminateur, et on leur propose dépistage, diagnostic et/ou traitement probabiliste (p. 182).\n**À relier** : même logique dans la syphilis : contact de moins de 6 semaines avec un sujet source certain → traitement systématique et sérologie (p. 198)."},{"id":"d162-qroc-014","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique","prévention"],"difficulty":1,"question":"Devant une IST, quels trois dépistages associés doit-on proposer systématiquement au patient ?","answer":"Sérologie VIH, test tréponémique (syphilis) et sérologie de l'hépatite B","accept":["vih, test tréponémique et hépatite b","vih tt hépatite b","vih, syphilis, hépatite b","vih syphilis hepatite b"],"keywords":["vih","hépatite b","trépon"],"explanation":"Devant toute IST (gonococcie, chlamydiose, trichomonose…), on propose une sérologie VIH, un test tréponémique et une sérologie de l'hépatite B, en plus des prélèvements du site atteint.","src":"p. 182, 185, 208","deep":"**Pourquoi** : devant toute IST, on propose systématiquement une sérologie VIH, un test tréponémique et une sérologie de l'hépatite B (p. 182).\n**Piège** : devant des condylomes ou une trichomonose, on y ajoute la PCR Chlamydia/gonocoque (urines ou autoprélèvement vaginal) ; une autre IST accompagne les condylomes dans 25 % des cas (p. 205, 208).\n**À relier** : contracter une syphilis témoigne d'une sexualité à haut risque : on vérifie VIH, hépatite B et autres IST (p. 200)."},{"id":"d162-qroc-015","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":1,"question":"Quelle prophylaxie contre le VIH peut-on envisager chez un patient atteint d'IST qui prend des risques trop réguliers ?","answer":"La PrEP (prophylaxie pré-exposition)","accept":["prep","prophylaxie pré-exposition","prophylaxie pre exposition","prophylaxie préexposition"],"keywords":["prep"],"explanation":"Un traitement de type PrEP peut être envisagé en cas de prises de risque trop régulières. Il s'ajoute à l'éducation sur les IST et au rappel des risques de recontamination.","src":"p. 182, 185","deep":"**Pourquoi** : la PrEP contre le VIH est à envisager quand les prises de risque sont trop régulières (p. 182, 185).\n**Piège** : elle complète, sans les remplacer, les mesures communes à toute IST : identifier les partenaires, proposer sérologies VIH, syphilis et hépatite B, insister sur le risque de recontamination, éduquer (p. 182, 185).\n**À relier** : une prévention vaccinale existe pour les HPV : filles et garçons entre 11 et 14 ans, rattrapage de 15 à 19 ans révolus (p. 204)."},{"id":"d162-qroc-016","type":"QROC","rank":"A","objective":"d162-obj-35","tags":["clinique","pièges"],"difficulty":2,"question":"Quel caractère de l'infection à C. trachomatis (50 % des cas chez l'homme, 50 à 90 % chez la femme) entretient la chaîne épidémiologique et favorise les complications tardives ?","answer":"Le portage asymptomatique","accept":["portage asymptomatique","asymptomatique","forme asymptomatique","infection asymptomatique"],"keywords":["asymptomatique"],"explanation":"Le portage asymptomatique est très fréquent : il maintient la chaîne de transmission et laisse évoluer silencieusement les complications tardives. La cervicite est la forme la plus fréquente chez la femme, le plus souvent asymptomatique.","src":"p. 184","deep":"**Pourquoi** : le portage asymptomatique (50 % des hommes, 50 à 90 % des femmes) maintient la chaîne épidémiologique et laisse survenir les complications tardives (p. 184).\n**Piège** : chez le gonocoque, le portage urétral asymptomatique de l'homme est exceptionnel, mais le portage pharyngé est fréquent (p. 180).\n**À relier** : chez la femme, la cervicite est la forme la plus fréquente et le plus souvent asymptomatique ; la PCR est l'examen clé (p. 184-185)."},{"id":"d162-qroc-017","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quel est l'aspect habituel de l'écoulement urétral (présent dans moins de 50 % des cas) au cours d'une urétrite à C. trachomatis ?","answer":"Clair, modéré et intermittent","accept":["clair","écoulement clair","clair modéré et intermittent","clair, modéré, intermittent"],"keywords":["clair"],"explanation":"L'écoulement de la chlamydiose est présent dans moins de 50 % des cas et le plus souvent clair, modéré et intermittent. Il contraste avec l'écoulement purulent de la gonococcie.","src":"p. 184, 186","deep":"**Pourquoi** : dans l'urétrite à C. trachomatis, l'écoulement est présent dans moins de 50 % des cas, le plus souvent clair, modéré et intermittent (p. 184).\n**Piège** : un écoulement discret n'écarte pas une IST : le tableau chlamydien est souvent moins bruyant que celui du gonocoque (p. 184).\n**À relier** : l'incubation de la chlamydiose est variable (quelques jours à quelques mois), contre 2 à 7 jours pour le gonocoque (p. 180, 184)."},{"id":"d162-qroc-018","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique","pièges"],"difficulty":2,"question":"Quel est l'intérêt de la sérologie dans le diagnostic d'une infection à Chlamydia trachomatis ?","answer":"Aucun","accept":["aucun","aucun intérêt","pas d'intérêt","pas d interet","inutile"],"keywords":["aucun"],"explanation":"La sérologie n'a pas d'intérêt pour le diagnostic de C. trachomatis : l'examen clé est la PCR, plus sensible que la culture.","src":"p. 185","deep":"**Pourquoi** : pour C. trachomatis, la sérologie n'a pas d'intérêt ; l'examen clé est la PCR, plus sensible que la culture (p. 185).\n**Piège** : à l'inverse, dans la syphilis, le tréponème ne se cultive pas et le diagnostic repose surtout sur la sérologie (test tréponémique + non tréponémique) (p. 194).\n**À relier** : prélèvements pour la PCR : 1er jet urinaire chez l'homme, auto-écouvillonnage vaginal chez la femme (p. 185)."},{"id":"d162-qroc-019","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement","pièges"],"difficulty":2,"question":"Pourquoi le traitement minute de C. trachomatis par azithromycine en dose unique est-il remis en question ?","answer":"Émergence de résistances de Mycoplasma genitalium à l'azithromycine","accept":["résistance de mycoplasma genitalium","resistances de mycoplasma genitalium","résistances de mycoplasma genitalium à l'azithromycine","mycoplasma genitalium résistant à l'azithromycine"],"keywords":["mycoplasma","résistance"],"explanation":"L'azithromycine en dose unique favorise l'émergence de résistances chez d'autres micro-organismes, notamment Mycoplasma genitalium. D'où la préférence donnée à la doxycycline sur 7 jours.","src":"p. 185, 187","deep":"**Pourquoi** : l'azithromycine favorise l'émergence de résistances chez d'autres micro-organismes, comme Mycoplasma genitalium, ce qui remet en question la prise unique (p. 185, 187).\n**Piège** : son avantage reste réel : la dose unique permet de traiter immédiatement le patient sans crainte de mauvaise observance (p. 185).\n**À relier** : il est préférable de privilégier la doxycycline 7 jours associée à une injection de ceftriaxone (p. 187)."},{"id":"d162-qroc-020","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"question":"Plutôt que le traitement minute par azithromycine, quelle association d'antibiotiques privilégier devant une urétrite en traitement probabiliste ?","answer":"Doxycycline pendant 7 jours + ceftriaxone en 1 injection","accept":["doxycycline et ceftriaxone","doxycycline + ceftriaxone","ceftriaxone et doxycycline","ceftriaxone + doxycycline","doxycycline 7 jours ceftriaxone"],"keywords":["doxycycline","ceftriaxone"],"explanation":"Il est préférable de donner la doxycycline pendant 7 jours (anti-Chlamydia) associée à une injection de ceftriaxone (anti-gonocoque).","src":"p. 187","deep":"**Pourquoi** : gonocoque et C. trachomatis sont les deux principaux germes d'urétrite (p. 187) et l'urétrite est mixte dans 15 % des cas : on couvre donc les deux (p. 182).\n**Piège** : l'azithromycine en prise unique garde l'avantage de l'observance, mais elle est remise en question par les résistances de Mycoplasma genitalium (p. 185, 187).\n**À relier** : le traitement probabiliste immédiat du patient et de ses contacts sexuels garde son intérêt épidémiologique et économique (p. 187)."},{"id":"d162-qroc-021","type":"QROC","rank":"B","objective":"d162-obj-35","tags":["complications","épidémiologie"],"difficulty":2,"question":"De quelle complication tubaire C. trachomatis est-il responsable dans 70 % des cas ?","answer":"La stérilité tubaire","accept":["stérilité tubaire","sterilite tubaire","stérilités tubaires","infertilité tubaire"],"keywords":["stérilité"],"explanation":"C. trachomatis est responsable de 50 % des salpingites de la femme jeune et de 70 % des stérilités tubaires, avec aussi un risque d'algies pelviennes inflammatoires et de grossesse extra-utérine.","src":"p. 183","deep":"**Pourquoi** : C. trachomatis est responsable de 50 % des salpingites de la femme jeune et de 70 % des stérilités tubaires (p. 183).\n**Piège** : le gonocoque peut aussi donner stérilité tubaire et grossesse extra-utérine, mais moins souvent que Chlamydia (p. 181).\n**À relier** : portage asymptomatique et complications hautes font de C. trachomatis un enjeu de santé publique chez les plus jeunes (p. 187) ; le dépistage systématique par autoprélèvement vise les femmes de moins de 25 ans (p. 183)."},{"id":"d162-qroc-022","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","prévention"],"difficulty":1,"question":"Quelle population féminine bénéficie en France d'un dépistage systématique de C. trachomatis par autoprélèvement vaginal ?","answer":"Les femmes de moins de 25 ans","accept":["moins de 25 ans","femmes de moins de 25 ans","15 à 25 ans","15-25 ans"],"keywords":["25 ans"],"explanation":"Le dépistage systématique par autoprélèvement vaginal vise les femmes de moins de 25 ans. Au-delà, il est opportuniste et ciblé sur les facteurs de risque, comme chez les hommes sexuellement actifs à risque.","src":"p. 183, 187","deep":"**Pourquoi** : le dépistage systématique par autoprélèvement vaginal vise les femmes de moins de 25 ans (p. 183) ; le portage silencieux et les complications hautes font de C. trachomatis un enjeu chez les plus jeunes (p. 187).\n**Piège** : au-delà, le dépistage est opportuniste ciblé : hommes à facteurs de risque quel que soit l'âge, femmes de plus de 25 ans à risque, femmes enceintes consultant pour une IVG sans limite d'âge (p. 183).\n**À relier** : le pic d'incidence se situe entre 15 et 34 ans chez la femme (p. 183)."},{"id":"d162-qroc-023","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications","clinique"],"difficulty":2,"question":"Quelle complication systémique de la gonococcie associe fièvre, atteinte cutanée acrale (purpura pétéchial, papulo-pustules) et mono- ou oligo-arthrites septiques ?","answer":"La septicémie gonococcique","accept":["septicémie gonococcique","septicemie gonococcique","septicémie à gonocoque"],"keywords":["septicémie"],"explanation":"La septicémie gonococcique est une complication systémique : elle impose l'hospitalisation et un traitement IV par ceftriaxone 1 g/jour pendant 7 à 10 jours. Plus rarement : péri-hépatite, endocardite ou méningite.","src":"p. 181-182","deep":"**Pourquoi** : la septicémie gonococcique associe fièvre, atteinte cutanée (purpura pétéchial, papules ou papulo-pustules acrales ou périarticulaires) et/ou mono- ou oligo-arthrites septiques, ténosynovites (p. 181).\n**Piège** : C. trachomatis donne une arthrite réactionnelle (syndrome oculo-urétro-synovial), alors que le gonocoque donne des arthrites septiques (tableau 9.1, p. 186).\n**À relier** : traitement : hospitalisation + ceftriaxone 1 g/jour IV pendant 7 à 10 jours (p. 182)."},{"id":"d162-qroc-024","type":"QROC","rank":"A","objective":"d162-obj-20","tags":["traitement","pièges"],"difficulty":1,"question":"Pourquoi les schémas thérapeutiques des infections à gonocoque doivent-ils être régulièrement réactualisés ?","answer":"Émergence de souches résistantes aux antibiotiques","accept":["résistance aux antibiotiques","souches résistantes","résistances aux antibiotiques","émergence de résistances"],"keywords":["résistan"],"explanation":"Parce que des souches de gonocoque résistantes aux antibiotiques émergent : les schémas de traitement doivent donc être remis à jour régulièrement (p. 187).","src":"p. 180, 182, 187","deep":"**Piège** : la prise unique d'azithromycine contre C. trachomatis est aussi remise en question, mais pour une autre raison : les résistances de Mycoplasma genitalium (p. 187).\n**À relier** : à l'oropharynx, les antibiotiques diffusent mal, ce qui explique un portage persistant après traitement (p. 180) ; le traitement probabiliste immédiat du patient et de ses contacts garde, lui, son intérêt épidémiologique et économique (p. 187)."},{"id":"d162-qru-101","type":"QRU","rank":"A","objective":"d162-obj-07","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Un homme de 28 ans consulte pour une ulcération de 8 mm du sillon balano-préputial, apparue 3 semaines après un rapport non protégé. Elle est à fond propre et rosé, indolore, indurée, avec une adénopathie satellite unilatérale non inflammatoire. Quel est le diagnostic le plus probable ?","options":[{"t":"Maladie de Nicolas-Favre","ok":false,"why":"Elle évoque plutôt une anorectite, des ulcérations anogénitales et des diarrhées trompeuses."},{"t":"Herpès génital","ok":false,"why":"L'herpès donne des ulcérations superficielles douloureuses à contours polycycliques."},{"t":"Donovanose","ok":false,"why":"Elle donne des lésions granulomateuses peu douloureuses, sur un terrain particulier (sujets africains)."},{"t":"Chancre mou","ok":false,"why":"Il est douloureux, à fond sale, avec des adénopathies inflammatoires."},{"t":"Chancre syphilitique","ok":true,"why":"Ulcération indurée, indolore, à fond propre, avec adénopathie satellite non inflammatoire, après environ 3 semaines d'incubation : syphilis primaire."}],"explanation":"L'induration est le seul caractère vraiment évocateur du chancre syphilitique, et l'absence de douleur le distingue de l'herpès. Toute ulcération muqueuse aiguë doit de toute façon faire évoquer la syphilis.","src":"p. 188-190, 197","deep":"**Pourquoi** : l'induration est le seul caractère sémiologique vraiment évocateur ; l'indolence distingue le chancre de l'herpès ; le sillon balano-préputial est son siège électif chez l'homme et l'incubation moyenne est de 3 semaines (p. 188-189).\n**Piège** : aucune de ces caractéristiques n'est pathognomonique : on évoque systématiquement la syphilis devant toute ulcération muqueuse aiguë (p. 189).\n**À relier** : devant une ulcération génitale, on traite sans attendre le TT et le TNT : benzathine-benzylpénicilline 2,4 MU en IM unique (p. 197-198)."},{"id":"d162-qru-102","type":"QRU","rank":"A","objective":"d162-obj-18","tags":["traitement","pièges"],"difficulty":2,"stem":"Une femme de 31 ans consulte pour une ulcération vulvaire indolore et indurée, apparue il y a 4 jours après un rapport non protégé. L'ELISA et le VDRL sont tous deux négatifs. Quelle est la meilleure attitude ?","options":[{"t":"Conclure à une fausse sérologie syphilitique","ok":false,"why":"Une fausse sérologie correspond à un TNT positif isolé, pas à deux tests négatifs."},{"t":"Traiter d'emblée, sans attendre la sérologie","ok":true,"why":"Devant une ulcération génitale, on ne doit pas attendre les résultats ; TT et TNT peuvent être négatifs pendant les 7 premiers jours du chancre."},{"t":"Attendre une deuxième sérologie avant tout traitement","ok":false,"why":"L'OMS recommande de ne pas attendre les résultats des tests pour traiter une ulcération génitale."},{"t":"Prescrire de la doxycycline pendant 14 jours","ok":false,"why":"La doxycycline est réservée aux patients allergiques à la pénicilline."},{"t":"Éliminer la syphilis puisque la sérologie est négative","ok":false,"why":"Dans les 7 premiers jours du chancre, les deux tests peuvent encore être négatifs."}],"explanation":"Le traitement de la syphilis précoce repose sur une injection IM unique de benzathine-benzylpénicilline 2,4 MU. La sérologie reste utile, mais elle ne doit pas retarder le traitement.","trap":"Une sérologie négative ne dispense pas de traiter un chancre récent.","src":"p. 194-198","deep":"**Pourquoi** : le TT se positive entre le 7e et le 10e jour du chancre et le TNT 10 à 15 jours après son apparition (p. 194) : au 4e jour, les deux peuvent être négatifs (p. 196).\n**Piège** : un profil TT négatif / TNT négatif correspond aussi bien à l'absence de tréponématose qu'à une tréponématose très récente (tableau 9.2, p. 195) : c'est la clinique qui tranche.\n**À relier** : on prescrit tout de même un TT et on recherche une autre IST (gonocoque, C. trachomatis, VIH, hépatite B) (p. 197)."},{"id":"d162-qru-103","type":"QRU","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"stem":"Un homme de 24 ans a un écoulement urétral purulent avec brûlures mictionnelles depuis 3 jours, après un rapport non protégé. Quel traitement probabiliste doit-on privilégier ?","options":[{"t":"Ceftriaxone en 1 injection + doxycycline pendant 7 jours","ok":true,"why":"Anti-gonocoque (ceftriaxone) et anti-Chlamydia associés systématiquement (urétrite mixte dans 15 % des cas) ; la doxycycline 7 jours est préférée à l'azithromycine en dose unique."},{"t":"Ceftriaxone en injection IM unique, sans autre antibiotique","ok":false,"why":"Il faut aussi traiter C. trachomatis, car l'urétrite est mixte dans 15 % des cas."},{"t":"Doxycycline pendant 7 jours, sans autre antibiotique","ok":false,"why":"Elle ne traite pas le gonocoque : la ceftriaxone est nécessaire."},{"t":"Azithromycine 1 g en prise orale unique, sans autre antibiotique","ok":false,"why":"C'est le traitement minute anti-Chlamydia, remis en question par les résistances de Mycoplasma genitalium ; et le gonocoque doit aussi être traité : on privilégie ceftriaxone + doxycycline 7 jours (p. 187)."},{"t":"Attendre les résultats de la PCR avant tout traitement","ok":false,"why":"Un traitement probabiliste immédiat, délivré sur place, est recommandé."}],"explanation":"Devant une urétrite aiguë, on traite d'emblée le gonocoque et C. trachomatis, on traite le(s) partenaire(s) et on propose sérologie VIH, test tréponémique et sérologie de l'hépatite B.","src":"p. 182, 187","deep":"**Pourquoi** : gonocoque et C. trachomatis sont les deux principaux germes d'urétrite ; on privilégie la doxycycline 7 jours associée à une injection de ceftriaxone (p. 187).\n**Piège** : l'azithromycine en prise unique a l'avantage de l'observance, mais elle favorise les résistances de Mycoplasma genitalium (p. 185, 187).\n**À relier** : traitement du ou des partenaires, rapports évités ou protégés au moins 7 jours, sérologies VIH, syphilis et hépatite B (p. 182)."},{"id":"d162-qru-104","type":"QRU","rank":"A","objective":"d162-obj-27","tags":["biologie","pièges"],"difficulty":2,"stem":"Une patiente de 34 ans, atteinte d'un lupus érythémateux systémique, est asymptomatique. Un bilan systématique montre un VDRL positif et un test tréponémique (ELISA) négatif. Quelle est l'interprétation la plus probable ?","options":[{"t":"Syphilis secondaire","ok":false,"why":"Au stade secondaire, le TT et le TNT sont toujours positifs."},{"t":"Syphilis très ancienne non traitée","ok":false,"why":"Elle donne un TT positif."},{"t":"Cicatrice sérologique d'une syphilis traitée","ok":false,"why":"Une cicatrice sérologique donne un TT positif et un TNT négatif, l'inverse du profil observé."},{"t":"Fausse sérologie syphilitique liée au lupus","ok":true,"why":"Un TNT positif isolé est en général une fausse sérologie (lupus, syndrome des anticorps anti-phospholipides, grossesse)."},{"t":"Tréponématose endémique non vénérienne","ok":false,"why":"Ces infections positivent le test tréponémique, ce qui n'est pas le cas ici."}],"explanation":"On interprète d'abord le TT : négatif, il signifie l'absence de tréponématose ou une tréponématose guérie. Un TNT positif isolé évoque une fausse sérologie ; le TNT ne se positive avant le TT que dans 10 % des cas.","src":"p. 194-196","deep":"**Pourquoi** : on lit d'abord le TT : négatif, il signifie l'absence de tréponématose ou sa guérison ; un TNT positif isolé est alors en général une fausse sérologie (SAPL, lupus, grossesse) (p. 196).\n**Piège** : dans 10 % des syphilis primaires, le TNT se positive avant le TT (p. 195-196) : devant une ulcération récente, ce même profil ne se lit pas comme un faux positif.\n**À relier** : à l'inverse, les positivités non tréponémiques du TPHA sont exceptionnelles (lupus systémique, maladie de Lyme) (p. 195)."},{"id":"d162-qru-105","type":"QRU","rank":"B","objective":"d162-obj-36","tags":["clinique","pièges"],"difficulty":2,"stem":"Une fillette de 4 ans est examinée pour des condylomes anogénitaux. Quelle affirmation est exacte ?","options":[{"t":"Une biopsie systématique est indiquée","ok":false,"why":"La biopsie est réservée aux doutes diagnostiques et aux suspicions de néoplasie."},{"t":"Ils sont le plus souvent d'origine manuportée","ok":true,"why":"La contamination vient souvent de verrues vulgaires ou de linges domestiques ; une transmission mère-enfant est possible."},{"t":"Ils prouvent l'existence de sévices sexuels, qu'il faut signaler","ok":false,"why":"Ils sont un mauvais marqueur de sévices sexuels, même s'il faut rester vigilant."},{"t":"Le traitement de référence est la podophyllotoxine","ok":false,"why":"La podophyllotoxine est contre-indiquée chez la femme enceinte et chez l'enfant."},{"t":"Ils sont toujours d'origine sexuelle chez l'enfant","ok":false,"why":"Chez l'enfant, la contamination est le plus souvent manuportée ; une transmission mère-enfant est aussi possible."}],"explanation":"Chez l'enfant, les condylomes sont le plus souvent d'origine manuportée (verrues vulgaires, linges). Leur présence est un mauvais marqueur de sévices sexuels.","src":"p. 201, 203, 205","deep":"**Pourquoi** : chez l'enfant, les condylomes viennent le plus souvent d'une contamination manuportée (verrues vulgaires, linges domestiques) ; une transmission mère-enfant est aussi possible (p. 203).\n**Piège** : ils sont un mauvais marqueur de sévices sexuels, sans dispenser de rester vigilant (p. 203) ; et la podophyllotoxine est contre-indiquée chez l'enfant (p. 205).\n**À relier** : une mère porteuse de condylomes expose l'enfant, lors de l'accouchement, au risque de papillomatose laryngée juvénile (p. 201)."},{"id":"d162-qru-106","type":"QRU","rank":"A","objective":"d162-obj-27","tags":["biologie"],"difficulty":2,"stem":"Un patient de 45 ans, traité il y a 8 ans pour une syphilis, est asymptomatique. Son ELISA est positif et son VDRL négatif. Quelle est l'interprétation la plus probable ?","options":[{"t":"Fausse sérologie syphilitique","ok":false,"why":"Elle correspond à un TNT positif isolé, avec un TT négatif."},{"t":"Absence de toute tréponématose","ok":false,"why":"Il faudrait un TT négatif pour l'affirmer."},{"t":"Syphilis secondaire en phase évolutive","ok":false,"why":"Au stade secondaire, le TT et le TNT sont toujours positifs, avec un titre élevé."},{"t":"Cicatrice sérologique","ok":true,"why":"Un TT positif avec un TNT négatif traduit une tréponématose guérie (cicatrice sérologique)."},{"t":"Recontamination syphilitique récente","ok":false,"why":"Elle se reconnaît à une remontée significative du TNT quantitatif (titre multiplié par 4 au moins)."}],"explanation":"Un TT positif signifie que le patient a contracté une tréponématose ; avec un TNT négatif, le tableau d'interprétation retient une tréponématose guérie (cicatrice sérologique), une tréponématose très précoce ou une syphilis tertiaire très ancienne. Chez ce patient traité et asymptomatique, c'est la cicatrice sérologique (p. 195-196).","src":"p. 195","deep":"**Pourquoi** : le TT affirme ou infirme une tréponématose, le TNT en précise l'évolutivité (p. 200) ; le profil TT positif / TNT négatif figure dans le tableau comme tréponématose guérie (cicatrice sérologique) (p. 195).\n**Piège** : on ne suit pas le TT quantitatif, qui varie beaucoup d'un examen à l'autre ; seul le TT qualitatif est intéressant (p. 194).\n**À relier** : la maladie n'est pas immunisante : une recontamination se reconnaît à une remontée du TNT quantitatif (titre multiplié au moins par 4) (p. 195)."},{"id":"d162-qru-107","type":"QRU","rank":"A","objective":"d162-obj-23","tags":["diagnostic","définition"],"difficulty":2,"stem":"Un homme de 29 ans, asymptomatique, a un ELISA positif lors d'un dépistage. Il fournit une sérologie syphilitique négative datant de 8 mois. Quel est le diagnostic ?","options":[{"t":"Syphilis tertiaire","ok":false,"why":"Elle appartient aux syphilis tardives, comme la latente tardive."},{"t":"Syphilis latente précoce","ok":true,"why":"Sérologie positive sans lésion clinique, avec une sérologie négative de moins de 1 an : syphilis latente précoce."},{"t":"Syphilis secondaire","ok":false,"why":"Il n'y a ni éruption ni signe général."},{"t":"Syphilis primaire","ok":false,"why":"Il n'y a pas de chancre : le patient est asymptomatique."},{"t":"Syphilis latente tardive","ok":false,"why":"Elle est non datable ou date de plus de 1 an."}],"explanation":"La syphilis précoce regroupe la syphilis primaire, secondaire et latente précoce. Le diagnostic de latente précoce n'est acceptable que si le patient fournit une sérologie négative de moins de 1 an. Le traitement est le même que pour les autres formes précoces.","src":"p. 188, 197","deep":"**Pourquoi** : la syphilis latente précoce est une sérologie positive sans lésion clinique datant de moins de 1 an ; ce diagnostic n'est acceptable que si le patient fournit une sérologie négative de moins de 1 an (p. 188, 197).\n**Piège** : sans sérologie antérieure datée, la syphilis est non datable et se classe en latente tardive (p. 188).\n**À relier** : le traitement est le même que pour la primaire et la secondaire : benzathine-benzylpénicilline 2,4 MU en IM unique (p. 197-198)."},{"id":"d162-qcm-101","type":"QRM","rank":"A","objective":"d162-obj-08","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un homme de 22 ans consulte pour un écoulement urétral purulent avec dysurie depuis 3 jours, après un rapport non protégé il y a 4 jours. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le portage asymptomatique urétral est fréquent chez l'homme","ok":false,"why":"Il est exceptionnel à l'urètre : le tableau est le plus souvent bruyant."},{"t":"Le traitement diffère en cas d'infection par le VIH","ok":false,"why":"Le traitement des urétrites est identique en cas d'infection par le VIH."},{"t":"L'écoulement est le plus souvent clair et intermittent","ok":false,"why":"C'est l'aspect de la chlamydiose ; l'écoulement gonococcique est purulent dans 90 % des cas."},{"t":"Il faut attendre le résultat de la culture avant de traiter","ok":false,"why":"Le traitement minute, en dose unique, est délivré sur place lors de la consultation."},{"t":"Une incubation de 2 à 7 jours oriente vers une gonococcie","ok":true,"why":"L'incubation de la gonococcie est de 2 à 7 jours, alors que celle de la chlamydiose est variable (quelques jours à quelques mois)."}],"explanation":"Urétrite aiguë purulente après une incubation courte (2 à 7 jours) : tableau typique de gonococcie (p. 180). On associe un traitement anti-Chlamydia (urétrite mixte dans 15 % des cas) et on traite le(s) partenaire(s) (p. 182).","src":"p. 180, 182","deep":"**Pourquoi** : écoulement purulent (90 % des cas) et incubation courte de 2 à 7 jours sont les deux traits du gonocoque (p. 180 ; tableau 9.1, p. 186).\n**Piège** : on n'attend pas les résultats : le traitement minute en dose unique est délivré sur place, et il est le même chez le patient infecté par le VIH (p. 182).\n**À relier** : on associe un anti-Chlamydia (urétrite mixte dans 15 %), on traite le(s) partenaire(s) et on propose sérologies VIH, syphilis et hépatite B (p. 182)."},{"id":"d162-qcm-102","type":"QRM","rank":"A","objective":"d162-obj-10","tags":["clinique","diagnostic"],"difficulty":2,"stem":"À propos des infections génitales à Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La sérologie est l'examen de référence du diagnostic","ok":false,"why":"La sérologie n'a pas d'intérêt ; l'examen clé est la PCR."},{"t":"L'écoulement urétral est constant et franchement purulent","ok":false,"why":"Il est présent dans moins de 50 % des cas, le plus souvent clair, modéré et intermittent."},{"t":"Le portage asymptomatique est fréquent","ok":true,"why":"Il concerne 50 % des hommes et 50 à 90 % des femmes, et entretient la chaîne épidémiologique."},{"t":"La culture est plus sensible que la PCR","ok":false,"why":"C'est la PCR qui est plus sensible que la culture."},{"t":"La cervicite est une forme rare chez la femme","ok":false,"why":"C'est la forme la plus fréquente des chlamydioses urogénitales basses de la femme."}],"explanation":"La chlamydiose est volontiers silencieuse, ce qui explique la diffusion dans la population et les complications tardives. Le diagnostic repose sur la PCR.","src":"p. 184-185","deep":"**Pourquoi** : le portage asymptomatique (50 % des hommes, 50 à 90 % des femmes) entretient la chaîne épidémiologique et favorise les complications tardives (p. 184).\n**Piège** : ce n'est pas la culture qui fait référence : la PCR est plus sensible, et la sérologie n'a aucun intérêt (p. 185).\n**À relier** : à l'examen d'une cervicite chlamydienne : col fragile, sécrétions mucopurulentes et/ou ectropion friable et hémorragique (p. 184)."},{"id":"d162-qcm-103","type":"QRM","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"stem":"Quels prélèvements sont adaptés à la recherche par PCR d'un gonocoque et de C. trachomatis ?","options":[{"t":"Chez l'homme, le 1er jet urinaire, au moins 2 h après la dernière miction","ok":true,"why":"C'est le prélèvement recommandé chez l'homme, symptomatique ou non."},{"t":"Un prélèvement pharyngé et/ou anal, selon les pratiques sexuelles","ok":true,"why":"Les sites extragénitaux sont à prélever selon les pratiques, dans les deux sexes."},{"t":"Une sérologie sanguine en première intention","ok":false,"why":"La sérologie n'a pas d'intérêt pour C. trachomatis ; le diagnostic repose sur la PCR."},{"t":"Des urines du milieu de jet, recueillies juste après une miction","ok":false,"why":"Il faut un 1er jet, au moins 2 heures après la dernière miction."},{"t":"Chez la femme, un écouvillonnage de l'endocol réalisé par un professionnel, seul recommandé","ok":false,"why":"Chez la femme symptomatique, l'auto-écouvillonnage vaginal est à préférer à l'écouvillonnage de l'endocol par un professionnel ; chez la femme asymptomatique, écouvillonnage vulvovaginal (autoprélèvement) (p. 185)."}],"explanation":"La PCR (souvent biplex gonocoque + C. trachomatis) se fait sur 1er jet urinaire chez l'homme et sur auto-écouvillonnage vaginal chez la femme (à préférer à l'écouvillonnage de l'endocol), avec prélèvements pharyngé et/ou anal selon les pratiques sexuelles.","src":"p. 181, 185","deep":"**Pourquoi** : la PCR se fait sur 1er jet urinaire (10 à 20 mL, au moins 2 h après la dernière miction) chez l'homme, sur auto-écouvillonnage vaginal chez la femme, et sur des sites pharyngé et/ou anal selon les pratiques (p. 181, 185).\n**Piège** : le portage pharyngé du gonocoque, fréquent et le plus souvent asymptomatique, doit être recherché systématiquement en cas de conduite à risque (p. 180).\n**À relier** : la sérologie est inutile pour C. trachomatis (p. 185) mais centrale pour la syphilis (p. 194)."},{"id":"d162-qcm-104","type":"QRM","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":2,"stem":"À propos du chancre de la syphilis primaire, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il est pathognomonique : sa présence suffit à conclure","ok":false,"why":"Aucune de ses caractéristiques n'est pathognomonique."},{"t":"Il est typiquement douloureux, comme l'herpès","ok":false,"why":"Il est indolore, à la différence de l'herpès."},{"t":"Il est toujours unique : il n'est jamais multiple","ok":false,"why":"Il est unique, mais possiblement multiple, avec des images en miroir (p. 188)."},{"t":"L'induration est son seul signe vraiment évocateur","ok":true,"why":"La lésion ne peut être plissée entre deux doigts : elle ne fait qu'un bloc avec l'induration sous-jacente."},{"t":"Il est toujours visible, donc jamais méconnu","ok":false,"why":"Il est souvent méconnu quand il siège au vagin, au col utérin, à l'anorectum ou au pharynx."}],"explanation":"Le chancre est une exulcération à fond propre, rosée, indolore, indurée, accompagnée d'une adénopathie non inflammatoire. Comme aucun signe n'est pathognomonique, on évoque la syphilis devant toute ulcération muqueuse aiguë.","src":"p. 188-189","deep":"**Pourquoi** : la lésion indurée ne peut être plissée entre deux doigts ; le chancre est contagieux car il fourmille de tréponèmes (p. 188).\n**Piège** : un chancre vaginal, du col, anorectal ou pharyngé passe souvent inaperçu, et l'adénopathie peut manquer cliniquement (col utérin, rectum) (p. 188, 190).\n**À relier** : le chancre régresse spontanément en quelques semaines ; sans traitement, environ 30 % des patients ayant eu un chancre visible présenteront des signes de syphilis secondaire (p. 190)."},{"id":"d162-qcm-105","type":"QRM","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"stem":"Parmi les manifestations suivantes, lesquelles peuvent s'observer au cours d'une syphilis secondaire ?","options":[{"t":"Ulcération douloureuse à fond sale avec adénopathies inflammatoires","ok":false,"why":"Cela évoque un chancre mou."},{"t":"Condylomes acuminés en « crêtes-de-coq »","ok":false,"why":"Ce sont des lésions à HPV ; les syphilides génitales (condylomata lata) font partie de leur diagnostic différentiel."},{"t":"Fausse perlèche (papule commissurale fendue en deux)","ok":true,"why":"Elle diffère d'une simple fissure sans relief du fond du pli."},{"t":"Alopécie diffuse et totale du cuir chevelu","ok":false,"why":"L'alopécie de la syphilis secondaire est en aires, incomplètement dépilées, dite en « fourrure mitée » (p. 192-193)."},{"t":"Dépapillation de la langue en aires (plaques « fauchées »)","ok":true,"why":"Elle fait partie des symptômes cutanéo-phanériens plus trompeurs."}],"explanation":"La syphilis secondaire, « grande simulatrice », associe des éruptions polymorphes (roséole, syphilides papuleuses cuivrées, palmo-plantaires) et des signes plus discrets : fausse perlèche, plaques fauchées, dépilation des sourcils, fourrure mitée.","src":"p. 192-193, 197, 203","deep":"**Pourquoi** : la syphilis secondaire traduit la diffusion systémique du tréponème, avec plusieurs éruptions (« floraisons ») entrecoupées de phases asymptomatiques (p. 190).\n**Piège** : les syphilides génitales sont indolores, non prurigineuses et très contagieuses ; elles entrent dans le diagnostic différentiel des condylomes (p. 192, 203).\n**À relier** : la dépilation des sourcils et les lésions séborrhéiques des sillons nasogéniens font aussi partie des signes trompeurs (p. 192) ; TT et TNT sont toujours positifs à ce stade (p. 195)."},{"id":"d162-qcm-106","type":"QRM","rank":"A","objective":"d162-obj-27","tags":["biologie","diagnostic"],"difficulty":2,"stem":"Un patient présente une éruption papuleuse cuivrée avec des papules palmo-plantaires évoquant une syphilis secondaire. Quels résultats sérologiques attend-on ?","options":[{"t":"Un TNT positif, avec un titre élevé","ok":true,"why":"Le TNT atteint un plateau durant la phase secondaire, en général entre 1/16 et 1/128."},{"t":"Un test tréponémique positif avec un TNT négatif","ok":false,"why":"C'est le profil d'une cicatrice sérologique ou d'une syphilis très précoce."},{"t":"Un test tréponémique positif","ok":true,"why":"Au stade secondaire, le TT et le TNT sont toujours positifs."},{"t":"Un test tréponémique négatif avec un TNT positif","ok":false,"why":"Ce profil évoque une fausse sérologie syphilitique."},{"t":"Deux tests négatifs","ok":false,"why":"Cela n'est possible que dans les 7 premiers jours du chancre."}],"explanation":"En syphilis secondaire, les deux tests sont positifs et le titre du TNT est élevé. Un TNT très positif traduit une maladie évolutive.","src":"p. 195-196, 200","deep":"**Pourquoi** : au stade secondaire, TT et TNT sont toujours positifs, et le titre du TNT atteint un plateau, en général entre 1/16 et 1/128 (p. 195).\n**Piège** : ce plateau ne permet pas de distinguer une syphilis latente précoce d'une latente tardive (p. 195).\n**À relier** : un titre élevé (1/16 par exemple) témoigne d'une maladie évolutive, sauf si elle est déjà traitée avec un titre qui décroît (p. 196)."},{"id":"d162-qcm-107","type":"QRM","rank":"A","objective":"d162-obj-28","tags":["suivi"],"difficulty":2,"stem":"Un patient est traité par benzathine-benzylpénicilline pour une syphilis primaire. Quelle(s) proposition(s) concernant le suivi est/sont exacte(s) ?","options":[{"t":"Le suivi se fait sur le TNT quantitatif : titre divisé par 4 à 6 mois","ok":true,"why":"Sans cette décroissance, l'avis d'un spécialiste est justifié et le traitement est repris."},{"t":"Le suivi se fait sur le titre du test tréponémique quantitatif, qui doit se négativer","ok":false,"why":"Le TT quantitatif varie beaucoup d'un examen à l'autre : ce n'est pas un bon marqueur d'évolutivité."},{"t":"Le TNT doit déjà être négatif dès le 1er mois suivant le traitement","ok":false,"why":"Il doit être négatif 1 an après le traitement d'une syphilis primaire, et dans les 2 ans pour une syphilis secondaire."},{"t":"Un contrôle unique à 3 mois est suffisant pour conclure à la guérison","ok":false,"why":"Les contrôles ont lieu à 3 mois, 6 mois, 1 an, puis tous les ans jusqu'à négativation."},{"t":"Une remontée du TNT ne peut pas évoquer une recontamination","ok":false,"why":"La maladie n'est pas immunisante : un titre multiplié au moins par 4 évoque une recontamination."}],"explanation":"Contrôle clinique et biologique à 3 mois, 6 mois, 1 an puis annuel jusqu'à négativation, sur le TNT quantitatif (VDRL). Le patient a un comportement sexuel à haut risque : on cherche une IST associée et on répète la prévention.","src":"p. 195, 198","deep":"**Pourquoi** : le TNT quantitatif reflète l'évolutivité : le traitement est jugé efficace si son titre est divisé par 4 (deux dilutions) à 6 mois (p. 195, 198).\n**Piège** : le TT quantitatif varie trop d'un examen à l'autre pour suivre le traitement (p. 194).\n**À relier** : sans décroissance suffisante : avis spécialisé et 3 injections de 2,4 MU à 8 jours d'intervalle ; TNT négatif attendu à 1 an (primaire) ou dans les 2 ans (secondaire) (p. 198)."},{"id":"d162-qcm-108","type":"QRM","rank":"A","objective":"d162-obj-30","tags":["diagnostic","prévention"],"difficulty":2,"stem":"Une femme de 24 ans consulte pour des condylomes acuminés vulvaires. Quelle(s) mesure(s) est/sont indiquée(s) ?","options":[{"t":"Une biopsie systématique de chaque condylome","ok":false,"why":"La biopsie n'est faite qu'en cas de doute diagnostique ou de suspicion de néoplasie."},{"t":"Un test HPV-HR en première intention, quel que soit l'âge","ok":false,"why":"Il est recommandé à partir de 30 ans ; avant, il est presque toujours positif sans pathologie sous-jacente."},{"t":"Un examen gynécologique et anal complet","ok":true,"why":"Les formes multifocales (vagin, périnée, région péri-anale) l'imposent, avec un dépistage cervical."},{"t":"Un traitement antibiotique par ceftriaxone","ok":false,"why":"Les condylomes sont des lésions dues à un virus, l'HPV (p. 200-201) : la ceftriaxone, antibiotique, ne les traite pas ; la prise en charge passe ici par l'examen complet et la recherche d'IST associée (p. 202, 205)."},{"t":"Une recherche d'IST associée (VIH, syphilis, hépatite B, PCR)","ok":true,"why":"Une autre IST est présente dans 25 % des cas en moyenne : sérologie VIH, test tréponémique, hépatite B, PCR Chlamydia et gonocoque."}],"explanation":"Le diagnostic est clinique. Chez la femme, l'atteinte multifocale impose un examen gynécologique et anal complet, un dépistage cervical (frottis avant 30 ans) et la recherche d'une IST associée.","src":"p. 201-202, 204-205","deep":"**Pourquoi** : les formes multifocales (vagin, périnée, région péri-anale) imposent un examen gynécologique et anal complet avec frottis ou test HPV-HR selon l'âge (p. 202).\n**Piège** : la co-infection par des HPV à haut risque oncogène est fréquente, d'où un risque de dysplasie (p. 202) ; la colposcopie avec acide acétique et/ou lugol dirige alors la biopsie (p. 202).\n**À relier** : lésions anales → anuscopie ; biopsie seulement en cas de doute diagnostique ou de suspicion de néoplasie (p. 201)."},{"id":"d162-qcm-109","type":"QRM","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"stem":"À propos de la vaccination anti-HPV, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle n'est pas recommandée chez les HSH","ok":false,"why":"Elle est recommandée chez les HSH jusqu'à 26 ans, en prévention des lésions anales, des cancers anaux et des condylomes."},{"t":"Elle s'adresse aux filles comme aux garçons","ok":true,"why":"Elle est proposée à tous les adolescents, entre 11 et 14 ans, avec rattrapage de 15 à 19 ans révolus."},{"t":"Elle est surtout efficace lorsqu'elle est faite après la contamination","ok":false,"why":"Elle est avant tout préventive et se fait au mieux avant toute contamination."},{"t":"Elle est contre-indiquée chez les patients immunodéprimés","ok":false,"why":"Elle est recommandée chez les immunodéprimés, garçons comme filles, avec rattrapage jusqu'à 19 ans révolus."},{"t":"Toute nouvelle vaccination commence par un vaccin ciblant seulement les HPV 6, 11, 16 et 18","ok":false,"why":"Toute nouvelle vaccination doit être initiée avec le vaccin nonavalent."}],"explanation":"Vaccin nonavalent (Gardasil 9) pour tous : 2 doses espacées de 6 à 13 mois entre 11 et 14 ans, 3 doses (0, 2, 6 mois) de 15 à 19 ans et chez les HSH jusqu'à 26 ans.","src":"p. 204-205","deep":"**Pourquoi** : le vaccin est avant tout préventif et doit être fait au mieux avant toute contamination, d'où une proposition dès 11 ans (p. 204).\n**Piège** : les cas particuliers ont leurs propres bornes : HSH jusqu'à 26 ans ; immunodéprimés aux mêmes âges avec rattrapage jusqu'à 19 ans révolus ; candidats à une greffe d'organe solide dès 9 ans (p. 204).\n**À relier** : 2 doses (6 à 13 mois d'écart) de 11 à 14 ans, 3 doses (0, 2, 6 mois) de 15 à 19 ans ; le nonavalent cible les HPV 6, 11, 16, 18, 31, 33, 45, 52 et 58 (p. 204-206)."},{"id":"d162-qcm-110","type":"QRM","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Parmi les propositions suivantes sur les causes d'ulcération génitale, lesquelles sont exactes ?","options":[{"t":"La maladie de Nicolas-Favre se limite à un chancre isolé du gland","ok":false,"why":"Elle associe anorectite, ulcérations anogénitales et diarrhées trompeuses."},{"t":"Le chancre syphilitique est typiquement douloureux, à fond sale","ok":false,"why":"Il est indolore, à fond propre."},{"t":"La donovanose donne des ulcérations très douloureuses","ok":false,"why":"Ses lésions granulomateuses sont peu douloureuses."},{"t":"L'herpès : ulcérations superficielles, douloureuses, polycycliques","ok":true,"why":"C'est la description de l'herpès, à distinguer du chancre syphilitique indolore."},{"t":"Le chancre mou est douloureux, à fond sale","ok":true,"why":"Il s'accompagne d'adénopathies inflammatoires, sur un terrain particulier (sujets africains), avec des lésions uniques ou multiples."}],"explanation":"Devant une ulcération génitale, on évoque systématiquement la syphilis et on élimine l'herpès, le chancre mou, la donovanose et la maladie de Nicolas-Favre.","src":"p. 188, 197","deep":"**Pourquoi** : douleur et aspect du fond orientent : herpès douloureux et polycyclique, chancre mou douloureux à fond sale avec adénopathies inflammatoires, chancre syphilitique indolore à fond propre (p. 188, 197).\n**Piège** : la donovanose est elle aussi peu douloureuse : l'absence de douleur ne suffit pas à affirmer la syphilis (p. 197).\n**À relier** : devant toute ulcération génitale, on évoque la syphilis et on traite sans attendre le résultat du TT et du TNT (p. 197)."},{"id":"d162-qcm-111","type":"QRM","rank":"B","objective":"d162-obj-15","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant le diagnostic microbiologique de la gonococcie, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La PCR fournit aussi la sensibilité de la souche aux différents antibiotiques","ok":false,"why":"Elle ne permet pas de tester la sensibilité de la souche, d'où l'intérêt de la culture."},{"t":"Examen direct : diplocoques à Gram négatif intracellulaires, « en grains de café »","ok":true,"why":"Sa sensibilité et sa spécificité dépassent 95 % dans l'urétrite masculine symptomatique."},{"t":"Un diplocoque extracellulaire à Gram négatif suffit à affirmer le diagnostic","ok":false,"why":"Il existe des Neisseria non pathogènes : cet aspect ne donne pas de certitude."},{"t":"L'examen direct est aussi performant chez la femme que dans l'urétrite masculine","ok":false,"why":"Sensibilité et spécificité sont moins bonnes pour les autres sites et chez la femme."},{"t":"La culture sur gélose au sang cuit est systématique, avec antibiogramme en 24-48 h","ok":true,"why":"Elle confirme le diagnostic et permet de suivre les résistances."}],"explanation":"En cas de symptômes, on peut faire un examen direct et une culture sur écoulement urétral (ou 1er jet urinaire) ; en dépistage, la PCR est préconisée.","src":"p. 181-182","deep":"**Pourquoi** : des diplocoques à Gram négatif intracellulaires « en grains de café » ont une sensibilité et une spécificité > 95 % dans l'urétrite masculine symptomatique (p. 181).\n**Piège** : une forme extracellulaire seule ne donne pas de certitude (Neisseria non pathogènes), et l'examen direct est moins performant chez la femme et aux autres sites (p. 181).\n**À relier** : la culture est moins sensible à l'oropharynx, à l'anus et au col, d'où l'intérêt de la PCR, qui ne teste pas la sensibilité de la souche (p. 182)."},{"id":"d162-qcm-112","type":"QRM","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement d'une infection non compliquée à Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"L'azithromycine 1 g en dose unique, si risque de mauvaise observance","ok":true,"why":"Elle a l'avantage de la dose unique, mais favorise des résistances chez d'autres micro-organismes (Mycoplasma genitalium)."},{"t":"Le contrôle par PCR ne doit pas être trop précoce","ok":true,"why":"Des débris cellulaires dans les 4 semaines suivant le traitement peuvent rendre la PCR faussement positive."},{"t":"La doxycycline 7 jours est un traitement de 1re intention","ok":true,"why":"Le schéma est de 100 mg toutes les 12 heures par voie orale pendant 7 jours."},{"t":"L'érythromycine est le traitement de première intention","ok":false,"why":"L'érythromycine (ou l'ofloxacine) est un traitement de deuxième intention."},{"t":"Les cyclines sont recommandées chez la femme enceinte","ok":false,"why":"Chez la femme enceinte, on prescrit l'azithromycine 1 g en prise unique avec PCR systématique à 1 mois (p. 186) ; les cyclines font partie des classes contre-indiquées pendant la grossesse (p. 182)."}],"explanation":"Doxycycline 7 jours en première intention, azithromycine en dose unique si risque d'inobservance ; contrôle PCR différé de plusieurs semaines.","src":"p. 185-186","deep":"**Pourquoi** : première intention : doxycycline 100 mg/12 h PO pendant 7 jours, ou azithromycine 1 g en prise unique si l'on craint une mauvaise observance (p. 185).\n**Piège** : un contrôle PCR trop précoce peut être faussement positif (débris de Chlamydia dans les 4 semaines) ; chez les patients à haut risque de réinfection, contrôle des sites atteints à 3-6 mois (p. 185).\n**À relier** : la doxycycline passe à 10 jours pour une orchiépididymite et à 14 jours pour une endométrite ou une salpingite (p. 186)."},{"id":"d162-qcm-113","type":"QRM","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement des condylomes, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La podophyllotoxine est contre-indiquée chez la femme enceinte et chez l'enfant","ok":true,"why":"Elle est appliquée par le patient matin et soir, 3 jours consécutifs par semaine, sur les lésions seulement."},{"t":"Les méthodes de destruction physique n'ont pas de risque cicatriciel","ok":false,"why":"Cryothérapie, laser CO2 et électrocoagulation ont en commun un risque cicatriciel."},{"t":"Pas de traitement spécifique de l'HPV : on vise la disparition des lésions visibles","ok":true,"why":"Il n'existe pas de traitement spécifique des HPV ; le risque de récidive est important et, après éradication des lésions, le virus peut persister dans l'épiderme sain (p. 204)."},{"t":"La cryothérapie est idéale pour les lésions étendues","ok":false,"why":"Elle ne se conçoit que pour des lésions d'étendue limitée, car elle est douloureuse."},{"t":"Après la disparition des lésions, le virus est éliminé de l'épiderme","ok":false,"why":"Le virus peut persister dans l'épiderme sain."}],"explanation":"Le traitement est adapté au type de lésion et à la localisation (destruction physique, chimique ou immunologique) ; un suivi à 1 mois puis tous les 3 mois jusqu'à guérison clinique est prévu.","src":"p. 204-205","deep":"**Pourquoi** : il n'existe pas de traitement spécifique des HPV : on vise la disparition des lésions visibles, le risque de récidive est important et le virus peut persister dans l'épiderme sain (p. 204).\n**Piège** : l'imiquimod se prescrit avec prudence chez la femme enceinte (3 applications par semaine pendant 16 semaines), alors que la podophyllotoxine y est contre-indiquée (p. 205-206).\n**À relier** : suivi à 1 mois puis tous les 3 mois jusqu'à guérison clinique, puis 6 mois après, et examen du ou des partenaires (p. 204)."},{"id":"d162-qcm-114","type":"QRM","rank":"B","objective":"d162-obj-28","tags":["traitement","pièges"],"difficulty":2,"stem":"Quelques heures après l'injection de benzathine-benzylpénicilline pour une syphilis secondaire, un patient présente fièvre, céphalées, myalgies et accentuation de son éruption. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle signe l'échec du traitement","ok":false,"why":"L'efficacité du traitement se juge sur le TNT quantitatif à 6 mois."},{"t":"Il s'agit d'une réaction d'Herxheimer, bénigne, secondaire à la lyse des tréponèmes","ok":true,"why":"Elle est toujours bénigne ; un antipyrétique peut être prescrit."},{"t":"Un protocole thérapeutique permet de la prévenir de façon fiable","ok":false,"why":"Aucun protocole thérapeutique ne la prévient réellement ; on prévient le patient du risque."},{"t":"Il s'agit d'une allergie à la pénicilline : toute nouvelle injection est contre-indiquée","ok":false,"why":"La réaction d'Herxheimer ne doit pas être interprétée comme une allergie à la pénicilline."},{"t":"Il faut passer d'emblée à la doxycycline pendant 14 jours","ok":false,"why":"La doxycycline est réservée aux patients allergiques à la pénicilline."}],"explanation":"La réaction d'Herxheimer est possible quelques heures après l'injection au stade secondaire (bénigne dans la syphilis primaire). On prévient le patient et on peut prescrire un antipyrétique.","src":"p. 198","deep":"**Pourquoi** : la réaction d'Herxheimer vient de la lyse des tréponèmes ; sans gravité dans la syphilis primaire, elle est possible quelques heures après l'injection au stade secondaire (p. 198).\n**Piège** : toujours bénigne, elle ne doit pas être prise pour une allergie ; aucun protocole ne la prévient réellement, on prévient donc le patient (p. 198).\n**À relier** : en cas de vraie allergie : doxycycline 100 mg matin et soir 14 jours, sauf femme enceinte et patient séropositif pour le VIH (induction de tolérance) (p. 198)."},{"id":"d162-qcm-115","type":"QRM","rank":"A","objective":"d162-obj-19","tags":["prévention","diagnostic"],"difficulty":2,"stem":"Concernant le dépistage des lésions cervicales liées aux HPV, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le test HPV-HR est recommandé en première intention à partir de 30 ans","ok":true,"why":"Il permet le typage des HPV oncogènes, en particulier 16 et 18."},{"t":"Le frottis cervico-vaginal est à répéter tous les 10 ans","ok":false,"why":"Le dépistage systématique repose sur un frottis tous les 3 ans (ou un test HPV-HR)."},{"t":"Avant 30 ans, un test HPV-HR positif traduit presque toujours une lésion","ok":false,"why":"Avant 30 ans, la clairance spontanée n'est pas totale : le test est presque toujours positif sans pathologie sous-jacente."},{"t":"En cas de dysplasie mineure, on se contente d'une surveillance sans colposcopie","ok":false,"why":"En cas de dysplasie, même mineure, on réalise une colposcopie et si nécessaire une biopsie dirigée."},{"t":"Une biopsie du col est systématique avant tout frottis","ok":false,"why":"La biopsie est dirigée par la colposcopie (acide acétique à 5 % ou lugol) sur les zones suspectes."}],"explanation":"Dépistage systématique du col : frottis tous les 3 ans ou test HPV-HR (dès 30 ans) ; toute dysplasie, même mineure, conduit à la colposcopie.","src":"p. 202, 205","deep":"**Pourquoi** : le test HPV-HR type les HPV oncogènes, surtout 16 et 18, et il est recommandé en première intention à partir de 30 ans (p. 202).\n**Piège** : avant 30 ans, la clairance spontanée des HPV est incomplète : le test serait presque toujours positif sans pathologie sous-jacente (p. 202).\n**À relier** : toute dysplasie, même mineure, conduit à une colposcopie (acide acétique à 5 % ou lugol) avec biopsie dirigée si nécessaire (p. 205)."},{"id":"d162-qroc-201","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":1,"question":"Quelles sont les deux lésions qui caractérisent la syphilis primaire ?","answer":"Un chancre au point d'inoculation et une adénopathie satellite","accept":["chancre et adénopathie","chancre + adénopathie","chancre et adénopathie satellite","chancre d'inoculation et adénopathie"],"keywords":["chancre","adénopathie"],"explanation":"Le chancre est contagieux (riche en tréponèmes). Le diagnostic est souvent méconnu quand il n'est pas visible : chancre vaginal, du col utérin, anorectal ou pharyngé.","src":"p. 188","deep":"**Pourquoi** : la syphilis primaire associe un chancre au point d'inoculation et une adénopathie satellite, après une incubation de 10 à 90 jours (3 semaines en moyenne) (p. 188).\n**Piège** : l'adénopathie n'est pas cliniquement visible quand le chancre siège au col utérin ou au rectum (p. 190).\n**À relier** : le chancre régresse spontanément sans séquelle en quelques semaines : le patient semble guéri mais peut évoluer vers les stades plus tardifs (p. 190)."},{"id":"d162-qroc-202","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel est le seul caractère sémiologique vraiment évocateur d'un chancre syphilitique ?","answer":"L'induration (base indurée)","accept":["induration","base indurée","induré","indurée","ulcération indurée"],"keywords":["indur"],"explanation":"Le chancre est une exulcération de 5 à 15 mm, à fond propre et rosé, indolore, unique mais possiblement multiple. L'induration (lésion impossible à plisser entre deux doigts) est le seul signe vraiment évocateur, mais aucun signe n'est pathognomonique (p. 188-189).","src":"p. 188-189","deep":"**Pourquoi** : la surface de l'ulcération ne peut pas être plissée entre deux doigts : elle ne fait qu'un bloc avec l'induration sous-jacente (p. 188).\n**Piège** : même l'induration n'est pas pathognomonique : toute ulcération muqueuse aiguë doit faire évoquer la syphilis (p. 189).\n**À relier** : diagnostics à éliminer : herpès (douloureux, polycyclique), chancre mou (douloureux, fond sale), donovanose, maladie de Nicolas-Favre (p. 197)."},{"id":"d162-qroc-203","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":1,"question":"Quel caractère fonctionnel distingue le chancre syphilitique d'une ulcération herpétique ?","answer":"Il est indolore (l'herpès est douloureux)","accept":["indolore","non douloureux","pas douloureux","sans douleur"],"keywords":["indolore"],"explanation":"Le chancre syphilitique est indolore, à la différence de l'herpès dont les ulcérations superficielles sont douloureuses.","src":"p. 188, 197","deep":"**Pourquoi** : le chancre syphilitique est indolore, alors que les ulcérations superficielles de l'herpès sont douloureuses (p. 188, 197).\n**Piège** : la donovanose donne elle aussi des lésions peu douloureuses (p. 197) : l'indolence oriente mais ne tranche pas seule.\n**À relier** : le chancre mou est très douloureux (+++), à fond sale, avec des adénopathies inflammatoires (p. 197)."},{"id":"d162-qroc-204","type":"QROC","rank":"A","objective":"d162-obj-06","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel est l'aspect des ulcérations de l'herpès génital, diagnostic différentiel du chancre syphilitique ?","answer":"Ulcérations superficielles, douloureuses, à contours polycycliques","accept":["contours polycycliques","polycycliques","polycyclique","superficielles douloureuses à contours polycycliques"],"keywords":["polycycl"],"explanation":"Devant une ulcération génitale, on élimine l'herpès (superficielle, douloureuse, polycyclique), le chancre mou, la donovanose et la maladie de Nicolas-Favre.","src":"p. 197","deep":"**Pourquoi** : l'herpès génital donne des ulcérations superficielles, douloureuses, à contours polycycliques (p. 197).\n**Piège** : même devant un aspect évocateur d'herpès, la syphilis doit être évoquée systématiquement devant toute ulcération muqueuse, génitale, anale ou buccopharyngée (p. 197).\n**À relier** : les infections à herpès sont traitées dans leur propre item (item 168), comme le VIH (item 169) (p. 208)."},{"id":"d162-qroc-205","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic"],"difficulty":1,"question":"Devant quelle situation clinique doit-on évoquer systématiquement un chancre syphilitique ?","answer":"Toute ulcération muqueuse aiguë (génitale, orale ou anale)","accept":["ulcération muqueuse","toute ulcération muqueuse","ulcération muqueuse aiguë","ulcération génitale"],"keywords":["ulcération","muqueuse"],"explanation":"Aucune caractéristique du chancre n'est pathognomonique : toute ulcération muqueuse aiguë, génitale, orale ou anale, doit faire évoquer la syphilis.","src":"p. 189, 197","deep":"**Pourquoi** : aucune caractéristique du chancre n'est pathognomonique, et un chancre syphilitique doit être évoqué systématiquement devant toute ulcération muqueuse aiguë (p. 189).\n**Piège** : le chancre peut être buccal ou pharyngé (fellation) ou anorectal ; vaginal, il passe volontiers inaperçu (p. 189).\n**À relier** : la prescription d'un test tréponémique est obligatoire dans ces circonstances (p. 200), sans attendre son résultat pour traiter (p. 197)."},{"id":"d162-qroc-206","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":2,"question":"Quelles sont les caractéristiques de l'adénopathie satellite du chancre syphilitique ?","answer":"Non inflammatoire, le plus souvent unilatérale","accept":["non inflammatoire","adénopathie non inflammatoire","non inflammatoire et unilatérale"],"keywords":["non inflammatoire"],"explanation":"L'adénopathie est non inflammatoire et le plus souvent unilatérale ; elle n'est pas visible quand le chancre siège au col utérin ou au rectum. Le chancre mou, lui, s'accompagne d'adénopathies inflammatoires.","src":"p. 190, 197","deep":"**Pourquoi** : l'adénopathie satellite du chancre est non inflammatoire et le plus souvent unilatérale (p. 190).\n**Piège** : elle peut manquer à l'examen quand le chancre siège au col utérin ou au rectum (p. 190).\n**À relier** : le chancre mou s'accompagne au contraire d'adénopathies inflammatoires, avec une ulcération douloureuse à fond sale (p. 197)."},{"id":"d162-qroc-207","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":1,"question":"Quelle couleur caractérise les papules de la syphilis secondaire ?","answer":"Cuivrée","accept":["cuivrée","cuivré","cuivre","couleur cuivrée","cuivrées"],"keywords":["cuivr"],"explanation":"Les éruptions de la syphilis secondaire sont polymorphes : il faut rechercher des lésions papuleuses de couleur cuivrée (p. 200).","src":"p. 191, 200","deep":"**Pourquoi** : les éruptions de la syphilis secondaire sont polymorphes ; la couleur cuivrée des papules est l'indice à rechercher (p. 200).\n**Piège** : la roséole syphilitique ne doit pas être confondue avec une éruption virale ou une toxidermie (p. 200).\n**À relier** : des papules palmo-plantaires évoquent très fortement une syphilis secondaire ; à ce stade, TT et TNT sont toujours fortement positifs (p. 200)."},{"id":"d162-qroc-208","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":2,"question":"Quelle localisation de papules évoque très fortement une syphilis secondaire ?","answer":"Les paumes et les plantes (papules palmo-plantaires)","accept":["palmo-plantaire","palmo-plantaires","palmo plantaire","paumes et plantes","paumes et plantaires"],"keywords":["palm"],"explanation":"Des papules palmo-plantaires évoquent très fortement une syphilis secondaire (p. 200).","src":"p. 192, 200","deep":"**Pourquoi** : des papules des paumes et des plantes évoquent très fortement une syphilis secondaire (p. 200).\n**Piège** : devant ce tableau, on prescrit un test tréponémique ; au stade secondaire, TT et TNT sont toujours fortement positifs (p. 200).\n**À relier** : le traitement de la syphilis précoce, secondaire comprise, repose sur une injection IM de benzathine-benzylpénicilline 2,4 MU (p. 200)."},{"id":"d162-qroc-209","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","biologie"],"difficulty":1,"question":"Quel test sérologique de la syphilis est réalisé en première intention ?","answer":"Un test tréponémique : l'ELISA","accept":["elisa","test tréponémique","test treponemique","tt"],"keywords":["elisa"],"explanation":"En pratique, on commence par l'ELISA (test tréponémique, TT). Si, et seulement si, il est positif, le biologiste réalise un test non tréponémique (VDRL ou RPR).","src":"p. 194","deep":"**Pourquoi** : l'ELISA, test tréponémique automatisé, est fait en première intention ; si et seulement s'il est positif, le biologiste réalise un TNT (p. 194).\n**Piège** : aucun test ne distingue la syphilis des tréponématoses endémiques non vénériennes (pian, béjel, pinta) (p. 194).\n**À relier** : le TT se positive entre le 7e et le 10e jour du chancre (p. 194)."},{"id":"d162-qroc-210","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","biologie"],"difficulty":2,"question":"Dans quelle condition réalise-t-on un test non tréponémique (VDRL, RPR) ?","answer":"Uniquement si le test tréponémique (ELISA) est positif","accept":["si le tt est positif","si le test tréponémique est positif","si elisa positif","si l'elisa est positif","tt positif"],"keywords":["trépon","positif"],"explanation":"Le TT affirme ou infirme une tréponématose ; le TNT, réalisé seulement si le TT est positif, précise l'évolutivité et sert au suivi.","src":"p. 194, 200","deep":"**Pourquoi** : un TT négatif signifie l'absence de tréponématose ou sa guérison ; le biologiste ne fait alors pas le TNT, qui serait négatif (p. 196).\n**Piège** : dans 10 % des syphilis primaires, le TNT se positive avant le TT (p. 195-196).\n**À relier** : le TNT quantitatif (VDRL) est l'outil de surveillance de l'efficacité du traitement (p. 195)."},{"id":"d162-qroc-211","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Quel piège sérologique existe pendant les 7 premiers jours d'un chancre syphilitique ?","answer":"Le TT et le TNT peuvent encore être négatifs","accept":["tt et tnt négatifs","les deux tests négatifs","sérologie négative","tt et tnt peuvent être négatifs","sérologie encore négative"],"keywords":["négatif"],"explanation":"Pendant les 7 premiers jours, les deux tests peuvent être négatifs. Ensuite le TT se positive rapidement (7e au 10e jour) et le TNT 10 à 15 jours après l'apparition du chancre ; au stade secondaire, les deux sont toujours positifs.","src":"p. 194-196","deep":"**Pourquoi** : le TT se positive entre le 7e et le 10e jour du chancre, le TNT 10 à 15 jours après son apparition (p. 194).\n**Piège** : une sérologie négative ne doit ni faire éliminer la syphilis ni retarder le traitement : devant une ulcération génitale, on n'attend pas les résultats (p. 197).\n**À relier** : ensuite le TNT grimpe pour culminer entre le 3e et le 6e mois ; tous les profils sont possibles au stade primaire (p. 195)."},{"id":"d162-qroc-212","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Citez une cause classique de fausse sérologie syphilitique (VDRL positif, TPHA négatif).","answer":"Lupus ou syndrome des anticorps anti-phospholipides (ou grossesse)","accept":["lupus","sapl","grossesse","anticorps anti-phospholipides","mycoplasma pneumoniae","borréliose"],"keywords":["lupus"],"explanation":"Un TNT positif isolé évoque une fausse sérologie : maladies dysimmunitaires (lupus, SAPL), grossesse, certaines infections (Mycoplasma pneumoniae, borrélioses). Dans 10 % des cas, le TNT se positive toutefois avant le TT.","src":"p. 194, 196","deep":"**Pourquoi** : le VDRL et le RPR ne sont pas spécifiques des tréponématoses ; ils peuvent être positifs dans les maladies dysimmunitaires (lupus, SAPL), la grossesse, certaines infections (p. 194).\n**Piège** : un TNT positif isolé peut aussi être une syphilis primaire débutante, le TNT se positivant avant le TT dans 10 % des cas (p. 195).\n**À relier** : les positivités non tréponémiques du TPHA, elles, sont exceptionnelles (lupus systémique, maladie de Lyme) (p. 195)."},{"id":"d162-qroc-213","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["suivi","biologie"],"difficulty":2,"question":"Quel critère d'évolution du TNT quantitatif, 6 mois après le traitement, atteste de son efficacité ?","answer":"Titre divisé par 4 (soit 2 dilutions)","accept":["divisé par 4","divise par 4","titre divisé par 4","2 dilutions","baisse de 2 dilutions","division par 4"],"keywords":["divis","4"],"explanation":"La surveillance de l'efficacité repose sur le TNT quantitatif (VDRL) : le titre doit être divisé par 4 à 6 mois. Sans cette décroissance, le traitement doit être repris. Le TT quantitatif n'est pas un bon marqueur de l'évolutivité.","src":"p. 195, 198","deep":"**Pourquoi** : c'est le TNT quantitatif qui reflète l'évolutivité : une baisse de deux dilutions (titre divisé par 4) à 6 mois signe l'efficacité (p. 195).\n**Piège** : le TT quantitatif n'est pas un bon marqueur de l'évolutivité ni de la réponse au traitement, car il varie beaucoup d'un examen à l'autre (p. 194).\n**À relier** : à l'inverse, un titre multiplié au moins par 4 fait évoquer une recontamination (p. 195)."},{"id":"d162-qroc-214","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement"],"difficulty":1,"question":"Quel est le traitement de la syphilis précoce (primaire, secondaire, latente précoce) en l'absence d'allergie à la pénicilline ?","answer":"Benzathine-benzylpénicilline 2,4 MU en 1 injection IM unique","accept":["benzathine","benzathine-benzylpénicilline","benzathine benzylpénicilline","extencilline"],"keywords":["benzathine"],"explanation":"Le schéma est identique pour les trois formes précoces : une seule injection IM de 2,4 MU de benzathine-benzylpénicilline. Si le TNT ne baisse pas assez, avis spécialisé et 3 injections à 8 jours d'intervalle.","src":"p. 197-198","deep":"**Pourquoi** : le schéma est le même pour les trois formes précoces : 2,4 MU de benzathine-benzylpénicilline en une injection IM, sauf allergie ou contre-indication aux injections IM (p. 197-198).\n**Piège** : le diagnostic de latente précoce n'est acceptable que si le patient fournit une sérologie négative de moins de 1 an (p. 197).\n**À relier** : suivi clinique et biologique à 3 mois, 6 mois, 1 an puis tous les ans jusqu'à négativation (p. 198)."},{"id":"d162-qroc-215","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement"],"difficulty":2,"question":"Quel traitement de la syphilis précoce chez un patient allergique à la pénicilline (hors grossesse et infection par le VIH) ?","answer":"Doxycycline 100 mg matin et soir pendant 14 jours","accept":["doxycycline","doxycycline 14 jours","doxycycline 100 mg x2 pendant 14 jours"],"keywords":["doxycycline"],"explanation":"En cas d'allergie : cure de 14 jours de doxycycline (100 mg matin et soir). Chez la femme enceinte et le patient séropositif pour le VIH, on s'oriente vers une induction de tolérance à la pénicilline.","src":"p. 198","deep":"**Pourquoi** : en cas d'allergie à la pénicilline, on prescrit une cure de 14 jours de doxycycline, 100 mg matin et soir (p. 198).\n**Piège** : exception chez la femme enceinte et le patient séropositif pour le VIH : indication d'une induction de tolérance (p. 198) ; dans ces situations délicates, il ne faut pas hésiter à contacter un spécialiste (p. 197).\n**À relier** : une réaction d'Herxheimer après l'injection n'est pas une allergie à la pénicilline (p. 198)."},{"id":"d162-qroc-216","type":"QROC","rank":"B","objective":"d162-obj-28","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle réaction bénigne, due à la lyse des tréponèmes, peut survenir quelques heures après l'injection de pénicilline dans la syphilis secondaire ?","answer":"La réaction d'Herxheimer","accept":["herxheimer","réaction d'herxheimer","reaction d herxheimer"],"keywords":["herxheimer"],"explanation":"Fièvre, céphalées, myalgies et accentuation des signes cutanés : elle est toujours bénigne et ne doit pas être prise pour une allergie à la pénicilline. On prescrit un antipyrétique et on prévient le patient.","src":"p. 198","deep":"**Pourquoi** : la réaction d'Herxheimer est secondaire à la lyse des tréponèmes ; sans gravité au stade primaire, elle associe au stade secondaire fièvre, céphalées, myalgies et accentuation des signes cutanés (p. 198).\n**Piège** : toujours bénigne, elle ne doit pas être interprétée comme une allergie ; aucun protocole ne la prévient, un antipyrétique peut être prescrit (p. 198).\n**À relier** : au stade secondaire, une atteinte ophtalmique ou d'une paire crânienne est une neurosyphilis précoce : ponction lombaire et pénicilline G 14 jours (p. 193)."},{"id":"d162-qroc-217","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["suivi","prévention"],"difficulty":2,"question":"Une personne a eu un contact sexuel il y a plus de 6 semaines avec un patient ayant une syphilis certaine. Sa sérologie est négative : que faire ?","answer":"Refaire la sérologie à 3 mois","accept":["refaire à 3 mois","refaire la sérologie à 3 mois","sérologie à 3 mois","contrôle à 3 mois"],"keywords":["3 mois"],"explanation":"Contact de plus de 6 semaines : on fait une sérologie ; si elle est positive on traite, si elle est négative on la refait à 3 mois.","src":"p. 198","deep":"**Pourquoi** : sujet source certain et contact de plus de 6 semaines : on fait la sérologie ; positive, on traite ; négative, on la refait à 3 mois (p. 198).\n**Piège** : si le contact date de moins de 6 semaines, on n'attend pas : traitement systématique par 2,4 MU de benzathine-benzylpénicilline, avec sérologie (p. 198).\n**À relier** : si la syphilis est douteuse chez le sujet source : examen et sérologie du contact, traitement si positive, contrôle à 3 mois si négative (p. 198)."},{"id":"d162-qroc-218","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["traitement","prévention"],"difficulty":2,"question":"Quelle conduite pour une personne ayant eu un contact sexuel il y a moins de 6 semaines avec un patient ayant une syphilis certaine ?","answer":"Traiter d'emblée (benzathine-benzylpénicilline 2,4 MU IM) + sérologie","accept":["traiter d'emblée","traiter systématiquement","traitement systématique","traitement d'emblée","benzathine"],"keywords":["trait"],"explanation":"Contact de moins de 6 semaines : on traite systématiquement par une injection de 2,4 MU de benzathine-benzylpénicilline, et une sérologie est prélevée.","src":"p. 198","deep":"**Pourquoi** : contact de moins de 6 semaines avec un sujet source certain : on traite systématiquement par une injection de 2,4 MU de benzathine-benzylpénicilline (p. 198).\n**Piège** : traiter ne dispense pas de prélever une sérologie de la syphilis (p. 198).\n**À relier** : au-delà de 6 semaines, la conduite dépend de la sérologie : traiter si positive, la refaire à 3 mois si négative (p. 198)."},{"id":"d162-qroc-219","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement","pièges"],"difficulty":2,"question":"Devant une ulcération génitale, que recommande l'OMS vis-à-vis des résultats des tests sérologiques avant de traiter ?","answer":"Ne pas attendre les résultats du TT et du TNT pour traiter","accept":["ne pas attendre","sans attendre","traiter sans attendre les résultats","ne pas attendre les résultats"],"keywords":["attendre"],"explanation":"Devant une ulcération génitale, il ne faut pas attendre les résultats des tests tréponémique et non tréponémique pour traiter.","src":"p. 197","deep":"**Pourquoi** : selon l'OMS, devant une ulcération génitale on traite sans attendre le résultat du TT et du TNT (p. 197), qui peuvent être négatifs les 7 premiers jours du chancre (p. 196).\n**Piège** : on prescrit quand même un test tréponémique et on recherche une autre IST : gonocoque, C. trachomatis, VIH, hépatite B (p. 197).\n**À relier** : avis spécialisé dans les situations délicates : femme enceinte, sujet séropositif pour le VIH, allergie à la pénicilline (p. 197)."},{"id":"d162-qroc-220","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Quelle cause d'ulcération génitale associe terrain africain, fond sale, douleurs vives et adénopathies inflammatoires ?","answer":"Le chancre mou","accept":["chancre mou","le chancre mou"],"keywords":["chancre mou"],"explanation":"À l'inverse du chancre syphilitique (fond propre, indolore, adénopathie non inflammatoire), le chancre mou est douloureux, à fond sale, avec des adénopathies inflammatoires.","src":"p. 188, 190, 197","deep":"**Pourquoi** : le chancre mou associe terrain (Africains), lésions uniques ou multiples, fond sale, douleurs (+++) et adénopathies inflammatoires (p. 197).\n**Piège** : la donovanose survient sur le même terrain, mais ses lésions granulomateuses sont peu douloureuses (p. 197).\n**À relier** : le chancre syphilitique est à l'opposé : fond propre, indolore, induré, avec une adénopathie non inflammatoire (p. 188, 190)."},{"id":"d162-qroc-221","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Quelle maladie du diagnostic différentiel d'une ulcération génitale associe anorectite, ulcérations anogénitales et diarrhées trompeuses chez des homosexuels ou des sujets africains ?","answer":"La maladie de Nicolas-Favre (lymphogranulomatose vénérienne, LGV)","accept":["nicolas-favre","nicolas favre","maladie de nicolas-favre","lymphogranulomatose vénérienne","lgv"],"keywords":["nicolas"],"explanation":"La maladie de Nicolas-Favre (lymphogranulomatose vénérienne) touche des sujets africains ou homosexuels et associe anorectite, ulcérations anogénitales et diarrhées trompeuses. Avec l'herpès, le chancre mou et la donovanose, elle fait partie des diagnostics à éliminer devant une ulcération génitale (p. 197).","src":"p. 183, 197","deep":"**Pourquoi** : la maladie de Nicolas-Favre (lymphogranulomatose vénérienne) touche des sujets africains ou homosexuels et associe anorectite, ulcérations anogénitales et diarrhées trompeuses (p. 197).\n**Piège** : ses signes peuvent être surtout digestifs (anorectite, diarrhées « trompeuses »), alors qu'elle fait partie du diagnostic différentiel des ulcérations génitales (p. 197).\n**À relier** : devant toute ulcération génitale, on évoque systématiquement la syphilis et on élimine herpès, chancre mou, donovanose et Nicolas-Favre (p. 197)."},{"id":"d162-qroc-222","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["grossesse","complications"],"difficulty":2,"question":"À partir de quand le tréponème franchit-il le placenta, ce qui rend la syphilis grave chez la femme enceinte ?","answer":"Après le 4e mois de grossesse","accept":["4e mois","16 sa","16e semaine","4 mois","quatrième mois"],"keywords":["4e mois"],"explanation":"Chez la femme enceinte, la syphilis est grave : après le 4e mois de grossesse, le passage du tréponème à travers le placenta expose à une atteinte fœtale (p. 200).","src":"p. 188, 200","deep":"**Pourquoi** : la syphilis est grave chez la femme enceinte par risque d'atteinte fœtale, le passage transplacentaire se faisant après le 4e mois de grossesse (p. 200).\n**Piège** : en cas d'allergie à la pénicilline, la doxycycline n'est pas l'option chez la femme enceinte : on s'oriente vers une induction de tolérance (p. 198), avec avis spécialisé (p. 197).\n**À relier** : contracter une syphilis témoigne d'une sexualité à haut risque : on vérifie VIH, hépatite B et autres IST (p. 200)."},{"id":"d162-qroc-223","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["complications","diagnostic"],"difficulty":2,"question":"Au cours d'une syphilis secondaire, une uvéite ou l'atteinte d'une paire crânienne (hypoacousie, paralysie faciale) fait évoquer quoi ?","answer":"Une neurosyphilis précoce","accept":["neurosyphilis","neurosyphilis précoce","syphilis neurologique","neuro syphilis"],"keywords":["neurosyphilis"],"explanation":"Les atteintes ophtalmiques et des paires crâniennes sont des neurosyphilis précoces : on fait une ponction lombaire et, quel que soit son résultat, on traite par pénicilline G pendant 14 jours. Les céphalées seules ne signent pas une atteinte neuroméningée.","src":"p. 193","deep":"**Pourquoi** : une atteinte ophtalmique (surtout uvéite antérieure) ou d'une paire crânienne au stade secondaire est une neurosyphilis précoce : ponction lombaire puis, quel que soit son résultat, pénicilline G 14 jours (p. 193).\n**Piège** : des céphalées isolées ne signent pas une atteinte neuroméningée ; elles sont souvent liées à des micro-abcès périostés (p. 193).\n**À relier** : d'où un interrogatoire ciblé sur la vision : baisse d'acuité, phosphènes, douleurs (p. 193)."},{"id":"d162-qroc-224","type":"QROC","rank":"B","objective":"d162-obj-26","tags":["clinique"],"difficulty":1,"question":"Quelle est la première éruption de la syphilis secondaire (macules rose pâle du tronc, souvent inaperçue, spontanément résolutive en 7 à 10 jours) ?","answer":"La roséole syphilitique","accept":["roséole","roséole syphilitique","roseole","roseole syphilitique"],"keywords":["roséole"],"explanation":"La roséole survient dans les 6 semaines après le chancre. Elle ne doit pas être confondue avec une éruption virale (une primo-infection VIH doit être éliminée) ou une toxidermie.","src":"p. 190, 197, 200","deep":"**Pourquoi** : la roséole est la première éruption du secondaire, dans les 6 semaines après le chancre : macules rose pâle de 5 à 15 mm sur le tronc, sans signes fonctionnels (p. 190).\n**Piège** : elle peut faire évoquer une virose (une primo-infection VIH doit être éliminée) ou une toxidermie (p. 197).\n**À relier** : viennent ensuite les syphilides papuleuses, de couleur cuivrée ; TT et TNT sont toujours positifs au stade secondaire (p. 191, 195)."},{"id":"d162-qroc-225","type":"QROC","rank":"B","objective":"d162-obj-30","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quels sont les deux types d'HPV à haut risque oncogène les plus fréquents ?","answer":"HPV 16 et 18","accept":["16 et 18","hpv 16 et 18","hpv16 et 18","16, 18","hpv 16 18"],"keywords":["16","18"],"explanation":"Les HPV à haut risque oncogène (principalement 16 et 18) sont responsables des lésions précancéreuses puis cancéreuses.","src":"p. 201","deep":"**Pourquoi** : les HPV à haut risque, surtout 16 et 18, sont responsables de lésions précancéreuses puis cancéreuses (p. 201).\n**Piège** : on s'infecte souvent par plusieurs types à la fois, oncogènes et non oncogènes (p. 201) ; et les néoplasies intra-épithéliales sont associées à tous les types d'HPV (p. 202).\n**À relier** : le test HPV-HR type les HPV oncogènes, en particulier 16 et 18 ; il est recommandé en première intention à partir de 30 ans (p. 202)."},{"id":"d162-qroc-226","type":"QROC","rank":"B","objective":"d162-obj-30","tags":["étiologie","épidémiologie"],"difficulty":1,"question":"Quels HPV à bas risque sont responsables d'environ 90 % des condylomes ?","answer":"HPV 6 et 11","accept":["6 et 11","hpv 6 et 11","hpv6 et 11","6, 11"],"keywords":["6","11"],"explanation":"Les HPV 6 et 11, à bas risque, causent près de 90 % des verrues génitales. Lors d'une infection, on peut être infecté à la fois par des types non oncogènes et oncogènes.","src":"p. 201","deep":"**Pourquoi** : les HPV à bas risque, le plus souvent 6 et 11, causent près de 90 % des verrues génitales (p. 201).\n**Piège** : des condylomes restent le marqueur possible d'une infection par des HPV oncogènes, d'où l'examen gynécologique chez la femme (p. 204).\n**À relier** : le vaccin nonavalent couvre les HPV 6, 11, 16, 18, 31, 33, 45, 52 et 58 (p. 206)."},{"id":"d162-qroc-227","type":"QROC","rank":"A","objective":"d162-obj-37","tags":["clinique"],"difficulty":1,"question":"Quel terme imagé désigne l'aspect classique des condylomes acuminés ?","answer":"Les « crêtes-de-coq »","accept":["crêtes-de-coq","crête de coq","crêtes de coq","crete de coq"],"keywords":["coq"],"explanation":"Les condylomes acuminés sont des excroissances charnues couvertes de petites verrucosités kératosiques (0,2 à 1 cm), en nombre variable. Les condylomes plans, eux, sont des maculo-papules rosées parfois à peine visibles.","src":"p. 201","deep":"**Pourquoi** : les condylomes acuminés sont des masses charnues hérissées de petites verrucosités kératosiques de 0,2 à 1 cm, de quelques-unes à plusieurs dizaines (p. 201).\n**Piège** : les condylomes plans, maculo-papules rosées isolées ou en nappe, sont parfois difficiles à voir à l'œil nu : l'acide acétique aide à les visualiser (p. 201).\n**À relier** : le diagnostic est presque exclusivement clinique ; biopsie seulement en cas de doute ou de suspicion de néoplasie (p. 201)."},{"id":"d162-qroc-228","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic","clinique"],"difficulty":2,"question":"Quel produit appliqué sur la peau ou la muqueuse permet de mieux visualiser les condylomes plans ?","answer":"L'acide acétique (à 5 %)","accept":["acide acétique","acide acetique","acide acétique à 5 %","acide acétique 5 %"],"keywords":["acétique"],"explanation":"L'application d'acide acétique à 5 % suivie d'un examen à la loupe est le principe de la colposcopie ; le lugol peut aussi servir à diriger la biopsie sur une zone suspecte.","src":"p. 201-202","deep":"**Pourquoi** : l'application d'acide acétique à 5 %, suivie d'un examen à la loupe, est le principe de la colposcopie et rend visibles les condylomes plans (p. 201).\n**Piège** : le lugol peut aussi être utilisé, avec l'acide acétique, pour diriger la biopsie sur une zone suspecte (p. 202).\n**À relier** : les infections HPV infracliniques se diagnostiquent par frottis, acidoréaction, colposcopie-biopsie et test HPV-HR (p. 206)."},{"id":"d162-qroc-229","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic","prévention"],"difficulty":1,"question":"Devant des verrues anogénitales, que faut-il systématiquement rechercher ?","answer":"Une autre IST associée","accept":["autre ist","ist associée","une autre ist","autre ist associée","ist associee"],"keywords":["ist"],"explanation":"Une autre IST est associée en moyenne dans 25 % des cas : sérologie VIH, test tréponémique, sérologie de l'hépatite B, PCR Chlamydia et gonocoque (urines ou autoprélèvement vaginal), et prélèvements microbiologiques en cas d'urétrite ou de vulvovaginite associée (p. 205).","src":"p. 205-206","deep":"**Pourquoi** : une autre IST est présente en moyenne dans 25 % des cas : sérologie VIH, test tréponémique, sérologie de l'hépatite B et PCR Chlamydia/gonocoque (p. 205).\n**Piège** : on ajoute des prélèvements microbiologiques s'il existe une urétrite ou une vulvovaginite associée (p. 205).\n**À relier** : chez la femme, dépistage des néoplasies cervicales par frottis tous les 3 ans ou test HPV-HR (p. 205)."},{"id":"d162-qroc-230","type":"QROC","rank":"A","objective":"d162-obj-19","tags":["diagnostic","prévention"],"difficulty":1,"question":"À partir de quel âge le test HPV-HR (PCR) est-il recommandé en première intention pour le dépistage chez la femme ?","answer":"À partir de 30 ans","accept":["30 ans","à partir de 30 ans","après 30 ans","plus de 30 ans"],"keywords":["30"],"explanation":"Avant 30 ans, la clairance spontanée des HPV est incomplète : le test serait presque toujours positif sans qu'il existe de pathologie sous-jacente.","src":"p. 202","deep":"**Pourquoi** : avant 30 ans, la clairance spontanée des HPV n'est pas totale : le test HPV-HR serait presque toujours positif sans pathologie sous-jacente (p. 202).\n**Piège** : avant 30 ans, le dépistage cervical repose sur le frottis cervico-vaginal (± colposcopie) ; le test HPV-HR est proposé aux patientes de plus de 30 ans (p. 201-202).\n**À relier** : le test HPV-HR repose sur la biologie moléculaire (hybridation et PCR) et type les HPV oncogènes, en particulier 16 et 18 (p. 202)."},{"id":"d162-qroc-231","type":"QROC","rank":"A","objective":"d162-obj-19","tags":["prévention","suivi"],"difficulty":1,"question":"Quelle est la périodicité du frottis cervico-vaginal de dépistage des néoplasies intra-épithéliales cervicales ?","answer":"Tous les 3 ans (ou test HPV-HR)","accept":["tous les 3 ans","3 ans","tous les trois ans","trois ans"],"keywords":["3 ans"],"explanation":"Le dépistage systématique repose sur un frottis tous les 3 ans ou un test HPV-HR. En cas de dysplasie, même mineure, on réalise une colposcopie et, si besoin, une biopsie dirigée.","src":"p. 205","deep":"**Pourquoi** : le dépistage systématique des néoplasies intra-épithéliales cervicales repose sur un frottis tous les 3 ans ou un test HPV-HR, pour prévenir le cancer du col (p. 205).\n**Piège** : toute dysplasie, même mineure, mène à la colposcopie, avec biopsie dirigée si nécessaire (p. 205).\n**À relier** : dépistage et vaccination anti-HPV assurent ensemble la prévention du cancer du col (p. 206)."},{"id":"d162-qroc-232","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":1,"question":"À quel âge propose-t-on la vaccination anti-HPV à tous les adolescents (filles et garçons) ?","answer":"Entre 11 et 14 ans (rattrapage de 15 à 19 ans révolus)","accept":["11 à 14 ans","11-14 ans","entre 11 et 14 ans","11 et 14 ans"],"keywords":["11","14"],"explanation":"La vaccination est proposée entre 11 et 14 ans, avec rattrapage de 15 à 19 ans révolus, de préférence avant toute contamination. Toute nouvelle vaccination débute par le vaccin nonavalent (Gardasil 9) ; chez les HSH, elle est recommandée jusqu'à 26 ans.","src":"p. 204","deep":"**Pourquoi** : le vaccin est avant tout préventif et doit être fait au mieux avant toute contamination : il est proposé entre 11 et 14 ans, avec rattrapage de 15 à 19 ans révolus (p. 204).\n**Piège** : il concerne les garçons comme les filles ; chez les HSH, il est recommandé jusqu'à 26 ans (p. 204).\n**À relier** : toute nouvelle vaccination commence par le vaccin nonavalent (Gardasil 9) ; 2 doses espacées de 6 à 13 mois entre 11 et 14 ans (p. 204)."},{"id":"d162-qroc-233","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"question":"Quel est le schéma du vaccin nonavalent anti-HPV chez un jeune de 15 à 19 ans révolus ?","answer":"3 doses selon un schéma 0, 2 et 6 mois","accept":["3 doses","0, 2 et 6 mois","0-2-6 mois","trois doses","0 2 6 mois"],"keywords":["3 doses"],"explanation":"De 15 à 19 ans révolus (et chez les HSH jusqu'à 26 ans) : 3 doses à 0, 2 et 6 mois. De 11 à 14 ans révolus : 2 doses espacées de 6 à 13 mois.","src":"p. 204-205","deep":"**Pourquoi** : de 15 à 19 ans révolus, le schéma passe à 3 doses à 0, 2 et 6 mois (p. 205).\n**Piège** : de 11 à 14 ans révolus, 2 doses espacées de 6 à 13 mois suffisent (p. 204) ; chez les HSH jusqu'à 26 ans, 3 doses à 0, 2 et 6 mois (p. 205).\n**À relier** : la vaccination vise les dysplasies cervicales, anales et oropharyngées (p. 204)."},{"id":"d162-qroc-234","type":"QROC","rank":"A","objective":"d162-obj-12","tags":["étiologie"],"difficulty":2,"question":"Parmi la candidose, la vaginose bactérienne et la trichomonose, laquelle est considérée comme une IST ?","answer":"La trichomonose (Trichomonas vaginalis)","accept":["trichomonose","trichomonas vaginalis","trichomonas","la trichomonose"],"keywords":["trichomon"],"explanation":"Trichomonas vaginalis, protozoaire flagellé anaérobie dont le réservoir est le tractus urogénital, est considéré comme une IST, contrairement à la candidose et à la vaginose bactérienne.","src":"p. 206","deep":"**Pourquoi** : l'infection à Trichomonas vaginalis est considérée comme une IST, contrairement à la candidose et à la vaginose bactérienne (p. 206).\n**Piège** : c'est un protozoaire (flagellé, anaérobie), pas une bactérie ; son réservoir naturel est le tractus urogénital (p. 206).\n**À relier** : comme pour toute IST : sérologie VIH, test tréponémique, sérologie de l'hépatite B et PCR biplex Chlamydia/gonocoque (p. 208)."},{"id":"d162-qroc-235","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Citez un traitement oral de la trichomonose (une dose unique de 2 g est possible).","answer":"Métronidazole 2 g en dose unique (ou secnidazole 2 g)","accept":["métronidazole","metronidazole","secnidazole","métronidazole 2 g"],"keywords":["nidazole"],"explanation":"Au choix : métronidazole (2 g en dose unique, ou 500 mg deux fois par jour pendant 7 jours) ou secnidazole 2 g en dose unique. Le(s) partenaire(s) doivent être traités simultanément.","src":"p. 207-208","deep":"**Pourquoi** : au choix : métronidazole PO 2 g en dose unique ou 500 mg deux fois par jour 7 jours, ou secnidazole 2 g en dose unique (p. 207).\n**Piège** : le ou la partenaire doit être traité simultanément, en raison de la forte transmissibilité (p. 208) ; les rares échecs viennent d'une moindre sensibilité au métronidazole (p. 208).\n**À relier** : pas de rapports non protégés pendant le traitement, et éducation sur les IST (p. 208)."},{"id":"d162-qroc-236","type":"QROC","rank":"B","objective":"d162-obj-33","tags":["paraclinique","diagnostic"],"difficulty":2,"question":"Comment pose-t-on le diagnostic direct d'une trichomonose (prélèvement vaginal ou urétral) ?","answer":"Examen direct à l'état frais (parasite mobile) ou PCR","accept":["examen direct à l'état frais","état frais","examen direct","pcr"],"keywords":["frais"],"explanation":"On dépose une goutte de sécrétion entre lame et lamelle : le parasite est mobile. Chez la femme, le recueil se fait dans le cul-de-sac vaginal postérieur ; chez l'homme, sur l'écoulement urétral ou le 1er jet urinaire.","src":"p. 207","deep":"**Pourquoi** : une goutte de sécrétion entre lame et lamelle montre le parasite, qui est mobile ; la PCR est plus récente (p. 207).\n**Piège** : le prélèvement se fait dans le cul-de-sac vaginal postérieur chez la femme, sur l'écoulement ou le 1er jet urinaire chez l'homme ; il est à acheminer rapidement au laboratoire si examen direct (p. 179, 207).\n**À relier** : chez la femme : leucorrhées abondantes, verdâtres, spumeuses et malodorantes, colpite punctiforme « léopard » (p. 207)."},{"id":"d162-qroc-701","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["étiologie","clinique"],"difficulty":1,"question":"Quels sont les principaux sites d'infection du gonocoque chez l'homme et chez la femme ?","answer":"Urètre (homme) ; col et vagin (femme)","accept":["urètre chez l'homme, col chez la femme","urètre et col"],"keywords":["uret","col"],"explanation":"Chez l'homme le gonocoque infecte l'urètre, où le portage asymptomatique est exceptionnel. Chez la femme il infecte le col et le vagin.","src":"p. 180","deep":"**Pourquoi** : le gonocoque infecte surtout l'urètre chez l'homme, le col et le vagin chez la femme (p. 180).\n**Piège** : le portage urétral asymptomatique est exceptionnel chez l'homme, alors que l'infection est asymptomatique dans 70 % des cas chez la femme (p. 180).\n**À relier** : le portage pharyngé est fréquent et le plus souvent asymptomatique chez les homo- ou bisexuels (p. 180)."},{"id":"d162-qroc-702","type":"QROC","rank":"A","objective":"d162-obj-01","tags":["épidémiologie","clinique"],"difficulty":2,"question":"Quelles pratiques sexuelles imposent de rechercher systématiquement un portage pharyngé de gonocoque, le plus souvent asymptomatique ?","answer":"Rapports orogénitaux réceptifs non protégés (partenaires multiples)","accept":["rapports orogénitaux","rapports oro-génitaux","fellation","rapports oraux"],"keywords":["oro"],"explanation":"Le portage pharyngé est fréquent et souvent muet chez les homo- ou bisexuels ; il faut le chercher devant une conduite à risque (partenaires multiples, rapports orogénitaux réceptifs non protégés).","src":"p. 180","deep":"**Pourquoi** : le portage pharyngé du gonocoque, fréquent et le plus souvent muet, impose une recherche systématique en cas de partenaires multiples et de rapports orogénitaux réceptifs non protégés (p. 180).\n**Piège** : l'oropharyngite traitée peut persister, car les antibiotiques y diffusent mal, ce qui maintient la chaîne de contamination (p. 180).\n**À relier** : le prélèvement pharyngé et/ou anal s'ajoute au prélèvement génital selon les pratiques sexuelles, dans les deux sexes (p. 181)."},{"id":"d162-qroc-703","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la manifestation la plus fréquente de la gonococcie non compliquée chez l'homme ?","answer":"L'urétrite antérieure aiguë","accept":["urétrite antérieure aiguë","urétrite aiguë","urétrite"],"keywords":["uretrite"],"explanation":"L'urétrite antérieure aiguë est la manifestation la plus fréquente : écoulement purulent, dysurie, brûlures urétrales, prurit. Le tableau est le plus souvent bruyant mais peut être asymptomatique.","src":"p. 180","deep":"**Pourquoi** : l'urétrite antérieure aiguë est la manifestation la plus fréquente : écoulement purulent (90 %), dysurie, brûlures, prurit urétral (p. 180).\n**Piège** : le tableau est le plus souvent bruyant, mais il peut être asymptomatique (p. 180).\n**À relier** : l'incubation est courte (2 à 7 jours) et le malade est contagieux (p. 180)."},{"id":"d162-qroc-704","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quelles atteintes de l'orifice urétral et du gland peuvent accompagner une urétrite gonococcique ?","answer":"Méatite, voire balanite","accept":["méatite","balanite"],"keywords":["meatite"],"explanation":"À côté de l'écoulement, de la dysurie et des brûlures, l'inflammation du méat (méatite) voire du gland (balanite) est possible.","src":"p. 180","deep":"**Pourquoi** : à côté de l'écoulement purulent, de la dysurie, des brûlures et du prurit urétral, on peut observer une méatite, voire une balanite (p. 180).\n**Piège** : dans l'urétrite à C. trachomatis, le tableau est plus discret : écoulement dans moins de 50 % des cas, le plus souvent clair, modéré et intermittent (p. 184).\n**À relier** : l'urétrite antérieure aiguë est la manifestation la plus fréquente chez l'homme (p. 180)."},{"id":"d162-qroc-705","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quelle proportion des anorectites gonococciques est asymptomatique ?","answer":"Les deux tiers (2/3)","accept":["2/3","deux tiers","les deux tiers"],"keywords":["tiers"],"explanation":"L'anorectite gonococcique est asymptomatique dans 2 cas sur 3 ; quand elle est symptomatique : prurit anal, anite, écoulement rectal purulent, saignements, diarrhée.","src":"p. 180","deep":"**Pourquoi** : l'anorectite gonococcique est asymptomatique dans 2/3 des cas ; sinon prurit anal, anite, écoulement rectal purulent, diarrhée, saignements (p. 180).\n**Piège** : chez la femme, l'anorectite gonococcique est plus rare que chez l'homme (p. 181).\n**À relier** : selon les pratiques sexuelles, un prélèvement anal s'ajoute au prélèvement génital, dans les deux sexes (p. 181)."},{"id":"d162-qroc-706","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":2,"question":"Quels signes composent le syndrome rectal d'une anorectite gonococcique symptomatique ?","answer":"Ténesme, épreintes, diarrhée mucopurulente","accept":["ténesme","épreintes","diarrhée mucopurulente"],"keywords":["tenesme"],"explanation":"Le syndrome rectal associe ténesme, épreintes et diarrhée mucopurulente ; une sensation de défécation incomplète est citée à part (« et/ou »). L'anorectite gonococcique reste asymptomatique dans 2/3 des cas (p. 180).","src":"p. 180","deep":"**Pourquoi** : le syndrome rectal associe ténesme, épreintes et diarrhée mucopurulente ; la sensation de défécation incomplète est citée à part, à côté de ce syndrome (« et/ou ») (p. 180).\n**Piège** : l'anorectite gonococcique est pourtant le plus souvent muette (2/3 des cas) : on la cherche par prélèvement anal selon les pratiques (p. 180-181).\n**À relier** : la maladie de Nicolas-Favre associe elle aussi anorectite et diarrhées trompeuses (p. 197)."},{"id":"d162-qroc-707","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique","physiopathologie"],"difficulty":2,"question":"Pourquoi une oropharyngite gonococcique traitée peut-elle persister et entretenir la chaîne de contamination ?","answer":"Mauvaise diffusion des antibiotiques à ce niveau","accept":["mauvaise diffusion des antibiotiques","mauvaise diffusion","diffusion insuffisante"],"keywords":["diffusion"],"explanation":"L'oropharyngite est le plus souvent asymptomatique ; comme les antibiotiques diffusent mal dans cette localisation, le portage persiste après traitement et le patient reste contaminant.","src":"p. 180","deep":"**Pourquoi** : les antibiotiques diffusent mal dans l'oropharynx : c'est ce qui explique le portage persistant après traitement et le maintien de la chaîne de contamination (p. 180).\n**Piège** : l'oropharyngite gonococcique est le plus souvent asymptomatique : elle ne se voit pas, il faut la chercher (p. 180).\n**À relier** : portage pharyngé à rechercher systématiquement si partenaires multiples et rapports orogénitaux réceptifs non protégés (p. 180)."},{"id":"d162-qroc-708","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"Citez un signe fonctionnel d'une cervicite gonococcique symptomatique chez la femme.","answer":"Leucorrhées purulentes ou pesanteur pelvienne","accept":["leucorrhées purulentes","pesanteur pelvienne","signes d'urétrite"],"keywords":["leucorrh","pesanteur"],"explanation":"La cervicite est la manifestation la plus fréquente chez la femme ; elle donne des leucorrhées purulentes, une pesanteur pelvienne, parfois des signes d'urétrite. Mais 70 % des infections non compliquées sont asymptomatiques.","src":"p. 180-181","deep":"**Pourquoi** : la cervicite gonococcique donne des leucorrhées purulentes, une pesanteur pelvienne, parfois des signes d'urétrite (p. 181).\n**Piège** : 70 % des gonococcies féminines non compliquées sont asymptomatiques (p. 180).\n**À relier** : à l'examen, le col est non ou peu inflammatoire avec un écoulement purulent à l'orifice cervical (p. 181)."},{"id":"d162-qroc-709","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Dans quel sexe et dans quelle région métropolitaine l'incidence de la gonococcie est-elle la plus élevée ?","answer":"Chez les hommes ; en Île-de-France","accept":["hommes et île-de-france","hommes, île-de-france"],"keywords":["homme","ile de france"],"explanation":"L'incidence de la gonococcie augmente ; elle est plus élevée chez les hommes que chez les femmes et plus élevée en Île-de-France qu'ailleurs en métropole.","src":"p. 180","deep":"**Pourquoi** : l'incidence de la gonococcie augmente ; elle est plus élevée chez les hommes et en Île-de-France qu'ailleurs en métropole (p. 180).\n**Piège** : la gonococcie reste beaucoup moins fréquente que la chlamydiose, 50 fois plus fréquente (p. 183).\n**À relier** : l'incidence des urétrites gonococciques est en augmentation en France depuis 1998 (p. 187)."},{"id":"d162-qroc-710","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["épidémiologie","physiopathologie"],"difficulty":2,"question":"Quel mécanisme explique la résistance du gonocoque à la pénicilline (15 % des souches) ?","answer":"La production de β-lactamase","accept":["lactamase","bêta-lactamase","production de lactamase"],"keywords":["lactamase"],"explanation":"15 % des souches produisent une β-lactamase ; les résistances touchent aussi les cyclines (20 %) et la ciprofloxacine (40 %).","src":"p. 180","deep":"**Pourquoi** : 15 % des souches résistent à la pénicilline par production de β-lactamase (p. 180).\n**Piège** : la résistance est encore plus fréquente pour les cyclines (20 %) et la ciprofloxacine (40 %) (p. 180).\n**À relier** : le traitement de première intention est la ceftriaxone 1000 mg IM unique (p. 182) ; les CMI des C3G augmentent, avec quelques résistances vraies (p. 180)."},{"id":"d162-qroc-711","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["épidémiologie"],"difficulty":2,"question":"Quelle est la fréquence de la résistance du gonocoque à la ciprofloxacine ?","answer":"40 % des souches","accept":["40 %","40"],"keywords":["40"],"explanation":"La résistance à la ciprofloxacine (40 %) dépasse celle aux cyclines (20 %) et à la pénicilline (15 %) (p. 180) ; en cas d'allergie aux β-lactamines, la ciprofloxacine 500 mg n'est utilisée qu'avec antibiogramme (p. 182).","src":"p. 180","deep":"**Pourquoi** : 40 % des souches de gonocoque sont résistantes à la ciprofloxacine, contre 20 % pour les cyclines et 15 % pour la pénicilline (p. 180).\n**Piège** : en cas d'allergie aux β-lactamines, la ciprofloxacine 500 mg PO reste une option, mais seulement avec antibiogramme (p. 182).\n**À relier** : la culture fournit un antibiogramme en 24 à 48 heures, utile au suivi des résistances (p. 182)."},{"id":"d162-qroc-712","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["épidémiologie"],"difficulty":2,"question":"Quelle évolution préoccupante de la sensibilité du gonocoque aux céphalosporines de 3e génération est observée ?","answer":"Augmentation des CMI, avec résistances vraies ponctuelles","accept":["augmentation des cmi","cmi augmentées","hausse des cmi"],"keywords":["cmi"],"explanation":"Les CMI des céphalosporines de 3e génération augmentent et de rares résistances vraies sont observées : d'où la nécessité de réactualiser régulièrement les schémas.","src":"p. 180","deep":"**Pourquoi** : les CMI des céphalosporines de 3e génération augmentent et des résistances vraies sont observées ponctuellement (p. 180).\n**Piège** : la ceftriaxone reste pourtant le traitement de première intention : 1000 mg en IM unique (p. 182).\n**À relier** : l'émergence de souches résistantes impose de réactualiser régulièrement les schémas thérapeutiques (p. 187)."},{"id":"d162-qroc-713","type":"QROC","rank":"B","objective":"d162-obj-36","tags":["pédiatrie","complications"],"difficulty":2,"question":"Quelle atteinte néonatale rare le gonocoque peut-il provoquer chez le nouveau-né d'une mère infectée ?","answer":"Une conjonctivite purulente","accept":["conjonctivite purulente","conjonctivite"],"keywords":["conjonctivite"],"explanation":"Le tableau de synthèse mentionne une rare conjonctivite purulente néonatale pour le gonocoque, alors que C. trachomatis donne une conjonctivite (kératoconjonctivite) et une pneumopathie.","src":"p. 186","deep":"**Pourquoi** : le tableau de synthèse retient pour le gonocoque une transmission néonatale rare sous forme de conjonctivite purulente (p. 186).\n**Piège** : avec C. trachomatis, l'atteinte néonatale comprend une conjonctivite (kératoconjonctivite) et une pneumopathie (p. 185-186).\n**À relier** : ophtalmie ou pneumopathie néonatale à Chlamydia : érythromycine 12,5 mg/kg/6 h pendant 14 jours (p. 186)."},{"id":"d162-qroc-714","type":"QROC","rank":"A","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Chez un homme symptomatique sans écoulement urétral, quel prélèvement bactériologique est préférable ?","answer":"1er jet d'urine, ≥ 2 h après la dernière miction","accept":["1er jet d'urine","premier jet d'urine","1er jet urinaire","premier jet"],"keywords":["jet"],"explanation":"En l'absence d'écoulement, on prélève au mieux un 1er jet d'urine (au moins 2 heures après la dernière miction), sinon un prélèvement endo-urétral.","src":"p. 181","deep":"**Pourquoi** : chez l'homme symptomatique, on prélève l'écoulement urétral spontané ; à défaut, au mieux un 1er jet d'urine au moins 2 heures après la dernière miction, sinon un prélèvement endo-urétral (p. 181).\n**Piège** : le prélèvement endo-urétral ne vient qu'en dernier recours, après le 1er jet d'urine (p. 181).\n**À relier** : en dépistage, le 1er jet urinaire de 10 à 20 mL sert à la PCR, souvent biplex avec C. trachomatis (p. 181)."},{"id":"d162-qroc-715","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Quels sont les seuils de polynucléaires neutrophiles définissant l'urétrite « biologique » au frottis urétral (grossissement 100 puis 400) ?","answer":"> 5 PNN (×100) ou > 10 PNN (×400)","accept":["5 et 10","5 pnn ou 10 pnn","plus de 5 et plus de 10"],"keywords":["5","10"],"explanation":"L'urétrite biologique est définie par plus de 5 PNN au grossissement 100 ou plus de 10 PNN au grossissement 400.","src":"p. 181","deep":"**Pourquoi** : l'urétrite « biologique » se définit par plus de 5 polynucléaires neutrophiles au grossissement 100, ou plus de 10 au grossissement 400 (p. 181).\n**Piège** : ne pas inverser les seuils : le seuil le plus bas (> 5) va avec le grossissement le plus faible (× 100) (p. 181).\n**À relier** : au même frottis, des diplocoques Gram négatif intracellulaires « en grains de café » orientent vers le gonocoque (p. 181)."},{"id":"d162-qroc-716","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Quelle expression imagée décrit l'aspect des diplocoques du gonocoque à l'examen direct ?","answer":"Diplocoques « en grains de café »","accept":["grains de café","grain de café","en grains de café"],"keywords":["cafe"],"explanation":"À l'examen direct (Gram ou bleu de méthylène), les diplocoques à Gram négatif sont intracellulaires, en « grains de café ».","src":"p. 181","deep":"**Pourquoi** : à l'examen direct (Gram ou bleu de méthylène), les diplocoques à Gram négatif intracellulaires ont un aspect « en grains de café » (p. 181).\n**Piège** : la localisation compte : un diplocoque extracellulaire ne donne pas de certitude, car il existe des Neisseria non pathogènes (p. 181).\n**À relier** : sensibilité et spécificité > 95 % dans l'urétrite masculine symptomatique, moins bonnes ailleurs et chez la femme (p. 181)."},{"id":"d162-qroc-717","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":3,"question":"Quelle est la sensibilité de l'examen direct dans l'urétrite masculine symptomatique à gonocoque ?","answer":"Sensibilité et spécificité > 95 %","accept":["> 95","95 %","95"],"keywords":["95"],"explanation":"Dans l'urétrite masculine symptomatique, l'examen direct a une sensibilité et une spécificité > 95 % ; elles sont moins bonnes aux autres sites et chez la femme.","src":"p. 181","deep":"**Pourquoi** : dans l'urétrite masculine symptomatique, l'examen direct a une bonne sensibilité et une spécificité > 95 % (p. 181).\n**Piège** : pour les autres sites et chez la femme, sensibilité et spécificité sont moins bonnes (p. 181).\n**À relier** : la culture sur gélose au sang cuit, systématique, confirme le diagnostic et donne l'antibiogramme (p. 182)."},{"id":"d162-qroc-718","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique","pièges"],"difficulty":2,"question":"Pourquoi l'identification de diplocoques extracellulaires ne suffit-elle pas à affirmer une gonococcie ?","answer":"Il existe des Neisseria non pathogènes","accept":["neisseria non pathogènes","neisseria non pathogenes","autres neisseria"],"keywords":["pathog"],"explanation":"Une forme extracellulaire ne donne pas de certitude diagnostique, car il existe des Neisseria non pathogènes ; l'aspect décrit à l'examen direct est celui de diplocoques à Gram négatif intracellulaires « en grains de café ». La culture, systématique, confirme le diagnostic (p. 181-182).","src":"p. 181","deep":"**Pourquoi** : il existe des Neisseria non pathogènes : un diplocoque extracellulaire ne donne pas de certitude diagnostique (p. 181).\n**Piège** : c'est l'aspect intracellulaire « en grains de café » qui est décrit à l'examen direct de l'urétrite gonococcique (p. 181).\n**À relier** : la culture, systématique, confirme le diagnostic et fournit un antibiogramme en 24 à 48 heures (p. 182)."},{"id":"d162-qroc-719","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Sur quel milieu la culture du gonocoque est-elle réalisée systématiquement ?","answer":"Gélose au sang cuit (gélose chocolat)","accept":["gélose chocolat","chocolat","sang cuit","gélose au sang cuit"],"keywords":["chocolat"],"explanation":"La culture sur gélose au sang cuit (« gélose chocolat ») est systématique : elle confirme le diagnostic et fournit un antibiogramme en 24 à 48 h.","src":"p. 182","deep":"**Pourquoi** : le gonocoque est mis en culture sur gélose au sang cuit (« gélose chocolat ») ; elle confirme le diagnostic et donne un antibiogramme en 24 à 48 heures (p. 182).\n**Piège** : la culture est moins sensible à l'oropharynx, à l'anus et au col : on y préfère la PCR (p. 182).\n**À relier** : la PCR ne permet pas de tester la sensibilité de la souche (p. 182)."},{"id":"d162-qroc-720","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"question":"Quel avantage de la culture du gonocoque, au-delà de la confirmation diagnostique, justifie qu'elle reste systématique ?","answer":"Elle donne un antibiogramme en 24-48 h (suivi des résistances)","accept":["antibiogramme","antibiogramme en 24 à 48 heures"],"keywords":["antibiogramme"],"explanation":"L'antibiogramme obtenu en 24 à 48 h est utile pour surveiller les résistances, d'autant que les souches deviennent moins sensibles aux antibiotiques.","src":"p. 182","deep":"**Pourquoi** : la culture donne un antibiogramme en 24 à 48 heures, utile pour le suivi des résistances (p. 182).\n**Piège** : la PCR, plus sensible aux sites oropharyngé, anal et cervical, ne teste pas la sensibilité de la souche (p. 182).\n**À relier** : résistances du gonocoque : pénicilline 15 %, cyclines 20 %, ciprofloxacine 40 % ; CMI des C3G en hausse (p. 180)."},{"id":"d162-qroc-721","type":"QROC","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":3,"question":"À l'oropharynx, à l'anus et au col, la PCR est plus sensible que la culture : quel est son inconvénient ?","answer":"Elle ne permet pas de tester la sensibilité de la souche","accept":["pas d'antibiogramme","pas de test de sensibilité","ne donne pas d'antibiogramme","sensibilité de la souche"],"keywords":["sensibilite"],"explanation":"La culture est moins sensible à ces sites, d'où l'intérêt de la PCR ; en revanche, la PCR ne donne pas l'antibiogramme.","src":"p. 182","deep":"**Pourquoi** : à l'oropharynx, à l'anus et au col, la culture est moins sensible, d'où l'intérêt de la PCR ; mais celle-ci ne permet pas de tester la sensibilité de la souche (p. 182).\n**Piège** : à l'oropharynx, si l'antibiogramme est impossible, on préconise la ceftriaxone 1000 mg (p. 182).\n**À relier** : à ce site, les antibiotiques diffusent mal, d'où un portage persistant après traitement (p. 180)."},{"id":"d162-qroc-722","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":1,"question":"Quel type de traitement, délivré sur le lieu même de la consultation, est recommandé dans la gonococcie ?","answer":"Le traitement minute (dose unique)","accept":["traitement minute","dose unique","minute"],"keywords":["minute"],"explanation":"Le traitement minute, en dose unique délivrée sur le lieu même de la consultation, est recommandé dans la gonococcie (p. 182).","src":"p. 182","deep":"**Pourquoi** : le traitement minute, en dose unique délivrée sur le lieu de la consultation, est recommandé dans la gonococcie (p. 182).\n**Piège** : pour C. trachomatis, la prise unique (azithromycine) est remise en question par les résistances de Mycoplasma genitalium : on privilégie la doxycycline 7 jours avec la ceftriaxone (p. 187).\n**À relier** : le traitement probabiliste immédiat du patient et de ses contacts sexuels garde un intérêt épidémiologique et économique (p. 187)."},{"id":"d162-qroc-723","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"question":"Quelle particularité du traitement d'une urétrite gonococcique faut-il connaître chez un patient infecté par le VIH ?","answer":"Aucune : le traitement est identique","accept":["identique","le même traitement","aucune"],"keywords":["identique"],"explanation":"Le traitement des urétrites est identique en cas d'infection par le VIH.","src":"p. 182","deep":"**Pourquoi** : le traitement des urétrites est identique en cas d'infection par le VIH (p. 182).\n**Piège** : la même règle vaut pour la syphilis primaire ou secondaire : traitement standard par pénicilline chez le sujet séropositif (p. 199).\n**À relier** : chez les patients VIH engagés dans des pratiques à risque, sérologie de la syphilis au moins 1 fois par an (p. 199)."},{"id":"d162-qroc-724","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["prévention","pièges"],"difficulty":1,"question":"Quel risque faut-il souligner (par l'éducation du patient) après le traitement d'une IST ?","answer":"Le risque de recontamination","accept":["recontamination","réinfection","recontaminer"],"keywords":["recontam"],"explanation":"Pour toute IST, on identifie les partenaires, on propose un dépistage, on insiste sur le risque de recontamination et on éduque le patient.","src":"p. 182","deep":"**Pourquoi** : comme pour toute IST, on insiste sur les risques de recontamination par l'éducation du patient (p. 182).\n**Piège** : la syphilis n'est pas immunisante : une recontamination se voit à la clinique et à la remontée du TNT (titre multiplié au moins par 4) (p. 195).\n**À relier** : en cas de prises de risque trop régulières, on envisage une PrEP contre le VIH (p. 182)."},{"id":"d162-qroc-725","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Dans quelle situation donne-t-on la ceftriaxone par voie IV plutôt qu'IM dans une gonococcie non compliquée ?","answer":"En cas d'anomalie de l'hémostase","accept":["anomalie de l'hémostase","trouble de l'hémostase","troubles de la coagulation","hémostase"],"keywords":["hemostase"],"explanation":"La ceftriaxone 1000 mg se donne en IM unique, ou en IV en cas d'anomalie de l'hémostase (p. 182).","src":"p. 182","deep":"**Pourquoi** : la ceftriaxone 1000 mg se donne en IM unique, ou en IV en cas d'anomalie de l'hémostase (p. 182).\n**Piège** : la dose ne change pas avec la voie : 1000 mg en dose unique dans les deux cas (p. 182).\n**À relier** : on y associe toujours un traitement anti-Chlamydia, doxycycline 7 jours de préférence (p. 182)."},{"id":"d162-qroc-726","type":"QROC","rank":"B","objective":"d162-obj-20","tags":["traitement"],"difficulty":2,"question":"Citez un antibiotique de remplacement de la ceftriaxone, en dose unique, en cas d'allergie aux β-lactamines dans une gonococcie non compliquée.","answer":"Azithromycine, gentamycine ou ciprofloxacine","accept":["azithromycine","gentamycine","gentamicine","ciprofloxacine"],"keywords":["azithromycine","gentamycine","ciprofloxacine"],"explanation":"Trois alternatives en dose unique : azithromycine 2 g PO, gentamycine 240 mg IM, ciprofloxacine 500 mg PO (cette dernière seulement avec antibiogramme).","src":"p. 182","deep":"**Pourquoi** : allergie aux β-lactamines : azithromycine 2 g PO, gentamycine 240 mg IM ou ciprofloxacine 500 mg PO, en dose unique (p. 182).\n**Piège** : la ciprofloxacine n'est donnée qu'avec antibiogramme (p. 182) ; 40 % des souches y sont résistantes (p. 180).\n**À relier** : chez la femme enceinte, quinolones, cyclines et aminosides sont contre-indiqués (p. 182)."},{"id":"d162-qroc-727","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle dose d'azithromycine en prise unique traite un gonocoque chez un patient allergique aux β-lactamines ?","answer":"2 g par voie orale","accept":["2 g","2g","2000 mg","2 grammes"],"keywords":["2 g"],"explanation":"Contre le gonocoque (allergie aux β-lactamines) l'azithromycine est donnée à 2 g en dose unique ; contre Chlamydia, la dose unique est de 1 g.","src":"p. 182","deep":"**Pourquoi** : contre le gonocoque, en cas d'allergie aux β-lactamines, l'azithromycine se donne à 2 g PO en dose unique (p. 182).\n**Piège** : ne pas confondre avec la dose anti-Chlamydia d'azithromycine, 1 g en prise unique (p. 185).\n**À relier** : l'azithromycine favorise des résistances de Mycoplasma genitalium (p. 185)."},{"id":"d162-qroc-728","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":3,"question":"Quelles trois classes d'antibiotiques sont contre-indiquées chez la femme enceinte atteinte de gonococcie ?","answer":"Quinolones, cyclines, aminosides","accept":["quinolones, cyclines, aminosides","quinolones cyclines aminosides"],"keywords":["quinolone","cycline","aminoside"],"explanation":"Chez la femme enceinte on évite quinolones, cyclines et aminosides ; on utilise la ceftriaxone IM ou le céfixime oral.","src":"p. 182","deep":"**Pourquoi** : chez la femme enceinte, quinolones, cyclines et aminosides sont contre-indiqués ; on donne la ceftriaxone 1000 mg IM unique ou le céfixime 400 mg PO unique (p. 182).\n**Piège** : le céfixime se donne à 400 mg chez la femme enceinte, mais à 800 mg dans l'orchiépididymite (p. 182).\n**À relier** : pour C. trachomatis chez la femme enceinte : azithromycine 1 g en prise unique, PCR systématique à 1 mois (p. 186)."},{"id":"d162-qroc-729","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":2,"question":"Quelle dose de céfixime en prise orale unique traite la gonococcie non compliquée de la femme enceinte ?","answer":"400 mg","accept":["400 mg","400"],"keywords":["400"],"explanation":"Chez la femme enceinte : ceftriaxone 1000 mg IM unique ou céfixime 400 mg per os en prise unique.","src":"p. 182","deep":"**Pourquoi** : chez la femme enceinte : ceftriaxone 1000 mg IM unique ou céfixime 400 mg en prise orale unique (p. 182).\n**Piège** : dans l'orchiépididymite, la dose de céfixime est de 800 mg (p. 182) : ne pas mélanger les deux.\n**À relier** : quinolones, cyclines et aminosides sont contre-indiqués pendant la grossesse (p. 182)."},{"id":"d162-qroc-730","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quelle dose de céfixime en prise orale unique peut remplacer la ceftriaxone dans une orchiépididymite gonococcique ?","answer":"800 mg","accept":["800 mg","800"],"keywords":["800"],"explanation":"L'orchiépididymite se traite par ceftriaxone 1000 mg IM unique ou céfixime 800 mg per os unique (400 mg chez la femme enceinte).","src":"p. 182","deep":"**Pourquoi** : orchiépididymite gonococcique : ceftriaxone 1000 mg IM unique ou céfixime 800 mg en prise orale unique (p. 182).\n**Piège** : chez la femme enceinte, le céfixime est donné à 400 mg (p. 182).\n**À relier** : orchiépididymite à C. trachomatis : doxycycline 100 mg/12 h pendant 10 jours (p. 186)."},{"id":"d162-qroc-731","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"À l'oropharynx, quel antibiotique est préconisé dans la gonococcie quand un antibiogramme est impossible ?","answer":"La ceftriaxone 1000 mg","accept":["ceftriaxone","ceftriaxone 1000 mg","ceftriaxone 1 g"],"keywords":["ceftriaxone"],"explanation":"Les antibiotiques diffusent mal à l'oropharynx : en l'absence d'antibiogramme on garde la ceftriaxone 1000 mg.","src":"p. 182","deep":"**Pourquoi** : à l'oropharynx, où les antibiotiques diffusent mal, la ceftriaxone 1000 mg est préconisée si l'antibiogramme est impossible (p. 182).\n**Piège** : à ce site, la culture est moins sensible et la PCR ne fournit pas la sensibilité de la souche (p. 182).\n**À relier** : la mauvaise diffusion explique le portage persistant après traitement (p. 180)."},{"id":"d162-qroc-732","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","complications"],"difficulty":2,"question":"Quelle est la prise en charge d'une septicémie gonococcique ?","answer":"Hospitalisation + ceftriaxone 1 g/j IV, 7 à 10 jours","accept":["hospitalisation et ceftriaxone","ceftriaxone iv 7 à 10 jours"],"keywords":["hospital","ceftriaxone"],"explanation":"La septicémie gonococcique impose l'hospitalisation et la ceftriaxone IV 1 g/jour pendant 7 à 10 jours.","src":"p. 182","deep":"**Pourquoi** : la septicémie gonococcique impose une hospitalisation et la ceftriaxone 1 g/jour IV pendant 7 à 10 jours (p. 182).\n**Piège** : méningite et endocardite demandent plus : ceftriaxone 1 à 2 g/jour IV, 10 à 14 jours pour la méningite et 4 semaines pour l'endocardite (p. 182-183).\n**À relier** : signes de septicémie : fièvre, purpura pétéchial, papulo-pustules acrales ou périarticulaires, arthrites septiques, ténosynovites (p. 181)."},{"id":"d162-qroc-733","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","complications"],"difficulty":2,"question":"Quelle est la durée de la ceftriaxone IV (1 à 2 g/jour) dans une méningite gonococcique ?","answer":"10 à 14 jours","accept":["10 à 14 jours","10-14 jours","10 à 14"],"keywords":["10","14"],"explanation":"Méningite : ceftriaxone IV 1 à 2 g/jour pendant 10 à 14 jours, avec hospitalisation.","src":"p. 182-183","deep":"**Pourquoi** : méningite gonococcique : hospitalisation et ceftriaxone 1 à 2 g/jour IV pendant 10 à 14 jours (p. 182-183).\n**Piège** : l'endocardite demande 4 semaines, la septicémie 7 à 10 jours (à 1 g/jour) (p. 182-183).\n**À relier** : méningite et endocardite sont des complications rares de la gonococcie, comme la péri-hépatite (p. 181)."},{"id":"d162-qroc-734","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","complications"],"difficulty":2,"question":"Quelle est la durée de la ceftriaxone IV (1 à 2 g/jour) dans une endocardite gonococcique ?","answer":"4 semaines","accept":["4 semaines","quatre semaines","un mois"],"keywords":["4 semaines"],"explanation":"Endocardite : hospitalisation et ceftriaxone IV 1 à 2 g/jour pendant 4 semaines (10 à 14 jours seulement pour une méningite).","src":"p. 182-183","deep":"**Pourquoi** : endocardite gonococcique : hospitalisation et ceftriaxone 1 à 2 g/jour IV pendant 4 semaines (p. 182-183).\n**Piège** : avec la même posologie, la méningite se traite 10 à 14 jours (p. 183).\n**À relier** : septicémie à gonocoque : ceftriaxone 1 g/jour IV pendant 7 à 10 jours (p. 182)."},{"id":"d162-qroc-735","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":2,"question":"Quel traitement antibiotique de l'endométrite ou de la salpingite gonococcique (dose, voie, durée) ?","answer":"Ceftriaxone 1 g/jour IV pendant 14 jours","accept":["ceftriaxone 1 g par jour 14 jours","ceftriaxone iv 14 jours"],"keywords":["ceftriaxone","14"],"explanation":"L'infection génitale haute gonococcique est traitée par ceftriaxone 1 g/jour IV pendant 14 jours.","src":"p. 183","deep":"**Pourquoi** : endométrite ou salpingite gonococcique : ceftriaxone 1 g/jour IV pendant 14 jours (p. 183).\n**Piège** : en probabiliste, une IGH non compliquée reçoit ceftriaxone 1 g IV/IM en dose unique + doxycycline et métronidazole 10 jours (recommandations 2018) (p. 186).\n**À relier** : la prise en charge des infections génitales hautes est souvent initialement probabiliste (p. 186)."},{"id":"d162-qroc-736","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":1,"question":"À quel moment réalise-t-on le contrôle clinique systématique après le traitement d'une gonococcie ?","answer":"À J7","accept":["j7","7 jours","jour 7","à 7 jours"],"keywords":["j7"],"explanation":"Un contrôle clinique à J7 est systématique ; un contrôle bactériologique n'est demandé que dans certaines situations.","src":"p. 183","deep":"**Pourquoi** : un contrôle clinique est systématique à J7 après le traitement d'une gonococcie (p. 183).\n**Piège** : le contrôle bactériologique à J7 n'est indiqué qu'en cas de persistance des signes cliniques ; dans les formes asymptomatiques, on contrôle la PCR 15 jours après le traitement (p. 183).\n**À relier** : ce contrôle évalue tolérance et efficacité, adapte le traitement aux résultats bactériologiques et sert à les communiquer au patient (p. 183)."},{"id":"d162-qroc-737","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Quels sont les objectifs du contrôle clinique de J7 après un traitement de gonococcie ?","answer":"Tolérance et efficacité, adapter au résultat bactério, informer","accept":["tolérance et efficacité","évaluer la tolérance","adapter le traitement"],"keywords":["tolerance","efficacite"],"explanation":"On évalue tolérance et efficacité, on adapte le traitement aux résultats bactériologiques et on communique les résultats au patient.","src":"p. 183","deep":"**Pourquoi** : à J7, on évalue la tolérance et l'efficacité, on adapte le traitement aux résultats bactériologiques et on communique ces résultats au patient (p. 183).\n**Piège** : un contrôle bactériologique n'est pas systématique : il est indiqué à J7 seulement si les signes persistent (p. 183).\n**À relier** : la culture sur gélose au sang cuit fournit un antibiogramme en 24 à 48 heures (p. 182)."},{"id":"d162-qroc-738","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Dans quel cas un contrôle bactériologique à J7 est-il indiqué après traitement d'une gonococcie ?","answer":"Persistance de signes cliniques","accept":["persistance de signes cliniques","signes cliniques persistants","persistance des signes"],"keywords":["persist"],"explanation":"Le contrôle clinique à J7 est systématique ; le contrôle bactériologique à J7 n'est indiqué qu'en cas de persistance des signes cliniques ; dans les formes asymptomatiques, contrôle de la PCR 15 jours après le traitement (p. 183).","src":"p. 183","deep":"**Pourquoi** : le contrôle bactériologique à J7 est indiqué si des signes cliniques persistent (p. 183).\n**Piège** : il ne faut pas le confondre avec le contrôle clinique de J7, qui est systématique (p. 183).\n**À relier** : dans les formes asymptomatiques, contrôle de la PCR 15 jours après le traitement (p. 183)."},{"id":"d162-qroc-739","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Quand propose-t-on un contrôle de la PCR dans les formes asymptomatiques de gonococcie ?","answer":"15 jours après le traitement","accept":["15 jours","quinze jours","2 semaines"],"keywords":["15"],"explanation":"Dans les formes asymptomatiques, on propose un contrôle par PCR 15 jours après le traitement.","src":"p. 183","deep":"**Pourquoi** : dans les formes asymptomatiques de gonococcie, un contrôle de la PCR est proposé 15 jours après le traitement (p. 183).\n**Piège** : pour C. trachomatis, le contrôle PCR ne doit pas être trop précoce : des débris cellulaires peuvent la rendre faussement positive dans les 4 semaines (p. 185).\n**À relier** : le contrôle clinique à J7, lui, est systématique (p. 183)."},{"id":"d162-qroc-740","type":"QROC","rank":"A","objective":"d162-obj-09","tags":["définition","étiologie"],"difficulty":1,"question":"Quelle est la nature bactériologique de Chlamydia trachomatis (Gram, mode de vie, mobilité) ?","answer":"Bacille à Gram négatif, intracellulaire obligatoire, immobile","accept":["bacille à gram négatif intracellulaire","bacille gram négatif intracellulaire obligatoire"],"keywords":["bacille","intracellul"],"explanation":"C. trachomatis est un bacille à Gram négatif, intracellulaire obligatoire et immobile.","src":"p. 183","deep":"**Pourquoi** : C. trachomatis est un bacille à Gram négatif, intracellulaire obligatoire et immobile (p. 183).\n**Piège** : le gonocoque, lui, est un diplocoque à Gram négatif, intra- ou extracellulaire (p. 179).\n**À relier** : la culture de C. trachomatis est moins sensible que la PCR, examen clé du diagnostic (p. 185)."},{"id":"d162-qroc-741","type":"QROC","rank":"A","objective":"d162-obj-09","tags":["étiologie"],"difficulty":1,"question":"Quels sérotypes de C. trachomatis sont responsables des infections urogénitales courantes ?","answer":"Les sérotypes D à K","accept":["d à k","d-k","sérotypes d à k"],"keywords":["d a k"],"explanation":"Les sérotypes D à K de C. trachomatis sont responsables des infections urogénitales (p. 183).","src":"p. 183","deep":"**Pourquoi** : les sérotypes D à K de C. trachomatis sont responsables des infections urogénitales (p. 183).\n**Piège** : ces infections sont souvent silencieuses : portage asymptomatique dans 50 % des cas chez l'homme et 50 à 90 % chez la femme (p. 184).\n**À relier** : chez la femme, la cervicite est la forme la plus fréquente des chlamydioses urogénitales basses (p. 184)."},{"id":"d162-qroc-742","type":"QROC","rank":"B","objective":"d162-obj-09","tags":["étiologie"],"difficulty":2,"question":"Quelle maladie est due aux sérotypes L1, L2 et L3 de Chlamydia trachomatis ?","answer":"La lymphogranulomatose vénérienne (maladie de Nicolas-Favre)","accept":["lymphogranulomatose vénérienne","lgv","maladie de nicolas-favre","nicolas-favre"],"keywords":["lymphogranulomatose"],"explanation":"Les sérotypes L1-L3 sont responsables de la LGV ou maladie de Nicolas-Favre, qui fait partie du diagnostic différentiel des ulcérations génitales.","src":"p. 183","deep":"**Pourquoi** : les sérotypes L1, L2 et L3 sont responsables de la lymphogranulomatose vénérienne ou maladie de Nicolas-Favre (p. 183).\n**Piège** : elle peut se présenter par une anorectite et des diarrhées trompeuses (p. 197).\n**À relier** : depuis 2003, elle réapparaît chez les homosexuels masculins, avec une forte proportion de patients infectés par le VIH (p. 183)."},{"id":"d162-qroc-743","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quelle bactérie est la première cause d'IST bactérienne dans les pays industrialisés et la première cause identifiée d'urétrite aiguë (devant le gonocoque) ?","answer":"Chlamydia trachomatis","accept":["chlamydia","c. trachomatis","chlamydia trachomatis"],"keywords":["chlamydia"],"explanation":"La chlamydiose est 50 fois plus fréquente que la gonococcie ; sa prévalence est estimée jusqu'à 10 %.","src":"p. 183","deep":"**Pourquoi** : C. trachomatis est la première cause d'IST bactérienne dans les pays industrialisés (prévalence estimée jusqu'à 10 %) et la première cause identifiée d'urétrite aiguë, devant le gonocoque (p. 183).\n**Piège** : première cause d'urétrite aiguë, elle donne pourtant un écoulement moins fréquent (< 50 %) et le plus souvent clair, à la différence du gonocoque (p. 183-184).\n**À relier** : la chlamydiose est 50 fois plus fréquente que la gonococcie (p. 183)."},{"id":"d162-qroc-744","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Combien de fois la chlamydiose est-elle plus fréquente que la gonococcie ?","answer":"50 fois","accept":["50 fois","50"],"keywords":["50"],"explanation":"La chlamydiose est environ 50 fois plus fréquente que la gonococcie, mais souvent silencieuse.","src":"p. 183","deep":"**Pourquoi** : la chlamydiose est 50 fois plus fréquente que la gonococcie (p. 183).\n**Piège** : sa fréquence est entretenue par un portage asymptomatique élevé, qui favorise sa diffusion dans la population générale (p. 183).\n**À relier** : le dépistage systématique par autoprélèvement vaginal est recommandé chez les femmes de moins de 25 ans (p. 183)."},{"id":"d162-qroc-745","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quels sont les pics d'incidence de la chlamydiose chez la femme et chez l'homme ?","answer":"Femme : 15-34 ans ; homme : 20-39 ans","accept":["15 à 34 ans et 20 à 39 ans","15-34 et 20-39"],"keywords":["15","34","39"],"explanation":"Le pic d'incidence se situe entre 15 et 34 ans chez la femme et entre 20 et 39 ans chez l'homme.","src":"p. 183","deep":"**Pourquoi** : le pic d'incidence de la chlamydiose se situe entre 15 et 34 ans chez la femme et entre 20 et 39 ans chez l'homme (p. 183).\n**Piège** : ne pas inverser : la femme est touchée plus tôt (15-34 ans) que l'homme (20-39 ans) (p. 183).\n**À relier** : le dépistage systématique concerne les femmes de moins de 25 ans ; chez l'homme à facteurs de risque, il est opportuniste quel que soit l'âge (p. 183)."},{"id":"d162-qroc-746","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","prévention"],"difficulty":2,"question":"Chez quelles femmes enceintes le dépistage opportuniste de C. trachomatis est-il recommandé, sans limite d'âge ?","answer":"Celles consultant pour une IVG","accept":["ivg","interruption volontaire de grossesse"],"keywords":["ivg"],"explanation":"Dépistage opportuniste ciblé : hommes à facteurs de risque (tout âge), femmes de plus de 25 ans à facteurs de risque, et femmes enceintes consultant pour une IVG, sans limite d'âge.","src":"p. 183","deep":"**Pourquoi** : le dépistage opportuniste ciblé inclut les femmes enceintes consultant pour une IVG, sans limite d'âge (p. 183).\n**Piège** : il vise aussi les hommes sexuellement actifs à facteurs de risque quel que soit l'âge et les femmes de plus de 25 ans à facteurs de risque (p. 183).\n**À relier** : avant 25 ans, le dépistage par autoprélèvement vaginal est systématique chez la femme (p. 183)."},{"id":"d162-qroc-747","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","complications"],"difficulty":2,"question":"Quelle proportion des salpingites de la femme jeune est due à C. trachomatis ?","answer":"50 %","accept":["50 %","50","la moitié"],"keywords":["50"],"explanation":"C. trachomatis est responsable de 50 % des salpingites de la femme jeune (et de 70 % des stérilités tubaires).","src":"p. 183","deep":"**Pourquoi** : C. trachomatis est responsable de 50 % des salpingites de la femme jeune (p. 183).\n**Piège** : il est aussi en cause dans 70 % des stérilités tubaires : ne pas inverser les deux chiffres (p. 183).\n**À relier** : ces salpingites sont le plus souvent subaiguës ou chroniques, avec ensuite algies pelviennes, stérilité tubaire et GEU (p. 184)."},{"id":"d162-qroc-748","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Depuis 2003, chez quelle population observe-t-on une résurgence de la lymphogranulomatose vénérienne ?","answer":"Homosexuels masculins, souvent infectés par le VIH","accept":["homosexuels masculins","hsh","homosexuels"],"keywords":["homosex"],"explanation":"La LGV a refait surface depuis 2003 chez les homosexuels de sexe masculin, avec une forte proportion de patients infectés par le VIH.","src":"p. 183","deep":"**Pourquoi** : depuis 2003, la lymphogranulomatose vénérienne resurgit chez les homosexuels de sexe masculin, avec une forte proportion de patients infectés par le VIH (p. 183).\n**Piège** : elle est due aux sérotypes L1, L2 et L3 de C. trachomatis, pas aux sérotypes D à K des infections urogénitales courantes (p. 183).\n**À relier** : dans le diagnostic différentiel des ulcérations génitales, elle touche des sujets africains ou homosexuels (p. 197)."},{"id":"d162-qroc-749","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation d'une chlamydiose génitale ?","answer":"Variable : de quelques jours à quelques mois","accept":["quelques jours à quelques mois","variable"],"keywords":["mois"],"explanation":"Contrairement au gonocoque (2 à 7 jours), l'incubation de Chlamydia est variable, de quelques jours à quelques mois ; le tableau est souvent moins bruyant.","src":"p. 184","deep":"**Pourquoi** : l'incubation de la chlamydiose est variable, de quelques jours à quelques mois (p. 184).\n**Piège** : celle du gonocoque est courte, de 2 à 7 jours (p. 180) : une incubation longue n'écarte pas une IST.\n**À relier** : le tableau chlamydien est souvent moins bruyant que celui du gonocoque et peut être asymptomatique (p. 184)."},{"id":"d162-qroc-750","type":"QROC","rank":"A","objective":"d162-obj-08","tags":["clinique"],"difficulty":1,"question":"Quelle est la manifestation la plus fréquente de la chlamydiose génitale chez l'homme ?","answer":"L'urétrite","accept":["urétrite","l'urétrite","urétrite antérieure"],"keywords":["uretrite"],"explanation":"L'urétrite est la manifestation la plus fréquente ; pharyngites et anorectites sont possibles mais rarement symptomatiques.","src":"p. 184","deep":"**Pourquoi** : l'urétrite est la manifestation la plus fréquente de la chlamydiose chez l'homme (p. 184).\n**Piège** : l'écoulement manque dans plus de la moitié des cas et il est le plus souvent clair, modéré et intermittent (p. 184).\n**À relier** : pharyngites et anorectites à C. trachomatis sont possibles mais rarement symptomatiques (p. 184)."},{"id":"d162-qroc-751","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"Quels signes à l'examen au spéculum évoquent une cervicite à Chlamydia trachomatis ?","answer":"Col fragile, sécrétions mucopurulentes, ectropion friable et hémorragique","accept":["col fragile","fragilité du col","ectropion friable","sécrétions mucopurulentes","ectropion hémorragique"],"keywords":["col","ectropion"],"explanation":"À l'examen : fragilité du col, sécrétions mucopurulentes et/ou ectropion friable et hémorragique ; mais la cervicite est le plus souvent asymptomatique.","src":"p. 184","deep":"**Pourquoi** : à l'examen d'une cervicite chlamydienne : fragilité du col, sécrétions mucopurulentes et/ou ectropion friable et hémorragique (p. 184).\n**Piège** : la cervicite est la forme la plus fréquente des chlamydioses basses de la femme, mais le plus souvent asymptomatique (50 à 90 % des cas) (p. 184).\n**À relier** : dans la gonococcie, le col est au contraire non ou peu inflammatoire, avec du pus à l'orifice cervical (p. 181)."},{"id":"d162-qroc-752","type":"QROC","rank":"A","objective":"d162-obj-10","tags":["clinique"],"difficulty":2,"question":"Citez un signe fonctionnel possible d'une cervicite symptomatique à Chlamydia trachomatis.","answer":"Leucorrhées, cystalgies, syndrome urétral ou dyspareunie","accept":["leucorrhées blanchâtres","leucorrhées jaunâtres","cystalgies","syndrome urétral","dyspareunie"],"keywords":["leucorrh","dyspareunie"],"explanation":"Si elle est symptomatique : leucorrhées blanchâtres ou jaunâtres, cystalgies, syndrome urétral et/ou dyspareunie.","src":"p. 184","deep":"**Pourquoi** : une cervicite symptomatique à C. trachomatis peut donner des leucorrhées blanchâtres ou jaunâtres, des cystalgies, un syndrome urétral et/ou une dyspareunie (p. 184).\n**Piège** : à l'examen, le col est fragile, avec sécrétions mucopurulentes et/ou ectropion friable, alors qu'il est peu inflammatoire dans la gonococcie (p. 181, 184).\n**À relier** : chez la femme symptomatique, la PCR se fait sur auto-écouvillonnage vaginal, à préférer à l'écouvillonnage de l'endocol (p. 185)."},{"id":"d162-qroc-753","type":"QROC","rank":"B","objective":"d162-obj-09","tags":["complications"],"difficulty":2,"question":"Quelles sont les complications locorégionales de la chlamydiose chez l'homme ?","answer":"Épididymite aiguë et prostatite chronique","accept":["épididymite aiguë et prostatite chronique","épididymite et prostatite"],"keywords":["epididym","prostat"],"explanation":"Chez l'homme : épididymite aiguë et prostatite chronique (les prostatites aiguës à C. trachomatis sont rares).","src":"p. 184","deep":"**Pourquoi** : chez l'homme, la chlamydiose se complique d'épididymite aiguë et de prostatite chronique (p. 184).\n**Piège** : les prostatites aiguës à C. trachomatis sont rares (p. 184).\n**À relier** : orchiépididymite à Chlamydia : doxycycline 100 mg/12 h pendant 10 jours (p. 186)."},{"id":"d162-qroc-754","type":"QROC","rank":"B","objective":"d162-obj-13","tags":["complications"],"difficulty":2,"question":"Sous quel mode évolutif se présentent le plus souvent l'endométrite et la salpingite à C. trachomatis ?","answer":"Subaiguës ou chroniques","accept":["subaiguës ou chroniques","subaiguë","chroniques"],"keywords":["subaigu","chroni"],"explanation":"L'endométrite et la salpingite à C. trachomatis sont le plus souvent subaiguës ou chroniques ; elles se compliquent secondairement d'algies pelviennes inflammatoires, de stérilité tubaire et de grossesse extra-utérine (p. 184).","src":"p. 184","deep":"**Pourquoi** : l'endométrite et la salpingite à C. trachomatis sont le plus souvent subaiguës ou chroniques (p. 184).\n**Piège** : elles se compliquent secondairement d'algies pelviennes inflammatoires, de stérilité tubaire et de grossesse extra-utérine (p. 184).\n**À relier** : traitement d'une endométrite ou salpingite à Chlamydia : doxycycline 100 mg/12 h, PO ou IV, pendant 14 jours (p. 186)."},{"id":"d162-qroc-755","type":"QROC","rank":"B","objective":"d162-obj-35","tags":["complications","suivi"],"difficulty":2,"question":"Quelles séquelles tardives menacent la femme après une infection génitale haute à Chlamydia ?","answer":"Algies pelviennes inflammatoires, stérilité tubaire, GEU","accept":["algies pelviennes, stérilité tubaire et grossesse extra-utérine","algies pelviennes inflammatoires, stérilité tubaire, geu"],"keywords":["algies","steril","extra"],"explanation":"Secondairement à l'endométrite ou à la salpingite : algies pelviennes inflammatoires, stérilité tubaire et grossesse extra-utérine.","src":"p. 184","deep":"**Pourquoi** : après une endométrite ou une salpingite à Chlamydia : algies pelviennes inflammatoires, stérilité tubaire et grossesse extra-utérine (p. 184).\n**Piège** : C. trachomatis est responsable de 70 % des stérilités tubaires ; le gonocoque en donne aussi, mais moins souvent (p. 181, 183).\n**À relier** : après traitement d'une IGH, un contrôle PCR systématique est fait 2 à 3 mois plus tard (p. 186)."},{"id":"d162-qroc-756","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications"],"difficulty":3,"question":"Quelle complication hépatique rare de la chlamydiose féminine simule une cholécystite alithiasique ?","answer":"La péri-hépatite (diagnostic sous cœlioscopie)","accept":["péri-hépatite","périhépatite","peri hepatite"],"keywords":["peri","hepatite"],"explanation":"Plus rarement, une péri-hépatite donne un tableau de cholécystite alithiasique dont le diagnostic se fait sous cœlioscopie.","src":"p. 184","deep":"**Pourquoi** : plus rarement, la chlamydiose féminine se complique d'une péri-hépatite, au tableau de cholécystite alithiasique, dont le diagnostic se fait sous cœlioscopie (p. 184).\n**Piège** : la péri-hépatite peut aussi compliquer, rarement, la gonococcie (p. 181).\n**À relier** : autres complications hautes : endométrite, salpingite, puis algies pelviennes, stérilité tubaire, GEU (p. 184)."},{"id":"d162-qroc-757","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications"],"difficulty":2,"question":"Quel syndrome associe polyarthrite réactionnelle, urétrite, conjonctivite bilatérale, balanite circinée et kératodermie palmo-plantaire psoriasiforme ?","answer":"Le syndrome oculo-urétro-synovial","accept":["oculo-urétro-synovial","oculo-uréthro-synovial","oculo urethro synovial"],"keywords":["oculo"],"explanation":"Syndrome oculo-urétro-synovial : complication d'une chlamydiose dans les deux sexes (polyarthrite aiguë ou subaiguë réactionnelle, urétrite, conjonctivite bilatérale, atteinte cutanée).","src":"p. 184-185","deep":"**Pourquoi** : le syndrome oculo-urétro-synovial associe polyarthrite aiguë ou subaiguë réactionnelle, urétrite, conjonctivite bilatérale, balanite circinée et kératodermie palmo-plantaire psoriasiforme (p. 184-185).\n**Piège** : l'arthrite de C. trachomatis est réactionnelle, alors que celle du gonocoque est septique (tableau 9.1, p. 186).\n**À relier** : il survient dans les deux sexes, au même titre que la kératoconjonctivite et l'arthrite (p. 185)."},{"id":"d162-qroc-758","type":"QROC","rank":"B","objective":"d162-obj-14","tags":["complications"],"difficulty":2,"question":"Quelles atteintes cutanées sont décrites dans le syndrome oculo-urétro-synovial d'origine chlamydienne ?","answer":"Balanite circinée et kératodermie palmo-plantaire psoriasiforme","accept":["balanite circinée","kératodermie palmo-plantaire","kératodermie palmo-plantaire psoriasiforme"],"keywords":["balanite","keratodermie"],"explanation":"Les deux atteintes cutanéo-muqueuses du syndrome sont la balanite circinée et la kératodermie palmo-plantaire psoriasiforme.","src":"p. 185","deep":"**Pourquoi** : dans le syndrome oculo-urétro-synovial, les atteintes cutanées sont la balanite circinée et la kératodermie palmo-plantaire psoriasiforme (p. 185).\n**Piège** : la kératodermie est « psoriasiforme » : ne pas la prendre pour des syphilides palmo-plantaires, cuivrées et à cheval sur les plis (p. 192).\n**À relier** : le reste du syndrome : polyarthrite réactionnelle, urétrite, conjonctivite bilatérale (p. 184)."},{"id":"d162-qroc-759","type":"QROC","rank":"B","objective":"d162-obj-36","tags":["pédiatrie","complications"],"difficulty":2,"question":"Quelles manifestations peut présenter un nouveau-né dont la mère a une infection urogénitale à Chlamydia ?","answer":"Kératoconjonctivite et pneumopathie","accept":["kératoconjonctivite et pneumopathie","conjonctivite et pneumopathie"],"keywords":["conjonctivite","pneumopathie"],"explanation":"Chez le nouveau-né d'une mère ayant une infection urogénitale à Chlamydia : kératoconjonctivite et pneumopathie ; en cas de pneumopathie ou d'ophtalmie, on traite par érythromycine (p. 185-186).","src":"p. 185","deep":"**Pourquoi** : en cas d'infection urogénitale maternelle, le nouveau-né peut présenter une kératoconjonctivite et une pneumopathie (p. 185).\n**Piège** : avec le gonocoque, la transmission néonatale est rare, sous forme de conjonctivite purulente (p. 186).\n**À relier** : pneumopathie ou ophtalmie néonatale : érythromycine 12,5 mg/kg/6 h, PO ou IV, pendant 14 jours (p. 186)."},{"id":"d162-qroc-760","type":"QROC","rank":"A","objective":"d162-obj-33","tags":["paraclinique"],"difficulty":1,"question":"Quel examen est l'examen clé du diagnostic d'une infection à C. trachomatis, plus sensible que la culture ?","answer":"La PCR (amplification génique)","accept":["pcr","amplification génique"],"keywords":["pcr"],"explanation":"La PCR est l'examen clé ; la sérologie n'a aucun intérêt.","src":"p. 185","deep":"**Pourquoi** : la PCR, plus sensible que la culture, est l'examen clé du diagnostic de C. trachomatis (p. 185).\n**Piège** : la sérologie n'a aucun intérêt pour ce diagnostic (p. 185).\n**À relier** : chez l'homme, symptomatique ou non, la PCR se fait sur un 1er jet urinaire au moins 2 heures après la dernière miction (p. 185)."},{"id":"d162-qroc-761","type":"QROC","rank":"A","objective":"d162-obj-18","tags":["traitement"],"difficulty":2,"question":"Quel est l'avantage pratique du traitement de la chlamydiose par azithromycine ?","answer":"Dose unique : traitement immédiat sans crainte de mauvaise observance","accept":["dose unique","prise unique","pas de mauvaise observance","traitement immédiat"],"keywords":["unique"],"explanation":"L'azithromycine est délivrée en dose unique, ce qui permet de traiter immédiatement sans craindre une mauvaise observance ; son inconvénient est l'émergence de résistances (Mycoplasma genitalium).","src":"p. 185","deep":"**Pourquoi** : l'azithromycine, délivrée en dose unique, permet de traiter immédiatement le patient sans crainte de mauvaise observance (p. 185).\n**Piège** : elle est à l'origine de résistances chez d'autres micro-organismes, comme Mycoplasma genitalium, d'où la remise en question de la prise unique (p. 185, 187).\n**À relier** : on privilégie la doxycycline 7 jours associée à une injection de ceftriaxone (p. 187)."},{"id":"d162-qroc-762","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quelle est la posologie de la doxycycline en première intention dans une chlamydiose non compliquée ?","answer":"100 mg toutes les 12 h pendant 7 jours","accept":["100 mg matin et soir 7 jours","100 mg x 2 par jour pendant 7 jours","100 mg/12 h 7 jours"],"keywords":["100","7"],"explanation":"Première intention : doxycycline 100 mg/12 h pendant 7 jours per os.","src":"p. 185","deep":"**Pourquoi** : en première intention : doxycycline 100 mg toutes les 12 heures PO pendant 7 jours (p. 185).\n**Piège** : la même dose dure 10 jours pour une orchiépididymite et 14 jours pour une endométrite ou une salpingite (p. 186).\n**À relier** : l'azithromycine 1 g en prise unique est l'alternative si l'on craint une mauvaise observance (p. 185)."},{"id":"d162-qroc-763","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle dose d'azithromycine en prise unique traite une chlamydiose non compliquée en cas de crainte de mauvaise observance ?","answer":"1 g","accept":["1 g","1g","1000 mg"],"keywords":["1 g"],"explanation":"Chlamydia : azithromycine 1 g en dose unique ; gonocoque (en cas d'allergie aux β-lactamines) : 2 g.","src":"p. 185","deep":"**Pourquoi** : contre C. trachomatis, l'azithromycine se donne à 1 g en prise orale unique, si l'on craint une mauvaise observance (p. 185).\n**Piège** : contre le gonocoque (allergie aux β-lactamines), la dose est de 2 g (p. 182).\n**À relier** : chez la femme enceinte, azithromycine 1 g en prise unique et PCR systématique à 1 mois (p. 186)."},{"id":"d162-qroc-764","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Citez un antibiotique de deuxième intention dans une chlamydiose non compliquée.","answer":"Érythromycine ou ofloxacine, pendant 7 jours","accept":["érythromycine","ofloxacine"],"keywords":["erythromycine","ofloxacine"],"explanation":"Deuxième intention : érythromycine 500 mg/6 h ou ofloxacine 200 mg/12 h, pendant 7 jours.","src":"p. 185","deep":"**Pourquoi** : en deuxième intention : érythromycine 500 mg/6 h ou ofloxacine 200 mg/12 h, PO pendant 7 jours (p. 185).\n**Piège** : la première intention reste la doxycycline 7 jours, ou l'azithromycine 1 g en prise unique en cas de crainte d'inobservance (p. 185).\n**À relier** : l'érythromycine est aussi le traitement de l'ophtalmie ou de la pneumopathie néonatale à Chlamydia (p. 186)."},{"id":"d162-qroc-765","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi","pièges"],"difficulty":3,"question":"Pendant combien de temps après le traitement la PCR de contrôle d'une chlamydiose peut-elle être faussement positive (débris cellulaires) ?","answer":"4 semaines","accept":["4 semaines","un mois","28 jours"],"keywords":["4 semaines"],"explanation":"Des débris cellulaires de Chlamydia persistent jusqu'à 4 semaines : un contrôle PCR trop précoce peut être faussement positif.","src":"p. 185","deep":"**Pourquoi** : des débris cellulaires de Chlamydia, dans les 4 semaines suivant le traitement, peuvent rendre la PCR faussement positive (p. 185).\n**Piège** : chez la femme enceinte, la PCR de contrôle est systématique à 1 mois (p. 186) ; après une IGH, à 2-3 mois (p. 186).\n**À relier** : chez les patients à haut risque de réinfection, contrôle des sites atteints 3 à 6 mois après le traitement (p. 185)."},{"id":"d162-qroc-766","type":"QROC","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"question":"Chez quels patients contrôle-t-on les sites atteints 3 à 6 mois après le traitement d'une chlamydiose ?","answer":"Ceux à haut risque de réinfection","accept":["haut risque de réinfection","risque de réinfection","haut risque"],"keywords":["reinfection"],"explanation":"Un contrôle des sites atteints (vaginal, urétral, pharyngé, anal) est préconisé 3 à 6 mois après traitement chez les patients exposés à un haut risque de réinfection.","src":"p. 185","deep":"**Pourquoi** : un contrôle des sites atteints (vaginal, urétral, pharyngé, anal) est préconisé 3 à 6 mois après le traitement chez les patients à haut risque de réinfection (p. 185).\n**Piège** : à distinguer du délai minimal : un contrôle PCR dans les 4 semaines risque d'être faussement positif (p. 185).\n**À relier** : comme pour toute IST, on insiste sur le risque de recontamination et on éduque le patient (p. 185)."},{"id":"d162-qroc-767","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":2,"question":"Quel antibiotique traite une chlamydiose chez la femme enceinte, et quel contrôle systématique est prévu ?","answer":"Azithromycine 1 g en prise unique ; PCR à 1 mois","accept":["azithromycine et pcr à 1 mois","azithromycine 1 g pcr 1 mois"],"keywords":["azithromycine","1 mois"],"explanation":"Femme enceinte : azithromycine 1 g en prise orale unique, avec PCR systématique à 1 mois.","src":"p. 186","deep":"**Pourquoi** : chez la femme enceinte, C. trachomatis se traite par azithromycine 1 g en prise orale unique, avec une PCR systématique à 1 mois (p. 186).\n**Piège** : les cyclines font partie des classes contre-indiquées pendant la grossesse (p. 182) : la doxycycline n'est pas l'option ici.\n**À relier** : pour le gonocoque chez la femme enceinte : ceftriaxone 1000 mg IM unique ou céfixime 400 mg PO unique (p. 182)."},{"id":"d162-qroc-768","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quelle est la durée de la doxycycline (100 mg/12 h) dans une orchiépididymite à C. trachomatis ?","answer":"10 jours","accept":["10 jours","dix jours"],"keywords":["10 jours"],"explanation":"Orchiépididymite à Chlamydia : doxycycline 100 mg/12 h pendant 10 jours (7 jours pour une forme non compliquée, 14 jours pour une endométrite-salpingite).","src":"p. 186","deep":"**Pourquoi** : orchiépididymite à C. trachomatis : doxycycline 100 mg/12 h pendant 10 jours (p. 186).\n**Piège** : forme non compliquée = 7 jours ; endométrite ou salpingite = 14 jours (p. 185-186).\n**À relier** : l'épididymite aiguë est une complication locorégionale de la chlamydiose chez l'homme (p. 184)."},{"id":"d162-qroc-769","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":2,"question":"Quelle est la durée de la doxycycline (PO ou IV) dans une endométrite ou une salpingite à Chlamydia ?","answer":"14 jours","accept":["14 jours","quatorze jours","2 semaines"],"keywords":["14"],"explanation":"Endométrite, salpingite : doxycycline 100 mg/12 h par voie orale ou IV pendant 14 jours.","src":"p. 186","deep":"**Pourquoi** : endométrite ou salpingite à Chlamydia : doxycycline 100 mg/12 h, PO ou IV, pendant 14 jours (p. 186).\n**Piège** : dans le schéma probabiliste 2018 d'une IGH non compliquée, la doxycycline est donnée 10 jours, avec ceftriaxone et métronidazole (p. 186).\n**À relier** : contrôle PCR systématique 2 à 3 mois après le traitement d'une IGH (p. 186)."},{"id":"d162-qroc-770","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement","pédiatrie"],"difficulty":2,"question":"Quel antibiotique traite une pneumopathie ou une ophtalmie néonatale à C. trachomatis ?","answer":"L'érythromycine (12,5 mg/kg/6 h, pendant 14 jours)","accept":["érythromycine","erythromycine 12,5 mg/kg"],"keywords":["erythromycine"],"explanation":"Chez le nouveau-né : érythromycine 12,5 mg/kg toutes les 6 h, PO ou IV, pendant 14 jours.","src":"p. 186","deep":"**Pourquoi** : pneumopathie ou ophtalmie néonatale à C. trachomatis : érythromycine 12,5 mg/kg toutes les 6 heures, PO ou IV, pendant 14 jours (p. 186).\n**Piège** : chez l'adulte, l'érythromycine n'est qu'un traitement de deuxième intention (p. 185).\n**À relier** : ces atteintes surviennent en cas d'infection urogénitale maternelle (p. 185)."},{"id":"d162-qroc-771","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":2,"question":"Quelle association antibiotique est préconisée (recommandations 2018) pour une infection génitale haute non compliquée ?","answer":"Ceftriaxone + doxycycline + métronidazole","accept":["ceftriaxone doxycycline métronidazole","ceftriaxone, doxycycline et métronidazole"],"keywords":["ceftriaxone","doxycycline","metronidazole"],"explanation":"Ceftriaxone 1 g IV/IM en dose unique, doxycycline 100 mg/12 h et métronidazole 500 mg/12 h pendant 10 jours.","src":"p. 186","deep":"**Pourquoi** : la prise en charge des IGH est souvent probabiliste ; en 2018 : ceftriaxone 1 g IV/IM en dose unique + doxycycline 100 mg/12 h PO 10 jours + métronidazole 500 mg/12 h PO 10 jours (p. 186).\n**Piège** : une salpingite gonococcique documentée reçoit, elle, ceftriaxone 1 g/jour IV pendant 14 jours (p. 183).\n**À relier** : contrôle PCR systématique 2 à 3 mois après le traitement (p. 186)."},{"id":"d162-qroc-772","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement","suivi"],"difficulty":2,"question":"Quel contrôle systématique fait-on après le traitement d'une infection génitale haute, et à quel délai ?","answer":"PCR de contrôle 2 à 3 mois après le traitement","accept":["pcr à 2 à 3 mois","pcr 2-3 mois","contrôle pcr à 2 à 3 mois"],"keywords":["pcr","mois"],"explanation":"Un contrôle PCR systématique est à faire 2 à 3 mois après le traitement d'une IGH.","src":"p. 186","deep":"**Pourquoi** : après le traitement d'une infection génitale haute, un contrôle PCR systématique est fait 2 à 3 mois plus tard (p. 186).\n**Piège** : ne pas confondre avec la PCR à 1 mois chez la femme enceinte traitée pour Chlamydia (p. 186).\n**À relier** : un contrôle trop précoce peut être faussement positif (débris de Chlamydia dans les 4 semaines) (p. 185)."},{"id":"d162-qroc-773","type":"QROC","rank":"B","objective":"d162-obj-21","tags":["traitement"],"difficulty":1,"question":"Comment débute habituellement la prise en charge d'une infection génitale haute ?","answer":"Par un traitement probabiliste","accept":["probabiliste","traitement probabiliste","initialement probabiliste"],"keywords":["probabil"],"explanation":"La prise en charge des IGH est souvent initialement probabiliste.","src":"p. 186","deep":"**Pourquoi** : le Collège dit la prise en charge des IGH « souvent » initialement probabiliste ; le schéma 2018 d'une IGH non compliquée associe 3 molécules : ceftriaxone 1 g IV/IM en dose unique + doxycycline 100 mg/12 h PO 10 jours + métronidazole 500 mg/12 h PO 10 jours (p. 186).\n**Piège** : la doxycycline seule 14 jours est le schéma de l'endométrite-salpingite à Chlamydia, pas ce probabiliste à 3 molécules (p. 186).\n**À relier** : contrôle PCR systématique 2 à 3 mois après le traitement ; C. trachomatis cause 50 % des salpingites de la femme jeune (p. 183, 186)."},{"id":"d162-qroc-774","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition","étiologie"],"difficulty":1,"question":"Quel est l'agent de la syphilis ?","answer":"Treponema pallidum (un spirochète)","accept":["treponema pallidum","tréponème pâle","tréponème","t. pallidum"],"keywords":["treponem"],"explanation":"La syphilis est une IST due à un spirochète, Treponema pallidum ; le tréponème ne se cultive pas in vitro.","src":"p. 187","deep":"**Pourquoi** : T. pallidum est un spirochète qui ne se cultive pas in vitro : le diagnostic passe par sa mise en évidence directe (fond noir, abandonné ; biologie moléculaire, non remboursée) ou, indirectement, par la sérologie (p. 187, 194).\n**Piège** : la sérologie ne distingue pas la syphilis des tréponématoses endémiques non vénériennes (pian, béjel, pinta) : on devrait parler de sérologie des tréponématoses (p. 194).\n**À relier** : maladie non immunisante et très contagieuse : une recontamination est possible après guérison (p. 187, 195)."},{"id":"d162-qroc-775","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition","physiopathologie"],"difficulty":2,"question":"Pourquoi une personne guérie d'une syphilis peut-elle se recontaminer ?","answer":"La syphilis est une maladie non immunisante","accept":["non immunisante","pas d'immunité","ne confère pas d'immunité"],"keywords":["immunis"],"explanation":"C'est une maladie non immunisante et très contagieuse ; une recontamination se reconnaît cliniquement ou à la remontée du TNT.","src":"p. 187","deep":"**Pourquoi** : la syphilis ne laisse pas d'immunité : un patient traité et guéri peut se recontaminer (p. 187).\n**Piège** : un TT positif peut correspondre à une syphilis guérie (cicatrice sérologique : TT+/TNT−) ; c'est la remontée du TNT quantitatif (titre multiplié au moins par 4) qui signe la recontamination (p. 195).\n**À relier** : contracter une syphilis témoigne d'une sexualité à haut risque : rechercher une IST concomitante et renouveler les conseils de prévention (p. 198)."},{"id":"d162-qroc-776","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":1,"question":"Quel groupe est principalement touché par la recrudescence de la syphilis en métropole depuis 2000 ?","answer":"Les homosexuels masculins","accept":["homosexuels masculins","hsh","homosexuels","hommes ayant des rapports sexuels avec des hommes"],"keywords":["homosex"],"explanation":"La recrudescence touche surtout les homosexuels masculins et traduit un relâchement de la prévention des pratiques à risque.","src":"p. 187","deep":"**Pourquoi** : la recrudescence observée en France depuis 2000 touche surtout les homosexuels masculins en métropole et témoigne d'un relâchement de la prévention des pratiques à risque (p. 187).\n**Piège** : outre-mer, c'est l'atteinte des hétérosexuels qui progresse, d'où la crainte d'une réémergence de la syphilis congénitale (p. 188).\n**À relier** : 40 % des syphilitiques sont infectés par le VIH ; sérologie syphilis au moins 1 fois par an chez les patients VIH (p. 188)."},{"id":"d162-qroc-777","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quelle proportion de patients syphilitiques est infectée par le VIH (sur-représentation) ?","answer":"Environ 40 %","accept":["40 %","40","environ 40 %"],"keywords":["40"],"explanation":"Les patients infectés par le VIH sont sur-représentés parmi les syphilitiques (40 %).","src":"p. 188","deep":"**Pourquoi** : 40 % des syphilitiques sont VIH+ et contracter une syphilis témoigne d'une sexualité à haut risque : le Collège demande de vérifier sérologie VIH, hépatite B et autres IST (p. 188, 200).\n**Piège** : ne pas confondre avec les « 30 % » du chapitre : chancres visibles non traités évoluant vers le secondaire, et fréquence des syphilides palmo-plantaires (p. 190, 192).\n**À relier** : chez le patient VIH, le traitement par pénicilline est le même ; sérologie syphilis au moins annuelle en cas de pratiques à risque (p. 199)."},{"id":"d162-qroc-778","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Dans quels territoires l'atteinte des hétérosexuels fait-elle craindre une réémergence de la syphilis congénitale ?","answer":"Départements et régions d'outre-mer","accept":["outre-mer","dom","dom-tom"],"keywords":["outre"],"explanation":"L'atteinte des hétérosexuels est de plus en plus nette dans les DROM, d'où la crainte d'une réémergence de la syphilis congénitale.","src":"p. 188","deep":"**Pourquoi** : le Collège note une atteinte de plus en plus manifeste des hétérosexuels dans les DROM, laissant craindre une réémergence de la syphilis congénitale ; la transmission maternofœtale est possible, surtout après la 16e semaine d'aménorrhée (p. 188).\n**Piège** : en métropole, la recrudescence concerne surtout les homosexuels masculins (p. 187).\n**À relier** : la sérologie syphilis est obligatoire au 1er trimestre de la grossesse et peut être renouvelée au cours de celle-ci (p. 188)."},{"id":"d162-qroc-779","type":"QROC","rank":"A","objective":"d162-obj-03","tags":["prévention","suivi"],"difficulty":2,"question":"À quelle fréquence minimale la sérologie de la syphilis est-elle recommandée chez les patients infectés par le VIH engagés dans des pratiques à risque ?","answer":"Au moins 1 fois par an","accept":["1 fois par an","une fois par an","tous les ans","annuelle"],"keywords":["par an"],"explanation":"Chez les patients VIH engagés dans des pratiques à risque, on recommande une sérologie de la syphilis au moins 1 fois par an (p. 199).","src":"p. 199","deep":"**Pourquoi** : les patients VIH sont sur-représentés parmi les syphilitiques (40 %, rang B) : chez ceux qui ont des pratiques à risque, une sérologie syphilis est recommandée au moins 1 fois par an (p. 188, 199).\n**Piège** : le traitement, lui, ne change pas : même pénicilline que chez le non-VIH pour une syphilis primaire ou secondaire (p. 199).\n**À relier** : (rang B) sérologie aussi chez les sujets à risque à partenaires multiples, et obligatoire au 1er trimestre de grossesse (p. 188)."},{"id":"d162-qroc-780","type":"QROC","rank":"B","objective":"d162-obj-03","tags":["prévention","grossesse"],"difficulty":1,"question":"À quel moment de la grossesse la sérologie de la syphilis est-elle obligatoire ?","answer":"Au 1er trimestre","accept":["1er trimestre","premier trimestre","au premier trimestre"],"keywords":["trimestre"],"explanation":"La sérologie syphilis est obligatoire au 1er trimestre de la grossesse et peut être renouvelée dans certaines situations.","src":"p. 188","deep":"**Pourquoi** : la transmission maternofœtale est possible, surtout après la 16e SA : la sérologie est obligatoire au 1er trimestre et peut être renouvelée au cours de la grossesse dans certaines situations (p. 188).\n**Piège** : la grossesse peut elle-même donner une fausse sérologie (TNT+ / TT−) : on interprète en commençant par le TT (p. 194, 196).\n**À relier** : femme enceinte allergique à la pénicilline : pas de doxycycline mais avis spécialisé et induction de tolérance (p. 197-198)."},{"id":"d162-qroc-781","type":"QROC","rank":"B","objective":"d162-obj-23","tags":["clinique","prévention"],"difficulty":2,"question":"Quelles lésions de la syphilis sont contagieuses ?","answer":"Lésions des muqueuses (et syphilides si grattées ou excoriées)","accept":["lésions des muqueuses et syphilides grattées ou excoriées","lésions muqueuses et syphilides excoriées","muqueuses et syphilides grattées","lésions muqueuses et syphilides grattées"],"keywords":["muqueu"],"explanation":"Transmission essentiellement sexuelle (fellation comprise) ; sont contagieuses les lésions muqueuses et les syphilides en cas de grattage ou d'excoriation.","src":"p. 188","deep":"**Pourquoi** : le chancre « fourmille de tréponèmes » et les syphilides génitales sont très contagieuses ; les syphilides cutanées le sont en cas de grattage ou d'excoriation (p. 188, 192).\n**Piège** : la transmission est essentiellement sexuelle, fellation comprise : un chancre buccal ou pharyngé est possible (p. 188-189).\n**À relier** : transmission maternofœtale possible (surtout après la 16e SA) ; post-transfusionnelle ou après greffe exceptionnelle (p. 188)."},{"id":"d162-qroc-782","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition"],"difficulty":1,"question":"Quelles formes cliniques composent la syphilis précoce ?","answer":"Primaire, secondaire et latente précoce","accept":["primaire, secondaire et latente précoce","primaire secondaire latente précoce"],"keywords":["primaire","secondaire","latente"],"explanation":"La syphilis précoce regroupe la syphilis primaire, la syphilis secondaire et la syphilis latente précoce.","src":"p. 188","deep":"**Pourquoi** : la frontière est temporelle : précoce = primaire, secondaire et latente précoce (moins de 1 an) ; tardive = tertiaire et latente tardive (plus de 1 an ou non datable) (p. 188).\n**Piège** : « latente précoce » n'est acceptable que si le patient fournit une sérologie négative datant de moins de 1 an (p. 197).\n**À relier** : les trois formes précoces ont le même traitement : une injection IM unique de 2,4 MU de benzathine-benzylpénicilline (p. 197-198)."},{"id":"d162-qroc-783","type":"QROC","rank":"A","objective":"d162-obj-24","tags":["définition"],"difficulty":1,"question":"Quelles formes composent la syphilis tardive ?","answer":"Syphilis tertiaire et syphilis latente tardive","accept":["tertiaire et latente tardive","tertiaire latente tardive"],"keywords":["tertiaire","latente"],"explanation":"La syphilis tardive regroupe la syphilis tertiaire et la syphilis latente tardive (non datable ou datant de plus de 1 an).","src":"p. 188","deep":"**Pourquoi** : est « tardive » une syphilis dont l'évolution dépasse 1 an ou n'est pas datable : syphilis tertiaire et syphilis latente tardive (p. 188).\n**Piège** : un patient non traité peut évoluer vers un stade tardif sans avoir présenté de signes secondaires (p. 190).\n**À relier** : le titre du TNT ne permet pas de distinguer une latente précoce d'une latente tardive ; seule une sérologie négative de moins de 1 an autorise le diagnostic de latente précoce (p. 195, 197)."},{"id":"d162-qroc-784","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["définition"],"difficulty":1,"question":"Quelle durée d'évolution sépare la syphilis latente précoce de la syphilis latente tardive ?","answer":"1 an","accept":["1 an","un an","12 mois"],"keywords":["1 an"],"explanation":"Latente précoce : sérologie positive sans lésion clinique, évolution de moins de 1 an ; latente tardive : non datable ou de plus de 1 an.","src":"p. 188","deep":"**Pourquoi** : une sérologie positive sans lésion clinique définit la syphilis latente ; elle est précoce si elle date de moins de 1 an, tardive si elle date de plus de 1 an ou n'est pas datable (p. 188).\n**Piège** : le titre du TNT ne sert pas à les distinguer ; il faut une sérologie négative datant de moins de 1 an pour retenir une latente précoce (p. 195, 197).\n**À relier** : la latente précoce se traite comme la primaire et la secondaire : 1 injection IM de 2,4 MU de benzathine-benzylpénicilline (p. 197-198)."},{"id":"d162-qroc-785","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée d'incubation moyenne de la syphilis primaire ?","answer":"3 semaines","accept":["3 semaines","trois semaines","21 jours"],"keywords":["3 semaines"],"explanation":"L'incubation est de 10 à 90 jours, en moyenne 3 semaines.","src":"p. 188","deep":"**Pourquoi** : retenir la moyenne (3 semaines) et la fourchette large (10 à 90 jours) : le chancre peut apparaître longtemps après le rapport en cause (p. 188).\n**Piège** : ne pas confondre avec les incubations du gonocoque (2 à 7 jours), de Chlamydia (quelques jours à quelques mois) ou de la trichomonose (4 à 28 jours, rang B) (p. 180, 184, 207).\n**À relier** : au tout début du chancre, la sérologie peut être négative : le TT se positive entre le 7e et le 10e jour du chancre (p. 194)."},{"id":"d162-qroc-786","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique"],"difficulty":2,"question":"Quelles sont les limites (minimum et maximum) de l'incubation de la syphilis primaire ?","answer":"10 à 90 jours","accept":["10 à 90 jours","10-90 jours","10 à 90"],"keywords":["10","90"],"explanation":"Incubation variable : 10 à 90 jours, en moyenne 3 semaines.","src":"p. 188","deep":"**Pourquoi** : incubation variable de 10 à 90 jours (moyenne 3 semaines) ; ensuite, TT et TNT sont négatifs pendant les 7 premiers jours du chancre (p. 188, 195).\n**Piège** : un sujet contact de moins de 6 semaines d'une syphilis certaine est traité d'emblée, sans attendre la sérologie (p. 198).\n**À relier** : contact de plus de 6 semaines : sérologie, traitement si positive, sinon nouvelle sérologie à 3 mois (p. 198)."},{"id":"d162-qroc-787","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Pourquoi le chancre syphilitique est-il contagieux ?","answer":"Il fourmille de tréponèmes","accept":["fourmille de tréponèmes","riche en tréponèmes","nombreux tréponèmes"],"keywords":["treponem"],"explanation":"Le chancre est contagieux car il fourmille de tréponèmes ; quand il n'est pas visible (vagin, col utérin, anorectal, pharynx), la syphilis primaire est souvent méconnue (p. 188).","src":"p. 188","deep":"**Pourquoi** : le chancre est contagieux car riche en tréponèmes ; le grattage d'une ulcération permet d'ailleurs un diagnostic immédiat au microscope à fond noir, technique devenue rare et non remboursée (p. 188, 196).\n**Piège** : un chancre non visible (vagin, col utérin, anorectal, pharynx) fait souvent méconnaître la syphilis primaire (p. 188).\n**À relier** : (rang B) au stade secondaire, les syphilides génitales et périnéales sont elles aussi très contagieuses (p. 192)."},{"id":"d162-qroc-788","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":2,"question":"Citez une localisation du chancre syphilitique qui fait souvent méconnaître la syphilis primaire (chancre non visible).","answer":"Vaginal, du col utérin, anorectal ou pharyngé","accept":["chancre vaginal","col utérin","anorectal","pharyngé"],"keywords":["vagin","col","anorect"],"explanation":"Quand le chancre n'est pas visible (vagin, col utérin, anorectal, pharynx), le diagnostic de syphilis primaire est souvent méconnu.","src":"p. 188","deep":"**Pourquoi** : vaginal, du col utérin, anorectal ou pharyngé, le chancre n'est pas visible : la syphilis primaire est alors souvent méconnue (p. 188).\n**Piège** : au col utérin et au rectum, l'adénopathie satellite n'est pas cliniquement visible non plus (p. 190).\n**À relier** : d'où la règle : évoquer systématiquement une syphilis devant toute ulcération muqueuse aiguë, génitale, anale ou buccale (p. 189, 197)."},{"id":"d162-qroc-789","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quelle lésion élémentaire correspond typiquement à un chancre syphilitique (perte de substance superficielle) ?","answer":"Une exulcération (érosion)","accept":["exulcération","érosion","exulceration"],"keywords":["exulc","erosion"],"explanation":"Le chancre est typiquement une exulcération, plus rarement une ulcération muqueuse (perte de substance profonde).","src":"p. 188","deep":"**Pourquoi** : l'exulcération est une perte de substance superficielle qui met plus ou moins à nu la partie superficielle du chorion ; l'ulcération, plus rare, atteint le chorion moyen et/ou profond (p. 188).\n**Piège** : la profondeur n'est pas le signe clé : le seul caractère vraiment évocateur est l'induration (p. 188).\n**À relier** : aucun caractère n'est pathognomonique, d'où la règle d'évoquer la syphilis devant toute ulcération muqueuse aiguë (p. 189)."},{"id":"d162-qroc-790","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quel est le diamètre moyen d'un chancre syphilitique ?","answer":"5 à 15 mm","accept":["5 à 15 mm","5-15 mm","5 à 15"],"keywords":["5","15"],"explanation":"Le chancre mesure en moyenne 5 à 15 mm, est unique (parfois multiple, en miroir), à fond propre et rosé, induré, indolore.","src":"p. 188","deep":"**Pourquoi** : portrait type du chancre : 5 à 15 mm, unique (parfois multiple, en miroir), à fond propre et rosé, induré, indolore (p. 188).\n**Piège** : 5 à 15 mm est aussi le diamètre des macules de la roséole syphilitique (rang B) : ne pas mélanger les deux stades (p. 190).\n**À relier** : la taille ne fait pas le diagnostic : aucun caractère n'est pathognomonique, seule l'induration est vraiment évocatrice (p. 188-189)."},{"id":"d162-qroc-791","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Comment décrit-on le fond d'un chancre syphilitique ?","answer":"Propre et rosé","accept":["propre et rosé","fond propre","propre"],"keywords":["propre"],"explanation":"Fond propre et rosé, à la différence du chancre mou (fond sale).","src":"p. 188","deep":"**Pourquoi** : le fond propre et rosé fait partie du portrait type du chancre syphilitique, avec l'induration et l'indolence (p. 188).\n**Piège** : chancre mou = fond sale, douleurs (+++), adénopathies inflammatoires ; herpès = ulcérations superficielles douloureuses à contours polycycliques (p. 197).\n**À relier** : l'adénopathie satellite du chancre syphilitique est au contraire non inflammatoire, le plus souvent unilatérale (p. 190)."},{"id":"d162-qroc-792","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Comment met-on en évidence l'induration d'un chancre syphilitique ?","answer":"Impossibilité de plisser la lésion entre deux doigts","accept":["plisser entre deux doigts","impossible de plisser","pincer entre deux doigts"],"keywords":["doigts"],"explanation":"La surface de l'ulcération ne peut pas être plissée entre deux doigts : elle fait bloc avec l'induration sous-jacente (seul caractère vraiment évocateur).","src":"p. 188","deep":"**Pourquoi** : la surface de la lésion fait bloc avec l'induration sous-jacente, d'où l'impossibilité de la plisser entre deux doigts : c'est le seul caractère sémiologique vraiment évocateur (p. 188).\n**Piège** : même l'induration n'est pas pathognomonique : aucun caractère du chancre ne l'est (p. 189).\n**À relier** : devant une ulcération génitale, l'OMS recommande de traiter sans attendre le résultat des TT et TNT (p. 197)."},{"id":"d162-qroc-793","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quel aspect particulier peuvent présenter des chancres syphilitiques multiples ?","answer":"Des images en miroir","accept":["images en miroir","en miroir","miroir"],"keywords":["miroir"],"explanation":"Le chancre est unique en général, mais peut être multiple avec des images en miroir.","src":"p. 188","deep":"**Pourquoi** : le chancre syphilitique est en général unique, mais il peut être multiple, avec des images en miroir (p. 188).\n**Piège** : la multiplicité n'élimine pas la syphilis ; le chancre mou peut aussi donner des lésions uniques ou multiples, mais à fond sale et très douloureuses (p. 197).\n**À relier** : l'herpès donne des ulcérations superficielles, douloureuses, à contours polycycliques (p. 197)."},{"id":"d162-qroc-794","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":1,"question":"Quel est le siège électif du chancre syphilitique chez l'homme ?","answer":"Le sillon balano-préputial","accept":["sillon balano-préputial","sillon balanopréputial","sillon"],"keywords":["sillon"],"explanation":"Chez l'homme, le chancre siège assez électivement dans le sillon balano-préputial, plus rarement sur le gland ou le fourreau.","src":"p. 189","deep":"**Pourquoi** : chez l'homme, le chancre siège assez électivement dans le sillon balano-préputial ; le gland et le fourreau sont plus rarement atteints (p. 189).\n**Piège** : les condylomes siègent aussi au sillon et au frein balano-préputial, mais ce sont des masses charnues hérissées de verrucosités, pas une ulcération (p. 201, 203).\n**À relier** : dans les deux sexes, chancres buccal ou pharyngé (fellation) et anorectal, souvent méconnus (p. 188-189)."},{"id":"d162-qroc-795","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Où siège le plus souvent le chancre syphilitique chez la femme ?","answer":"Sur la vulve (petites lèvres, grandes lèvres, fourchette)","accept":["vulve","partie externe de la vulve","petites lèvres"],"keywords":["vulv"],"explanation":"Chez la femme, le chancre est le plus souvent vulvaire ; plus rarement vaginal, il passe alors volontiers inaperçu.","src":"p. 189","deep":"**Pourquoi** : chez la femme, le chancre siège le plus souvent sur la partie externe de la vulve : petites lèvres, grandes lèvres, fourchette (p. 189).\n**Piège** : un chancre vaginal ou du col passe volontiers inaperçu ; au col, l'adénopathie satellite n'est pas cliniquement visible (p. 188-190).\n**À relier** : (rang B) la sérologie syphilis est obligatoire au 1er trimestre de grossesse, et la transmission maternofœtale est possible (surtout après la 16e SA) (p. 188)."},{"id":"d162-qroc-796","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":2,"question":"Quelles localisations muqueuses extragénitales peut avoir un chancre syphilitique, dans les deux sexes ?","answer":"Buccale ou pharyngée (fellation) et anorectale","accept":["buccale et anorectale","pharyngée et anorectale","anorectale et buccale","anorectale et pharyngée"],"keywords":["bucc","anorect"],"explanation":"Dans les deux sexes, le chancre peut siéger sur la muqueuse buccale ou pharyngée (fellation) ou anorectale.","src":"p. 189","deep":"**Pourquoi** : le chancre siège au point d'inoculation : dans les deux sexes, il peut être buccal ou pharyngé (fellation) ou anorectal (p. 188-189).\n**Piège** : les chancres pharyngé et anorectal ne sont pas visibles : la syphilis primaire est alors souvent méconnue (p. 188).\n**À relier** : évoquer systématiquement la syphilis devant toute ulcération muqueuse, génitale, anale ou buccopharyngée (p. 197)."},{"id":"d162-qroc-797","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique"],"difficulty":3,"question":"Quelle particularité de l'adénopathie satellite existe quand le chancre siège sur le col utérin ou le rectum ?","answer":"Elle n'est pas visible cliniquement","accept":["non visible","pas visible","pas cliniquement visible","invisible"],"keywords":["non visible"],"explanation":"Pour les chancres du col utérin et du rectum, l'adénopathie satellite n'est pas visible cliniquement.","src":"p. 190","deep":"**Pourquoi** : l'adénopathie satellite du chancre est non inflammatoire et le plus souvent unilatérale ; au col utérin et au rectum, elle n'est pas cliniquement visible (p. 190).\n**Piège** : des adénopathies inflammatoires avec des lésions très douloureuses orientent plutôt vers un chancre mou (p. 197).\n**À relier** : chancre du col ou anorectal = chancre non visible, syphilis primaire souvent méconnue (p. 188)."},{"id":"d162-qroc-798","type":"QROC","rank":"A","objective":"d162-obj-07","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Que devient un chancre syphilitique en l'absence de traitement ?","answer":"Régression spontanée sans séquelle en quelques semaines","accept":["régression spontanée","guérison spontanée","disparaît spontanément"],"keywords":["spontan"],"explanation":"Le chancre régresse sans séquelle en quelques semaines (rarement plusieurs mois) : le patient paraît guéri mais la maladie peut évoluer vers les stades suivants.","src":"p. 190","deep":"**Pourquoi** : le chancre régresse spontanément sans séquelle en quelques semaines (rarement, il persiste plusieurs mois) : le patient paraît guéri, mais il peut évoluer vers des stades plus tardifs (p. 190).\n**Piège** : environ 30 % des patients ayant eu un chancre visible présenteront une syphilis secondaire, et un stade tardif est possible sans signe secondaire (p. 190).\n**À relier** : devant une ulcération génitale, l'OMS recommande de traiter sans attendre la sérologie (p. 197)."},{"id":"d162-qroc-799","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique","épidémiologie"],"difficulty":2,"question":"Quelle proportion des patients ayant eu un chancre visible, non traités, présentera une syphilis secondaire ?","answer":"Environ 30 %","accept":["30 %","30","environ 30 %"],"keywords":["30"],"explanation":"Environ 30 % des chancres visibles non traités évoluent vers la syphilis secondaire ; une syphilis tardive peut aussi apparaître sans passer par des signes secondaires.","src":"p. 190","deep":"**Pourquoi** : sans traitement, environ 30 % des patients ayant présenté un chancre visible auront des signes de syphilis secondaire (p. 190).\n**Piège** : les autres ne sont pas guéris pour autant : une évolution vers une syphilis tardive (tertiaire ou latente tardive) est possible sans signe secondaire (p. 190).\n**À relier** : (rang B) 30 % est aussi la fréquence approximative des syphilides palmo-plantaires au cours du secondaire (p. 192)."},{"id":"d162-qroc-801","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":1,"question":"Quelle est la durée habituelle de la syphilis secondaire ?","answer":"Inférieure à 1 an","accept":["moins de 1 an","inférieure à 1 an","moins d'un an","< 1 an"],"keywords":["1 an"],"explanation":"La syphilis secondaire dure en règle moins de 1 an ; elle appartient, avec la primaire et la latente précoce, à la syphilis précoce (p. 188, 190).","src":"p. 190","deep":"**Pourquoi** : la syphilis secondaire correspond à la diffusion systémique du tréponème ; elle évolue par éruptions (« floraisons ») séparées de phases asymptomatiques de quelques semaines ou mois, en règle sur moins de 1 an (p. 190).\n**Piège** : le seuil de 1 an sépare aussi syphilis précoce et tardive, et latente précoce et latente tardive (p. 188).\n**À relier** : le TNT reste très positif pendant toute la phase secondaire, avec un plateau généralement entre 1/16 et 1/128 (p. 195)."},{"id":"d162-qroc-802","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["physiopathologie"],"difficulty":2,"question":"Quel mécanisme est à l'origine de la syphilis secondaire ?","answer":"La diffusion systémique du tréponème","accept":["diffusion systémique","dissémination","diffusion générale"],"keywords":["diffusion"],"explanation":"La syphilis secondaire correspond à la diffusion systémique du tréponème, d'où les éruptions cutanéo-muqueuses et les signes généraux ou viscéraux.","src":"p. 190","deep":"**Pourquoi** : le tréponème diffuse dans tout l'organisme : éruptions cutanéo-muqueuses et signes généraux qui traduisent la dissémination (fébricule, polyadénopathies, hépatosplénomégalie…) (p. 190, 193).\n**Piège** : les céphalées ne signent pas forcément une atteinte neuroméningée : elles sont souvent secondaires à des micro-abcès périostés (p. 193).\n**À relier** : à ce stade, TT et TNT sont toujours positifs (p. 195)."},{"id":"d162-qroc-803","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Comment appelle-t-on les poussées éruptives de la syphilis secondaire, entrecoupées de phases asymptomatiques ?","answer":"Les « floraisons »","accept":["floraisons","floraison"],"keywords":["floraison"],"explanation":"Les éruptions cutanéo-muqueuses (« floraisons ») alternent avec des phases asymptomatiques de quelques semaines ou mois.","src":"p. 190","deep":"**Pourquoi** : plusieurs éruptions cutanéo-muqueuses (« floraisons ») se succèdent, entrecoupées de phases asymptomatiques de quelques semaines ou mois, avec des signes généraux et parfois viscéraux d'intensité variable (p. 190).\n**Piège** : la première floraison, la roséole, passe souvent inaperçue (peu intense, disparaît spontanément en 7 à 10 jours) (p. 190).\n**À relier** : le TNT reste très positif durant toute la phase secondaire (p. 195)."},{"id":"d162-qroc-804","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique","pièges"],"difficulty":1,"question":"Pourquoi la syphilis secondaire est-elle surnommée « la grande simulatrice » ?","answer":"Polymorphisme des lésions cliniques","accept":["polymorphisme","lésions polymorphes","éruptions polymorphes"],"keywords":["polymorph"],"explanation":"Le diagnostic n'est pas toujours évoqué à cause du polymorphisme des lésions : il faut y penser devant toute éruption maculo-papuleuse, fugace ou persistante.","src":"p. 190","deep":"**Pourquoi** : roséole, papules, syphilides palmo-plantaires et génitales, lésions du visage, de la langue, des phanères : cette diversité fait que le diagnostic n'est pas toujours évoqué (p. 190-192).\n**Piège** : roséole ≈ virose (primo-infection VIH à éliminer) ou toxidermie ; papules ≈ psoriasis, lichen plan, eczéma ; visage ≈ dermatite séborrhéique, acné, psoriasis (p. 197).\n**À relier** : y penser devant toute éruption maculo-papuleuse et chercher des papules cuivrées, notamment palmo-plantaires (p. 197, 200)."},{"id":"d162-qroc-805","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Dans quel délai après le chancre survient la roséole syphilitique ?","answer":"Dans les 6 semaines","accept":["6 semaines","six semaines","dans les 6 semaines"],"keywords":["6 semaines"],"explanation":"La roséole est la première éruption de la syphilis secondaire, dans les 6 semaines après le chancre.","src":"p. 190","deep":"**Pourquoi** : la roséole est la 1re éruption de la syphilis secondaire, dans les 6 semaines qui suivent le chancre ; elle disparaît spontanément en 7 à 10 jours (p. 190).\n**Piège** : 6 semaines est aussi le seuil des sujets contacts : contact de moins de 6 semaines avec une syphilis certaine → traitement d'emblée (p. 198).\n**À relier** : la roséole peut faire évoquer une virose (primo-infection VIH à éliminer) ou une toxidermie (p. 197)."},{"id":"d162-qroc-806","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":1,"question":"Quelle est la lésion élémentaire de la roséole syphilitique ?","answer":"Des macules rose pâle, disséminées sur le tronc","accept":["macules rose pâle","macules roses","macules"],"keywords":["macule"],"explanation":"La roséole associe des macules rose pâle de 5 à 15 mm sur le tronc, sans signes fonctionnels, et disparaît spontanément en 7 à 10 jours.","src":"p. 190","deep":"**Pourquoi** : la roséole est faite de macules rose pâle de 5 à 15 mm, disséminées sur le tronc, sans signe fonctionnel (p. 190).\n**Piège** : les syphilides papuleuses, plus tard, sont des papules monomorphes de couleur cuivrée, parfois avec une fine desquamation périlésionnelle (p. 191).\n**À relier** : diagnostic différentiel : virose (primo-infection VIH à éliminer) et toxidermie à type d'exanthème maculeux (p. 197)."},{"id":"d162-qroc-807","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Quels signes fonctionnels accompagnent la roséole syphilitique ?","answer":"Aucun","accept":["aucun","absence de signes fonctionnels","pas de signes fonctionnels"],"keywords":["aucun"],"explanation":"La roséole est peu intense, transitoire et sans signe fonctionnel : elle passe souvent inaperçue.","src":"p. 190","deep":"**Pourquoi** : la roséole est peu intense, transitoire (7 à 10 jours) et sans signe fonctionnel : elle passe souvent inaperçue (p. 190).\n**Piège** : les syphilides génitales et périnéales sont, elles aussi, indolores et non prurigineuses, mais très contagieuses (p. 192).\n**À relier** : le chancre est également indolore, à la différence de l'herpès (p. 188)."},{"id":"d162-qroc-808","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Quelle modification de surface, évocatrice mais non spécifique, entoure parfois les papules de la syphilis secondaire ?","answer":"Une fine desquamation périlésionnelle","accept":["desquamation","fine desquamation","desquamation périlésionnelle"],"keywords":["desquamation"],"explanation":"Une fine desquamation périlésionnelle est inconstante, évocatrice mais non spécifique ; les papules peuvent aussi être nécrotiques, croûteuses ou ulcérées.","src":"p. 191","deep":"**Pourquoi** : la fine desquamation périlésionnelle est inconstante, évocatrice mais non spécifique (p. 191).\n**Piège** : ces papules peuvent simuler un psoriasis (érythémato-squameux), un lichen plan ou un eczéma (p. 197).\n**À relier** : la lésion élémentaire est presque toujours une papule, monomorphe, cuivrée, en nombre variable (quelques-unes à plus d'une centaine), parfois nécrotique, croûteuse ou ulcérée (p. 191)."},{"id":"d162-qroc-809","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique","épidémiologie"],"difficulty":2,"question":"Quelle est la fréquence des syphilides palmo-plantaires dans la syphilis secondaire ?","answer":"Environ 30 % des cas (inconstantes)","accept":["30 %","30","environ 30 %"],"keywords":["30"],"explanation":"Elles sont inconstantes (environ 30 %) et souvent discrètes, mais très évocatrices : il faut penser à les chercher.","src":"p. 192","deep":"**Pourquoi** : les syphilides palmo-plantaires sont inconstantes (environ 30 % des cas) et souvent discrètes, mais très évocatrices : il faut penser à les rechercher (p. 192).\n**Piège** : leur absence n'élimine pas une syphilis secondaire, puisqu'elles ne sont présentes que dans environ 30 % des cas (p. 192).\n**À relier** : ce sont des papules cuivrées, siégeant électivement à cheval sur les plis palmaires (p. 192)."},{"id":"d162-qroc-810","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Comment les syphilides palmo-plantaires siègent-elles par rapport aux plis palmaires ?","answer":"À cheval sur les plis palmaires","accept":["à cheval sur les plis","cheval sur les plis palmaires"],"keywords":["cheval"],"explanation":"Elles sont cuivrées et siègent électivement à cheval sur les plis palmaires.","src":"p. 192","deep":"**Pourquoi** : les syphilides palmo-plantaires sont des papules cuivrées qui siègent électivement à cheval sur les plis palmaires (p. 192).\n**Piège** : souvent discrètes et présentes dans environ 30 % des cas seulement : il faut les chercher à l'examen (p. 192).\n**À relier** : des papules palmo-plantaires évoquent très fortement une syphilis secondaire, stade où TT et TNT sont toujours fortement positifs (p. 200)."},{"id":"d162-qroc-811","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Quels sont les caractères fonctionnels et le risque des syphilides génitales et périnéales ?","answer":"Indolores, non prurigineuses ; très contagieuses","accept":["indolores, non prurigineuses, très contagieuses","indolores non prurigineuses très contagieuses","indolores, non prurigineuses et très contagieuses"],"keywords":["indolore","contagie"],"explanation":"Elles sont indolores, non prurigineuses, en général multiples, molles, papuleuses ou érosives, et très contagieuses.","src":"p. 192","deep":"**Pourquoi** : les syphilides génitales et périnéales sont indolores, non prurigineuses, en général multiples, molles, papuleuses ou érosives, et très contagieuses (p. 192).\n**Piège** : en zone anogénitale, des syphilides de type condylomata lata figurent dans le diagnostic différentiel des condylomes acuminés (p. 203).\n**À relier** : lésions contagieuses de la syphilis = lésions muqueuses, et syphilides en cas de grattage ou d'excoriation (p. 188)."},{"id":"d162-qroc-812","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Comment reconnaît-on la fausse perlèche de la syphilis secondaire ?","answer":"Papule commissurale fendue en deux (et non simple fissure)","accept":["papule commissurale","fendue en deux","papule fendue en deux"],"keywords":["papule","deux"],"explanation":"Contrairement à une perlèche banale (fissure sans relief du fond du pli), la fausse perlèche est une papule commissurale fendue en deux.","src":"p. 192","deep":"**Pourquoi** : la fausse perlèche est une papule commissurale fendue en deux, alors qu'une perlèche banale est une simple fissure sans relief du fond du pli (p. 192).\n**Piège** : elle fait partie des signes cutanéo-phanériens « plus trompeurs », avec les lésions séborrhéiques des sillons nasogéniens, les papules acnéiformes du menton et les plaques fauchées de la langue (p. 192).\n**À relier** : la lésion élémentaire de la syphilis secondaire est presque toujours une papule (p. 191)."},{"id":"d162-qroc-813","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Quelles lésions trompeuses du visage peut-on observer au cours de la syphilis secondaire (sillons nasogéniens, menton) ?","answer":"Lésions d'allure séborrhéique ; papules acnéiformes du menton","accept":["allure séborrhéique et papules acnéiformes","papules acnéiformes et lésions d'allure séborrhéique","séborrhéiques et acnéiformes"],"keywords":["seborrh","acneiform"],"explanation":"Les sillons nasogéniens peuvent porter des lésions d'allure séborrhéique et le menton des papules acnéiformes : elles simulent dermatite séborrhéique ou acné.","src":"p. 192","deep":"**Pourquoi** : au visage, on peut voir des lésions d'allure séborrhéique des sillons nasogéniens et des papules acnéiformes du menton (p. 192).\n**Piège** : d'où des confusions possibles avec une dermatite séborrhéique, une acné ou un psoriasis (p. 197).\n**À relier** : autres signes trompeurs : fausse perlèche, dépapillation linguale en plaques fauchées, dépilation des sourcils, alopécie en « fourrure mitée » (p. 192)."},{"id":"d162-qroc-814","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Quelle atteinte linguale évoque une syphilis secondaire ?","answer":"Dépapillation en aires (plaques « fauchées »)","accept":["plaques fauchées","dépapillation en aires","dépapillation"],"keywords":["fauch","depapill"],"explanation":"La dépapillation de la langue en aires, dite en plaques « fauchées », fait partie des signes cutanéo-muqueux trompeurs.","src":"p. 192","deep":"**Pourquoi** : la dépapillation en aires de la langue (« plaques fauchées ») fait partie des signes cutanéo-muqueux trompeurs du secondaire (p. 192).\n**Piège** : à la commissure, la fausse perlèche syphilitique est une papule fendue en deux, pas une simple fissure (p. 192).\n**À relier** : les lésions muqueuses de la syphilis sont contagieuses (p. 188)."},{"id":"d162-qroc-815","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique"],"difficulty":2,"question":"Quelles atteintes des poils et des cheveux peut-on observer dans la syphilis secondaire ?","answer":"Dépilation des sourcils ; alopécie « en fourrure mitée »","accept":["dépilation des sourcils et alopécie en fourrure mitée","alopécie en fourrure mitée et dépilation des sourcils","sourcils et fourrure mitée","fourrure mitée et sourcils"],"keywords":["fourrure","sourcil"],"explanation":"On peut voir une dépilation des sourcils et une alopécie récente faite de plusieurs aires incomplètement dépilées sur un cuir chevelu intact, dite en « fourrure mitée ».","src":"p. 192","deep":"**Pourquoi** : alopécie récente faite de plusieurs aires incomplètement dépilées sur un cuir chevelu intact (« fourrure mitée ») et dépilation des sourcils (p. 192).\n**Piège** : ces signes sont classés parmi les symptômes cutanéo-phanériens « plus trompeurs » : il faut y penser, la syphilis secondaire étant la « grande simulatrice » (p. 190, 192).\n**À relier** : l'alopécie est une situation de départ de cet item ; devant une éruption évocatrice, un test tréponémique est obligatoire (p. 177, 200)."},{"id":"d162-qroc-816","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique","pièges"],"difficulty":3,"question":"À quoi sont souvent secondaires les céphalées de la syphilis secondaire, qui ne signent pas forcément une atteinte neuroméningée ?","answer":"À des micro-abcès périostés","accept":["micro-abcès périostés","microabcès périostés","abcès périostés"],"keywords":["periost"],"explanation":"Les céphalées ne sont pas synonymes d'atteinte neuroméningée : elles sont souvent liées à des micro-abcès périostés.","src":"p. 193","deep":"**Pourquoi** : les céphalées font partie des signes généraux et ne sont pas synonymes d'atteinte neuroméningée : elles sont souvent secondaires à des micro-abcès périostés (p. 193).\n**Piège** : en revanche, une atteinte ophtalmique ou d'une paire crânienne (hypoacousie, acouphènes, paralysie faciale) est une neurosyphilis précoce (p. 193).\n**À relier** : un syndrome méningé fait aussi partie des signes généraux possibles du secondaire (p. 193)."},{"id":"d162-qroc-817","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique","paraclinique"],"difficulty":2,"question":"Quelle atteinte biologique hépatique peut accompagner l'hépatosplénomégalie de la syphilis secondaire ?","answer":"Hépatite biologique cytolytique ou cholestatique","accept":["hépatite cytolytique","hépatite cholestatique","cytolytique","cholestatique"],"keywords":["cytolytique","cholestatique"],"explanation":"L'hépatosplénomégalie s'accompagne d'une hépatite biologique cytolytique ou cholestatique.","src":"p. 193","deep":"**Pourquoi** : l'hépatosplénomégalie du secondaire peut s'accompagner d'une hépatite biologique cytolytique ou cholestatique ; ces signes généraux traduisent la dissémination de l'infection (p. 193).\n**Piège** : les signes généraux sont le plus souvent discrets, mais peuvent être sévères (p. 193).\n**À relier** : autres signes généraux : fébricule, polyadénopathies, polyarthralgies, douleurs osseuses, raucité de la voix, altération de l'état général (p. 193)."},{"id":"d162-qroc-818","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["clinique","urgence"],"difficulty":3,"question":"Au cours de la syphilis secondaire, quelle conduite impose une atteinte ophtalmique (uvéite, papillite, névrite optique) ?","answer":"Ponction lombaire + pénicilline G 14 jours, quel que soit le résultat","accept":["ponction lombaire et pénicilline g","ponction lombaire pénicilline g 14 jours"],"keywords":["ponction","14"],"explanation":"Une atteinte ophtalmique est interprétée comme une neurosyphilis précoce : ponction lombaire, puis pénicilline G pendant 14 jours quel que soit le résultat de la ponction.","src":"p. 193","deep":"**Pourquoi** : une atteinte ophtalmique (surtout uvéite antérieure, mais aussi postérieure, papillite, névrite optique) est interprétée comme une neurosyphilis précoce (p. 193).\n**Piège** : ne pas attendre une PL anormale pour traiter, et ne pas se contenter d'une injection unique de benzathine-benzylpénicilline (p. 193, 198).\n**À relier** : interroger sur les troubles visuels (baisse d'acuité, phosphènes, douleurs) ; l'atteinte d'une paire crânienne a la même valeur (p. 193)."},{"id":"d162-qroc-819","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle primo-infection doit être éliminée devant une roséole syphilitique pouvant évoquer une virose ?","answer":"La primo-infection par le VIH","accept":["primo-infection vih","primo infection vih","primo-infection par le vih"],"keywords":["vih"],"explanation":"La roséole peut faire évoquer une virose (primo-infection VIH à éliminer) ou une toxidermie maculeuse.","src":"p. 197","deep":"**Pourquoi** : la roséole (macules rose pâle du tronc) peut faire évoquer une virose : une primo-infection VIH doit alors être éliminée (p. 197).\n**Piège** : l'autre confusion classique est la toxidermie (exanthème maculeux) (p. 197).\n**À relier** : 40 % des syphilitiques sont infectés par le VIH, qui fait partie des IST à rechercher devant une syphilis (p. 188, 197)."},{"id":"d162-qroc-820","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["diagnostic","pièges"],"difficulty":1,"question":"Avec quelles éruptions ne faut-il pas confondre la roséole syphilitique ?","answer":"Une éruption virale et une toxidermie","accept":["éruption virale et toxidermie","virose et toxidermie","toxidermie et virose","toxidermie et éruption virale"],"keywords":["viral","toxiderm"],"explanation":"La roséole syphilitique ne doit pas être confondue avec une éruption virale ou une toxidermie ; la prescription d'un test tréponémique est alors obligatoire.","src":"p. 200","deep":"**Pourquoi** : les points clés demandent de ne pas confondre la roséole syphilitique avec une éruption virale ou une toxidermie, et rendent la prescription d'un test tréponémique obligatoire dans ces circonstances (p. 200).\n**Piège** : (rang B) devant une « virose », penser à éliminer une primo-infection VIH ; la roséole passe souvent inaperçue car peu intense et transitoire (p. 190, 197).\n**À relier** : au stade secondaire, TT et TNT sont toujours fortement positifs (p. 200)."},{"id":"d162-qroc-821","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["diagnostic"],"difficulty":2,"question":"Citez une dermatose du visage que la syphilis secondaire peut mimer.","answer":"Dermatite séborrhéique, acné ou psoriasis","accept":["dermatite séborrhéique","acné","psoriasis"],"keywords":["seborrh","acne","psoriasis"],"explanation":"Au visage, la syphilis secondaire peut mimer une dermatite séborrhéique, une acné ou un psoriasis.","src":"p. 197","deep":"**Pourquoi** : au visage, la syphilis secondaire peut donner des lésions d'allure séborrhéique des sillons nasogéniens ou des papules acnéiformes du menton (p. 192, 197).\n**Piège** : sur le corps, les lésions papuleuses peuvent simuler un psoriasis, un lichen plan ou un eczéma (p. 197).\n**À relier** : « grande simulatrice » : l'évoquer devant toute éruption maculo-papuleuse, fugace ou persistante (p. 197)."},{"id":"d162-qroc-822","type":"QROC","rank":"B","objective":"d162-obj-25","tags":["diagnostic"],"difficulty":2,"question":"Quelles dermatoses les lésions papuleuses de la syphilis secondaire peuvent-elles simuler (en dehors du psoriasis) ?","answer":"Lichen plan et eczéma","accept":["lichen plan et eczéma","eczéma et lichen plan","lichen plan eczéma"],"keywords":["lichen","eczema"],"explanation":"Les papules peuvent simuler un psoriasis (érythémato-squameux), un lichen plan ou un eczéma.","src":"p. 197","deep":"**Pourquoi** : les syphilides papuleuses, parfois finement desquamatives, peuvent simuler un psoriasis (érythémato-squameux), un lichen plan ou un eczéma (p. 191, 197).\n**Piège** : la couleur cuivrée et la présence de papules palmo-plantaires doivent faire évoquer la syphilis (p. 191-192, 200).\n**À relier** : la roséole, elle, mime une virose ou une toxidermie (p. 197)."},{"id":"d162-qroc-823","type":"QROC","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Quelle cause d'ulcération génitale se manifeste par des lésions granulomateuses peu douloureuses chez des sujets africains ?","answer":"La donovanose","accept":["donovanose","la donovanose"],"keywords":["donovanose"],"explanation":"La donovanose (terrain africain, lésions granulomateuses peu douloureuses) fait partie du diagnostic différentiel du chancre syphilitique, avec l'herpès, le chancre mou et la maladie de Nicolas-Favre.","src":"p. 197","deep":"**Pourquoi** : au stade de chancre, le diagnostic différentiel est celui des ulcérations génitales ; la donovanose se distingue par un terrain africain et des lésions granulomateuses peu douloureuses (p. 196-197).\n**Piège** : le chancre mou survient aussi sur terrain africain, mais avec un fond sale, des douleurs (+++) et des adénopathies inflammatoires (p. 197).\n**À relier** : maladie de Nicolas-Favre (lymphogranulomatose vénérienne) : anorectite, ulcérations anogénitales, diarrhées trompeuses (p. 197)."},{"id":"d162-qroc-824","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","physiopathologie"],"difficulty":2,"question":"Pourquoi le diagnostic de syphilis ne peut-il pas reposer sur la culture du germe ?","answer":"Le tréponème ne se cultive pas in vitro","accept":["ne se cultive pas","pas de culture","non cultivable"],"keywords":["cultiv"],"explanation":"Faute de culture possible, le diagnostic se fait par mise en évidence du tréponème (fond noir, biologie moléculaire, immunohistochimie) ou, indirectement, par la sérologie (p. 194).","src":"p. 194","deep":"**Pourquoi** : sans culture possible, il reste la mise en évidence directe (fond noir, abandonné ; biologie moléculaire, non remboursée ; immunohistochimie sur biopsie) ou indirecte par la sérologie (p. 194).\n**Piège** : (rang B) à l'inverse, pour le gonocoque, la culture sur gélose au sang cuit avec antibiogramme est systématique (p. 182).\n**À relier** : en pratique, ELISA en première intention, puis un TNT seulement si l'ELISA est positif (p. 194)."},{"id":"d162-qroc-825","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":1,"question":"Quels sont les deux tests non tréponémiques (TNT) de la syphilis ?","answer":"Le VDRL et le RPR","accept":["vdrl et rpr","rpr et vdrl","vdrl rpr","rpr vdrl"],"keywords":["vdrl","rpr"],"explanation":"Les TNT (VDRL, RPR) ne sont pas spécifiques des tréponématoses ; les tests tréponémiques sont l'ELISA et le TPHA.","src":"p. 194","deep":"**Pourquoi** : TNT = VDRL et RPR ; TT = ELISA et TPHA. Le TT affirme ou infirme la tréponématose, le TNT en précise l'évolutivité (p. 194, 200).\n**Piège** : les TNT ne sont pas spécifiques des tréponématoses : un TNT positif isolé (TT négatif) correspond en général à une fausse sérologie (p. 194, 196).\n**À relier** : le suivi après traitement se fait sur le TNT quantitatif (VDRL), dont le titre doit être divisé par 4 à 6 mois (p. 198)."},{"id":"d162-qroc-826","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":1,"question":"Quel test tréponémique, test d'agglutination manuel, est utilisé à côté de l'ELISA automatisé ?","answer":"Le TPHA","accept":["tpha","treponema pallidum haemagglutination assay"],"keywords":["tpha"],"explanation":"Les tests tréponémiques sont l'ELISA (immuno-enzymatique automatique) et le TPHA (agglutination manuelle) ; l'ELISA est réalisé en première intention.","src":"p. 194","deep":"**Pourquoi** : les deux TT sont l'ELISA (immuno-enzymatique automatique, résultat en IgM et IgG) et le TPHA (agglutination manuelle, coté en dilutions 1/80, 1/160, 1/320…) (p. 194).\n**Piège** : le TT quantitatif varie beaucoup d'un examen à l'autre : il ne suit ni l'évolutivité ni la réponse au traitement ; seul son résultat qualitatif compte (p. 194).\n**À relier** : les positivités non tréponémiques du TPHA sont exceptionnelles (lupus systémique, maladie de Lyme) (p. 195)."},{"id":"d162-qroc-827","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Citez une tréponématose endémique non vénérienne que la sérologie syphilitique ne permet pas de distinguer de la syphilis.","answer":"Pian, béjel ou pinta","accept":["pian","béjel","bejel","pinta"],"keywords":["pian","bejel","pinta"],"explanation":"Aucun test sérologique ne distingue la syphilis des tréponématoses endémiques non vénériennes (zones tropicales) : on devrait parler de sérologie des tréponématoses.","src":"p. 194","deep":"**Pourquoi** : les TT sont spécifiques des tréponématoses, pas de la syphilis : ils ne distinguent pas les anticorps syphilitiques de ceux des tréponématoses endémiques tropicales non vénériennes (pian, béjel, pinta) (p. 194).\n**Piège** : aucun test sérologique ne fait cette distinction : on devrait parler de « sérologie des tréponématoses » (p. 194).\n**À relier** : un TT positif signifie donc « tréponématose » (syphilis ou forme endémique) ; c'est le TNT qui renseigne sur l'évolutivité (p. 196)."},{"id":"d162-qroc-828","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"À partir de quand le test tréponémique se positive-t-il après l'apparition du chancre ?","answer":"Entre le 7e et le 10e jour","accept":["7e au 10e jour","7 à 10 jours","j7 à j10"],"keywords":["7","10"],"explanation":"Le TT se positive entre le 7e et le 10e jour du chancre ; le TNT se positive en moyenne 10 à 15 jours après.","src":"p. 194","deep":"**Pourquoi** : le TT est le premier à se positiver, entre le 7e et le 10e jour du chancre ; le TNT suit, en moyenne 10 à 15 jours après l'apparition du chancre (p. 194).\n**Piège** : dans les 7 premiers jours du chancre, TT et TNT peuvent être négatifs : le TT peut être négatif au tout début du chancre (p. 196, 200).\n**À relier** : recommandation OMS : devant une ulcération génitale, ne pas attendre les résultats des TT et TNT pour traiter (p. 197)."},{"id":"d162-qroc-829","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"En moyenne, combien de jours après l'apparition du chancre le TNT se positive-t-il ?","answer":"10 à 15 jours","accept":["10 à 15 jours","10-15 jours","10 à 15"],"keywords":["10","15"],"explanation":"Le TNT se positive en moyenne 10 à 15 jours après le chancre, après le TT (7e-10e jour).","src":"p. 194","deep":"**Pourquoi** : le TNT se positive après le TT, en moyenne 10 à 15 jours après le chancre, puis son titre monte jusqu'à un maximum entre le 3e et le 6e mois (p. 194-195).\n**Piège** : dans environ 10 % des syphilis primaires, le TNT se positive pourtant avant le TT (profil TT−/TNT+) (p. 195-196).\n**À relier** : au stade primaire, tous les profils TT/TNT sont possibles ; au stade secondaire, les deux tests sont toujours positifs (p. 195)."},{"id":"d162-qroc-830","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Pourquoi le VDRL et le RPR peuvent-ils être positifs en dehors de toute syphilis ?","answer":"Ils ne sont pas spécifiques des tréponématoses","accept":["pas spécifiques","non spécifiques","ne sont pas spécifiques"],"keywords":["specifique"],"explanation":"Le VDRL et le RPR (tests non tréponémiques) ne sont pas des réactions spécifiques des tréponématoses : d'où les fausses sérologies (lupus, SAPL, grossesse...).","src":"p. 194","deep":"**Pourquoi** : le VDRL et le RPR ne sont pas spécifiques des tréponématoses : ils peuvent être positifs au cours de maladies dysimmunitaires (lupus, SAPL), de la grossesse ou de certaines infections (Mycoplasma pneumoniae, borrélioses) (p. 194).\n**Piège** : un TNT positif isolé n'est pas toujours un faux positif : dans 10 % des syphilis primaires, il se positive avant le TT (p. 196).\n**À relier** : en pratique, le biologiste ne réalise un TNT que si l'ELISA est positif (p. 194)."},{"id":"d162-qroc-831","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"Comment définit-on le titre d'un test non tréponémique ?","answer":"La dernière dilution pour laquelle le test est positif","accept":["dernière dilution positive","dernière dilution"],"keywords":["derniere dilution"],"explanation":"On teste le sérum pur puis des dilutions de raison 2 (1/2, 1/4, 1/8...) ; le titre est la dernière dilution encore positive.","src":"p. 195","deep":"**Pourquoi** : on teste le sérum pur, puis, s'il est positif, des dilutions de pas de 2 (1/2, 1/4, 1/8…) ; le titre est la dernière dilution encore positive (p. 195).\n**Piège** : retenir le facteur 4 (2 dilutions) dans les deux sens : titre divisé par 4 à 6 mois = traitement efficace ; titre multiplié au moins par 4 = recontamination (p. 195).\n**À relier** : pendant la phase secondaire, le titre plafonne en général entre 1/16 et 1/128 (p. 195)."},{"id":"d162-qroc-832","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"Entre quelles valeurs se situe en général le plateau du titre du TNT durant la phase secondaire ?","answer":"Entre 1/16 et 1/128","accept":["1/16 et 1/128","1/16 à 1/128","1/16-1/128"],"keywords":["16","128"],"explanation":"Le titre du TNT monte rapidement jusqu'à un plateau généralement situé entre 1/16 et 1/128 ; il reste très positif pendant toute la phase secondaire.","src":"p. 195","deep":"**Pourquoi** : après la phase initiale, le titre du TNT monte rapidement jusqu'à un plateau, variable selon les patients, généralement entre 1/16 et 1/128 : le TNT reste très positif durant toute la phase secondaire (p. 195).\n**Piège** : ce titre ne permet pas de distinguer une syphilis latente précoce d'une latente tardive (p. 195).\n**À relier** : un titre élevé (1/16 par exemple) témoigne d'une maladie évolutive, sauf si elle est déjà traitée avec décroissance progressive du titre (p. 196)."},{"id":"d162-qroc-833","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","suivi"],"difficulty":3,"question":"Comment diagnostique-t-on biologiquement une recontamination syphilitique ?","answer":"Remontée du TNT : titre multiplié par au moins 4","accept":["titre multiplié par 4","multiplié par 4","x4","remontée du tnt"],"keywords":["multipli","4"],"explanation":"La syphilis n'étant pas immunisante, une recontamination se reconnaît à la clinique ou à une remontée significative du TNT quantitatif (titre multiplié au moins par 4).","src":"p. 195","deep":"**Pourquoi** : la syphilis n'étant pas immunisante, une recontamination se diagnostique sur la clinique ou sur une remontée significative du TNT quantitatif (titre multiplié au moins par 4) (p. 187, 195).\n**Piège** : le TT n'aide pas : son résultat quantitatif varie beaucoup d'un examen à l'autre, et un TT positif peut correspondre à une tréponématose guérie (TT+/TNT−) (p. 194-195).\n**À relier** : symétrique du critère d'efficacité thérapeutique : titre divisé par 4 (2 dilutions) à 6 mois (p. 195)."},{"id":"d162-qroc-834","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","suivi"],"difficulty":2,"question":"Que faire en l'absence de décroissance du titre du TNT 6 mois après le traitement d'une syphilis ?","answer":"3 injections de benzathine-benzylpénicilline 2,4 MU à 8 jours d'intervalle","accept":["3 injections de benzathine-benzylpénicilline","3 injections"],"keywords":["3 injections"],"explanation":"Sans décroissance (titre divisé par 4), on demande l'avis d'un spécialiste et le traitement repose sur 3 injections de benzathine-benzylpénicilline 2,4 MU à 8 jours d'intervalle.","src":"p. 198","deep":"**Pourquoi** : le traitement est jugé efficace si le titre du TNT est divisé par 4 (2 dilutions) à 6 mois ; sinon, avis d'un spécialiste et 3 injections de benzathine-benzylpénicilline 2,4 MU à 8 jours d'intervalle (p. 195, 198).\n**Piège** : le suivi ne se fait pas sur le TT quantitatif, trop variable d'un examen à l'autre (p. 194).\n**À relier** : contrôle clinique et biologique à 3 mois, 6 mois, 1 an puis tous les ans jusqu'à négativation (p. 198)."},{"id":"d162-qroc-835","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":3,"question":"Quels profils TT/TNT peut-on observer au cours de la syphilis primaire ?","answer":"Tous les profils possibles","accept":["tous les profils","tous","les quatre profils"],"keywords":["tous"],"explanation":"Au cours de la syphilis primaire, tous les profils sont observables (TT-/TNT-, TT+/TNT-, TT-/TNT+, TT+/TNT+) ; en secondaire, TT et TNT sont toujours positifs.","src":"p. 195","deep":"**Pourquoi** : au stade primaire, les tests se positivent progressivement : négatifs les 7 premiers jours, puis TT rapidement positif et TNT qui grimpe ; et dans 10 % des cas le TNT précède le TT. Tous les profils sont donc observables (p. 195).\n**Piège** : au stade secondaire, au contraire, TT et TNT sont toujours positifs (p. 195).\n**À relier** : recommandation OMS : devant une ulcération génitale, traiter sans attendre la sérologie (p. 197)."},{"id":"d162-qroc-836","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"À quel moment de la syphilis primaire le titre du TNT atteint-il son maximum ?","answer":"Entre le 3e et le 6e mois de la maladie","accept":["entre le 3e et le 6e mois","3e au 6e mois","3 à 6 mois"],"keywords":["3","6"],"explanation":"Passé les 7 premiers jours, le TT est rapidement positif et le TNT monte progressivement jusqu'à un maximum entre le 3e et le 6e mois.","src":"p. 195","deep":"**Pourquoi** : passé le 7e jour, le TT est rapidement positif et le TNT grimpe progressivement jusqu'à son maximum entre le 3e et le 6e mois de la maladie (p. 195).\n**Piège** : ne pas confondre avec le délai d'évaluation du traitement : le titre doit être divisé par 4 six mois APRÈS le traitement (p. 195, 198).\n**À relier** : pendant la phase secondaire, le plateau se situe en général entre 1/16 et 1/128 (p. 195)."},{"id":"d162-qroc-837","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"Quels résultats attend-on pour le TT et le TNT au stade de syphilis secondaire ?","answer":"Les deux toujours positifs","accept":["toujours positifs","deux positifs","tt et tnt positifs"],"keywords":["toujours","positif"],"explanation":"Au stade de syphilis secondaire, TT et TNT sont toujours (et fortement) positifs.","src":"p. 195","deep":"**Pourquoi** : contrairement au stade primaire, où tous les profils sont possibles, TT et TNT sont toujours fortement positifs au stade secondaire, le TNT étant en plateau (généralement 1/16 à 1/128) (p. 195, 200).\n**Piège** : ce titre ne permet pas de dater une syphilis latente (précoce ou tardive) (p. 195).\n**À relier** : (rang B) après traitement d'une syphilis secondaire, le TNT doit être négatif dans un délai de 2 ans (p. 198)."},{"id":"d162-qroc-838","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":3,"question":"Dans environ 10 % des cas, quel test se positive en premier au cours d'une syphilis primaire ?","answer":"Le TNT, avant le TT","accept":["tnt","le tnt","vdrl"],"keywords":["tnt"],"explanation":"Dans 10 % des cas, le TNT se positive avant le TT (profil TT-/TNT+) : un TNT isolément positif est donc en général une fausse sérologie, mais pas toujours.","src":"p. 195-196","deep":"**Pourquoi** : dans 10 % des syphilis primaires, le TNT se positive avant le TT : profil TT−/TNT+ (tableau 9.2) (p. 195-196).\n**Piège** : un TNT isolément positif correspond en général à une fausse sérologie (SAPL, lupus, grossesse), mais pas toujours : il peut s'agir d'une syphilis primaire débutante (p. 195-196).\n**À relier** : dans les 7 premiers jours du chancre, les deux tests peuvent être négatifs (p. 196)."},{"id":"d162-qroc-839","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":2,"question":"Que traduit un titre élevé de TNT (par exemple 1/16) chez un patient non traité ?","answer":"Une maladie évolutive","accept":["maladie évolutive","syphilis évolutive","évolutive"],"keywords":["evolutiv"],"explanation":"Un TNT à titre élevé témoigne toujours d'une maladie évolutive, sauf si elle est déjà traitée avec décroissance progressive du titre.","src":"p. 196","deep":"**Pourquoi** : le TT affirme la tréponématose ; le TNT, par sa positivité et son titre, renseigne sur l'évolutivité : un titre élevé (1/16 par exemple) témoigne toujours d'une maladie évolutive (p. 196).\n**Piège** : exception : maladie déjà traitée dont le titre décroît progressivement (p. 196).\n**À relier** : TT+/TNT− = tréponématose guérie (cicatrice sérologique), tréponématose très précoce ou syphilis tertiaire très ancienne (rare) (p. 195)."},{"id":"d162-qroc-840","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":1,"question":"Que précise le TNT une fois qu'un TT positif a affirmé une tréponématose ?","answer":"L'évolutivité de la maladie","accept":["évolutivité","activité de la maladie"],"keywords":["evolutiv"],"explanation":"Le TT affirme ou infirme la tréponématose ; le TNT en précise l'évolutivité.","src":"p. 196","deep":"**Pourquoi** : on lit la sérologie dans l'ordre : TT d'abord (positif = tréponématose, syphilis ou forme endémique), puis TNT, dont la positivité et le titre donnent l'évolutivité (p. 196).\n**Piège** : un TT négatif signifie absence de tréponématose ou guérison ; le biologiste ne réalise alors pas le TNT (p. 196).\n**À relier** : c'est aussi le TNT quantitatif (VDRL) qui sert au suivi du traitement (p. 198)."},{"id":"d162-qroc-841","type":"QROC","rank":"B","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"question":"Citez une cause non infectieuse de fausse sérologie syphilitique (VDRL positif), en dehors du lupus, du syndrome des anticorps antiphospholipides et de la grossesse.","answer":"Toxicomanie IV, hépatopathie chronique, gammapathie monoclonale, cancers","accept":["toxicomanie intraveineuse","hépatopathie chronique","gammapathie monoclonale","cancer"],"keywords":["hepatopathie","gammapathie","toxicomanie"],"explanation":"Causes non infectieuses : grossesse, toxicomanie intraveineuse, hépatopathie chronique, gammapathie monoclonale, lupus, SAPL, cancers.","src":"p. 195","deep":"**Pourquoi** : le VDRL n'est pas spécifique ; côté non infectieux, le tableau 9.3 cite grossesse, toxicomanie IV, hépatopathie chronique, gammapathie monoclonale, lupus systémique, SAPL et cancers (p. 195).\n**Piège** : une fausse sérologie a le profil TNT+ / TT− ; un TT positif oriente vers une vraie tréponématose (p. 196).\n**À relier** : les positivités non tréponémiques du TPHA, elles, sont exceptionnelles (lupus, maladie de Lyme) (p. 195)."},{"id":"d162-qroc-842","type":"QROC","rank":"B","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":3,"question":"Citez une cause infectieuse de fausse positivité du VDRL.","answer":"Lèpre, tuberculose, borréliose, varicelle, VIH, paludisme...","accept":["lèpre","tuberculose","borréliose","varicelle","vih","paludisme"],"keywords":["tuberculose","borreliose","paludisme"],"explanation":"Bactériennes (lèpre, tuberculose, pneumococcie, leptospirose, borréliose, scarlatine), virales (varicelle, oreillons, MNI, hépatite virale, rougeole, VIH) ou parasitaires (paludisme).","src":"p. 195","deep":"**Pourquoi** : le VDRL n'étant pas spécifique, de nombreuses infections le positivent (tableau 9.3) : bactériennes (lèpre, tuberculose, pneumococcie, leptospirose, borréliose, scarlatine), virales (varicelle, oreillons, MNI, hépatite virale, rougeole, VIH), parasitaires (paludisme) (p. 195).\n**Piège** : la maladie de Lyme peut aussi, exceptionnellement, positiver le TPHA (p. 195).\n**À relier** : Mycoplasma pneumoniae est également cité parmi les infections donnant une fausse sérologie (p. 194)."},{"id":"d162-qroc-843","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":3,"question":"Citez une cause exceptionnelle de positivité non tréponémique du TPHA.","answer":"Lupus systémique ou maladie de Lyme","accept":["lupus","maladie de lyme","lyme"],"keywords":["lupus","lyme"],"explanation":"Les faux positifs du TPHA sont exceptionnels (lupus systémique, maladie de Lyme), alors que le VDRL est souvent faussement positif.","src":"p. 195","deep":"**Pourquoi** : le TPHA est un test tréponémique, spécifique des tréponématoses : ses positivités non tréponémiques sont exceptionnelles (lupus systémique, maladie de Lyme…) (p. 194-195).\n**Piège** : à l'inverse, le VDRL, test non spécifique, a de nombreuses causes de faux positifs (tableau 9.3, rang B) (p. 195).\n**À relier** : fausse sérologie syphilitique = TNT+ / TT− (lupus, SAPL, grossesse) (p. 200)."},{"id":"d162-qroc-844","type":"QROC","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":1,"question":"Quel examen direct, rarement disponible et non remboursé, permet un diagnostic immédiat de certitude après grattage d'une lésion syphilitique ?","answer":"Le microscope à fond noir","accept":["microscope à fond noir","fond noir","microscopie à fond noir"],"keywords":["fond noir"],"explanation":"Le microscope à fond noir donne un diagnostic immédiat de certitude sur grattage d'une ulcération, érosion ou syphilide, mais n'est plus remboursé.","src":"p. 196","deep":"**Pourquoi** : le fond noir montre le tréponème lui-même après grattage d'une ulcération, d'une érosion ou d'une syphilide : diagnostic immédiat de certitude (p. 196).\n**Piège** : la technique est abandonnée, rarement disponible et sortie de la nomenclature ; en pratique, la sérologie débute par l'ELISA, le TNT n'étant réalisé que si l'ELISA est positif (p. 194, 196).\n**À relier** : le tréponème ne se cultivant pas in vitro, il n'existe pas de culture (p. 194)."},{"id":"d162-qroc-846","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement","diagnostic"],"difficulty":2,"question":"Devant une syphilis précoce suspectée, quels signes cliniques cherche-t-on lors de l'examen soigneux ?","answer":"Signes neurologiques et ophtalmologiques","accept":["neurologiques et ophtalmologiques","ophtalmologiques et neurologiques","neurologiques ophtalmologiques"],"keywords":["neurolog","ophtalm"],"explanation":"Devant une syphilis précoce, l'examen clinique soigneux recherche notamment des signes neurologiques et ophtalmologiques ; on recherche aussi une autre IST et on prescrit un test tréponémique (ELISA) (p. 197).","src":"p. 197","deep":"**Pourquoi** : devant une syphilis précoce, l'OMS demande un examen clinique soigneux (signes neurologiques, ophtalmologiques…), la recherche d'une autre IST et un test tréponémique (p. 197).\n**Piège** : (rang B) au stade secondaire, une atteinte ophtalmique ou d'une paire crânienne est une neurosyphilis précoce : PL et pénicilline G 14 jours, pas une simple injection de benzathine (p. 193).\n**À relier** : ne pas hésiter à prendre un avis spécialisé : femme enceinte, VIH, allergie à la pénicilline (p. 197)."},{"id":"d162-qroc-847","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement","diagnostic"],"difficulty":2,"question":"Quelles autres IST faut-il rechercher devant une syphilis précoce ?","answer":"Gonocoque, C. trachomatis, VIH, hépatite B","accept":["gonocoque chlamydia vih hépatite b","gonocoque, chlamydia, vih et hépatite b"],"keywords":["gonocoque","chlamydia","vih"],"explanation":"Rechercher une autre IST (gonocoque, C. trachomatis, VIH, hépatite B) et prescrire un test tréponémique (ELISA).","src":"p. 197","deep":"**Pourquoi** : une syphilis signe une sexualité à haut risque : il faut chercher une IST associée (gonocoque, C. trachomatis, VIH, hépatite B) (p. 197-198).\n**Piège** : (rang B) 40 % des syphilitiques sont infectés par le VIH : ne pas oublier la sérologie VIH (p. 188).\n**À relier** : à l'inverse, devant une urétrite, des condylomes ou une trichomonose, on propose sérologie VIH, test tréponémique et sérologie de l'hépatite B (p. 182, 205, 208)."},{"id":"d162-qroc-848","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement"],"difficulty":2,"question":"Dans quelles situations délicates recommande-t-on de contacter un spécialiste pour une syphilis précoce ?","answer":"Femme enceinte, patient VIH+, allergie à la pénicilline","accept":["femme enceinte, vih, allergie à la pénicilline","enceinte vih allergie"],"keywords":["enceinte","vih","allergie"],"explanation":"L'OMS conseille de ne pas hésiter à contacter un spécialiste dans ces trois situations.","src":"p. 197","deep":"**Pourquoi** : recommandation OMS : avis spécialisé si femme enceinte, VIH+ ou allergie à la pénicilline ; c'est aussi chez la femme enceinte et le VIH+ allergiques que la doxycycline cède la place à une induction de tolérance (p. 197-198).\n**Piège** : chez le VIH+ non allergique, le traitement standard par pénicilline est le même (p. 199).\n**À relier** : pendant la grossesse, la syphilis est grave : le tréponème peut atteindre le fœtus en traversant le placenta après le 4e mois (p. 200)."},{"id":"d162-qroc-849","type":"QROC","rank":"B","objective":"d162-obj-28","tags":["traitement"],"difficulty":1,"question":"Quel traitement symptomatique peut-on prescrire en cas de réaction d'Herxheimer ?","answer":"Un antipyrétique","accept":["antipyrétique","antipyrétiques"],"keywords":["antipyret"],"explanation":"Aucun protocole ne la prévient réellement ; on peut prescrire un antipyrétique et il faut prévenir le patient du risque.","src":"p. 198","deep":"**Pourquoi** : la réaction d'Herxheimer est secondaire à la lyse des tréponèmes ; aucun protocole ne la prévient réellement, mais un antipyrétique peut être prescrit (p. 198).\n**Piège** : toujours bénigne, elle ne doit pas être interprétée comme une allergie à la pénicilline (p. 198).\n**À relier** : il faut prévenir le patient du risque et des caractéristiques de cette réaction ; dans la syphilis primaire, elle est sans gravité (p. 198)."},{"id":"d162-qroc-850","type":"QROC","rank":"B","objective":"d162-obj-28","tags":["clinique","traitement"],"difficulty":1,"question":"Quels signes composent la réaction d'Herxheimer au stade secondaire ?","answer":"Fièvre, céphalées, myalgies, accentuation des signes cutanés","accept":["fièvre, céphalées, myalgies, accentuation des signes cutanés","fièvre céphalées myalgies accentuation des signes cutanés"],"keywords":["fievre","myalgies"],"explanation":"Quelques heures après l'injection : fièvre, céphalées, myalgies et accentuation des signes cutanés. Toujours bénigne, elle ne doit pas être prise pour une allergie à la pénicilline.","src":"p. 198","deep":"**Pourquoi** : au stade secondaire, quelques heures après l'injection, la lyse des tréponèmes peut donner fièvre, céphalées, myalgies et accentuation des signes cutanés (p. 198).\n**Piège** : ce n'est pas une allergie à la pénicilline : la réaction est toujours bénigne (p. 198).\n**À relier** : antipyrétique possible, aucun protocole préventif réellement efficace ; prévenir le patient (p. 198)."},{"id":"d162-qroc-851","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["traitement"],"difficulty":2,"question":"Chez quels patients allergiques à la pénicilline une induction de tolérance est-elle indiquée plutôt que la doxycycline ?","answer":"Femme enceinte et patient séropositif pour le VIH","accept":["femme enceinte et vih","femme enceinte et patient séropositif"],"keywords":["enceinte","vih"],"explanation":"La doxycycline 14 jours est le traitement de l'allergie, sauf chez la femme enceinte et le patient séropositif pour le VIH (induction de tolérance).","src":"p. 198","deep":"**Pourquoi** : en cas d'allergie à la pénicilline, l'alternative est la doxycycline 100 mg matin et soir pendant 14 jours, sauf chez la femme enceinte et le patient VIH+, chez qui une induction de tolérance est indiquée (p. 198).\n**Piège** : (rang B) une réaction d'Herxheimer ne doit pas être interprétée comme une allergie à la pénicilline (p. 198).\n**À relier** : ces deux terrains font partie des situations où contacter un spécialiste est recommandé (p. 197)."},{"id":"d162-qroc-852","type":"QROC","rank":"A","objective":"d162-obj-28","tags":["suivi"],"difficulty":2,"question":"À quels délais contrôle-t-on cliniquement et biologiquement l'efficacité du traitement d'une syphilis ?","answer":"3 mois, 6 mois, 1 an, puis tous les ans jusqu'à négativation","accept":["3 mois 6 mois 1 an","3, 6 et 12 mois"],"keywords":["3 mois","6 mois","1 an"],"explanation":"Contrôle à 3 mois, 6 mois et 1 an, puis chaque année jusqu'à négativation, sur le TNT quantitatif (VDRL).","src":"p. 198","deep":"**Pourquoi** : contrôle clinique et biologique à 3 mois, 6 mois, 1 an puis tous les ans jusqu'à négativation, sur le TNT quantitatif (VDRL) (p. 198).\n**Piège** : le critère d'efficacité se juge à 6 mois : titre divisé par 4 (2 dilutions) ; sinon avis spécialisé et 3 injections à 8 jours d'intervalle (p. 198).\n**À relier** : TNT négatif 1 an après une syphilis primaire, dans un délai de 2 ans après une syphilis secondaire (rang B) (p. 198)."},{"id":"d162-qroc-853","type":"QROC","rank":"B","objective":"d162-obj-28","tags":["suivi"],"difficulty":3,"question":"Dans quels délais le TNT doit-il être négatif après le traitement d'une syphilis primaire puis d'une syphilis secondaire ?","answer":"1 an (primaire) ; 2 ans (secondaire)","accept":["1 an et 2 ans","1 an pour la primaire et 2 ans pour la secondaire"],"keywords":["1 an","2 ans"],"explanation":"Le TNT doit être négatif 1 an après le traitement d'une syphilis primaire et dans un délai de 2 ans après celui d'une syphilis secondaire.","src":"p. 198","deep":"**Pourquoi** : après traitement, le TNT doit être devenu négatif à 1 an pour une syphilis primaire, et en 2 ans au plus pour une syphilis secondaire (p. 198).\n**Piège** : étape intermédiaire à ne pas oublier : titre divisé par 4 à 6 mois ; sinon le traitement doit être repris (p. 195, 198).\n**À relier** : on ne suit pas le TT : un TT positif avec TNT négatif peut être une cicatrice sérologique de tréponématose guérie (p. 194-195)."},{"id":"d162-qroc-854","type":"QROC","rank":"A","objective":"d162-obj-03","tags":["prévention","suivi"],"difficulty":1,"question":"Que faut-il rechercher chez un patient qui vient de contracter une syphilis ?","answer":"Une IST concomitante","accept":["ist concomitante","autre ist","ist associée"],"keywords":["ist"],"explanation":"Contracter une syphilis témoigne d'une activité sexuelle à haut risque : on recherche une IST concomitante (VIH, hépatite B, gonocoque, Chlamydia) et on renouvelle la prévention.","src":"p. 198","deep":"**Pourquoi** : une syphilis signe une sexualité à haut risque : on cherche une IST associée et on renouvelle les conseils de prévention des IST (p. 198).\n**Piège** : la syphilis n'est pas immunisante : un patient traité peut se recontaminer (p. 187).\n**À relier** : IST à rechercher : VIH (40 % des syphilitiques sont VIH+, rang B), hépatite B, gonocoque, C. trachomatis (p. 188, 197)."},{"id":"d162-qroc-855","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["prévention"],"difficulty":3,"question":"Que faire pour un contact sexuel d'un patient dont la syphilis est seulement douteuse ?","answer":"Examen + sérologie : si positive traiter, si négative refaire à 3 mois","accept":["sérologie traiter si positive refaire à 3 mois","sérologie puis refaire à 3 mois"],"keywords":["3 mois"],"explanation":"Si la syphilis du sujet source est douteuse, on examine le contact et on fait une sérologie : positive, on traite ; négative, on la refait à 3 mois.","src":"p. 198","deep":"**Pourquoi** : si la syphilis du sujet source est douteuse, on examine le contact et on fait une sérologie : positive → traiter ; négative → la refaire à 3 mois (p. 198).\n**Piège** : si la syphilis du sujet source est certaine et le contact date de moins de 6 semaines, on traite d'emblée (1 injection de 2,4 MU), sérologie prélevée (p. 198).\n**À relier** : syphilis certaine et contact de plus de 6 semaines : sérologie, traitement si positive, sinon nouvelle sérologie à 3 mois (p. 198)."},{"id":"d162-qroc-856","type":"QROC","rank":"A","objective":"d162-obj-29","tags":["traitement"],"difficulty":2,"question":"Le traitement d'une syphilis primaire ou secondaire est-il différent chez un patient séropositif pour le VIH ?","answer":"Non : le traitement standard par pénicilline est le même","accept":["identique","le même traitement","même traitement","même schéma"],"keywords":["identique"],"explanation":"Chez le patient séropositif pour le VIH, le traitement standard par pénicilline d'une syphilis primaire ou secondaire est le même ; on recommande une sérologie syphilis au moins 1 fois par an en cas de pratiques à risque (p. 199).","src":"p. 199","deep":"**Pourquoi** : le Collège ne modifie pas le schéma chez le VIH+ : pour une syphilis précoce, benzathine-benzylpénicilline 2,4 MU en une injection IM unique (p. 198-199).\n**Piège** : en cas d'allergie à la pénicilline, le patient VIH+ ne reçoit pas de doxycycline : une induction de tolérance est indiquée (p. 198).\n**À relier** : le patient VIH+ fait partie des situations où un avis spécialisé est recommandé (p. 197)."},{"id":"d162-qroc-857","type":"QROC","rank":"A","objective":"d162-obj-23","tags":["clinique","prévention"],"difficulty":1,"question":"Quel type de rapport sexuel transmet la syphilis ?","answer":"Tout rapport avec pénétration non protégé","accept":["rapport non protégé","pénétration non protégé","rapport avec pénétration non protégé"],"keywords":["protege"],"explanation":"La transmission est sexuelle après tout rapport avec pénétration non protégé ; l'incubation moyenne est de 3 semaines (p. 200).","src":"p. 200","deep":"**Pourquoi** : la syphilis se transmet après tout rapport avec pénétration non protégé (fellation comprise, rang B) ; l'incubation moyenne est de 3 semaines (p. 188, 200).\n**Piège** : (rang B) la transmission maternofœtale existe (surtout après la 16e SA), alors que les transmissions post-transfusionnelles ou après greffe sont exceptionnelles (p. 188).\n**À relier** : préservatif et vaccination sont les mesures préventives des IST citées par le Collège (p. 177)."},{"id":"d162-qroc-858","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":1,"question":"Quelle est l'IST la plus fréquente actuellement ?","answer":"L'infection à papillomavirus humain (HPV)","accept":["hpv","papillomavirus","infection à hpv"],"keywords":["hpv","papillomavirus"],"explanation":"Près de 40 % des jeunes femmes européennes sont infectées ; la prédilection d'âge est de 16 à 25 ans et la grande majorité élimine le virus en quelques mois.","src":"p. 200-201","deep":"**Pourquoi** : près de 40 % des jeunes femmes européennes sont infectées, avec une prédilection pour les 16-25 ans ; la transmission survient surtout dans les mois qui suivent les premiers rapports (p. 200-201).\n**Piège** : infecté ne veut pas dire malade : la grande majorité élimine le virus en quelques mois, moins de 10 % restent porteurs asymptomatiques, environ 1 % développe des lésions génitales (p. 201).\n**À relier** : C. trachomatis est, lui, la première cause d'IST bactérienne dans les pays industrialisés (p. 183)."},{"id":"d162-qroc-859","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","prévention"],"difficulty":2,"question":"Citez une voie de transmission non sexuelle des HPV.","answer":"Linges humides contaminés ou accouchement (mère avec condylomes)","accept":["linges humides","linges contaminés","accouchement"],"keywords":["linge","accouchement"],"explanation":"La transmission non sexuelle est possible par des linges humides contaminés ou lors de l'accouchement si la mère a des condylomes.","src":"p. 201","deep":"**Pourquoi** : la transmission des HPV est majoritairement sexuelle, mais elle est possible par contact avec des linges humides contaminés ou lors de l'accouchement si la mère a des condylomes (p. 200-201).\n**Piège** : un comportement sexuel à risque n'est pas nécessaire pour développer des condylomes (p. 204).\n**À relier** : chez l'enfant, les condylomes viennent le plus souvent d'une contamination manuportée (verrues vulgaires) ou de linges domestiques (p. 203)."},{"id":"d162-qroc-860","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie","complications"],"difficulty":2,"question":"Quel risque court l'enfant né d'une mère porteuse de condylomes ?","answer":"La papillomatose laryngée juvénile","accept":["papillomatose laryngée juvénile","papillomatose laryngée","papillomatose juvénile"],"keywords":["laryng"],"explanation":"La transmission lors de l'accouchement expose l'enfant au risque de papillomatose laryngée juvénile.","src":"p. 201","deep":"**Pourquoi** : une mère porteuse de condylomes expose l'enfant, lors de l'accouchement, au risque de papillomatose laryngée juvénile (p. 201).\n**Piège** : il s'agit d'une transmission non sexuelle des HPV, comme celle par des linges humides contaminés (p. 201).\n**À relier** : chez l'enfant, les condylomes peuvent aussi venir d'une contamination mère-enfant ; ils sont un mauvais marqueur de sévices sexuels (p. 203)."},{"id":"d162-qroc-861","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic"],"difficulty":1,"question":"Sur quoi repose le diagnostic des condylomes ?","answer":"Presque exclusivement sur l'examen clinique","accept":["examen clinique","clinique","l'examen clinique"],"keywords":["clinique"],"explanation":"Le diagnostic est clinique : l'examen doit être complet (localisations anales et génitales), en bonnes conditions (table gynécologique chez la femme).","src":"p. 201","deep":"**Pourquoi** : les condylomes se reconnaissent à l'examen : acuminés (« crêtes-de-coq ») ou plans (maculo-papules rosées) ; l'examen doit être complet, anal et génital, en bonnes conditions (table gynécologique chez la femme) (p. 201).\n**Piège** : la biopsie n'est faite qu'en cas de doute diagnostique ou de suspicion de néoplasie (p. 201).\n**À relier** : examens associés : frottis ± colposcopie ou test HPV-HR après 30 ans pour les lésions génitales, anuscopie pour les lésions anales (p. 201)."},{"id":"d162-qroc-862","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Dans quelles circonstances réalise-t-on une biopsie devant des condylomes ?","answer":"Doute diagnostique ou suspicion de néoplasie","accept":["doute diagnostique ou suspicion de néoplasie","doute diagnostique et suspicion de néoplasie","suspicion de néoplasie ou doute diagnostique","doute diagnostique ou suspicion de néoplasie intra-épithéliale"],"keywords":["doute","neoplasie"],"explanation":"La biopsie n'est pas systématique : elle est réservée au doute diagnostique ou à la suspicion de néoplasie.","src":"p. 201","deep":"**Pourquoi** : le diagnostic des condylomes est presque exclusivement clinique : la biopsie est réservée au doute diagnostique ou à la suspicion de néoplasie (p. 201).\n**Piège** : les néoplasies intra-épithéliales peuvent évoluer, principalement vers un carcinome épidermoïde, notamment au col (p. 202).\n**À relier** : chez la femme, la colposcopie avec acide acétique et/ou lugol permet de diriger la biopsie sur une zone suspecte (p. 202)."},{"id":"d162-qroc-863","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["clinique"],"difficulty":2,"question":"Quel est l'aspect des condylomes plans ?","answer":"Maculo-papules rosées isolées, en nappe ou en mosaïque","accept":["maculo-papules rosées","maculo-papules","macules et papules rosées"],"keywords":["maculo"],"explanation":"Les condylomes plans sont des maculo-papules rosées, parfois difficiles à voir à l'œil nu : l'acide acétique les révèle.","src":"p. 201","deep":"**Pourquoi** : les condylomes plans sont des maculo-papules rosées, isolées, en nappe ou en mosaïque, parfois difficiles à voir à l'œil nu : l'application d'acide acétique les révèle mieux (p. 201).\n**Piège** : les condylomes acuminés sont au contraire des masses charnues hérissées de petites verrucosités (« crêtes-de-coq ») de 0,2 à 1 cm (p. 201).\n**À relier** : la colposcopie repose sur l'application d'acide acétique à 5 % suivie d'un examen à la loupe (p. 201)."},{"id":"d162-qroc-864","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["physiopathologie","complications"],"difficulty":2,"question":"Vers quel cancer peuvent évoluer les néoplasies intra-épithéliales, notamment celles du col ?","answer":"Le carcinome épidermoïde","accept":["carcinome épidermoïde","carcinome malpighien","épidermoïde"],"keywords":["epidermoide"],"explanation":"Les néoplasies intra-épithéliales sont des lésions dysplasiques précancéreuses qui évoluent principalement vers un carcinome épidermoïde.","src":"p. 202","deep":"**Pourquoi** : les néoplasies intra-épithéliales sont des lésions dysplasiques précancéreuses, le plus souvent associées aux HPV, qui peuvent évoluer principalement vers un carcinome épidermoïde, notamment au col (p. 202).\n**Piège** : elles sont associées à tous les types d'HPV, oncogènes ou non oncogènes (p. 202).\n**À relier** : grades HSIL (haut grade) et LSIL (bas grade) ; localisations cervicale, vulvaire, anale, pénienne (p. 202)."},{"id":"d162-qroc-865","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["définition"],"difficulty":1,"question":"Quels sont les deux grades des néoplasies intra-épithéliales (sigles anglais) ?","answer":"HSIL (haut grade) et LSIL (bas grade)","accept":["hsil et lsil","lsil et hsil","hsil lsil"],"keywords":["hsil","lsil"],"explanation":"HSIL = lésion de haut grade ; LSIL = lésion de bas grade. On les distingue aussi selon la localisation : cervicale, vulvaire, anale, pénienne.","src":"p. 202","deep":"**Pourquoi** : on classe les néoplasies intra-épithéliales selon le grade (HSIL = haut grade, LSIL = bas grade) et selon la localisation (cervicale, vulvaire, anale, pénienne) (p. 202).\n**Piège** : ces lésions dysplasiques ne sont pas réservées aux HPV oncogènes : elles sont associées à tous les types d'HPV (p. 202).\n**À relier** : en cas de dysplasie, même mineure, au frottis : colposcopie et, si nécessaire, biopsie dirigée (p. 205)."},{"id":"d162-qroc-866","type":"QROC","rank":"A","objective":"d162-obj-19","tags":["paraclinique","pièges"],"difficulty":3,"question":"Pourquoi le test HPV-HR n'est-il pas recommandé en première intention avant 30 ans ?","answer":"Clairance spontanée incomplète : test presque toujours positif","accept":["clairance spontanée","clairance","positivité presque certaine"],"keywords":["clairance"],"explanation":"Avant 30 ans, la clairance spontanée des HPV n'est pas totale : le test est presque certainement positif sans qu'il y ait de maladie sous-jacente.","src":"p. 202","deep":"**Pourquoi** : avant 30 ans, la clairance spontanée des HPV n'est pas totale : le test HPV-HR serait presque toujours positif sans pathologie sous-jacente (p. 202).\n**Piège** : à partir de 30 ans, le test HPV-HR est recommandé en première intention (p. 202).\n**À relier** : le test HPV-HR est une technique de biologie moléculaire (hybridation, PCR) qui type les HPV oncogènes, en particulier 16 et 18 (p. 202)."},{"id":"d162-qroc-867","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["clinique"],"difficulty":2,"question":"Quelles sont les localisations habituelles des condylomes chez l'homme ?","answer":"Pubis, prépuce, sillon et frein balano-préputial","accept":["pubis, prépuce, sillon et frein balano-préputial","pubis prépuce sillon frein"],"keywords":["prepuce","pubis"],"explanation":"Chez l'homme : pubis, prépuce, sillon et frein balano-préputial, plus rarement gland et fourreau ; la localisation urétrale est limitée au méat.","src":"p. 203","deep":"**Pourquoi** : chez l'homme, les condylomes siègent au pubis, au prépuce, au sillon et au frein balano-préputial ; plus rarement au gland et au fourreau (p. 203).\n**Piège** : la localisation urétrale est limitée au méat ; l'urétroscopie peut se justifier en cas de récidives fréquentes avec atteinte du versant intra-urétral (p. 203).\n**À relier** : (rang B) la présence de condylomes impose l'examen du ou des partenaires (p. 204, 206)."},{"id":"d162-qroc-868","type":"QROC","rank":"A","objective":"d162-obj-36","tags":["pédiatrie","pièges"],"difficulty":2,"question":"Quelle est la valeur de la présence de condylomes chez l'enfant pour suspecter des sévices sexuels ?","answer":"Mauvais marqueur (la vigilance reste de mise)","accept":["mauvais marqueur","mauvais marqueur de sévices sexuels"],"keywords":["mauvais"],"explanation":"Chez l'enfant, les condylomes viennent le plus souvent de verrues vulgaires ou de linges (contamination manuportée), parfois de la mère : ils sont un mauvais marqueur de sévices.","src":"p. 203","deep":"**Pourquoi** : chez l'enfant, les condylomes viennent le plus souvent d'une contamination manuportée (verrues vulgaires) ou de linges domestiques, ou d'une transmission mère-enfant (p. 203).\n**Piège** : « mauvais marqueur » ne veut pas dire « à ignorer » : le Collège demande de rester vigilant (p. 203).\n**À relier** : (rang B) la transmission lors de l'accouchement expose aussi au risque de papillomatose laryngée juvénile (p. 201)."},{"id":"d162-qroc-869","type":"QROC","rank":"B","objective":"d162-obj-37","tags":["diagnostic"],"difficulty":2,"question":"Quelle hyperplasie physiologique du gland est un diagnostic différentiel des condylomes acuminés ?","answer":"La couronne perlée du gland","accept":["couronne perlée du gland","couronne perlée","papilles de la couronne du gland"],"keywords":["couronne"],"explanation":"À distinguer des condylomes : couronne perlée du gland, papillomatose vestibulaire vulvaire physiologique, syphilides secondaires, lésions dysplasiques, kératoses séborrhéiques, molluscum, nodules scabieux.","src":"p. 203","deep":"**Pourquoi** : la couronne perlée du gland est une hyperplasie physiologique des papilles de la couronne ; son équivalent féminin est la papillomatose vestibulaire vulvaire physiologique (p. 203).\n**Piège** : les autres diagnostics différentiels sont pathologiques : syphilides secondaires (condylomata lata), lésions dysplasiques, kératoses séborrhéiques, molluscum contagiosum, nodules scabieux (p. 203).\n**À relier** : le diagnostic des condylomes est presque exclusivement clinique (p. 201)."},{"id":"d162-qroc-870","type":"QROC","rank":"B","objective":"d162-obj-37","tags":["diagnostic"],"difficulty":2,"question":"Quelles lésions de syphilis secondaire peut-on confondre avec des condylomes acuminés ?","answer":"Les condylomata lata","accept":["condylomata lata","condylomata"],"keywords":["lata"],"explanation":"Les syphilides secondaires de type condylomata lata font partie du diagnostic différentiel des condylomes acuminés.","src":"p. 203","deep":"**Pourquoi** : les syphilides secondaires de type condylomata lata figurent dans le diagnostic différentiel des condylomes acuminés (p. 203).\n**Piège** : les syphilides génitales sont indolores, non prurigineuses, multiples, molles, papuleuses ou érosives, et très contagieuses (p. 192).\n**À relier** : devant des condylomes, on recherche une IST associée, dont un test tréponémique (p. 205)."},{"id":"d162-qroc-871","type":"QROC","rank":"B","objective":"d162-obj-31","tags":["suivi","traitement"],"difficulty":2,"question":"Quel est le rythme de suivi d'un patient traité pour condylomes ?","answer":"1 mois, puis tous les 3 mois jusqu'à guérison, puis 6 mois après","accept":["à 1 mois puis tous les 3 mois","1 mois 3 mois 6 mois"],"keywords":["1 mois","3 mois","6 mois"],"explanation":"Suivi évolutif à 1 mois, puis tous les 3 mois jusqu'à la guérison clinique, puis à 6 mois après la guérison (récidives fréquentes).","src":"p. 204","deep":"**Pourquoi** : le risque de récidive est important et le virus peut persister dans l'épiderme sain : suivi à 1 mois, puis tous les 3 mois jusqu'à guérison clinique, puis 6 mois après la guérison (p. 204).\n**Piège** : l'objectif du traitement est la disparition des lésions macroscopiquement visibles : il n'existe pas de traitement spécifique des infections à HPV (p. 204).\n**À relier** : il faut aussi dédramatiser, déculpabiliser et examiner le ou les partenaires (p. 204)."},{"id":"d162-qroc-872","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"question":"Contre quelles dysplasies la vaccination anti-HPV est-elle dirigée ?","answer":"Dysplasies cervicales, anales et oropharyngées","accept":["cervicales, anales et oropharyngées","cervicales anales oropharyngées"],"keywords":["cervical","anale","oropharyng"],"explanation":"La vaccination vise les dysplasies cervicales, anales et oropharyngées ; elle s'adresse aux filles et aux garçons et, avant tout préventive, doit être administrée au mieux avant toute contamination (p. 204).","src":"p. 204","deep":"**Pourquoi** : la vaccination anti-HPV a avant tout une efficacité préventive : elle doit être administrée au mieux avant toute contamination, et elle est donc proposée dès 11 ans (p. 204).\n**Piège** : elle concerne les garçons comme les filles, pas seulement les jeunes filles (p. 204).\n**À relier** : avec le dépistage cervical (frottis ou test HPV-HR), la vaccination assure la prévention du cancer du col (p. 206)."},{"id":"d162-qroc-873","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"question":"Jusqu'à quel âge la vaccination anti-HPV est-elle recommandée chez les hommes ayant des rapports sexuels avec des hommes (HSH) ?","answer":"Jusqu'à 26 ans","accept":["26 ans","26 ans révolus","26"],"keywords":["26"],"explanation":"Pour les HSH : Gardasil 9 jusqu'à 26 ans révolus (3 doses 0, 2, 6 mois), en prévention des lésions précancéreuses et cancers anaux et des condylomes.","src":"p. 204-205","deep":"**Pourquoi** : chez les HSH, Gardasil 9 est recommandé jusqu'à 26 ans, en prévention des lésions précancéreuses anales, des cancers anaux et des condylomes (p. 204).\n**Piège** : le schéma est alors de 3 doses (0, 2 et 6 mois), comme pour le rattrapage de 15 à 19 ans révolus (p. 205).\n**À relier** : en population générale : 11-14 ans (2 doses à 6-13 mois d'intervalle), rattrapage de 15 à 19 ans révolus (p. 204-205)."},{"id":"d162-qroc-874","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"question":"Quel est le schéma de la vaccination anti-HPV (Gardasil 9) chez un adolescent de 11 à 14 ans révolus ?","answer":"2 doses espacées de 6 à 13 mois","accept":["2 doses","2 doses espacées de 6 à 13 mois","deux doses"],"keywords":["2 doses"],"explanation":"11-14 ans : 2 doses espacées de 6 à 13 mois ; 15-19 ans : 3 doses (0, 2, 6 mois).","src":"p. 204","deep":"**Pourquoi** : entre 11 et 14 ans révolus, 2 doses de vaccin nonavalent espacées de 6 à 13 mois (p. 204).\n**Piège** : de 15 à 19 ans révolus (rattrapage) et chez les HSH jusqu'à 26 ans : 3 doses à 0, 2 et 6 mois (p. 205).\n**À relier** : chez l'enfant candidat à une greffe d'organe solide, la vaccination peut être initiée dès 9 ans (p. 204)."},{"id":"d162-qroc-875","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":1,"question":"Quel vaccin anti-HPV doit être utilisé pour toute nouvelle vaccination ?","answer":"Le vaccin nonavalent (Gardasil 9)","accept":["nonavalent","gardasil 9","vaccin nonavalent"],"keywords":["nonavalent","gardasil"],"explanation":"Toute nouvelle vaccination est initiée avec le vaccin nonavalent, qui cible 9 types d'HPV et peut aussi protéger contre d'autres sérotypes.","src":"p. 204","deep":"**Pourquoi** : toute nouvelle vaccination doit être initiée avec le vaccin nonavalent (Gardasil 9) : 9 types ciblés, avec une protection croisée possible contre d'autres sérotypes (p. 204).\n**Piège** : le vaccin disponible depuis 2007 visait seulement HPV 6, 11, 16 et 18 ; le nonavalent (2017) ajoute 31, 33, 45, 52 et 58 (p. 206).\n**À relier** : (rang B) HPV 6 et 11 (bas risque) causent près de 90 % des condylomes ; HPV 16 et 18 (haut risque) les lésions précancéreuses puis cancéreuses (p. 201)."},{"id":"d162-qroc-876","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":3,"question":"Quels types d'HPV s'ajoutent à 6, 11, 16 et 18 dans le vaccin nonavalent (disponible depuis 2017) ?","answer":"HPV 31, 33, 45, 52 et 58","accept":["31, 33, 45, 52 et 58","31 33 45 52 58"],"keywords":["31","33","58"],"explanation":"Le vaccin nonavalent cible les HPV 6, 11, 16, 18, 31, 33, 45, 52 et 58 (le vaccin disponible depuis 2007 ciblait 6, 11, 16 et 18).","src":"p. 206","deep":"**Pourquoi** : le vaccin nonavalent (Gardasil 9, depuis 2017) vise HPV 6, 11, 16, 18, 31, 33, 45, 52 et 58 ; le précédent (2007) se limitait à 6, 11, 16 et 18 (p. 206).\n**Piège** : (rang B) il vise à la fois des types à bas risque (6, 11 : condylomes) et des types à haut risque oncogène (16, 18 notamment) (p. 201, 206).\n**À relier** : toute nouvelle vaccination est initiée avec le nonavalent (p. 204)."},{"id":"d162-qroc-877","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["épidémiologie","diagnostic"],"difficulty":2,"question":"Dans quelle proportion de cas en moyenne une autre IST est-elle associée aux verrues anogénitales ?","answer":"25 % des cas","accept":["25 %","25","un quart"],"keywords":["25"],"explanation":"Une autre IST est présente dans 25 % des cas : sérologies VIH, TT, hépatite B, PCR Chlamydia et gonocoque, prélèvements en cas d'urétrite ou de vulvovaginite.","src":"p. 205","deep":"**Pourquoi** : une autre IST est associée aux condylomes dans 25 % des cas en moyenne : la présence de verrues anogénitales impose la recherche d'une IST associée (p. 205-206).\n**Piège** : (rang B) un comportement sexuel à risque n'est pourtant pas nécessaire pour développer des condylomes : il faut dédramatiser et déculpabiliser (p. 204).\n**À relier** : bilan : sérologie VIH, test tréponémique, sérologie hépatite B, PCR Chlamydia et gonocoque (urines ou autoprélèvement vaginal), prélèvements si urétrite ou vulvovaginite (p. 205)."},{"id":"d162-qroc-878","type":"QROC","rank":"A","objective":"d162-obj-19","tags":["prévention","paraclinique"],"difficulty":2,"question":"Que fait-on en cas de dysplasie cervicale, même mineure, au frottis de dépistage ?","answer":"Colposcopie, et biopsie dirigée si nécessaire","accept":["colposcopie","colposcopie et biopsie dirigée"],"keywords":["colposcopie"],"explanation":"En cas de dysplasie, même mineure : colposcopie puis, si nécessaire, biopsie dirigée sur les zones suspectes révélées par l'acide acétique à 5 % ou le lugol.","src":"p. 205","deep":"**Pourquoi** : dépistage des CIN : frottis tous les 3 ans ou test HPV-HR ; en cas de dysplasie, même mineure, colposcopie et si nécessaire biopsie dirigée sur les zones révélées par l'acide acétique à 5 % ou le lugol (p. 205).\n**Piège** : le test HPV-HR est recommandé en première intention à partir de 30 ans, pas avant (p. 202).\n**À relier** : les néoplasies intra-épithéliales peuvent évoluer vers un carcinome épidermoïde, notamment au col (p. 202)."},{"id":"d162-qroc-879","type":"QROC","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":2,"question":"Quel est le schéma d'application de la podophyllotoxine à 0,5 % dans les condylomes ?","answer":"Matin et soir, 3 jours consécutifs par semaine, jusqu'à guérison","accept":["matin et soir 3 jours par semaine","2 fois par jour 3 jours par semaine"],"keywords":["3 jours"],"explanation":"Résine naturelle appliquée par le patient, uniquement sur les lésions (caustique) ; elle convient mal aux lésions vulvaires ou intravaginales et est contre-indiquée chez la femme enceinte et l'enfant.","src":"p. 205","deep":"**Pourquoi** : la podophyllotoxine 0,5 % est une résine naturelle appliquée par le patient lui-même, matin et soir 3 jours consécutifs par semaine jusqu'à guérison (p. 205).\n**Piège** : caustique, elle ne s'applique que sur les lésions, convient mal aux lésions vulvaires ou intravaginales et est contre-indiquée chez la femme enceinte et l'enfant (p. 205).\n**À relier** : imiquimod : 3 fois par semaine pendant 16 semaines, avec prudence chez la femme enceinte (p. 205-206)."},{"id":"d162-qroc-880","type":"QROC","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":1,"question":"Quelle molécule immunomodulatrice d'application locale peut-on utiliser dans le traitement des condylomes ?","answer":"L'imiquimod","accept":["imiquimod","l'imiquimod"],"keywords":["imiquimod"],"explanation":"L'imiquimod induit la synthèse de cytokines pro-inflammatoires antivirales ; elle peut irriter et se prescrit avec prudence chez la femme enceinte.","src":"p. 205","deep":"**Pourquoi** : l'imiquimod est un immunomodulateur local qui induit la synthèse de cytokines aux propriétés pro-inflammatoires antivirales (IFNγ, TNFα, IL-1, IL-6) (p. 205).\n**Piège** : il peut irriter et se prescrit avec prudence chez la femme enceinte, alors que la podophyllotoxine y est contre-indiquée (p. 205-206).\n**À relier** : il n'existe pas de traitement spécifique des HPV : on vise la disparition des lésions visibles (p. 204)."},{"id":"d162-qroc-881","type":"QROC","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":2,"question":"Quel est le rythme d'application de l'imiquimod dans les condylomes ?","answer":"3 fois par semaine pendant 16 semaines","accept":["3 fois par semaine","3 fois par semaine pendant 16 semaines"],"keywords":["3 fois","16"],"explanation":"Imiquimod : applications 3 fois par semaine pendant 16 semaines.","src":"p. 206","deep":"**Pourquoi** : l'imiquimod s'applique 3 fois par semaine pendant 16 semaines (p. 206).\n**Piège** : ne pas confondre avec la podophyllotoxine : matin et soir, 3 jours consécutifs par semaine, jusqu'à guérison (p. 205).\n**À relier** : l'imiquimod, immunomodulateur d'application locale, peut provoquer une irritation (p. 205)."},{"id":"d162-qroc-882","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic"],"difficulty":2,"question":"Sur quels examens repose le diagnostic des infections génitales à HPV infracliniques ?","answer":"Frottis, acidoréaction, colposcopie-biopsie, test HPV-HR","accept":["frottis, acidoréaction, colposcopie-biopsie et test hpv-hr","frottis acidoréaction colposcopie test hpv-hr"],"keywords":["frottis","colposcopie"],"explanation":"Le diagnostic positif repose sur la clinique ; celui des infections infracliniques sur le frottis, l'acidoréaction, la colposcopie-biopsie et le test HPV-HR.","src":"p. 206","deep":"**Pourquoi** : les infections génitales infracliniques ne se voient pas à l'œil nu : leur diagnostic repose sur le frottis, l'acidoréaction, la colposcopie-biopsie et le test HPV-HR (p. 206).\n**Piège** : les condylomes visibles, eux, se diagnostiquent presque exclusivement à l'examen clinique (p. 201).\n**À relier** : le test HPV-HR est recommandé en première intention à partir de 30 ans (p. 202)."},{"id":"d162-qroc-883","type":"QROC","rank":"A","objective":"d162-obj-32","tags":["étiologie","définition"],"difficulty":1,"question":"Quelle est la nature de Trichomonas vaginalis ?","answer":"Un protozoaire flagellé anaérobie","accept":["protozoaire flagellé","protozoaire","parasite flagellé"],"keywords":["protozoaire"],"explanation":"T. vaginalis est un protozoaire flagellé anaérobie dont le réservoir naturel est le tractus urogénital ; c'est une IST, contrairement à la candidose et à la vaginose bactérienne.","src":"p. 206","deep":"**Pourquoi** : T. vaginalis est un protozoaire flagellé anaérobie dont le réservoir naturel est le tractus urogénital ; la trichomonose est considérée comme une IST (p. 206).\n**Piège** : la candidose et la vaginose bactérienne, elles, ne sont pas considérées comme des IST (p. 206).\n**À relier** : (rang B) à l'examen direct à l'état frais, le parasite apparaît mobile ; la PCR est plus récente (p. 207)."},{"id":"d162-qroc-884","type":"QROC","rank":"B","objective":"d162-obj-32","tags":["épidémiologie","clinique"],"difficulty":2,"question":"Quelle est la durée d'incubation de la trichomonose ?","answer":"4 à 28 jours","accept":["4 à 28 jours","4-28 jours","4 à 28"],"keywords":["4","28"],"explanation":"L'incubation varie de 4 à 28 jours ; la transmission est presque exclusivement sexuelle, en milieu humide.","src":"p. 207","deep":"**Pourquoi** : l'incubation de la trichomonose varie de 4 à 28 jours ; la transmission est presque exclusivement sexuelle et ne peut se faire qu'en milieu humide (p. 207).\n**Piège** : à comparer : gonocoque 2 à 7 jours, Chlamydia quelques jours à quelques mois, syphilis 10 à 90 jours (p. 180, 184, 188).\n**À relier** : l'infection est asymptomatique dans la majorité des cas, chez l'homme comme chez la femme (p. 207)."},{"id":"d162-qroc-885","type":"QROC","rank":"B","objective":"d162-obj-32","tags":["clinique"],"difficulty":2,"question":"Quelles manifestations la trichomonose peut-elle donner chez l'homme symptomatique ?","answer":"Urétrite subaiguë ou balanoposthite","accept":["urétrite subaiguë","balanoposthite","urétrite"],"keywords":["uretrite","balanoposthite"],"explanation":"Chez l'homme l'infection est le plus souvent asymptomatique ; elle peut donner une urétrite subaiguë ou une balanoposthite, avec écoulement matinal et prurit.","src":"p. 207","deep":"**Pourquoi** : chez l'homme, T. vaginalis donne des urétrites le plus souvent subaiguës ou des balanoposthites, parfois avec écoulement urétral matinal et prurit (p. 207).\n**Piège** : l'infection masculine est le plus souvent asymptomatique ; le partenaire est pourtant traité simultanément (p. 207-208).\n**À relier** : prélèvement chez l'homme : écoulement urétral s'il existe, sinon 1er jet urinaire (p. 207)."},{"id":"d162-qroc-886","type":"QROC","rank":"B","objective":"d162-obj-32","tags":["clinique"],"difficulty":2,"question":"Quel est l'aspect typique des leucorrhées de la trichomonose ?","answer":"Abondantes, verdâtres, spumeuses, malodorantes","accept":["verdâtres et spumeuses","verdâtres spumeuses","spumeuses et verdâtres","verdâtres, spumeuses, malodorantes"],"keywords":["verdatres","spumeuses"],"explanation":"Chez la femme (vulvovaginite ou cervicovaginite) : prurit intense, leucorrhées abondantes verdâtres spumeuses et malodorantes, vulve œdématiée.","src":"p. 207","deep":"**Pourquoi** : chez la femme, vulvovaginite ou cervicovaginite avec leucorrhées abondantes, verdâtres, spumeuses, malodorantes, prurit intense et vulve œdématiée (p. 207).\n**Piège** : le diagnostic différentiel avec une vaginose bactérienne n'est pas forcément aisé ; une candidose doit aussi être exclue (p. 207).\n**À relier** : l'examen au spéculum peut montrer une colpite punctiforme dite « léopard » (p. 207)."},{"id":"d162-qroc-887","type":"QROC","rank":"B","objective":"d162-obj-32","tags":["clinique"],"difficulty":2,"question":"Quel aspect l'examen au spéculum peut-il mettre en évidence dans la trichomonose ?","answer":"Colpite punctiforme (« léopard »)","accept":["colpite punctiforme","léopard","colpite léopard"],"keywords":["punctiforme"],"explanation":"Le spéculum peut montrer une colpite punctiforme dite « léopard ». Le diagnostic différentiel avec une vaginose bactérienne n'est pas toujours aisé.","src":"p. 207","deep":"**Pourquoi** : l'examen au spéculum peut montrer une colpite punctiforme dite « léopard », avec une vulve œdématiée et des leucorrhées verdâtres spumeuses (p. 207).\n**Piège** : col peu inflammatoire avec écoulement purulent à l'orifice = cervicite gonococcique ; col fragile, ectropion friable et hémorragique = Chlamydia (p. 181, 184).\n**À relier** : diagnostic par examen direct à l'état frais (parasite mobile) ou PCR, sur un prélèvement du cul-de-sac vaginal postérieur (p. 207)."},{"id":"d162-qroc-888","type":"QROC","rank":"B","objective":"d162-obj-33","tags":["paraclinique"],"difficulty":2,"question":"Où prélève-t-on chez la femme pour rechercher Trichomonas vaginalis à l'état frais ?","answer":"Dans le cul-de-sac vaginal postérieur","accept":["cul-de-sac vaginal postérieur","cul de sac postérieur","cul-de-sac postérieur"],"keywords":["cul de sac"],"explanation":"Chez la femme : cul-de-sac vaginal postérieur ; chez l'homme : écoulement urétral s'il existe, sinon 1er jet urinaire.","src":"p. 207","deep":"**Pourquoi** : chez la femme, le recueil se fait dans le cul-de-sac vaginal postérieur ; une goutte de sécrétion est examinée à l'état frais entre lame et lamelle (parasite mobile), ou analysée par PCR (p. 207).\n**Piège** : en cas d'examen direct, le prélèvement doit être acheminé rapidement au laboratoire (p. 179).\n**À relier** : chez l'homme : écoulement urétral s'il existe, sinon 1er jet urinaire ; colorations (May-Grünwald Giemsa) et cultures spéciales possibles mais peu réalisées (p. 207)."},{"id":"d162-qroc-889","type":"QROC","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":2,"question":"Quel est le schéma prolongé de métronidazole dans la trichomonose (alternative à la dose unique de 2 g) ?","answer":"500 mg 2 fois par jour pendant 7 jours","accept":["500 mg 2 fois par jour pendant 7 jours","500 mg matin et soir 7 jours"],"keywords":["500","7 jours"],"explanation":"Métronidazole PO 2 g en dose unique ou 500 mg 2 fois/jour pendant 7 jours, ou secnidazole 2 g en dose unique.","src":"p. 207","deep":"**Pourquoi** : au choix, trois options : métronidazole per os, soit 2 g en une prise, soit 500 mg matin et soir 7 jours ; ou secnidazole 2 g en une prise (p. 207).\n**Piège** : le/la partenaire est traité(e) simultanément ; les rares échecs sont dus à une diminution de sensibilité au métronidazole (p. 208).\n**À relier** : le métronidazole entre aussi dans le traitement probabiliste d'une IGH non compliquée (500 mg/12 h pendant 10 jours) (p. 186)."},{"id":"d162-qroc-890","type":"QROC","rank":"A","objective":"d162-obj-04","tags":["traitement","prévention"],"difficulty":2,"question":"Que doit-on faire pour le(s) partenaire(s) d'un patient atteint de trichomonose, vu la forte transmissibilité ?","answer":"Les dépister et les traiter simultanément","accept":["traiter simultanément","traitement simultané","dépister et traiter simultanément"],"keywords":["simultan"],"explanation":"En raison de la forte transmissibilité de l'infection, le ou les partenaires sont dépistés et traités simultanément ; on leur propose aussi sérologie VIH, test tréponémique, sérologie de l'hépatite B et PCR biplex (p. 208).","src":"p. 208","deep":"**Pourquoi** : le Collège justifie le dépistage et le traitement simultané du ou des partenaires par la forte transmissibilité de la trichomonose (p. 208).\n**Piège** : ne pas attendre que le partenaire ait des symptômes : chez l'homme, l'infection est le plus souvent asymptomatique (rang B) (p. 207).\n**À relier** : pendant le traitement, pas de rapports non protégés ; éducation sur les IST ; les rares échecs sont dus à une diminution de sensibilité au métronidazole (rang B) (p. 208)."},{"id":"d162-qroc-891","type":"QROC","rank":"A","objective":"d162-obj-33","tags":["paraclinique","prévention"],"difficulty":2,"question":"Quel bilan d'IST propose-t-on à un patient atteint de trichomonose et à ses partenaires ?","answer":"VIH, test tréponémique, hépatite B, PCR biplex Chlamydia-gonocoque","accept":["sérologie vih, tt, hépatite b et pcr biplex","vih, test tréponémique, hépatite b et pcr biplex"],"keywords":["vih","hepatite","biplex"],"explanation":"Sérologie VIH, test tréponémique, sérologie de l'hépatite B et PCR biplex C. trachomatis / N. gonorrhoeae (urines ou prélèvement vaginal), avec éducation et abstention de rapports non protégés pendant le traitement.","src":"p. 208","deep":"**Pourquoi** : comme pour toute IST, on propose au patient et à ses partenaires sérologie VIH, test tréponémique, sérologie de l'hépatite B et PCR biplex C. trachomatis / N. gonorrhoeae (urines ou prélèvement vaginal) (p. 208).\n**Piège** : même si les complications de la trichomonose sont rares, ce bilan et l'identification des partenaires restent nécessaires (p. 208).\n**À relier** : même bilan devant des condylomes, où une autre IST est associée dans 25 % des cas (p. 205)."},{"id":"d162-qroc-892","type":"QROC","rank":"A","objective":"d162-obj-32","tags":["étiologie","prévention"],"difficulty":2,"question":"Pourquoi la gale impose-t-elle de rechercher des conduites sexuelles à risque ?","answer":"Son mode de transmission l'apparente à une IST","accept":["apparente à une ist","mode de transmission","transmission sexuelle"],"keywords":["transmission"],"explanation":"La scabiose (et la phtiriase) sont traitées dans l'item 171 ; le mode de transmission de la gale l'apparente à une IST, d'où la recherche de conduites à risque et le dépistage des autres IST.","src":"p. 208","deep":"**Pourquoi** : le mode de transmission de la scabiose l'apparente à une IST : il impose une recherche de conduites à risque et, le cas échéant, un dépistage des autres IST (p. 208).\n**Piège** : la gale et la phtiriase sont détaillées dans l'item 171 ; dans cet item, c'est la démarche de dépistage des IST qui compte (p. 208).\n**À relier** : (rang B) les nodules scabieux font partie du diagnostic différentiel des condylomes (p. 203)."},{"id":"d162-qroc-893","type":"QROC","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"question":"Quelles sont les prévalences respectives de C. trachomatis et du gonocoque parmi les urétrites en France ?","answer":"Chlamydia 20-30 % ; gonocoque 10 %","accept":["chlamydia 20-30 % gonocoque 10 %","20 à 30 % et 10 %"],"keywords":["20","30","10"],"explanation":"D'après le tableau de synthèse, C. trachomatis représente 20 à 30 % des urétrites et le gonocoque 10 %, ce qui fait de Chlamydia la première cause identifiée d'urétrite.","src":"p. 186","deep":"**Pourquoi** : tableau 9.1 : parmi les urétrites en France, C. trachomatis représente 20 à 30 % des cas et le gonocoque 10 % ; Chlamydia est la première cause identifiée d'urétrite aiguë, suivie par le gonocoque (p. 183, 186).\n**Piège** : ne pas inverser les colonnes : 10 % pour le gonocoque, 20-30 % pour Chlamydia (p. 186).\n**À relier** : l'urétrite est mixte dans 15 % des cas, d'où le traitement anti-Chlamydia systématiquement associé à celui du gonocoque (p. 182)."},{"id":"d162-qroc-894","type":"QROC","rank":"A","objective":"d162-obj-30","tags":["diagnostic"],"difficulty":2,"question":"Quel examen est recommandé pour explorer des condylomes de localisation anale ?","answer":"Un examen proctologique complet (anuscopie)","accept":["anuscopie","examen proctologique","examen proctologique complet"],"keywords":["anuscopie","proctolog"],"explanation":"Pour les lésions anales : examen proctologique complet avec anuscopie ; pour les lésions génitales : frottis cervico-vaginal ± colposcopie ou test HPV-HR après 30 ans.","src":"p. 201","deep":"**Pourquoi** : chez la femme, des formes multifocales s'étendent au vagin, au périnée et à la région périanale : l'examen doit être complet, et les lésions anales relèvent d'un examen proctologique complet avec anuscopie (p. 201-202).\n**Piège** : la biopsie n'est pas systématique : seulement en cas de doute diagnostique ou de suspicion de néoplasie (p. 201).\n**À relier** : chez les HSH, la vaccination HPV jusqu'à 26 ans vise les lésions précancéreuses et les cancers anaux (p. 204)."},{"id":"d162-qroc-895","type":"QROC","rank":"B","objective":"d162-obj-31","tags":["prévention","clinique"],"difficulty":2,"question":"Pourquoi un examen gynécologique est-il nécessaire chez une femme présentant des condylomes ?","answer":"Ils sont le marqueur possible d'une infection par HPV à risque oncogène","accept":["marqueur d'une infection par hpv oncogène","hpv à risque oncogène","hpv oncogène"],"keywords":["oncogene"],"explanation":"Les condylomes peuvent signer une co-infection par des HPV à risque oncogène, d'où la recherche de dysplasie du col (frottis ou test HPV-HR, colposcopie).","src":"p. 204","deep":"**Pourquoi** : les condylomes sont le marqueur possible d'une infection par des HPV à risque oncogène ; chez la femme, la co-infection par des HPV à haut risque est fréquente, donc il existe un risque de dysplasie (p. 202, 204).\n**Piège** : le caractère multifocal impose un examen gynécologique ET anal complet, avec dépistage par frottis ou test HPV-HR selon l'âge (p. 202).\n**À relier** : en cas de dysplasie, même mineure : colposcopie et, si nécessaire, biopsie dirigée (p. 205)."},{"id":"d162-qroc-896","type":"QROC","rank":"B","objective":"d162-obj-04","tags":["prévention"],"difficulty":2,"question":"Que faut-il faire pour le ou les partenaires d'un patient porteur de condylomes ?","answer":"Les examiner","accept":["examen du partenaire","examiner le partenaire","les examiner"],"keywords":["examen","examiner"],"explanation":"L'examen du partenaire est nécessaire ; l'incubation est très variable et le portage latent très fréquent, ce qui permet souvent de dédramatiser pour le couple.","src":"p. 204, 206","deep":"**Pourquoi** : l'examen du ou des partenaires est nécessaire ; l'incubation très variable et le portage latent très fréquent permettent souvent de dédramatiser la situation pour le couple (p. 204).\n**Piège** : un comportement sexuel à risque n'est pas nécessaire pour développer des condylomes : il faut dédramatiser et déculpabiliser (p. 204).\n**À relier** : la présence de verrues anogénitales impose aussi la recherche d'une IST associée (p. 206)."},{"id":"d162-qroc-897","type":"QROC","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":3,"question":"À partir de quel âge la vaccination anti-HPV peut-elle être initiée chez les enfants candidats à une transplantation d'organe solide ?","answer":"Dès 9 ans","accept":["9 ans","dès 9 ans","neuf ans"],"keywords":["9 ans"],"explanation":"Chez les immunodéprimés, la vaccination suit les âges de la population générale (rattrapage jusqu'à 19 ans révolus), mais peut être initiée dès 9 ans chez les enfants candidats à une greffe d'organe solide.","src":"p. 204","deep":"**Pourquoi** : chez l'immunodéprimé, la vaccination suit les âges de la population générale, avec rattrapage jusqu'à 19 ans révolus ; chez l'enfant candidat à une greffe d'organe solide, elle peut être initiée dès 9 ans (p. 204).\n**Piège** : en population générale, on vaccine entre 11 et 14 ans (2 doses), avec rattrapage de 15 à 19 ans (3 doses) (p. 204-205).\n**À relier** : (rang B) chez le VIH+ ou l'immunodéprimé, les infections à HPV sont plus fréquentes, récidivent plus souvent et plus sévèrement, et progressent davantage vers des néoplasies intra-épithéliales (p. 201)."},{"id":"d162-qroc-898","type":"QROC","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":2,"question":"Quelle technique de destruction des condylomes permet aussi un prélèvement pour analyse histologique ?","answer":"L'électrocoagulation","accept":["électrocoagulation","electrocoagulation"],"keywords":["electrocoag"],"explanation":"L'électrocoagulation se fait sous anesthésie locale : elle détruit les lésions ou permet un prélèvement histologique.","src":"p. 205","deep":"**Pourquoi** : l'électrocoagulation, réalisée sous anesthésie locale, permet soit la destruction des lésions, soit un prélèvement pour analyse histologique (p. 205).\n**Piège** : toutes les destructions physiques (cryothérapie, laser CO2, électrocoagulation) exposent à un risque cicatriciel ; la cryothérapie, douloureuse, est réservée aux lésions d'étendue limitée (p. 205).\n**À relier** : le laser CO2 se fait sous anesthésie topique, locale ou générale (p. 205)."},{"id":"d162-qcm-701","type":"QRM","rank":"A","objective":"d162-obj-08","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Un homme de 26 ans consulte pour un écoulement urétral apparu après un rapport non protégé. Parmi les éléments suivants, lesquels orientent vers une urétrite à Chlamydia trachomatis plutôt que vers une gonococcie ?","options":[{"t":"Un écoulement franchement purulent dans environ 90 % des cas","ok":false,"why":"C'est la présentation de la gonococcie (écoulement purulent dans 90 % des cas) ; l'écoulement chlamydien est le plus souvent clair, modéré et intermittent (p. 180, 184)."},{"t":"Un écoulement clair, modéré et intermittent, présent dans moins de la moitié des cas","ok":true,"why":"L'écoulement de la chlamydiose est présent dans 40 à 50 % des cas, le plus souvent clair, modéré et intermittent."},{"t":"Des diplocoques à Gram négatif dans le prélèvement urétral","ok":false,"why":"Faux : le gonocoque est un diplocoque à Gram négatif ; C. trachomatis est un bacille à Gram négatif intracellulaire obligatoire, diagnostiqué par PCR (p. 179, 183, 185)."},{"t":"Une incubation courte de 2 à 7 jours","ok":false,"why":"Faux : c'est l'incubation courte du gonocoque (2 à 7 jours, malade contagieux) ; celle de Chlamydia va de quelques jours à quelques mois (p. 180, 184)."},{"t":"Une incubation variable, de quelques jours à quelques mois","ok":true,"why":"Contrairement à l'incubation courte du gonocoque (2 à 7 jours), celle de Chlamydia est variable."}],"explanation":"Gonocoque : incubation 2-7 jours, écoulement purulent (90 %), diplocoque à Gram négatif. Chlamydia : incubation variable (jours à mois), écoulement clair, présent dans 40-50 % des cas.","src":"p. 180, 184, 186","deep":"**Pourquoi** : tableau 9.1 : gonocoque = incubation de 2 à 7 jours, écoulement purulent (90 %) ; Chlamydia = incubation de quelques jours à quelques mois, écoulement clair dans 40-50 % des cas (p. 180, 184, 186).\n**Piège** : le tableau chlamydien est souvent moins bruyant et le portage asymptomatique fréquent (50 % à l'urètre chez l'homme) : l'absence d'écoulement n'élimine pas Chlamydia (p. 184, 186).\n**À relier** : l'urétrite est mixte dans 15 % des cas : traitement anti-Chlamydia systématiquement associé à celui du gonocoque (p. 182)."},{"id":"d162-qru-701","type":"QRU","rank":"A","objective":"d162-obj-10","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Une femme de 22 ans consulte pour des leucorrhées purulentes et une pesanteur pelvienne apparues 4 jours après un rapport non protégé. Au spéculum, le col est peu inflammatoire avec un écoulement purulent à l'orifice cervical. Quel est le germe le plus probable ?","options":[{"t":"Treponema pallidum","ok":false,"why":"La syphilis primaire donne un chancre indolore et induré, pas des leucorrhées purulentes."},{"t":"Trichomonas vaginalis","ok":false,"why":"(rang B) Il donne des leucorrhées abondantes, verdâtres, spumeuses et malodorantes, avec parfois une colpite punctiforme au spéculum (p. 207)."},{"t":"Papillomavirus humain (HPV)","ok":false,"why":"Les HPV donnent des condylomes (verrues anogénitales) et des néoplasies intra-épithéliales, pas une cervicite purulente (p. 201-202)."},{"t":"Neisseria gonorrhoeae","ok":true,"why":"Oui : incubation courte (2 à 7 jours), leucorrhées purulentes, pesanteur pelvienne, col non ou peu inflammatoire avec écoulement purulent à l'orifice cervical : cervicite gonococcique (p. 180-181)."},{"t":"Chlamydia trachomatis","ok":false,"why":"La cervicite chlamydienne est le plus souvent asymptomatique ; l'examen montre plutôt un col fragile, des sécrétions mucopurulentes ou un ectropion friable, et l'incubation est plus variable."}],"explanation":"La cervicite gonococcique associe incubation courte, leucorrhées purulentes, pesanteur pelvienne et col peu inflammatoire avec écoulement purulent à l'orifice cervical ; 70 % des formes sont toutefois asymptomatiques.","src":"p. 180-181, 184, 207","deep":"**Pourquoi** : incubation courte (4 jours, dans la fourchette de 2 à 7 jours), leucorrhées purulentes, pesanteur pelvienne, col peu inflammatoire avec écoulement purulent à l'orifice : c'est la cervicite gonococcique décrite par le Collège (p. 180-181).\n**Piège** : 70 % des infections gonococciques féminines et 50 à 90 % des cervicites chlamydiennes sont asymptomatiques : ne pas attendre des symptômes pour dépister (p. 180, 184).\n**À relier** : (rang B) traitement : ceftriaxone 1000 mg IM en dose unique + anti-Chlamydia systématique + traitement du ou des partenaires (p. 182)."},{"id":"d162-qcm-702","type":"QRM","rank":"B","objective":"d162-obj-14","tags":["complications","traitement"],"difficulty":2,"stem":"Un homme de 30 ans, traité récemment pour une urétrite, est hospitalisé pour une fièvre, un purpura pétéchial des extrémités et une arthrite du genou. Une septicémie gonococcique est suspectée. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"L'atteinte cutanée peut associer purpura pétéchial et papulo-pustules acrales ou périarticulaires","ok":true,"why":"Oui : avec la fièvre, l'atteinte cutanée de la septicémie gonococcique associe purpura pétéchial et papules ou papulo-pustules acrales ou périarticulaires (p. 181)."},{"t":"L'endocardite et la méningite sont des complications fréquentes de la septicémie gonococcique, au même titre que l'atteinte articulaire","ok":false,"why":"Elles sont des localisations plus rares (comme la péri-hépatite) ; elles se traitent par ceftriaxone IV 1 à 2 g/jour (10-14 jours pour une méningite, 4 semaines pour une endocardite)."},{"t":"Le traitement repose sur l'hospitalisation et la ceftriaxone IV 1 g/jour pendant 7 à 10 jours","ok":true,"why":"Oui : septicémie à gonocoque = hospitalisation + ceftriaxone 1 g/jour IV pendant 7 à 10 jours (p. 182)."},{"t":"Une ténosynovite ou une mono-/oligo-arthrite septique peut faire partie du tableau","ok":true,"why":"L'atteinte articulaire de la septicémie associe mono- ou oligo-arthrites septiques et ténosynovites."},{"t":"Une dose unique de ceftriaxone 1000 mg IM suffit à la traiter","ok":false,"why":"La dose unique concerne les formes non compliquées ; la septicémie impose hospitalisation et ceftriaxone IV 1 g/jour pendant 7 à 10 jours."}],"explanation":"La septicémie gonococcique est une complication systémique (fièvre, atteinte cutanée acrale, arthrites septiques) traitée à l'hôpital par ceftriaxone IV 1 g/jour pendant 7 à 10 jours.","src":"p. 181-182","deep":"**Pourquoi** : la gonococcie peut se compliquer sur le plan systémique : septicémie avec fièvre, atteinte cutanée (purpura pétéchial, papules ou papulo-pustules acrales ou périarticulaires) et/ou atteinte articulaire septique (p. 181).\n**Piège** : l'arthrite réactionnelle (syndrome oculo-urétro-synovial) est celle de Chlamydia ; le gonocoque donne des arthrites septiques (p. 184, 186).\n**À relier** : localisations plus rares : péri-hépatite, endocardite (ceftriaxone 4 semaines), méningite (10 à 14 jours) (p. 181, 183)."},{"id":"d162-qcm-703","type":"QRM","rank":"B","objective":"d162-obj-34","tags":["traitement","grossesse"],"difficulty":2,"stem":"Une femme enceinte de 24 ans a une cervicite gonococcique non compliquée confirmée. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Un traitement anti-Chlamydia est inutile, l'infection mixte étant exceptionnelle","ok":false,"why":"L'urétrite/cervicite est mixte dans 15 % des cas : un traitement anti-Chlamydia est systématiquement associé."},{"t":"Le traitement du partenaire est facultatif","ok":false,"why":"Le traitement du ou des partenaires est systématique."},{"t":"Une dose unique de gentamycine 240 mg IM est recommandée","ok":false,"why":"Les aminosides sont contre-indiqués chez la femme enceinte."},{"t":"La ceftriaxone 1000 mg en IM unique est un traitement possible","ok":true,"why":"Chez la femme enceinte : ceftriaxone IM unique de 1000 mg ou céfixime 400 mg per os en prise unique."},{"t":"Les cyclines peuvent être utilisées sans restriction","ok":false,"why":"Quinolones, cyclines et aminosides sont contre-indiqués pendant la grossesse."}],"explanation":"Grossesse et gonococcie : ceftriaxone 1000 mg IM ou céfixime 400 mg PO en prise unique ; quinolones, cyclines et aminosides contre-indiqués ; anti-Chlamydia associé et partenaire traité.","src":"p. 182","deep":"**Pourquoi** : chez la femme enceinte, quinolones, cyclines et aminosides sont contre-indiqués : restent la ceftriaxone 1000 mg IM unique ou le céfixime 400 mg PO en prise unique (p. 182).\n**Piège** : l'anti-Chlamydia reste systématique, mais pas par doxycycline (une cycline) : chez la femme enceinte, azithromycine 1 g en prise unique et PCR systématique à 1 mois (p. 182, 186).\n**À relier** : comme pour toute IST : partenaire(s) traité(s), sérologie VIH, test tréponémique et sérologie de l'hépatite B (p. 182)."},{"id":"d162-qcm-704","type":"QRM","rank":"B","objective":"d162-obj-16","tags":["suivi"],"difficulty":2,"stem":"Vous avez traité par ceftriaxone une urétrite gonococcique non compliquée chez un homme de 25 ans. Quelles modalités de suivi sont recommandées ?","options":[{"t":"Dans les formes asymptomatiques, un contrôle de la PCR 3 mois après le traitement","ok":false,"why":"Dans les formes asymptomatiques, le contrôle de la PCR est proposé 15 jours après le traitement."},{"t":"Un contrôle clinique systématique à J7","ok":true,"why":"Il évalue la tolérance et l'efficacité, permet d'adapter le traitement aux résultats bactériologiques et de communiquer les résultats."},{"t":"Le patient n'est revu que s'il présente de nouveaux symptômes","ok":false,"why":"Le contrôle clinique à J7 est systématique, y compris sans nouveau symptôme."},{"t":"Un contrôle bactériologique à J7 si des signes cliniques persistent","ok":true,"why":"En cas de persistance des signes cliniques, un contrôle bactériologique est indiqué à J7 (p. 183)."},{"t":"Un contrôle par culture avec antibiogramme est systématiquement refait à J2, puis un contrôle de la PCR à J15 chez tous les patients, qu'ils soient symptomatiques ou non","ok":false,"why":"Faux : le Collège prévoit un contrôle clinique systématique à J7, un contrôle bactériologique à J7 seulement si les signes persistent, et une PCR à 15 jours dans les formes asymptomatiques (p. 183)."}],"explanation":"Après un traitement de gonococcie : contrôle clinique systématique à J7 ; contrôle bactériologique à J7 si signes persistants ; PCR de contrôle à 15 jours dans les formes asymptomatiques.","src":"p. 183","deep":"**Pourquoi** : le contrôle clinique systématique à J7 permet d'évaluer la tolérance et l'efficacité, d'adapter le traitement aux résultats bactériologiques et de communiquer les résultats au patient (p. 183).\n**Piège** : ne pas confondre les délais : PCR de contrôle à 15 jours dans les formes asymptomatiques de gonococcie, mais PCR Chlamydia pas trop précoce (débris pouvant la rendre faussement positive dans les 4 semaines) (p. 183, 185).\n**À relier** : relations sexuelles évitées ou protégées pendant au moins 7 jours ; traitement du ou des partenaires systématique (p. 182)."},{"id":"d162-qru-702","type":"QRU","rank":"B","objective":"d162-obj-20","tags":["traitement","pièges"],"difficulty":2,"stem":"Un homme de 27 ans, allergique aux β-lactamines, a une urétrite à gonocoque non compliquée. Quel traitement en dose unique est approprié pour le gonocoque ?","options":[{"t":"Doxycycline 100 mg/12 h pendant 7 jours","ok":false,"why":"C'est un traitement anti-Chlamydia, de plus prolongé et non en dose unique."},{"t":"Azithromycine 2 g par voie orale","ok":true,"why":"En cas d'allergie aux β-lactamines : azithromycine 2 g PO, gentamycine 240 mg IM ou ciprofloxacine 500 mg PO (avec antibiogramme), en dose unique ; on associe toujours un traitement anti-Chlamydia."},{"t":"Ceftriaxone 1000 mg IM","ok":false,"why":"C'est le traitement de 1re intention, mais c'est une β-lactamine, contre-indiquée en cas d'allergie."},{"t":"Érythromycine 500 mg/6 h pendant 7 jours","ok":false,"why":"C'est un traitement de deuxième intention de la chlamydiose, pas du gonocoque."},{"t":"Azithromycine 1 g","ok":false,"why":"1 g est la dose anti-Chlamydia ; contre le gonocoque, l'azithromycine est utilisée à 2 g."}],"explanation":"Allergie aux β-lactamines et gonocoque : azithromycine 2 g, gentamycine 240 mg IM ou ciprofloxacine 500 mg (avec antibiogramme) en dose unique, plus anti-Chlamydia.","src":"p. 182","deep":"**Pourquoi** : en cas d'allergie aux β-lactamines, le gonocoque se traite en dose unique par azithromycine 2 g PO, gentamycine 240 mg IM ou ciprofloxacine 500 mg PO avec antibiogramme (p. 182).\n**Piège** : la ciprofloxacine se prescrit avec antibiogramme, et 40 % des souches de gonocoque sont résistantes à la ciprofloxacine (p. 180, 182).\n**À relier** : traitement anti-Chlamydia systématique associé : doxycycline 7 jours, à privilégier par rapport à l'azithromycine 1 g en dose unique (p. 182)."},{"id":"d162-qcm-705","type":"QRM","rank":"B","objective":"d162-obj-35","tags":["complications"],"difficulty":2,"stem":"Parmi les complications possibles d'une infection à Chlamydia trachomatis, lesquelles sont exactes ?","options":[{"t":"L'épididymite aiguë chez l'homme","ok":true,"why":"L'épididymite aiguë est une complication locorégionale chez l'homme (la prostatite est plutôt chronique)."},{"t":"La grossesse extra-utérine","ok":true,"why":"Oui : après une endométrite ou une salpingite à Chlamydia, la GEU fait partie des complications secondaires, avec la stérilité tubaire et les algies pelviennes inflammatoires (p. 183-184)."},{"t":"La stérilité tubaire chez la femme","ok":true,"why":"C. trachomatis est responsable de 70 % des stérilités tubaires."},{"t":"La septicémie avec papulo-pustules acrales, complication caractéristique de la chlamydiose","ok":false,"why":"La septicémie à signes cutanés et arthrites septiques est une complication de la gonococcie."},{"t":"La kératoconjonctivite et la pneumopathie du nouveau-né d'une mère infectée","ok":true,"why":"Ce sont les manifestations néonatales d'une infection urogénitale maternelle à C. trachomatis."}],"explanation":"La chlamydiose, souvent asymptomatique, se complique : salpingite, algies pelviennes, stérilité tubaire, GEU chez la femme ; épididymite, prostatite chronique chez l'homme ; syndrome oculo-urétro-synovial ; atteintes néonatales.","src":"p. 183-186","deep":"**Pourquoi** : souvent asymptomatique, C. trachomatis atteint le haut appareil génital féminin : 50 % des salpingites de la femme jeune, 70 % des stérilités tubaires, risque de GEU et d'algies pelviennes inflammatoires (p. 183-184).\n**Piège** : chez l'homme, la prostatite à Chlamydia est plutôt chronique (les prostatites aiguës sont rares), alors que l'épididymite est aiguë (p. 184).\n**À relier** : nouveau-né de mère infectée : kératoconjonctivite et pneumopathie, traitées par érythromycine pendant 14 jours (p. 185-186)."},{"id":"d162-qru-703","type":"QRU","rank":"B","objective":"d162-obj-15","tags":["paraclinique"],"difficulty":2,"stem":"Quelle définition correspond à l'urétrite « biologique » au frottis urétral ?","options":[{"t":"Plus de 10 polynucléaires neutrophiles au grossissement 100","ok":false,"why":"Le seuil de 10 PNN s'applique au grossissement 400, pas 100."},{"t":"Plus de 20 polynucléaires neutrophiles au grossissement 400 uniquement","ok":false,"why":"Ce seuil ne figure pas dans la définition : c'est plus de 10 PNN à ×400."},{"t":"Plus de 5 polynucléaires neutrophiles au grossissement 400 uniquement","ok":false,"why":"Les seuils sont inversés : plus de 5 PNN au grossissement 100."},{"t":"Plus de 5 polynucléaires neutrophiles au grossissement 100, ou plus de 10 au grossissement 400","ok":true,"why":"Oui : deux seuils équivalents selon le grossissement : plus de 5 PNN au grossissement 100 ou plus de 10 PNN au grossissement 400 (p. 181)."},{"t":"Plus de 5 polynucléaires neutrophiles au grossissement 1000","ok":false,"why":"La définition se fait aux grossissements 100 et 400."}],"explanation":"Urétrite biologique : > 5 PNN au grossissement 100 ou > 10 PNN au grossissement 400.","src":"p. 181","deep":"**Pourquoi** : le frottis urétral définit l'urétrite biologique par le nombre de polynucléaires neutrophiles : plus de 5 au grossissement 100 ou plus de 10 au grossissement 400 (p. 181).\n**Piège** : à l'examen direct, seuls des diplocoques à Gram négatif intracellulaires « en grains de café » orientent vers le gonocoque ; une forme extracellulaire ne donne pas de certitude (Neisseria non pathogènes) (p. 181).\n**À relier** : dans l'urétrite masculine symptomatique, l'examen direct a une sensibilité et une spécificité > 95 % ; elles sont moins bonnes chez la femme et aux autres sites (p. 181)."},{"id":"d162-qcm-706","type":"QRM","rank":"B","objective":"d162-obj-34","tags":["traitement"],"difficulty":3,"stem":"Concernant le traitement des formes particulières de l'infection à Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Forme non compliquée : l'érythromycine est le traitement de première intention","ok":false,"why":"En 1re intention : doxycycline 7 jours (ou azithromycine 1 g si crainte de mauvaise observance) ; l'érythromycine est de 2e intention."},{"t":"Femme enceinte : azithromycine 1 g en prise orale unique, avec PCR systématique à 1 mois","ok":true,"why":"Oui : chez la femme enceinte, azithromycine en prise orale unique de 1 g et PCR systématique à 1 mois (p. 186)."},{"t":"Nouveau-né avec pneumopathie ou ophtalmie : doxycycline 100 mg/12 h par voie orale ou IV pendant 14 jours","ok":false,"why":"Chez le nouveau-né, on utilise l'érythromycine (12,5 mg/kg/6 h pendant 14 jours)."},{"t":"Orchiépididymite : doxycycline 100 mg/12 h pendant 10 jours","ok":true,"why":"Oui : doxycycline 100 mg/12 h prolongée à 10 jours dans l'orchiépididymite, contre 7 jours dans la forme non compliquée (p. 185-186)."},{"t":"Endométrite ou salpingite : doxycycline pendant 7 jours","ok":false,"why":"Le traitement de l'endométrite ou de la salpingite dure 14 jours."}],"explanation":"Chlamydia : non compliquée doxycycline 7 j ; orchiépididymite 10 j ; endométrite-salpingite 14 j ; femme enceinte azithromycine 1 g + PCR à 1 mois ; nouveau-né érythromycine.","src":"p. 185-186","deep":"**Pourquoi** : la durée de la doxycycline (100 mg/12 h) dépend de la forme : 7 jours (non compliquée), 10 jours (orchiépididymite), 14 jours (endométrite, salpingite) (p. 185-186).\n**Piège** : chez la femme enceinte, pas de cycline : azithromycine 1 g DU + PCR à 1 mois ; chez le nouveau-né : érythromycine 12,5 mg/kg/6 h pendant 14 jours (p. 186).\n**À relier** : PCR de contrôle pas trop précoce : les débris de Chlamydia peuvent la rendre faussement positive dans les 4 semaines suivant le traitement (p. 185)."},{"id":"d162-qru-704","type":"QRU","rank":"B","objective":"d162-obj-14","tags":["diagnostic","complications"],"difficulty":2,"stem":"Une femme de 24 ans présente une polyarthrite réactionnelle, une urétrite, une conjonctivite bilatérale et une kératodermie palmo-plantaire psoriasiforme. Quel agent est en cause ?","options":[{"t":"Treponema pallidum","ok":false,"why":"La syphilis secondaire peut avoir des papules palmo-plantaires cuivrées, mais pas ce syndrome oculo-urétro-synovial."},{"t":"Chlamydia trachomatis","ok":true,"why":"Oui : polyarthrite réactionnelle, urétrite, conjonctivite bilatérale, balanite circinée et kératodermie palmo-plantaire psoriasiforme forment le syndrome oculo-urétro-synovial de la chlamydiose, dans les deux sexes (p. 184-185)."},{"t":"Neisseria gonorrhoeae","ok":false,"why":"La gonococcie se complique plutôt de septicémie avec arthrites septiques, pas d'arthrite réactionnelle."},{"t":"Trichomonas vaginalis","ok":false,"why":"La trichomonose est le plus souvent asymptomatique ou donne une vulvovaginite ; pas de syndrome oculo-urétro-synovial."},{"t":"Papillomavirus humain 16","ok":false,"why":"L'HPV 16 est un type à haut risque oncogène (lésions précancéreuses)."}],"explanation":"Polyarthrite réactionnelle + urétrite + conjonctivite bilatérale + balanite circinée + kératodermie palmo-plantaire psoriasiforme = syndrome oculo-urétro-synovial de la chlamydiose.","src":"p. 184-185","deep":"**Pourquoi** : le syndrome oculo-urétro-synovial de Chlamydia associe polyarthrite réactionnelle aiguë ou subaiguë, urétrite, conjonctivite bilatérale, balanite circinée et kératodermie palmo-plantaire psoriasiforme (p. 184-185).\n**Piège** : le gonocoque donne des arthrites septiques dans le cadre d'une septicémie, pas d'arthrite réactionnelle (p. 181, 186).\n**À relier** : C. trachomatis se diagnostique par PCR (1er jet d'urine, autoprélèvement vaginal) ; la sérologie n'a pas d'intérêt (p. 185)."},{"id":"d162-qcm-707","type":"QRM","rank":"B","objective":"d162-obj-25","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 32 ans consulte pour une éruption du tronc survenue 8 semaines après une ulcération génitale spontanément guérie. On note des papules cuivrées avec une fine desquamation périlésionnelle, des papules palmo-plantaires et des polyadénopathies. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Les papules palmo-plantaires sont très évocatrices de syphilis secondaire","ok":true,"why":"Elles sont cuivrées, à cheval sur les plis palmaires, très évocatrices (mais inconstantes, environ 30 %)."},{"t":"La fine desquamation périlésionnelle est évocatrice mais non spécifique","ok":true,"why":"C'est un signe inconstant, évocateur mais non spécifique."},{"t":"Le TNT est le plus souvent négatif à ce stade","ok":false,"why":"Au stade secondaire, TT et TNT sont toujours positifs (titre élevé)."},{"t":"Les papules palmo-plantaires sont présentes dans la quasi-totalité des cas","ok":false,"why":"Elles sont inconstantes (environ 30 % des cas)."},{"t":"La prescription d'un test tréponémique est obligatoire","ok":true,"why":"Devant une éruption évocatrice de syphilis secondaire, le test tréponémique (ELISA) est obligatoire."}],"explanation":"Syphilis secondaire : papules cuivrées monomorphes, desquamation périlésionnelle inconstante, syphilides palmo-plantaires (30 %), signes généraux ; TT et TNT toujours positifs.","src":"p. 191-192, 195, 200","deep":"**Pourquoi** : ulcération génitale guérie spontanément puis éruption quelques semaines plus tard : chancre puis floraisons du secondaire ; papules cuivrées, papules palmo-plantaires et polyadénopathies sont typiques (p. 190-193).\n**Piège** : les papules palmo-plantaires ne sont présentes que dans environ 30 % des cas : leur absence n'aurait pas éliminé le diagnostic (p. 192).\n**À relier** : traitement : benzathine-benzylpénicilline 2,4 MU IM unique ; prévenir le patient d'une possible réaction d'Herxheimer (fièvre, céphalées, myalgies) (p. 198)."},{"id":"d162-qcm-708","type":"QRM","rank":"A","objective":"d162-obj-27","tags":["paraclinique","diagnostic"],"difficulty":3,"stem":"Un patient de 40 ans, n'ayant jamais été traité pour une syphilis, a un ELISA positif et un VDRL à 1/64. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il s'agit d'une fausse sérologie syphilitique","ok":false,"why":"Une fausse sérologie correspond à un TNT positif avec un TT négatif ; ici le TT est positif."},{"t":"Le patient n'a pas contracté de tréponématose","ok":false,"why":"Un TT positif signe une tréponématose (syphilis ou tréponématose endémique non vénérienne)."},{"t":"La sérologie permet de distinguer la syphilis d'une tréponématose endémique non vénérienne","ok":false,"why":"Aucun test sérologique ne distingue la syphilis du pian, du béjel ou du pinta."},{"t":"Il s'agit d'une cicatrice sérologique","ok":false,"why":"Une cicatrice sérologique associe un TT positif à un TNT négatif."},{"t":"Un titre élevé de TNT témoigne d'une tréponématose évolutive","ok":true,"why":"Le TT affirme la tréponématose et le titre élevé du TNT (par exemple 1/16 ou plus) témoigne d'une maladie évolutive."}],"explanation":"Lecture de la sérologie : on commence par le TT (affirme la tréponématose), puis le TNT en précise l'évolutivité ; titre élevé = maladie évolutive.","src":"p. 195-196, 200","deep":"**Pourquoi** : on lit d'abord le TT : positif = tréponématose (syphilis ou forme endémique) ; puis le TNT : un titre élevé (1/16 par exemple) témoigne d'une maladie évolutive chez un patient non traité (p. 196).\n**Piège** : cicatrice sérologique = TT+/TNT− ; fausse sérologie = TNT+/TT− ; ici les deux tests sont positifs (p. 195-196).\n**À relier** : après traitement, le suivi se fait sur ce même TNT quantitatif, dont le titre doit être divisé par 4 à 6 mois (p. 198)."},{"id":"d162-qru-705","type":"QRU","rank":"A","objective":"d162-obj-28","tags":["suivi","traitement"],"difficulty":3,"stem":"Un patient de 34 ans a reçu une injection de benzathine-benzylpénicilline 2,4 MU pour une syphilis secondaire (VDRL à 1/64). À 6 mois, le VDRL est à 1/32. Quelle conduite est appropriée ?","options":[{"t":"Avis spécialisé et 3 injections de benzathine-benzylpénicilline 2,4 MU à 8 jours d'intervalle","ok":true,"why":"En l'absence de décroissance attendue du TNT, le traitement doit être repris : 3 injections à 8 jours d'intervalle, avec avis spécialisé."},{"t":"Considérer l'évolution comme favorable et le revoir à 1 an","ok":false,"why":"Le titre n'a pas été divisé par 4 (2 dilutions) à 6 mois : le traitement est considéré comme insuffisant."},{"t":"Conclure à une recontamination et refaire une injection unique","ok":false,"why":"Faux : une recontamination se reconnaît à la clinique ou à une remontée du TNT quantitatif (titre multiplié au moins par 4) ; ici le titre a baissé, mais pas assez (p. 195)."},{"t":"Remplacer par une cure de doxycycline 100 mg matin et soir pendant 14 jours","ok":false,"why":"Faux : la doxycycline 14 jours est l'alternative en cas d'allergie à la pénicilline ; l'échec biologique se traite par 3 injections de benzathine-benzylpénicilline à 8 jours d'intervalle (p. 198)."},{"t":"Surveiller le titre du TT quantitatif plutôt que celui du TNT","ok":false,"why":"Le TT quantitatif n'est pas un bon marqueur de la réponse au traitement ; le suivi se fait sur le TNT quantitatif."}],"explanation":"Efficacité d'un traitement de syphilis : TNT divisé par 4 (2 dilutions) à 6 mois ; sinon avis spécialisé et 3 injections de benzathine-benzylpénicilline à 8 jours d'intervalle.","src":"p. 195, 198","deep":"**Pourquoi** : passer de 1/64 à 1/32, c'est une seule dilution : le titre n'est pas divisé par 4 (2 dilutions, soit 1/16) à 6 mois, donc le traitement doit être repris (p. 195, 198).\n**Piège** : ne pas surveiller le TT quantitatif, qui varie beaucoup d'un examen à l'autre et ne reflète pas la réponse au traitement (p. 194).\n**À relier** : (rang B) après une syphilis secondaire, le TNT doit être négatif dans un délai de 2 ans (p. 198)."},{"id":"d162-qcm-709","type":"QRM","rank":"A","objective":"d162-obj-29","tags":["traitement","suivi"],"difficulty":2,"stem":"Un patient de 38 ans, séropositif pour le VIH, a un chancre syphilitique. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Un traitement par 3 injections de benzathine-benzylpénicilline à 8 jours d'intervalle est systématique chez tout patient infecté par le VIH","ok":false,"why":"Faux : pour un chancre (syphilis précoce), une injection IM unique de 2,4 MU suffit, chez le VIH+ comme chez les autres ; les 3 injections à 8 jours d'intervalle s'emploient si le TNT n'est pas divisé par 4 à 6 mois (p. 198-199)."},{"t":"Une sérologie de la syphilis doit être répétée au moins une fois par an s'il a des pratiques à risque","ok":true,"why":"On recommande une sérologie de syphilis au moins 1 fois par an chez les patients VIH engagés dans des pratiques à risque."},{"t":"Le suivi de l'efficacité se fait sur le TT quantitatif","ok":false,"why":"Le suivi biologique repose sur le TNT quantitatif."},{"t":"Le traitement standard par pénicilline est le même que chez un patient non infecté","ok":true,"why":"Le traitement standard par pénicilline est identique en cas de syphilis primaire ou secondaire chez un patient VIH."},{"t":"La doxycycline 14 jours est le traitement d'emblée","ok":false,"why":"La doxycycline est le traitement de l'allergie à la pénicilline, et pas chez le patient VIH (induction de tolérance)."}],"explanation":"Syphilis et VIH : même traitement par benzathine-benzylpénicilline ; sérologie syphilitique au moins annuelle en cas de pratiques à risque ; suivi sur le TNT.","src":"p. 198-199","deep":"**Pourquoi** : le traitement standard par pénicilline est le même chez le VIH+ pour une syphilis primaire ou secondaire ; on recommande une sérologie syphilis au moins 1 fois par an en cas de pratiques à risque (p. 199).\n**Piège** : si ce patient VIH+ était allergique à la pénicilline, pas de doxycycline mais une induction de tolérance (p. 198).\n**À relier** : (rang B) 40 % des syphilitiques sont VIH+ ; suivi sur le TNT à 3 mois, 6 mois, 1 an puis tous les ans (p. 188, 198)."},{"id":"d162-qru-706","type":"QRU","rank":"A","objective":"d162-obj-28","tags":["traitement","grossesse"],"difficulty":2,"stem":"Une femme enceinte de 28 ans, allergique à la pénicilline, a une syphilis primaire. Quelle attitude est préconisée ?","options":[{"t":"Une cure de doxycycline 100 mg matin et soir pendant 14 jours","ok":false,"why":"La doxycycline est le traitement de l'allergie sauf chez la femme enceinte et le patient séropositif pour le VIH."},{"t":"Une abstention thérapeutique jusqu'à l'accouchement","ok":false,"why":"La syphilis est grave chez la femme enceinte : risque d'atteinte fœtale ; elle doit être traitée."},{"t":"Un avis spécialisé et une induction de tolérance à la pénicilline","ok":true,"why":"Chez la femme enceinte allergique, on a recours à l'induction de tolérance, avec avis d'un spécialiste ; la syphilis est grave pendant la grossesse (passage transplacentaire après le 4e mois)."},{"t":"Une injection unique de ceftriaxone 1000 mg IM","ok":false,"why":"Ce schéma est celui de la gonococcie, pas de la syphilis."},{"t":"Une injection de benzathine-benzylpénicilline sans précaution, la réaction étant une réaction d'Herxheimer","ok":false,"why":"Faux : chez une femme enceinte allergique, la pénicilline passe par une induction de tolérance, avec avis spécialisé ; (rang B) une réaction d'Herxheimer, bénigne, ne doit pas être confondue avec une allergie (p. 197-198)."}],"explanation":"Allergie à la pénicilline : doxycycline 14 jours, sauf chez la femme enceinte et le patient VIH (induction de tolérance). Contacter un spécialiste en cas de grossesse, VIH ou allergie.","src":"p. 197-198, 200","deep":"**Pourquoi** : l'alternative à la pénicilline (doxycycline 14 jours) ne s'applique ni à la femme enceinte ni au patient VIH+ : une induction de tolérance est indiquée, avec avis spécialisé (p. 197-198).\n**Piège** : pendant la grossesse, la syphilis est grave : le tréponème peut atteindre le fœtus en traversant le placenta après le 4e mois (p. 200).\n**À relier** : (rang B) la sérologie syphilis est obligatoire au 1er trimestre de la grossesse (p. 188)."},{"id":"d162-qcm-710","type":"QRM","rank":"A","objective":"d162-obj-04","tags":["prévention","traitement"],"difficulty":2,"stem":"Une patiente apprend que son partenaire a une syphilis certaine. Leur dernier rapport date de 4 semaines et sa sérologie est négative. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le traitement n'est justifié que si le TNT est positif","ok":false,"why":"Le contact récent est traité sans attendre un résultat sérologique."},{"t":"Elle doit être traitée d'emblée, le contact datant de moins de 6 semaines","ok":true,"why":"Oui : contact de moins de 6 semaines avec une syphilis certaine → traitement systématique du contact, sans attendre la sérologie (p. 198)."},{"t":"Il suffit de refaire la sérologie à 3 mois sans la traiter, la sérologie initiale étant négative","ok":false,"why":"Cette attitude concerne un contact de plus de 6 semaines avec une sérologie négative."},{"t":"Une sérologie de la syphilis est tout de même prélevée","ok":true,"why":"Le traitement est donné et une sérologie est bien sûr prélevée."},{"t":"Le traitement repose sur une injection IM unique de benzathine-benzylpénicilline 2,4 MU","ok":true,"why":"C'est le traitement de la syphilis précoce, y compris en traitement présomptif du contact récent."}],"explanation":"Contact d'une syphilis certaine : < 6 semaines → traiter d'emblée (+ sérologie) ; > 6 semaines → sérologie, traiter si positive, sinon refaire à 3 mois.","src":"p. 198","deep":"**Pourquoi** : syphilis certaine chez le partenaire et contact de moins de 6 semaines : traitement systématique (1 injection de 2,4 MU de benzathine-benzylpénicilline), une sérologie étant prélevée (p. 198).\n**Piège** : la sérologie peut encore être négative : l'incubation dure 10 à 90 jours et le TT peut être négatif au tout début du chancre (p. 188, 200).\n**À relier** : contact de plus de 6 semaines (ou syphilis douteuse chez la source) : sérologie, traitement si positive, sinon nouvelle sérologie à 3 mois (p. 198)."},{"id":"d162-qcm-711","type":"QRM","rank":"A","objective":"d162-obj-27","tags":["paraclinique","pièges"],"difficulty":2,"stem":"Un VDRL positif avec un TPHA négatif (fausse sérologie syphilitique) peut s'observer dans lesquelles de ces situations ?","options":[{"t":"Un syndrome des anticorps anti-phospholipides","ok":true,"why":"Primaire ou secondaire (lupus), il peut positiver le TNT isolément."},{"t":"Une infection à Mycoplasma pneumoniae","ok":true,"why":"Certaines maladies infectieuses (Mycoplasma pneumoniae, borrélioses) donnent un VDRL faussement positif."},{"t":"Une cicatrice sérologique d'une syphilis traitée","ok":false,"why":"Une cicatrice sérologique associe un TT positif et un TNT négatif : c'est l'inverse."},{"t":"Une grossesse","ok":true,"why":"La grossesse est une cause non infectieuse de faux positif du VDRL."},{"t":"Un lupus érythémateux systémique","ok":true,"why":"Maladie dysimmunitaire classiquement responsable de fausses sérologies syphilitiques."}],"explanation":"VDRL+ / TPHA− : fausse sérologie (lupus, SAPL, grossesse, Mycoplasma pneumoniae, borrélioses...), alors que cicatrice sérologique = TT+ / TNT−.","src":"p. 194-196","deep":"**Pourquoi** : le VDRL n'est pas spécifique des tréponématoses : maladies dysimmunitaires (lupus, SAPL), grossesse et certaines infections (Mycoplasma pneumoniae, borrélioses) peuvent le positiver avec un TT négatif (p. 194).\n**Piège** : un TNT positif isolé n'est pas toujours faux : dans 10 % des syphilis primaires, il se positive avant le TT (p. 196).\n**À relier** : TT+/TNT− = cicatrice sérologique (tréponématose guérie), tréponématose très précoce ou syphilis tertiaire très ancienne (rare) (p. 195)."},{"id":"d162-qcm-712","type":"QRM","rank":"B","objective":"d162-obj-30","tags":["étiologie","physiopathologie"],"difficulty":2,"stem":"À propos des types d'HPV, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Un patient est infecté par un seul type d'HPV à la fois","ok":false,"why":"On s'infecte par des types différents, oncogènes et non oncogènes."},{"t":"Les HPV 6 et 11 sont à bas risque et responsables d'environ 90 % des condylomes","ok":true,"why":"Ce sont les types les plus fréquents des verrues génitales."},{"t":"Les HPV 16 et 18 sont responsables de 90 % des condylomes","ok":false,"why":"Les condylomes sont dus aux HPV à bas risque 6 et 11."},{"t":"Les HPV 16 et 18 sont à haut risque oncogène","ok":true,"why":"Ils sont principalement responsables des lésions précancéreuses puis cancéreuses."},{"t":"Les néoplasies intra-épithéliales ne sont associées qu'aux HPV oncogènes 16 et 18, jamais aux HPV non oncogènes","ok":false,"why":"Elles sont associées à tous les types d'HPV, oncogènes ou non."}],"explanation":"HPV 6 et 11 : bas risque, ~90 % des condylomes. HPV 16 et 18 : haut risque, lésions précancéreuses et cancers ; infections souvent multiples.","src":"p. 201-202","deep":"**Pourquoi** : HPV à bas risque (6 et 11) → près de 90 % des condylomes ; HPV à haut risque (surtout 16 et 18) → lésions précancéreuses puis cancéreuses (p. 201).\n**Piège** : on s'infecte par des types différents, oncogènes et non oncogènes ; les condylomes sont le marqueur possible d'une infection à HPV oncogène, d'où l'examen gynécologique chez la femme (p. 201, 204).\n**À relier** : les néoplasies intra-épithéliales sont associées à tous les types d'HPV ; le test HPV-HR type surtout 16 et 18 (p. 202)."},{"id":"d162-qru-707","type":"QRU","rank":"A","objective":"d162-obj-22","tags":["prévention"],"difficulty":2,"stem":"Un adolescent de 17 ans, jamais vacciné contre les HPV, consulte pour mise à jour de ses vaccins. Quelle attitude est correcte ?","options":[{"t":"Il n'est plus éligible car la vaccination s'arrête à 14 ans","ok":false,"why":"Le rattrapage est possible de 15 à 19 ans révolus."},{"t":"Vaccin réservé aux filles, donc non indiqué chez lui","ok":false,"why":"La vaccination s'adresse aux filles et aux garçons."},{"t":"Vaccin quadrivalent (HPV 6, 11, 16, 18), car il s'agit d'une nouvelle vaccination","ok":false,"why":"Toute nouvelle vaccination doit être initiée avec le vaccin nonavalent."},{"t":"2 doses de vaccin nonavalent espacées de 6 à 13 mois","ok":false,"why":"Ce schéma à 2 doses s'applique entre 11 et 14 ans révolus."},{"t":"Vaccin nonavalent en 3 doses selon un schéma 0, 2 et 6 mois","ok":true,"why":"De 15 à 19 ans révolus, la vaccination (garçons comme filles) se fait en 3 doses selon un schéma 0, 2 et 6 mois avec le vaccin nonavalent."}],"explanation":"Vaccination anti-HPV : 11-14 ans (2 doses à 6-13 mois), rattrapage 15-19 ans révolus (3 doses 0, 2, 6 mois), vaccin nonavalent ; HSH jusqu'à 26 ans.","src":"p. 204-205","deep":"**Pourquoi** : 17 ans = âge du rattrapage (15 à 19 ans révolus) : vaccin nonavalent en 3 doses à 0, 2 et 6 mois, chez les garçons comme chez les filles (p. 204-205).\n**Piège** : le schéma à 2 doses (espacées de 6 à 13 mois) ne vaut que de 11 à 14 ans révolus (p. 204).\n**À relier** : chez un HSH, la vaccination reste recommandée jusqu'à 26 ans révolus (3 doses) (p. 204-205)."},{"id":"d162-qcm-713","type":"QRM","rank":"B","objective":"d162-obj-31","tags":["traitement"],"difficulty":2,"stem":"Concernant les traitements locaux des condylomes, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La podophyllotoxine convient bien aux lésions vulvaires et intravaginales et peut être appliquée largement sur la peau saine","ok":false,"why":"Du fait de sa causticité, elle ne doit être appliquée que sur les lésions et convient mal aux lésions vulvaires ou intravaginales."},{"t":"Après disparition des lésions, le virus est éliminé de l'épiderme sain","ok":false,"why":"Le virus peut persister dans l'épiderme sain : le risque de récidive est important."},{"t":"Les méthodes de destruction physique exposent toutes à un risque cicatriciel","ok":true,"why":"C'est un point commun à la cryothérapie, au laser CO2 et à l'électrocoagulation."},{"t":"La cryothérapie est réservée aux lésions d'étendue limitée car elle est douloureuse","ok":true,"why":"Elle consiste à appliquer de l'azote liquide ; son caractère douloureux la limite aux lésions peu étendues."},{"t":"L'imiquimod s'applique 3 fois par semaine pendant 16 semaines","ok":true,"why":"Oui : 3 applications par semaine pendant 16 semaines ; cet immunomodulateur local peut provoquer une irritation (p. 205-206)."}],"explanation":"Condylomes : destruction physique (cryothérapie, laser CO2, électrocoagulation, risque cicatriciel), chimique (podophyllotoxine 0,5 %) ou immunologique (imiquimod). Récidives fréquentes.","src":"p. 204-206","deep":"**Pourquoi** : il n'existe pas de traitement spécifique des HPV : on détruit les lésions visibles, par voie physique (cryothérapie, laser CO2, électrocoagulation), chimique (podophyllotoxine 0,5 %) ou immunologique (imiquimod) (p. 204-205).\n**Piège** : le virus peut persister dans l'épiderme sain après disparition des lésions : récidives fréquentes, suivi à 1 mois puis tous les 3 mois jusqu'à guérison, puis 6 mois après (p. 204).\n**À relier** : podophyllotoxine contre-indiquée chez la femme enceinte et l'enfant ; imiquimod avec prudence chez la femme enceinte (p. 205-206)."},{"id":"d162-qcm-714","type":"QRM","rank":"A","objective":"d162-obj-19","tags":["paraclinique","prévention"],"difficulty":2,"stem":"À propos du test HPV-HR, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Avant 30 ans, il est presque toujours positif sans maladie sous-jacente","ok":true,"why":"La clairance spontanée des HPV n'est pas totale chez les femmes jeunes."},{"t":"Il est recommandé en première intention dès l'âge de 15 ans, dès le début de l'activité sexuelle, chez toutes les femmes","ok":false,"why":"Il est recommandé en première intention à partir de 30 ans."},{"t":"Il repose sur une technique de biologie moléculaire (hybridation moléculaire et PCR)","ok":true,"why":"Oui : c'est une technique de biologie moléculaire associant hybridation moléculaire et PCR (p. 202)."},{"t":"Il permet le typage des HPV oncogènes, en particulier les HPV 16 et 18","ok":true,"why":"Oui : il permet le typage des HPV oncogènes, en particulier les HPV 16 et 18 (p. 202)."},{"t":"Il détecte principalement les HPV non oncogènes","ok":false,"why":"Faux : le test HPV-HR (HR = haut risque) permet le typage des HPV oncogènes, en particulier les HPV 16 et 18 (p. 201-202)."}],"explanation":"Test HPV-HR (PCR) : typage des HPV oncogènes 16 et 18, recommandé en première intention à partir de 30 ans (avant : positivité presque certaine sans lésion).","src":"p. 202","deep":"**Pourquoi** : le test HPV-HR (hybridation moléculaire, PCR) détecte et type les HPV oncogènes, en particulier 16 et 18 ; il est recommandé en première intention à partir de 30 ans (p. 202).\n**Piège** : avant 30 ans, la clairance spontanée des HPV n'est pas totale : test presque toujours positif sans pathologie sous-jacente (p. 202).\n**À relier** : dépistage des CIN : frottis tous les 3 ans ou test HPV-HR ; dysplasie même mineure → colposcopie ± biopsie dirigée (p. 205)."},{"id":"d162-qcm-715","type":"QRM","rank":"B","objective":"d162-obj-33","tags":["diagnostic","traitement"],"difficulty":2,"stem":"Une femme de 29 ans consulte pour des leucorrhées abondantes, verdâtres, spumeuses et malodorantes avec prurit intense et dyspareunie. Le spéculum montre une colpite punctiforme. Quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Le partenaire doit être traité simultanément même s'il est asymptomatique","ok":true,"why":"Le/la partenaire est traité(e) simultanément en raison de la forte transmissibilité."},{"t":"Le traitement repose sur une injection de ceftriaxone 1000 mg IM, associée à la doxycycline pendant 7 jours","ok":false,"why":"Le traitement est le métronidazole (2 g en dose unique ou 500 mg 2 fois/jour 7 jours) ou le secnidazole 2 g."},{"t":"Le partenaire n'est traité que s'il présente un écoulement urétral","ok":false,"why":"Chez l'homme l'infection est le plus souvent asymptomatique : le partenaire est traité simultanément quoi qu'il en soit."},{"t":"L'examen direct montre des diplocoques à Gram négatif intracellulaires","ok":false,"why":"C'est l'aspect du gonocoque. Ici, c'est un protozoaire flagellé mobile qu'on cherche à l'état frais."},{"t":"Le germe est une bactérie intracellulaire obligatoire","ok":false,"why":"T. vaginalis est un protozoaire flagellé anaérobie, pas une bactérie intracellulaire obligatoire."}],"explanation":"Trichomonose : leucorrhées verdâtres spumeuses malodorantes, colpite punctiforme, parasite mobile à l'examen direct ou PCR, métronidazole ou secnidazole, partenaire traité simultanément.","src":"p. 206-208","deep":"**Pourquoi** : leucorrhées verdâtres, spumeuses, malodorantes, prurit intense, dyspareunie et colpite punctiforme « léopard » : tableau de trichomonose ; traitement par métronidazole (2 g DU ou 500 mg 2 fois/jour 7 jours) ou secnidazole 2 g DU (p. 207).\n**Piège** : le partenaire est traité simultanément, même asymptomatique : chez l'homme, l'infection est le plus souvent asymptomatique (p. 207-208).\n**À relier** : diagnostic par examen direct à l'état frais (parasite mobile) ou PCR, sur prélèvement du cul-de-sac vaginal postérieur (p. 207)."},{"id":"d162-qcm-716","type":"QRM","rank":"A","objective":"d162-obj-05","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Concernant le diagnostic différentiel d'une ulcération génitale, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La donovanose donne des lésions granulomateuses peu douloureuses, sur terrain africain","ok":true,"why":"C'est sa description dans le diagnostic différentiel du chancre syphilitique."},{"t":"Aucun caractère clinique du chancre syphilitique n'est pathognomonique","ok":true,"why":"Aucune caractéristique n'est pathognomonique ; la syphilis doit être évoquée devant toute ulcération muqueuse aiguë."},{"t":"L'herpès donne une ulcération profonde, indurée et indolore","ok":false,"why":"L'herpès donne des ulcérations superficielles, douloureuses, à contours polycycliques."},{"t":"La maladie de Nicolas-Favre associe anorectite, ulcérations anogénitales et diarrhées trompeuses","ok":true,"why":"Oui : la lymphogranulomatose vénérienne (sérotypes L1, L2, L3 de C. trachomatis, rang B) touche surtout Africains et homosexuels, avec anorectite, ulcérations anogénitales et diarrhées trompeuses (p. 183, 197)."},{"t":"Le chancre mou donne des lésions indolores à fond propre et rosé, avec des adénopathies non inflammatoires","ok":false,"why":"Le chancre mou est très douloureux, à fond sale, avec des adénopathies inflammatoires."}],"explanation":"Ulcération génitale : syphilis (indolore, indurée), herpès (douloureux, polycyclique), chancre mou (douloureux, fond sale), donovanose (granulomateuse, peu douloureuse), LGV (anorectite).","src":"p. 189, 197","deep":"**Pourquoi** : aucun caractère du chancre syphilitique n'est pathognomonique ; la syphilis doit être évoquée systématiquement devant toute ulcération muqueuse aiguë (p. 189, 197).\n**Piège** : ne pas inverser : chancre syphilitique indolore, induré, à fond propre ; chancre mou très douloureux, à fond sale, adénopathies inflammatoires ; herpès douloureux, superficiel, polycyclique (p. 188, 197).\n**À relier** : devant une ulcération génitale, l'OMS recommande de traiter sans attendre les TT et TNT (p. 197)."},{"id":"d162-qcm-717","type":"QRM","rank":"B","objective":"d162-obj-02","tags":["épidémiologie"],"difficulty":2,"stem":"À propos de l'épidémiologie des infections anogénitales à HPV, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La majorité des sujets infectés développent des condylomes","ok":false,"why":"Seule une très faible proportion (environ 1 %) développe des lésions génitales à HPV."},{"t":"Un comportement sexuel à risque est nécessaire pour développer des condylomes","ok":false,"why":"Faux : le Collège précise qu'un comportement à risque sexuel n'est pas nécessaire pour développer des condylomes ; l'incubation est très variable et le portage latent très fréquent (p. 204)."},{"t":"C'est actuellement l'IST la plus fréquente","ok":true,"why":"Près de 40 % des jeunes femmes européennes sont infectées."},{"t":"L'infection par le VIH diminue la fréquence des récidives","ok":false,"why":"L'infection par le VIH augmente l'incidence, la fréquence et la sévérité des récurrences."},{"t":"La très grande majorité des sujets élimine le virus après quelques mois","ok":true,"why":"Les porteurs asymptomatiques sont une faible fraction (< 10 %)."}],"explanation":"HPV : IST la plus fréquente, prédilection 16-25 ans ; la majorité élimine le virus ; < 10 % porteurs asymptomatiques, ~1 % de lésions génitales ; VIH et immunodépression aggravent.","src":"p. 200-201, 204","deep":"**Pourquoi** : HPV = IST la plus fréquente (près de 40 % des jeunes femmes européennes), mais la grande majorité élimine le virus en quelques mois ; moins de 10 % restent porteurs, environ 1 % développe des lésions génitales (p. 200-201).\n**Piège** : VIH et immunodépression augmentent l'incidence, la fréquence et la sévérité des récurrences et la progression vers des néoplasies intra-épithéliales (p. 201).\n**À relier** : transmission majoritairement sexuelle, mais possible par linges humides ou à l'accouchement (papillomatose laryngée juvénile) (p. 200-201)."},{"id":"d162-qcm-718","type":"QRM","rank":"A","objective":"d162-obj-27","tags":["paraclinique"],"difficulty":3,"stem":"Concernant le diagnostic biologique de la syphilis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"La sérologie permet de distinguer la syphilis du pian et du béjel","ok":false,"why":"Aucun test sérologique ne le permet."},{"t":"L'ELISA est le test réalisé en première intention, le TNT n'étant fait que s'il est positif","ok":true,"why":"Si le TT est négatif, le TNT n'est plus réalisé."},{"t":"Le titre du TT quantitatif est le meilleur marqueur de l'évolutivité de la maladie et de la réponse au traitement","ok":false,"why":"Le résultat du TT quantitatif varie beaucoup d'un examen à l'autre : seul le TT qualitatif est intéressant ; le suivi se fait sur le TNT."},{"t":"Le tréponème ne se cultive pas in vitro","ok":true,"why":"Oui : faute de culture, le diagnostic repose sur la mise en évidence directe du tréponème (fond noir, biologie moléculaire, immunohistochimie) ou, indirectement, sur la sérologie (p. 194)."},{"t":"Le microscope à fond noir permet un diagnostic immédiat de certitude mais n'est plus remboursé","ok":true,"why":"Oui : il donne un diagnostic immédiat de certitude après grattage d'une ulcération, érosion ou syphilide, mais il est rarement disponible et n'est plus remboursé (p. 196)."}],"explanation":"Syphilis : pas de culture ; fond noir (abandonné), biologie moléculaire (non remboursée), ou sérologie : ELISA d'abord, TNT seulement si ELISA positif ; suivi sur le TNT quantitatif.","src":"p. 194-196","deep":"**Pourquoi** : le tréponème ne se cultive pas : diagnostic direct (fond noir, abandonné ; biologie moléculaire ; immunohistochimie) ou indirect par la sérologie : ELISA en première intention, puis un TNT si et seulement si l'ELISA est positif (p. 194).\n**Piège** : le TT quantitatif varie trop d'un examen à l'autre : seul son résultat qualitatif compte ; évolutivité et suivi reposent sur le TNT quantitatif (p. 194-195).\n**À relier** : aucun test sérologique ne distingue la syphilis des tréponématoses endémiques (pian, béjel, pinta) (p. 194)."},{"id":"d162-qcm-719","type":"QRM","rank":"B","objective":"d162-obj-22","tags":["prévention","épidémiologie"],"difficulty":2,"stem":"Concernant le dépistage de Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il est réservé aux femmes de plus de 25 ans à facteurs de risque","ok":false,"why":"Les femmes de plus de 25 ans à facteurs de risque relèvent d'un dépistage opportuniste ciblé, en plus du dépistage systématique des moins de 25 ans."},{"t":"Il est systématique chez tous les hommes quel que soit l'âge","ok":false,"why":"Chez l'homme, le dépistage est opportuniste et ciblé sur ceux qui présentent des facteurs de risque."},{"t":"Chez les femmes enceintes consultant pour une IVG, il n'est proposé que si elles ont moins de 25 ans, sans autre condition","ok":false,"why":"Il est proposé aux femmes consultant pour une IVG sans limite d'âge."},{"t":"Il repose sur la sérologie chez les femmes de moins de 25 ans","ok":false,"why":"La sérologie n'a aucun intérêt dans le diagnostic des infections à C. trachomatis."},{"t":"Il est recommandé de façon systématique chez les femmes de moins de 25 ans, par autoprélèvement vaginal","ok":true,"why":"En France, dépistage systématique par autoprélèvement vaginal chez les femmes de moins de 25 ans."}],"explanation":"Chlamydia : dépistage systématique par autoprélèvement vaginal des femmes < 25 ans ; opportuniste ciblé chez hommes à risque, femmes > 25 ans à risque, femmes enceintes pour IVG (sans limite d'âge).","src":"p. 183, 187","deep":"**Pourquoi** : portage asymptomatique fréquent et complications tubaires font de C. trachomatis un enjeu de santé publique chez les plus jeunes : dépistage systématique des femmes de moins de 25 ans par autoprélèvement vaginal (p. 183, 187).\n**Piège** : dépistage opportuniste ciblé = hommes à facteurs de risque (quel que soit l'âge), femmes de plus de 25 ans à facteurs de risque, femmes consultant pour une IVG sans limite d'âge (p. 183).\n**À relier** : le diagnostic repose sur la PCR ; la sérologie n'a pas d'intérêt (p. 185)."},{"id":"d162-qcm-720","type":"QRM","rank":"A","objective":"d162-obj-07","tags":["clinique","pièges"],"difficulty":2,"stem":"Dans quelles localisations du chancre le diagnostic de syphilis primaire est-il souvent méconnu car la lésion n'est pas visible ?","options":[{"t":"Chancre du sillon balano-préputial","ok":false,"why":"C'est le siège électif chez l'homme et il est facilement visible."},{"t":"Chancre du vagin","ok":true,"why":"Oui : plus rare que le chancre vulvaire, le chancre vaginal passe volontiers inaperçu (p. 188-189)."},{"t":"Chancre pharyngé","ok":true,"why":"Il est contracté par fellation et reste souvent méconnu."},{"t":"Chancre du col utérin","ok":true,"why":"Le chancre du col utérin n'est pas visible et son adénopathie satellite non plus : la syphilis primaire est souvent méconnue."},{"t":"Chancre anorectal","ok":true,"why":"Le chancre anorectal fait partie des chancres non visibles, d'où le diagnostic souvent méconnu."}],"explanation":"Le chancre n'est pas visible quand il est vaginal, du col utérin, anorectal ou pharyngé : syphilis primaire souvent méconnue, d'où l'importance d'évoquer une syphilis devant toute ulcération muqueuse.","src":"p. 188-190","deep":"**Pourquoi** : vaginal, du col utérin, anorectal ou pharyngé, le chancre n'est pas visible : la syphilis primaire est alors souvent méconnue (p. 188).\n**Piège** : au col utérin et au rectum, l'adénopathie satellite n'est pas cliniquement visible non plus (p. 190).\n**À relier** : chez l'homme, siège électif au sillon balano-préputial ; chez la femme, le plus souvent sur la partie externe de la vulve (p. 189)."},{"id":"d162-qcm-721","type":"QRM","rank":"B","objective":"d162-obj-33","tags":["paraclinique"],"difficulty":2,"stem":"Concernant le diagnostic biologique d'une infection à Chlamydia trachomatis, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Chez l'homme symptomatique ou non, le 1er jet urinaire (10 à 20 mL) est prélevé moins de 2 heures après la dernière miction pour la PCR","ok":false,"why":"Il doit être prélevé au moins 2 heures après la dernière miction."},{"t":"La culture sur gélose au sang cuit est systématique","ok":false,"why":"Cette culture concerne le gonocoque ; la chlamydiose se diagnostique par PCR."},{"t":"La sérologie est utile pour confirmer l'infection","ok":false,"why":"La sérologie n'a pas d'intérêt dans le diagnostic."},{"t":"La PCR est l'examen clé, plus sensible que la culture","ok":true,"why":"L'amplification génique est l'examen clé du diagnostic."},{"t":"Chez la femme symptomatique, l'auto-écouvillonnage vaginal est à préférer à l'écouvillonnage de l'endocol par un professionnel","ok":true,"why":"C'est la recommandation pour la femme symptomatique."}],"explanation":"Chlamydia : PCR (1er jet d'urine ≥ 2 h après la miction chez l'homme ; auto-écouvillonnage vaginal chez la femme), pas de sérologie.","src":"p. 185","deep":"**Pourquoi** : la PCR (amplification génique), plus sensible que la culture, est l'examen clé : 1er jet urinaire (10 à 20 mL, au moins 2 heures après la dernière miction) chez l'homme, auto-écouvillonnage vaginal chez la femme (p. 185).\n**Piège** : la sérologie n'a pas d'intérêt dans le diagnostic des infections à C. trachomatis (p. 185).\n**À relier** : PCR de contrôle pas trop précoce : des débris de Chlamydia peuvent la rendre faussement positive dans les 4 semaines suivant le traitement (p. 185)."},{"id":"d162-qru-708","type":"QRU","rank":"B","objective":"d162-obj-25","tags":["urgence","traitement"],"difficulty":3,"stem":"Un homme de 29 ans, atteint d'une syphilis secondaire, signale une baisse d'acuité visuelle avec des phosphènes. Quelle conduite est justifiée ?","options":[{"t":"Une ponction lombaire, puis pénicilline G pendant 14 jours quel que soit son résultat","ok":true,"why":"L'atteinte ophtalmique (uvéite surtout) est interprétée comme une neurosyphilis précoce : ponction lombaire et, quel que soit son résultat, pénicilline G 14 jours."},{"t":"Une injection unique de benzathine-benzylpénicilline 2,4 MU avec simple surveillance","ok":false,"why":"Une atteinte ophtalmique est une neurosyphilis précoce : elle justifie une ponction lombaire et la pénicilline G pendant 14 jours."},{"t":"Une cure de doxycycline pendant 14 jours","ok":false,"why":"La doxycycline est réservée à l'allergie à la pénicilline."},{"t":"Une injection unique de ceftriaxone 1000 mg IM","ok":false,"why":"Ce schéma est celui de la gonococcie."},{"t":"Une ponction lombaire, le traitement n'étant débuté que si elle est anormale","ok":false,"why":"Le traitement est donné quel que soit le résultat de la ponction lombaire."}],"explanation":"Syphilis secondaire avec manifestation ophtalmique (uvéite, papillite, névrite optique) ou atteinte d'une paire crânienne = neurosyphilis précoce : PL + pénicilline G 14 jours.","src":"p. 193","deep":"**Pourquoi** : une atteinte ophtalmique du secondaire (uvéite antérieure surtout, mais aussi postérieure, papillite, névrite optique) est une neurosyphilis précoce : PL puis pénicilline G 14 jours quel que soit le résultat (p. 193).\n**Piège** : l'atteinte d'une paire crânienne (hypoacousie, acouphènes, paralysie faciale) a la même signification ; des céphalées isolées, elles, ne signent pas une atteinte neuroméningée (p. 193).\n**À relier** : d'où l'importance d'interroger sur les troubles visuels (baisse d'acuité, phosphènes, douleurs) et de faire un examen soigneux devant toute syphilis précoce (p. 193, 197)."},{"id":"d162-qru-709","type":"QRU","rank":"B","objective":"d162-obj-37","tags":["diagnostic"],"difficulty":2,"stem":"Parmi les diagnostics différentiels des condylomes acuminés, lequel correspond à une variante physiologique ?","options":[{"t":"La couronne perlée du gland (hyperplasie physiologique des papilles)","ok":true,"why":"Elle correspond à une hyperplasie physiologique des papilles de la couronne du gland ; de même la papillomatose vestibulaire vulvaire physiologique."},{"t":"Le molluscum contagiosum","ok":false,"why":"Faux : le molluscum contagiosum figure parmi les diagnostics différentiels pathologiques des condylomes, pas parmi les variantes physiologiques (p. 203)."},{"t":"La kératose séborrhéique","ok":false,"why":"Faux : les kératoses séborrhéiques sont un diagnostic différentiel des condylomes, mais ce ne sont pas des variantes physiologiques (p. 203)."},{"t":"Les condylomata lata","ok":false,"why":"Ce sont des syphilides secondaires."},{"t":"Les nodules scabieux","ok":false,"why":"Ils sont liés à la gale."}],"explanation":"Diagnostics différentiels des condylomes : couronne perlée du gland et papillomatose vestibulaire vulvaire (physiologiques), syphilides secondaires, lésions dysplasiques, kératoses séborrhéiques, molluscum, nodules scabieux.","src":"p. 203","deep":"**Pourquoi** : la couronne perlée du gland (hyperplasie physiologique des papilles) et la papillomatose vestibulaire vulvaire sont les deux variantes physiologiques du diagnostic différentiel des condylomes (p. 203).\n**Piège** : les condylomata lata sont des syphilides secondaires : la recherche d'IST associée devant des condylomes comprend un test tréponémique (p. 203, 205).\n**À relier** : autres différentiels : lésions dysplasiques, kératoses séborrhéiques, molluscum contagiosum, nodules scabieux (p. 203)."}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d162-pareto","points":[{"id":"d162-par-01","rank":"A","cat":"clinique","text":"Chancre syphilitique = ulcération **indolore**, à fond propre, **indurée** + adénopathie satellite **non inflammatoire** ; évoquer la syphilis devant toute ulcération muqueuse aiguë (génitale, orale, anale)","src":"p. 188-190"},{"id":"d162-par-02","rank":"A","cat":"examen","text":"Sérologie syphilis : **ELISA (TT) en 1er** ; **TNT** (VDRL/RPR) seulement si TT positif ; syphilis secondaire = **TT + TNT toujours positifs**","src":"p. 194-195, 200"},{"id":"d162-par-03","rank":"A","cat":"piège","text":"**7 premiers jours du chancre** : TT et TNT possiblement **négatifs** → devant une ulcération génitale, **ne pas attendre** la sérologie pour traiter (OMS)","src":"p. 194-197"},{"id":"d162-par-04","rank":"A","cat":"traitement","text":"Syphilis précoce (primaire, secondaire, latente précoce) : **benzathine-benzylpénicilline 2,4 MU IM en 1 injection** ; si allergie : **doxycycline 14 j** (sauf grossesse et VIH)","src":"p. 197-198"},{"id":"d162-par-05","rank":"A","cat":"suivi","text":"Suivi syphilis : **TNT quantitatif** ; titre **divisé par 4 à 6 mois** ; contrôles à 3 mois, 6 mois, 1 an puis annuels ; titre multiplié par 4 = recontamination","src":"p. 195, 198"},{"id":"d162-par-06","rank":"A","cat":"piège","text":"**Herxheimer** (fièvre, céphalées, myalgies quelques heures après l'injection) = lyse des tréponèmes, bénigne ; ce n'est **pas une allergie** à la pénicilline","src":"p. 198"},{"id":"d162-par-07","rank":"A","cat":"piège","text":"TNT positif isolé (TT négatif) = **fausse sérologie** (**lupus**, SAPL, grossesse) ; TT positif + TNT négatif = cicatrice sérologique","src":"p. 194-196"},{"id":"d162-par-08","rank":"A","cat":"clinique","text":"Syphilis secondaire = « grande simulatrice » : papules **cuivrées**, papules **palmo-plantaires** très évocatrices ; roséole à ne pas confondre avec virose ou toxidermie","src":"p. 191-192, 200"},{"id":"d162-par-09","rank":"A","cat":"traitement","text":"Urétrite : traitement minute **ceftriaxone** (gonocoque) + **anti-Chlamydia systématique** (**doxycycline 7 j** préférée à l'azithromycine 1 g) ; traiter les partenaires ; rapports protégés ≥ 7 j","src":"p. 182, 187"},{"id":"d162-par-10","rank":"A","cat":"clinique","text":"Gonococcie : incubation **2-7 j**, écoulement **purulent** (90 %), femme **asymptomatique 70 %** ; diagnostic par **PCR** (1er jet urinaire chez l'homme, auto-écouvillonnage vaginal chez la femme)","src":"p. 180-181"},{"id":"d162-par-11","rank":"A","cat":"piège","text":"Chlamydia : **portage asymptomatique** fréquent (50 % H, 50-90 % F), écoulement clair intermittent ; examen clé = **PCR** ; la **sérologie est inutile**","src":"p. 184-185"},{"id":"d162-par-12","rank":"A","cat":"prévention","text":"Devant toute IST : dépister/traiter les **partenaires** ; proposer **VIH + test tréponémique + hépatite B** ; pas de rapports non protégés pendant le traitement ; **PrEP** si risques répétés","src":"p. 182, 185, 208"},{"id":"d162-par-13","rank":"A","cat":"examen","text":"Condylomes : diagnostic **clinique** (crêtes-de-coq) ; chercher une **IST associée** (25 %) ; col : frottis **tous les 3 ans** ou **test HPV-HR dès 30 ans**","src":"p. 201-202, 205"},{"id":"d162-par-14","rank":"A","cat":"prévention","text":"Vaccin anti-HPV **nonavalent** : filles et garçons **11-14 ans** (2 doses), rattrapage **15-19 ans** (3 doses 0-2-6 mois), HSH jusqu'à **26 ans**","src":"p. 204-205"},{"id":"d162-par-15","rank":"A","cat":"prévention","text":"Contact d'une syphilis certaine : **< 6 semaines → traiter d'emblée** (2,4 MU) ; **> 6 semaines → sérologie**, refaite à 3 mois si négative","src":"p. 198"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
